#!/usr/bin/env python3
"""Viki — compagnon de bureau animé pour KDE Plasma (CachyOS / Arch) et Windows.

Clic gauche     : elle réagit (zones : tête, joues, nez, mains…)
Double-clic     : lui écrire directement (aussi : clic molette, ou « run.sh --ecrire »)
Glisser         : la déplacer
Clic droit      : menu (personnage, phrases, rappels, voix, discussion, outils…)
"""
import sys as _s
if _s.platform == "win32" and "--ecoute" not in _s.argv:   # Windows : journal de démarrage + trace si plantage
    import faulthandler as _fh
    import os as _o
    _d = _o.path.join(_o.environ.get("LOCALAPPDATA", _o.path.expanduser("~")), "Viki")
    _o.makedirs(_d, exist_ok=True)
    _DEMARRAGE = open(_o.path.join(_d, "demarrage.log"), "w", encoding="utf-8", buffering=1)
    _fh.enable(_DEMARRAGE)

    def _etape(t):
        _DEMARRAGE.write(t + "\n")
        _DEMARRAGE.flush()
        if _s.stderr:
            try:
                _s.stderr.write("[démarrage] " + t + "\n")
                _s.stderr.flush()
            except Exception:
                pass
else:
    def _etape(t):
        pass
_etape("1 python ok " + _s.version.split()[0])
