PORTABLE = bool(os.environ.get("APPIMAGE") or os.environ.get("COMPAGNON_PORTABLE") or plateforme.FROZEN)
# Le logiciel s'appelle maintenant « Viki » : les anciens dossiers « compagnon » sont repris tels quels.
_MOVED = []


def _migrate_dir(old, new):
    """Renomme l'ancien dossier (et laisse un raccourci à l'ancienne place pour les vieux scripts)."""
    try:
        if old.exists() and not old.is_symlink() and not new.exists():
            new.parent.mkdir(parents=True, exist_ok=True)
            old.rename(new)
            _MOVED.append((str(old), str(new)))
            try:
                old.symlink_to(new, target_is_directory=True)
            except Exception:
                pass
    except Exception as e:
        print("Passage à Viki (dossier) :", e, file=sys.stderr)
    return new


if IS_WIN:
    _LA = Path(os.environ.get("LOCALAPPDATA", Path.home()))
    DATA_DIR = _migrate_dir(_LA / "Compagnon", _LA / "Viki") if PORTABLE else APP_DIR
else:
    _XD = Path(os.environ.get("XDG_DATA_HOME", Path.home() / ".local" / "share"))
    DATA_DIR = _migrate_dir(_XD / "compagnon", _XD / "viki") if PORTABLE else APP_DIR
ASSETS_DIR = DATA_DIR / "assets"
