def _prepare_portable():
    """1er lancement de l'AppImage : copie les personnages fournis (modifiables ensuite)."""
    if not PORTABLE:
        return
    try:
        src = APP_DIR / "assets"
        for f in src.rglob("*"):
            dst = ASSETS_DIR / f.relative_to(src)
            if f.is_dir():
                dst.mkdir(parents=True, exist_ok=True)
            elif not dst.exists():
                dst.parent.mkdir(parents=True, exist_ok=True)
                dst.write_bytes(f.read_bytes())
        (DATA_DIR / "voices").mkdir(parents=True, exist_ok=True)
    except Exception as e:
        print("Préparation des données :", e, file=sys.stderr)


_etape("4 modules ok")
