def heure_txt():
    n = datetime.datetime.now()
    return f"{n.hour} heures pile" if n.minute == 0 else f"{n.hour} heures {n.minute}"


JOURS_FR = ("lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche")
MOIS_FR = ("janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre",
           "novembre", "décembre")


def date_txt(d=None):
    """« jeudi 12 novembre 2026 » (sans dépendre de la langue du système)."""
    d = d or datetime.date.today()
    return f"{JOURS_FR[d.weekday()]} {'1er' if d.day == 1 else d.day} {MOIS_FR[d.month - 1]} {d.year}"


def load_phrases(char_dir):
    data = {k: list(v) for k, v in DEFAULT_PHRASES.items()}
    try:
        user = json.loads((Path(char_dir) / "phrases.json").read_text())
        for k, v in user.items():
            if k in data and isinstance(v, list) and v:
                data[k] = [str(x) for x in v]
    except Exception:
        pass
    return data


def save_phrases(char_dir, data):
    (Path(char_dir) / "phrases.json").write_text(json.dumps(data, indent=2, ensure_ascii=False))


def greeting_key():
    h = datetime.datetime.now().hour
    if 5 <= h < 12:
        return "matin"
    if 12 <= h < 14:
        return "midi"
    if 14 <= h < 18:
        return "apres_midi"
    if 18 <= h < 23:
        return "soir"
    return "nuit"


# ---------------------------------------------------------------- config
def probe_hardware():
    """Nombre de cœurs et mémoire vive (Go) : sert à choisir la qualité de départ."""
    cores = os.cpu_count() or 2
    ram = 8.0
    if IS_WIN:
        try:
            return cores, plateforme.mem_info()[1]
        except Exception:
            return cores, ram
    try:
        for line in open("/proc/meminfo"):
            if line.startswith("MemTotal:"):
                ram = int(line.split()[1]) / 1024 / 1024
                break
    except Exception:
        pass
    return cores, ram


