_PIPER_OK = {}


def piper_compatible(model_path):
    """Le Piper intégré ne lit que les voix dont chaque phonème tient en un seul caractère
    (certaines voix récentes ont « aɪ » : Piper plante avec « is not a single codepoint »)."""
    j = Path(str(model_path) + ".json")
    try:
        key = (str(j), j.stat().st_mtime)
    except OSError:
        return False
    if key not in _PIPER_OK:
        try:
            ids = json.loads(j.read_text(encoding="utf-8")).get("phoneme_id_map", {})
            _PIPER_OK[key] = all(len(k) == 1 for k in ids)
        except Exception:
            _PIPER_OK[key] = True
    return _PIPER_OK[key]


def piper_model(model_path):
    """Chemin à donner à Piper. Voix récente (phonèmes comme « aɪ ») : on lui prépare une copie de sa
    configuration sans ces phonèmes groupés (le modèle lui-même est juste relié), Piper les lit lettre par lettre."""
    if not model_path or piper_compatible(model_path):
        return model_path
    src = Path(model_path)
    d = DATA_DIR / "cache" / "piper"
    lien, cfg = d / src.name, d / (src.name + ".json")
    try:
        js = Path(str(src) + ".json")
        if not cfg.exists() or cfg.stat().st_mtime < js.stat().st_mtime:
            d.mkdir(parents=True, exist_ok=True)
            conf = json.loads(js.read_text(encoding="utf-8"))
            conf["phoneme_id_map"] = {k: v for k, v in conf.get("phoneme_id_map", {}).items() if len(k) == 1}
            cfg.write_text(json.dumps(conf, ensure_ascii=False), encoding="utf-8")
            print(f"Voix {src.name} adaptée pour Piper (phonèmes groupés retirés)", file=sys.stderr)
        if not lien.exists():
            if lien.is_symlink():
                lien.unlink()
            try:
                lien.symlink_to(src.resolve())
            except OSError:
                shutil.copy2(src, lien)
        return str(lien)
    except Exception as e:
        print("Adaptation de la voix pour Piper :", e, file=sys.stderr)
        return model_path


def voice_files():
    """Tous les modèles de voix Piper (.onnx) trouvés (dossier de données puis voix intégrées)."""
    seen, out = set(), []
    for vdir in VOICE_DIRS:
        for m in sorted(vdir.glob("*.onnx")) if vdir.exists() else []:
            if m.name not in seen:
                seen.add(m.name)
                out.append(m)
    return out


def find_voice_model(preferred=""):
    """Une voix Piper n'est utilisable qu'avec son fichier .onnx.json à côté."""
    if preferred:
        for vdir in VOICE_DIRS:
            p = vdir / f"{preferred}.onnx"
            if p.exists() and Path(str(p) + ".json").exists():
                return str(p)
    models = sorted(voice_files(), key=lambda m: (not m.name.startswith("fr_"), m.name))
    for m in models:
        if Path(str(m) + ".json").exists():
            return str(m)
    if models:
        print(f"Voix Piper incomplète : il manque {models[0].name}.json", file=sys.stderr)
    return None


PIPER_LABELS = {
    "fr_FR-siwis-medium": "Siwis — féminine, claire",
    "fr_FR-siwis-low": "Siwis — féminine (léger)",
    "fr_FR-tom-medium": "Tom — masculine",
    "fr_FR-gilles-low": "Gilles — masculine, grave (léger)",
    "fr_FR-mls-medium": "MLS — masculine",
    "fr_FR-mls_1840-low": "MLS 1840 — masculine (léger)",
}


def piper_voice_choices():
    """Voix Piper disponibles dans voices/ : (fichier, libellé, locuteur)."""
    out = []
    for m in voice_files():
        if not Path(str(m) + ".json").exists():
            continue
        stem = m.stem
        if not stem.startswith("fr_"):        # les autres langues se règlent dans « Langue »
            continue
        if stem == "fr_FR-upmc-medium":      # modèle à deux voix : Jessica, Pierre
            out.append((stem, "UPMC Jessica — féminine", 0))
            out.append((stem, "UPMC Pierre — masculine", 1))
            continue
        sp = voix.speakers_of(m) if voix else []
        if sp:
            label = PIPER_LABELS.get(stem, stem)
            out += [(stem, f"{label} — {name}", i) for i, name in sp]
            continue
        out.append((stem, PIPER_LABELS.get(stem, stem), -1))
    return out


_NAT_PY = {}


def natural_dirs(kind="naturelle"):
    """Dossiers où une voix avancée (.venv-voix / .venv-voix-legere) a pu être installée : réglage, données
    de Viki, dossier du programme, et les dossiers où on a lancé son script d'installation (ex : ~/compagnon)."""
    e = NAT_ENGINES[kind]
    out = []
    try:
        d = json.loads((BASE_CONFIG_DIR / e["dossier"]).read_text()).get("dossier", "")
        if d:
            out.append(Path(d))
    except Exception:
        pass
    out += [DATA_DIR, APP_DIR]
    h = Path.home()
    for pat in (f"*/{e['venv']}", f"*/*/{e['venv']}", f".local/share/compagnon/{e['venv']}"):
        try:
            out += [p.parent for p in sorted(h.glob(pat))[:20]]
        except Exception:
            pass
    return out


def natural_python(refresh=False, kind="naturelle"):
    """Le Python d'une voix avancée, où qu'il soit (None si elle n'est pas installée)."""
    if kind not in NAT_ENGINES:
        return None
    if kind not in _NAT_PY or refresh:
        _NAT_PY[kind] = ""
        for d in natural_dirs(kind):
            p = d / NAT_ENGINES[kind]["venv"] / ("Scripts/python.exe" if IS_WIN else "bin/python")
            try:
                if p.exists() and p.resolve().exists():     # lien du venv pas cassé
                    _NAT_PY[kind] = str(p)
                    break
            except Exception:
                pass
    return _NAT_PY[kind] or None


def split_speech(text):
    """Découpe en phrases pour la voix naturelle : la 1re courte (elle commence vite), les suivantes
    regroupées jusqu'à ~160 caractères."""
    parts = [p for p in re.split(r"(?<=[.!?…])\s+|\n+", text.strip()) if p.strip()]
    out = []
    for p in parts:
        if out and len(out) > 1 and len(out[-1]) + len(p) < 160:
            out[-1] += " " + p
        elif out and len(out[-1]) < 25 and len(out[-1]) + len(p) < 120:
            out[-1] += " " + p
        else:
            out.append(p)
    return out


def figure_height(pix):
    """Hauteur du personnage DESSINÉ dans l'image (sans les marges transparentes), en pixels."""
    try:
        import numpy as np
        img = pix.toImage().convertToFormat(QImage.Format.Format_ARGB32)
        w, h = img.width(), img.height()
        ptr = img.constBits()
        ptr.setsize(h * img.bytesPerLine())
        a = np.frombuffer(ptr, np.uint8).reshape(h, img.bytesPerLine())[:, 3:w * 4:4]
        rows = np.where((a > 40).sum(axis=1) > max(2, w // 200))[0]
        return int(rows[-1] - rows[0] + 1) if len(rows) else h
    except Exception:
        return pix.height()


