def clean_for_tts(text):
    text = re.sub(r"[*_#`~>\[\]]", "", text)
    text = re.sub(r"[\U0001F000-\U0001FAFF☀-➿]", "", text)
    return text.strip()


def wav_envelope(path, fps=FPS):
    """Volume (0..1) de l'audio pour chaque image d'animation."""
    with wave.open(path, "rb") as w:
        sr, sw, ch = w.getframerate(), w.getsampwidth(), w.getnchannels()
        raw = w.readframes(w.getnframes())
    if sw != 2:
        return [], 0.0
    samples = array("h", raw)
    if ch > 1:
        samples = samples[::ch]
    step = max(1, sr // fps)
    env = []
    for i in range(0, len(samples), step):
        chunk = samples[i:i + step]
        if not chunk:
            break
        sub = chunk[::16]
        env.append(math.sqrt(sum(s * s for s in sub) / max(1, len(sub))))
    peak = max(env) if env else 1
    env = [min(1.0, (e / peak) * 1.4) if peak else 0 for e in env]
    return env, len(samples) / sr


def fake_envelope(text, fps=FPS):
    dur = max(1.2, len(text) * 0.065)
    n = int(dur * fps)
    env = []
    for i in range(n):
        syll = abs(math.sin(i * 0.9)) * (0.6 + 0.4 * random.random())
        env.append(syll if text[min(len(text) - 1, i * len(text) // n)] not in " ,.!?" else 0.1)
    return env, dur


