_ISOLATION = None        # (commande systemd-run, options acceptées) ou "" si indisponible


def _probe_isolation():
    """Teste VRAIMENT les options sur ce PC (elles varient selon la version de systemd)."""
    exe = shutil.which("systemd-run")
    if not exe:
        return ""
    for props in (["-p", "MemoryMax={mem}", "-p", "MemorySwapMax=0"], ["-p", "MemoryMax={mem}"]):
        test = [a.replace("{mem}", "1G") for a in props]
        try:
            r = subprocess.run([exe, "--user", "--scope", "--quiet", "--collect"] + test + ["--", "true"],
                               capture_output=True, timeout=15)
            if r.returncode == 0:
                return exe, props
        except Exception:
            pass
    return ""


def isolated(cmd, max_gb, name="aide", swap=False):
    """Lance un programme d'aide dans sa PROPRE « boîte mémoire » (scope systemd) avec un plafond.
    S'il déborde, Linux ne tue que lui, et plus jamais le compagnon avec.
    Si systemd ne le permet pas sur ce PC, le programme est lancé normalement."""
    global _ISOLATION
    if _ISOLATION is None:
        _ISOLATION = _probe_isolation()
    choom = shutil.which("choom")              # le désigner en premier si la mémoire manque
    base = ([choom, "-n", "800", "--"] if choom else []) + list(cmd)
    if not _ISOLATION:
        return base
    exe, props = _ISOLATION
    mem = f"{max(0.5, max_gb):.1f}G"
    if swap:                                   # gros programme (voix naturelle) : le swap reste permis
        props = [a for i, a in enumerate(props)
                 if "MemorySwapMax" not in a and not (a == "-p" and i + 1 < len(props)
                                                      and "MemorySwapMax" in props[i + 1])]
    return ([exe, "--user", "--scope", "--quiet", "--collect",
             f"--unit=compagnon-{name}-{os.getpid()}-{int(time.time() * 1000) % 100000}"]
            + [a.replace("{mem}", mem) for a in props] + ["--"] + base)


def _isolation_failed(stderr):
    """Erreur venant de systemd-run lui-même (et pas du programme) ?"""
    e = (stderr or "").lower()
    return any(k in e for k in ("unknown assignment", "failed to start transient", "failed to create bus",
                                "transient scope", "invalid argument"))


_CUTOUT_SCRIPT = r"""
import sys
from PIL import Image
from rembg import new_session, remove
src, dst, model = sys.argv[1:4]
im = Image.open(src).convert("RGB")
if max(im.size) > 2048:                       # inutile d'aller plus haut : plus lent, plus de mémoire
    k = 2048 / max(im.size)
    im = im.resize((round(im.width * k), round(im.height * k)), Image.LANCZOS)
remove(im, session=new_session(model)).save(dst)
"""


def remove_background(src, dst, model="isnet-anime"):
    """Détourage dans un PROCESSUS SÉPARÉ : s'il manque de mémoire ou plante,
    le compagnon, lui, continue de tourner."""
    need = 3.5 if "birefnet" in model else 1.2
    cap = min(max(need + 1.0, mem_available_gb() * 0.75), 7.0)
    global _ISOLATION
    env = dict(os.environ, OMP_NUM_THREADS=str(max(1, (os.cpu_count() or 2) // 2)))
    cmd = [sys.executable, "-c", _CUTOUT_SCRIPT, src, dst, model]
    r = subprocess.run(isolated(cmd, cap, "detourage"), capture_output=True, text=True, timeout=1200, env=env)
    if r.returncode != 0 and _isolation_failed(r.stderr):      # systemd refuse : on relance sans la boîte
        print("Isolation mémoire indisponible :", (r.stderr or "").strip()[-200:], file=sys.stderr)
        _ISOLATION = ""
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=1200, env=env)
    if r.returncode != 0 or not Path(dst).exists():
        err = (r.stderr or "").strip().splitlines()
        msg = err[-1] if err else f"code {r.returncode}"
        if r.returncode < 0 or "MemoryError" in (r.stderr or "") or r.returncode in (137, 9, -9):
            msg = "pas assez de mémoire pour ce détourage (essaie « Anime (rapide) »)"
        raise RuntimeError(msg)


def image_has_transparency(img):
    if not img.hasAlphaChannel():
        return False
    w, h = img.width(), img.height()
    corners = [(0, 0), (w - 1, 0), (0, h - 1), (w - 1, h - 1)]
    return any(img.pixelColor(x, y).alpha() < 20 for x, y in corners)


_SOLID = bytes(0 if i <= 10 else 255 for i in range(256))


def solid_alpha(img):
    """Copie où tout pixel un peu visible (alpha > 10) devient opaque.
    Sert au masque de clic et au recadrage : les mèches fines et bords flous
    ne sont plus coupés (le seuil par défaut de Qt est 50 %)."""
    im = img.convertToFormat(QImage.Format.Format_ARGB32)
    n = im.sizeInBytes()
    data = bytes(im.constBits().asstring(n)).translate(_SOLID)   # les couleurs n'importent pas
    out = QImage(data, im.width(), im.height(), im.bytesPerLine(), QImage.Format.Format_ARGB32)
    return out.copy()


def tidy_image(img, max_h=900):
    """Recadre sur le personnage, réduit si trop grand, adoucit le bas s'il est coupé."""
    img = img.convertToFormat(QImage.Format.Format_ARGB32)
    box = QRegion(QBitmap.fromImage(solid_alpha(img).createAlphaMask())).boundingRect()
    # le personnage touche-t-il le bas de l'image d'origine ? (sinon : en pied, pieds visibles)
    touches_bottom = not box.isValid() or box.bottom() >= img.height() - 3
    if box.isValid() and box.width() > 10:
        img = img.copy(box)
    if img.height() > max_h:
        img = img.scaledToHeight(max_h, Qt.TransformationMode.SmoothTransformation)
    w, h = img.width(), img.height()
    bottom_opaque = sum(1 for x in range(0, w, 3) if img.pixelColor(x, h - 1).alpha() > 128)
    if image_has_transparency(img) and bottom_opaque > 8 and touches_bottom:
        f = max(10, min(45, h // 10))
        p = QPainter(img)
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationIn)
        g = QLinearGradient(0, h - f, 0, h)
        g.setColorAt(0, QColor(0, 0, 0, 255))
        g.setColorAt(1, QColor(0, 0, 0, 0))
        p.fillRect(0, h - f, w, f, g)
        p.end()
        img.setText("cut", "1")          # personnage coupé en bas : pas d'ombre au sol
    return img


def make_hitmask(img, r=6):
    img = solid_alpha(img)
    m = QImage(img.size(), QImage.Format.Format_ARGB32)
    m.fill(Qt.GlobalColor.transparent)
    p = QPainter(m)
    for dx in (-r, 0, r):
        for dy in (-r, 0, r):
            p.drawImage(dx, dy, img)
    p.end()
    return m


def analyse_eye(img, e, skin):
    """Détecte automatiquement l'iris et le blanc de l'œil autour du point cliqué.
    Renvoie None si l'œil n'est pas exploitable (l'appli garde alors l'œil fixe)."""
    w, h = e["w"], e["h"]
    pad = 3
    box = QRect(int(e["x"] - w / 2 - pad), int(e["y"] - h / 2 - pad), int(w + 2 * pad), int(h + 2 * pad))
    box = box.intersected(img.rect())
    if box.width() < 6 or box.height() < 4:
        return None
    cx, cy = e["x"] - box.left(), e["y"] - box.top()
    rx, ry = w / 2 + 1, h / 2 + 1
    opening = QImage(box.size(), QImage.Format.Format_ARGB32)
    opening.fill(Qt.GlobalColor.transparent)
    iris_pts, sclera = [], []
    for y in range(box.height()):
        for x in range(box.width()):
            if ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 > 1:
                continue
            q = img.pixelColor(box.left() + x, box.top() + y)
            if q.alpha() < 200:
                continue
            L, S = q.lightness(), q.hsvSaturation()
            dskin = abs(q.red() - skin.red()) + abs(q.green() - skin.green()) + abs(q.blue() - skin.blue())
            top = y < cy - ry * 0.35                     # zone des cils du haut
            if L > 200 and S < 40 and dskin > 25:
                sclera.append(q)
                opening.setPixelColor(x, y, QColor(0, 0, 0, 255))
            elif dskin < 45:
                continue                                  # peau
            elif L < 70 and top:
                continue                                  # cils
            else:
                iris_pts.append((x, y))
                opening.setPixelColor(x, y, QColor(0, 0, 0, 255))
    if len(iris_pts) < 12:
        return None
    ix = sum(p[0] for p in iris_pts) / len(iris_pts)
    iy = sum(p[1] for p in iris_pts) / len(iris_pts)
    r = max(h * 0.4, math.sqrt(len(iris_pts) / math.pi))
    patch = QImage(box.size(), QImage.Format.Format_ARGB32)
    patch.fill(Qt.GlobalColor.transparent)
    for (x, y) in iris_pts:
        dd = math.hypot(x - ix, y - iy) / (r * 1.15)
        if dd <= 1:
            q = img.pixelColor(box.left() + x, box.top() + y)
            q.setAlpha(int(255 * min(1.0, (1 - dd) / 0.3)))    # bord adouci
            patch.setPixelColor(x, y, q)
    if sclera:
        sc = sorted(sclera, key=lambda q: q.lightness())[len(sclera) // 2]
    else:
        sc = QColor(246, 240, 240)
    path = QPainterPath()
    path.addRegion(QRegion(QBitmap.fromImage(opening.createAlphaMask())).translated(box.topLeft()))
    return {"box": box, "patch": patch, "clip": path, "sclera": sc,
            "max_dx": max(1.0, w * 0.1), "max_dy": max(0.6, h * 0.07)}


# ---------------------------------------------------------------- zone cliquable (X11)
class _XRect(ctypes.Structure):
    _fields_ = [("x", ctypes.c_short), ("y", ctypes.c_short),
                ("width", ctypes.c_ushort), ("height", ctypes.c_ushort)]


class X11InputShape:
    """Ne règle QUE la zone qui reçoit les clics (extension XShape, « ShapeInput »).
    L'image n'est donc jamais rognée : avant, le masque coupait aussi l'affichage."""

    def __init__(self):
        self.ok = False
        if QApplication.platformName() != "xcb":
            return
        try:
            self.xlib = ctypes.CDLL("libX11.so.6")
            self.xext = ctypes.CDLL("libXext.so.6")
            self.xlib.XOpenDisplay.restype = ctypes.c_void_p
            self.xlib.XOpenDisplay.argtypes = [ctypes.c_char_p]
            self.xlib.XFlush.argtypes = [ctypes.c_void_p]
            self.xext.XShapeCombineRectangles.argtypes = [
                ctypes.c_void_p, ctypes.c_ulong, ctypes.c_int, ctypes.c_int, ctypes.c_int,
                ctypes.POINTER(_XRect), ctypes.c_int, ctypes.c_int, ctypes.c_int]
            self.dpy = self.xlib.XOpenDisplay(None)
            self.ok = bool(self.dpy)
        except Exception as e:
            print("Zone de clic X11 indisponible :", e, file=sys.stderr)

    def managed_props(self, wid):
        """Fenêtre gérée par KDE mais discrète : hors barre des tâches et du sélecteur, toujours au-dessus.
        (À poser avant que la fenêtre s'affiche.)"""
        try:
            x = self.xlib
            x.XInternAtom.restype = ctypes.c_ulong
            x.XInternAtom.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_int]
            x.XChangeProperty.argtypes = [ctypes.c_void_p, ctypes.c_ulong, ctypes.c_ulong, ctypes.c_ulong,
                                          ctypes.c_int, ctypes.c_int, ctypes.c_void_p, ctypes.c_int]
            atom = lambda n: x.XInternAtom(self.dpy, n, 0)
            states = (ctypes.c_ulong * 3)(atom(b"_NET_WM_STATE_SKIP_TASKBAR"), atom(b"_NET_WM_STATE_SKIP_PAGER"),
                                          atom(b"_NET_WM_STATE_ABOVE"))
            # 4 = XA_ATOM, 32 bits, PropModeReplace = 0
            x.XChangeProperty(self.dpy, wid, atom(b"_NET_WM_STATE"), 4, 32, 0, ctypes.cast(states, ctypes.c_void_p), 3)
            x.XFlush(self.dpy)
        except Exception as e:
            print("Propriétés de fenêtre X11 :", e, file=sys.stderr)

    def apply(self, wid, rects):
        arr = (_XRect * max(1, len(rects)))(*[_XRect(int(x), int(y), max(0, int(w)), max(0, int(h)))
                                               for x, y, w, h in rects])
        # ShapeInput = 2, ShapeSet = 0, Unsorted = 0
        self.xext.XShapeCombineRectangles(self.dpy, wid, 2, 0, 0, arr, len(rects), 0, 0)
        self.xlib.XFlush(self.dpy)


_FLOU = {}


def _sa_simple(t):
    return re.sub(r"[^a-z0-9+]", "", (t or "").lower())


def flou_possible():
    """Le flou derrière les fenêtres (verre dépoli) : KDE le fait pour nous. Ailleurs (GNOME…) : transparence seule."""
    if "ok" not in _FLOU:
        _FLOU["ok"] = False
        try:
            if QApplication.platformName() == "xcb" and "KDE" in os.environ.get("XDG_CURRENT_DESKTOP", "").upper():
                x = ctypes.CDLL("libX11.so.6")
                x.XOpenDisplay.restype = ctypes.c_void_p
                x.XOpenDisplay.argtypes = [ctypes.c_char_p]
                x.XInternAtom.restype = ctypes.c_ulong
                x.XInternAtom.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_int]
                x.XChangeProperty.argtypes = [ctypes.c_void_p, ctypes.c_ulong, ctypes.c_ulong, ctypes.c_ulong,
                                              ctypes.c_int, ctypes.c_int, ctypes.c_void_p, ctypes.c_int]
                x.XFlush.argtypes = [ctypes.c_void_p]
                dpy = x.XOpenDisplay(None)
                if dpy:
                    _FLOU.update(ok=True, x=x, dpy=dpy, atom=x.XInternAtom(dpy, b"_KDE_NET_WM_BLUR_BEHIND_REGION", 0))
        except Exception:
            _FLOU["ok"] = False
    return _FLOU["ok"]


def flou_kde(w, rayon=0):
    """Demande à KDE de flouter ce qu'il y a derrière la fenêtre (coins arrondis : on évite les angles)."""
    if not flou_possible() or w is None:
        return False
    try:
        x, dpy = _FLOU["x"], _FLOU["dpy"]
        wid = int(w.winId())
        dpr = w.devicePixelRatioF()
        W, H = int(w.width() * dpr), int(w.height() * dpr)
        if rayon:
            r = int(rayon * dpr)
            vals = [0, r, W, max(0, H - 2 * r), r, 0, max(0, W - 2 * r), H]
        else:
            vals = []
        arr = (ctypes.c_long * max(1, len(vals)))(*vals) if vals else (ctypes.c_long * 1)(0)
        x.XChangeProperty(dpy, wid, _FLOU["atom"], 6, 32, 0, ctypes.cast(arr, ctypes.c_void_p), len(vals))
        x.XFlush(dpy)
        return True
    except Exception:
        return False


if menu_style:
    menu_style.flou_ok = flou_possible


def image_rects(img, step=2):
    """Rectangles (lignes) couvrant les pixels visibles d'une image."""
    im = img.convertToFormat(QImage.Format.Format_ARGB32)
    w, h, bpl = im.width(), im.height(), im.bytesPerLine()
    data = bytes(im.constBits().asstring(im.sizeInBytes()))
    rects = []
    for y in range(0, h, step):
        row = data[y * bpl: y * bpl + w * 4]
        alpha = row[3::4]
        x = 0
        while x < w:
            if alpha[x] > 10:
                x0 = x
                while x < w and alpha[x] > 10:
                    x += 1
                rects.append((x0, y, x - x0, step))
            else:
                x += 1
    return rects


