def parse_reminder(text):
    """« rappelle-moi dans 20 minutes de sortir le linge » / « … à 18h30 de … »
    -> (horodatage, texte) ou None."""
    t = text.lower().strip()
    if not re.search(r"rappel+e[- ]?moi|fais[- ]moi penser", t):
        return None
    now = datetime.datetime.now()
    when = None
    m = re.search(r"dans\s+(\d+|[a-zé]+)\s*(min|minutes?|mn|h|heures?|s|secondes?)", t)
    if m:
        n = int(m.group(1)) if m.group(1).isdigit() else _NOMBRES.get(m.group(1))
        if n:
            unit = m.group(2)
            secs = n * 3600 if unit.startswith("h") else n if unit.startswith("s") else n * 60
            when = now + datetime.timedelta(seconds=secs)
    m2 = re.search(r"(?:à|a)\s+(\d{1,2})\s*(?:h|:)\s*(\d{2})?", t)
    if not when and m2:
        hh, mm = int(m2.group(1)), int(m2.group(2) or 0)
        if hh < 24 and mm < 60:
            when = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
            if when <= now:
                when += datetime.timedelta(days=1)
    if not when:
        return None
    rest = re.sub(r".*?(rappel+e[- ]?moi|fais[- ]moi penser)", "", t, count=1)
    rest = re.sub(r"dans\s+\S+\s*(?:min|minutes?|mn|h|heures?|s|secondes?)\b", " ", rest)
    rest = re.sub(r"(?:à|a)\s+\d{1,2}\s*(?:h|:)\s*\d{0,2}", " ", rest)
    rest = re.sub(r"^\s*(?:de\b|d'|que\b|qu'|pour\b|à\b)\s*", "", rest.strip())
    what = re.sub(r"\s+", " ", rest).strip(" .!?,")
    return when.timestamp(), what or "ce que tu m'as demandé"


