_ICON_FAMILY = None


def icon_family():
    """La police des pictogrammes (chargée une fois) ; "" si elle manque."""
    global _ICON_FAMILY
    if _ICON_FAMILY is None:
        _ICON_FAMILY = ""
        try:
            from PyQt6.QtGui import QFontDatabase
            fid = QFontDatabase.addApplicationFont(str(APP_DIR / "assets" / "icones" / "tabler-icons-300.ttf"))
            fams = QFontDatabase.applicationFontFamilies(fid) if fid >= 0 else []
            _ICON_FAMILY = fams[0] if fams else ""
        except Exception:
            _ICON_FAMILY = ""
    return _ICON_FAMILY
