def _son_survol_path():
    """« Tic » très doux et très court pour le survol des menus (fabriqué ici, gardé dans le cache)."""
    import math as _m, struct as _st, wave as _wv
    p = Path(os.environ.get("XDG_CACHE_HOME", Path.home() / ".cache")) / "viki" / "survol-v1.wav"
    if p.exists():
        return p
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        sr, n = 44100, int(44100 * 0.028)
        data = bytearray()
        for i in range(n):
            t = i / sr
            env = _m.exp(-t * 160) * min(1.0, i / 30)
            v = (_m.sin(2 * _m.pi * 2100 * t) * 0.7 + _m.sin(2 * _m.pi * 4200 * t) * 0.15) * env * 0.22
            data += _st.pack("<h", int(v * 32767))
        with _wv.open(str(p), "wb") as w:
            w.setnchannels(1)
            w.setsampwidth(2)
            w.setframerate(sr)
            w.writeframes(bytes(data))
        return p
    except Exception:
        return None


class _MenusFiltre(QObject):
    """Tous les menus de Viki (même ceux des fenêtres et des sous-menus) prennent le style des ronds."""

    def __init__(self, comp):
        super().__init__(comp)
        self.comp = comp

    def _style_tard(self, m):
        st = RONDS_STYLES.get(self.comp.cfg.get("ronds_theme", "verre"))
        if st and menu_style and not m.property("style_viki"):
            try:
                menu_style.appliquer(m, st, icon_family())
                menu_style.convertir(m, st, icon_family())
            except Exception:
                pass

    def eventFilter(self, obj, ev):
        if ev.type() == QEvent.Type.Show and isinstance(obj, QMenu) and obj.property("style_viki") \
                and flou_possible():
            QTimer.singleShot(0, lambda m=obj: flou_kde(m, 14))
        if ev.type() == QEvent.Type.Polish and isinstance(obj, QMenu) and not obj.property("style_viki") \
                and not obj.property("sans_style"):
            st = RONDS_STYLES.get(self.comp.cfg.get("ronds_theme", "verre"))
            if st and menu_style:
                if getattr(themes, "EN_COURS", False):     # en plein changement de thème : plus tard, à l'ouverture
                    if not obj.property("style_plus_tard"):
                        obj.setProperty("style_plus_tard", True)
                        obj.aboutToShow.connect(lambda m=obj: self._style_tard(m))
                    return False
                try:
                    menu_style.appliquer(obj, st, icon_family())
                    menu_style.convertir(obj, st, icon_family())
                except Exception:
                    pass
        return False


def _son_clic_path():
    """Petit « toc » doux, fabriqué ici (deux sinus très courts) et gardé dans le cache."""
    import math as _m, struct as _st, wave as _wv
    p = Path(os.environ.get("XDG_CACHE_HOME", Path.home() / ".cache")) / "viki" / "clic-v1.wav"
    if p.exists():
        return p
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        sr, n = 44100, int(44100 * 0.07)
        data = bytearray()
        for i in range(n):
            t = i / sr
            env = _m.exp(-t * 70) * min(1.0, i / 40)
            v = (_m.sin(2 * _m.pi * 1250 * t) * 0.6 + _m.sin(2 * _m.pi * 2500 * t) * 0.25) * env * 0.55
            data += _st.pack("<h", int(v * 32767))
        with _wv.open(str(p), "wb") as w:
            w.setnchannels(1)
            w.setsampwidth(2)
            w.setframerate(sr)
            w.writeframes(bytes(data))
        return p
    except Exception:
        return None
