# mots qui désignent presque toujours un fichier (« trouve mon CV », « où est ma facture »)
FILE_NOUNS = (r"cv|curriculum|facture|devis|contrat|bulletin|fiche de paie|releve|attestation|certificat|"
              r"diplome|permis|passeport|carte d'?identite|impot|avis d'?imposition|quittance|ordonnance|"
              r"capture|screenshot|telechargement|telecharge|rapport|memoire|these|cours|expose|lettre|"
              r"courrier|recu|ticket|billet|plan|schema|logo|maquette|projet|sauvegarde|save|backup|"
              r"partition|playlist|wallpaper|fond d'?ecran|appimage|installeur|setup")
DATE_WORDS = {"aujourd'hui": 1, "aujourdhui": 1, "hier": 2, "cette semaine": 7, "la semaine derniere": 14,
              "ce mois": 31, "le mois dernier": 62, "recemment": 14, "recent": 14, "recents": 14}
_STOP |= set("que qui quoi ou j'ai telecharge telecharges telechargee hier aujourd'hui aujourdhui semaine mois "
             "derniere dernier derniers dernieres recemment cette ce cet ces etait parle parlant contient sujet "
             "propos a l'ai trouve-moi cherche-moi montre-moi ouvre-moi mis range garde enregistre sauve "
             "sauvegarde".split()) - {"sauvegarde"}


def parse_file_query(text):
    """« trouve ma facture edf en pdf » -> (['facture', 'edf'], {'.pdf'}, ouvrir?, dossier?)
    Gère aussi : « trouve mon CV », « le pdf que j'ai téléchargé hier », « mes dernières captures d'écran »."""
    t = _sans_accents(text)
    if not re.search(r"\b(trouve[rsz]?|retrouve[rsz]?|cherche[rsz]?|recherche[rsz]?|localise[rsz]?|ou (est|sont)|"
                     r"ou j'ai mis|ou se trouve|ouvre[rsz]?|montre[rsz]?|ou j'ai range|ou j'ai enregistre)\b", t):
        return None
    if re.search(r"\b(internet|web|en ligne|google|sur le net)\b", t):
        return None
    typed = re.search(r"\b(fichier|fichiers|dossier|document|documents|pdf|photo|photos|image|images|video|videos|"
                      r"film|films|musique|musiques|chanson|archive|zip|tableur|excel|word|texte|presentation|"
                      r"script|iso|\.[a-z0-9]{2,5})\b", t)
    owned = re.search(r"\b(mon|ma|mes)\s+(?:\w+\s+){0,2}?(?:" + FILE_NOUNS + r")s?\b", t) or \
        re.search(r"\b(?:" + FILE_NOUNS + r")s?\b", t) and re.search(r"\b(mon|ma|mes|le|la|les)\b", t) or \
        re.search(r"\b(trouve|retrouve|cherche|ou est|ou sont)\w*\s+(mon|ma|mes)\s+\w{3,}", t)
    if not (typed or owned):
        return None
    exts = set()
    for word, e in FILE_TYPES.items():
        if re.search(r"\b" + word + r"s?\b", t):
            exts |= e
    for m in re.finditer(r"(?<![\w])\.([a-z0-9]{2,5})\b", t):
        exts.add("." + m.group(1))
    if re.search(r"\b(captures? d'?ecran|screenshots?)\b", t):
        exts |= {".png", ".jpg", ".jpeg", ".webp"}
    days = next((d for w, d in DATE_WORDS.items() if re.search(r"(?<![\w'])" + re.escape(w) + r"\b", t)), 0)
    if not days and re.search(r"\b(dernier|derniere|derniers|dernieres)\b", t):
        days = -1                                         # « mon dernier pdf » : trier par date
    words = re.findall(r"[a-z0-9_\-']+", re.sub(r"(?<![\w])\.[a-z0-9]{2,5}\b", " ", t))
    words = [re.sub(r"-(moi|toi|les|le|la)$", "", w).strip("'") for w in words]
    words = [re.sub(r"^[ldjsmtnc]'", "", w) for w in words]
    special = []
    if re.search(r"\b(captures? d'?ecran|screenshots?)\b", t):
        special.append("capture|screenshot|ecran")
    if re.search(r"\btelecharge\w*\b", t):
        special.append("@telechargements")
    terms = [w for w in words if w and w not in _STOP and w not in FILE_TYPES and w.rstrip("s") not in FILE_TYPES
             and w not in ("capture", "captures", "ecran", "screenshot", "screenshots") and len(w) > 1]
    if re.search(r"\b(caches?|cachees?|invisibles?|masques?|masquees?|config|configuration|\.config|\.local)\b", t):
        special.append("@caches")
        terms = [w for w in terms if w not in ("cache", "caches", "cachee", "cachees", "invisible", "invisibles",
                                                "masque", "masques", "masquee", "masquees")]
    folder = bool(re.search(r"\bdossiers?\b", t)) and not exts
    return terms + special, exts, bool(re.match(r"\s*ouvre", t)), folder, days


def search_roots(extra=()):
    """Dossier perso + disques montés (autres partitions, disques externes) + dossiers ajoutés dans les réglages."""
    home = Path.home()
    roots = [home]
    if IS_WIN:
        import string
        for L in string.ascii_uppercase:
            d = Path(f"{L}:/")
            if d.exists() and str(d).lower() not in (str(home.anchor).lower(),):
                roots.append(d)
    else:
        sysdirs = ("/", "/boot", "/efi", "/home", "/var", "/usr", "/tmp", "/opt", "/srv", "/root", "/nix", "/snap")
        try:
            for line in Path("/proc/mounts").read_text().splitlines():
                dev, mnt, fs = line.split()[:3]
                mnt = mnt.replace("\\040", " ")
                if fs not in ("ext4", "ext3", "btrfs", "xfs", "ntfs", "ntfs3", "fuseblk", "exfat", "vfat", "f2fs",
                              "zfs", "nfs", "nfs4", "cifs"):
                    continue
                if mnt in sysdirs or mnt.startswith(("/boot", "/var", "/usr", "/snap", "/proc", "/sys", "/run/user",
                                                     "/opt", "/etc", "/dev", "/tmp", "/srv", "/root")) \
                        or str(home).startswith(mnt + "/") and mnt != "/":
                    continue
                if Path(mnt).is_dir() and os.access(mnt, os.R_OK | os.X_OK):
                    roots.append(Path(mnt))
        except Exception:
            pass
    roots += [Path(x) for x in extra if x and Path(x).is_dir()]
    out, seen = [], set()
    for r in roots:
        k = str(r.resolve()) if r.exists() else str(r)
        if k not in seen and not any(k.startswith(s + os.sep) for s in seen):
            seen.add(k)
            out.append(r)
    return out


def _singular(w):
    return w[:-1] if len(w) > 3 and w[-1] in "sx" else w


HIDDEN_SKIP = {".cache", ".git", ".npm", ".cargo", ".rustup", ".gradle", ".m2", ".nuget", ".pyenv", ".conda",
               ".venv", ".venv-voix", ".venv-piper", ".mozilla", ".thunderbird", ".wine", ".ollama", ".vscode-oss",
               ".vscode", ".nvm", ".dotnet", "Trash", "node_modules", "__pycache__", "site-packages", "dosdevices",
               "drive_c", "compatdata", "shadercache", "GPUCache", "Code Cache", "Cache", "CacheStorage",
               "IndexedDB", "Service Worker", "baloo", "flatpak", "containers", "docker", "akonadi"}


def search_files(terms, exts, folder=False, limit=60, budget=10.0, days=0, extra_roots=(), hidden=None):
    """hidden=None : d'abord les dossiers normaux, puis les dossiers cachés (.config, .local/share…) si rien trouvé.
    hidden=True : inclut tout de suite les dossiers cachés."""
    if "@caches" in terms:
        terms = [t for t in terms if t != "@caches"]
        hidden = True
    if hidden is None:
        res = search_files(terms, exts, folder, limit, budget * 0.6, days, extra_roots, hidden=False)
        if len(res) >= 3 or not [t for t in terms if not t.startswith("@") and "|" not in t]:
            return res
        more = search_files(terms, exts, folder, limit, budget * 0.6, days, extra_roots, hidden=True)
        return res + [x for x in more if x not in res][:limit - len(res)]
    return _search_files(terms, exts, folder, limit, budget, days, extra_roots, hidden)


def _search_files(terms, exts, folder, limit, budget, days, extra_roots, hidden):
    """Cherche partout où tu as tes fichiers : index de KDE (Baloo), fd, locate, puis parcours direct.
    Tolère pluriels, accents, fautes légères ; filtre par date (« hier », « cette semaine », « dernier »)."""
    import difflib
    home = Path.home()
    roots = search_roots(extra_roots)
    rootstr = [str(r) for r in roots]
    downloads = {_sans_accents(n) for n in ("Téléchargements", "Downloads")}
    want_dl = "@telechargements" in terms
    regex_terms = [t for t in terms if "|" in t]
    plain = [t for t in terms if not t.startswith("@") and "|" not in t]
    stems = [_singular(t) for t in plain]
    since = time.time() - days * 86400 if days > 0 else 0
    found = {}

    def accept(path):
        p = Path(path)
        sp = str(p)
        if not any(sp == r or sp.startswith(r.rstrip(os.sep) + os.sep) for r in rootstr):
            return
        if not hidden and any(part.startswith(".") for part in p.parts[1:]):
            return
        if hidden and any(part in HIDDEN_SKIP for part in p.parts[1:]):
            return
        if folder and not p.is_dir():
            return
        if not folder and p.is_dir():
            return
        if exts and p.suffix.lower() not in exts:
            return
        name = _sans_accents(p.stem)
        full = _sans_accents(sp)
        if want_dl and not any(d in full for d in downloads):
            return
        if regex_terms and not all(re.search(rt, full) for rt in regex_terms):
            return
        hits = sum(1 for s in stems if s in full)
        fuzzy = 0
        if stems and hits < len(stems):
            toks = re.findall(r"[a-z0-9]+", name)
            for s in stems:
                if s not in full and len(s) >= 4 and difflib.get_close_matches(s, toks, n=1, cutoff=0.8):
                    fuzzy += 1
        if stems and hits + fuzzy < max(1, (len(stems) + 1) // 2):
            return                                        # au moins la moitié des mots (ou proches)
        try:
            st = p.stat()
        except OSError:
            return
        if since and st.st_mtime < since:
            return
        score = 3 * hits + 2 * fuzzy + sum(2 for s in stems if s in name) + (5 if hits == len(stems) else 0)
        if any(seg in full for seg in ("/documents/", "/bureau/", "/desktop/", "/telechargements/", "/downloads/",
                                       "/images/", "/pictures/")):
            score += 1
        found[sp] = (score, st.st_mtime)

    query = " ".join(plain)
    t_end = time.monotonic() + budget
    if shutil.which("baloosearch") and query:
        try:
            out = subprocess.run(["baloosearch", "-l", "400", query], capture_output=True, text=True,
                                 timeout=6).stdout
            for line in out.splitlines():
                accept(line.strip())
        except Exception:
            pass
    fd = shutil.which("fd") or shutil.which("fdfind")
    key = max(stems, key=len) if stems else ""
    if fd and (key or exts):
        cmd = [fd, "-i", "-a", "--type", "d" if folder else "f", "--max-results", "3000"]
        if hidden:
            cmd += ["-H", "--no-ignore"] + [x for s in HIDDEN_SKIP for x in ("-E", s)]
        for e in list(exts)[:12]:
            cmd += ["-e", e.lstrip(".")]
        cmd += [re.escape(key) if key else "."] + rootstr
        try:
            out = subprocess.run(cmd, capture_output=True, text=True, timeout=12).stdout
            for line in out.splitlines():
                accept(line.strip())
        except Exception:
            pass
    loc = shutil.which("plocate") or shutil.which("locate")
    if loc and key and len(found) < 10:
        try:
            out = subprocess.run([loc, "-i", "-l", "5000", key], capture_output=True, text=True, timeout=6).stdout
            for line in out.splitlines():
                accept(line.strip())
        except Exception:
            pass
    if len(found) < 8 and time.monotonic() < t_end:          # parcours direct, les dossiers utiles d'abord
        skip = {"node_modules", "__pycache__", ".git", ".cache", ".local", ".venv", ".venv-voix",
                ".venv-piper", "venv", ".steam", ".var", "Trash", "AppData", "Application Data",
                "Local Settings", "$Recycle.Bin", "System Volume Information", "steamapps", "proton", "Windows",
                "Program Files", "Program Files (x86)", "ProgramData", "lost+found", "target", "build", "dist"}
        first = [home / n for n in ("Bureau", "Desktop", "Documents", "Téléchargements", "Downloads", "Images",
                                    "Pictures", "Vidéos", "Videos", "Musique", "Music") if (home / n).is_dir()]
        if hidden:
            first = [home / n for n in (".config", ".local/share", ".local/state", ".var/app", ".steam/steam/userdata")
                     if (home / n).is_dir()] + first
        for start in first + roots:
            for root, dirs, files in os.walk(start):
                if hidden:
                    dirs[:] = [d for d in dirs if d not in HIDDEN_SKIP and d not in skip - {".local"}]
                else:
                    dirs[:] = [d for d in dirs if not d.startswith(".") and d not in skip]
                for f in (dirs if folder else files):
                    accept(os.path.join(root, f))
                if time.monotonic() > t_end:
                    break
            if time.monotonic() > t_end:
                break
    if days == -1 or (not stems and since):
        res = sorted(found.items(), key=lambda kv: -kv[1][1])          # le plus récent d'abord
    else:
        res = sorted(found.items(), key=lambda kv: (-kv[1][0], -kv[1][1]))
    return [p for p, _ in res[:limit]]


def parse_web_query(text):
    """« cherche sur internet la météo de demain » -> ('recherche', 'la météo de demain')
       « ouvre youtube » / « va sur wikipedia.org » -> ('site', url)"""
    t = text.strip()
    tl = _sans_accents(t)
    m = re.match(r"^\s*(?:ouvre|va sur|affiche)\s+(?:le site\s+)?((?:https?://)?[\w\-]+(?:\.[\w\-]+)+(?:/\S*)?)\s*$",
                 t, re.I)
    if m:
        url = m.group(1)
        return ("site", url if url.startswith("http") else "https://" + url)
    sites = {"youtube": "https://www.youtube.com", "wikipedia": "https://fr.wikipedia.org",
             "google": "https://www.google.com", "gmail": "https://mail.google.com", "twitch": "https://www.twitch.tv",
             "reddit": "https://www.reddit.com", "github": "https://github.com", "netflix": "https://www.netflix.com",
             "amazon": "https://www.amazon.fr", "deepl": "https://www.deepl.com/translator"}
    m = re.match(r"^\s*(?:ouvre|va sur|lance)\s+(\w+)\s*$", tl)
    if m and m.group(1) in sites:
        return ("site", sites[m.group(1)])
    web = re.search(r"\b(internet|le web|sur le net|google|en ligne|duckduckgo|recherche web)\b", tl)
    verbe = re.search(r"\b(cherch|recherch|regard|trouv|googl|renseign|infos?\b|informations?\b|"
                      r"c'est quoi|qu'est[- ]ce|qui est|quel|quelle|combien|actualit|news)", tl)
    if re.search(r"\b(acces|accede|acceder|connecte|connectee|connexion|branche)\b", tl) or \
            re.search(r"\b(tu (as|a|peux|sais|vas)|peux[- ]tu|sais[- ]tu)\b.*\b(aller|utiliser|naviguer)\b", tl):
        return None                            # « tu as accès à internet ? » : c'est une question, pas une recherche
    if web and verbe:
        q = t
        # on retire la demande (« tu peux chercher sur internet… ») pour garder le sujet
        q = re.sub(r"(?i)\b(?:est[- ]ce que\s+)?(?:tu\s+)?(?:peux|pourrais|pourras|veux|sais)[- ]?(?:tu\s+)?\b", " ", q)
        q = re.sub(r"(?i)\b(?:me\s+|moi\s+)?(?:re)?(?:cherch|regard|trouv|googl|renseign)\w*(?:[- ]moi)?\b", " ", q)
        q = re.sub(r"(?i)\b(?:sur|dans|via|avec|en)\s+(?:internet|le web|le net|google|duckduckgo|ligne)\b", " ", q)
        q = re.sub(r"(?i)\b(?:internet|recherche web|stp|s'il te pla[iî]t|svp|vite|un peu|pour moi)\b", " ", q)
        q = re.sub(r"(?i)^\W*(?:et\s+|alors\s+|dis\s+|hey\s+)?(?:des infos|des informations|ce que dit)\s+(?:sur|de)\s+", "", q)
        q = re.sub(r"(?i)^\W*(?:sur|de|des|du|la|le|les|:)\s+", "", q.strip())
        q = re.sub(r"\s+", " ", q).strip(" ?!.,:;")
        vides = {"deja", "si", "oui", "non", "la", "le", "les", "un", "une", "des", "de", "du", "et", "ou", "a", "en",
                 "ca", "ce", "cela", "moi", "toi", "il", "elle", "est", "c", "quoi", "tu", "je", "me", "te", "y",
                 "pas", "plus", "bien", "aussi", "encore", "truc", "chose", "quelque"}
        mots = [m for m in re.findall(r"[a-z0-9]+", _sans_accents(q)) if m not in vides and len(m) > 1]
        if mots:
            return ("recherche", q)
    return None


WEB_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) "
          "Chrome/124.0 Safari/537.36")


def web_search(query, n=6):
    """Recherche DuckDuckGo (sans compte). Essaie plusieurs versions du site.
    Renvoie [(titre, url, extrait)] ; une liste vide = rien de lisible (on ouvrira le navigateur)."""
    from urllib.parse import quote, urlencode
    tries = [
        ("https://html.duckduckgo.com/html/", urlencode({"q": query, "kl": "fr-fr"}).encode()),   # POST
        ("https://html.duckduckgo.com/html/?kl=fr-fr&q=" + quote(query), None),
        ("https://lite.duckduckgo.com/lite/?kl=fr-fr&q=" + quote(query), None),
    ]
    last = None
    for url, data in tries:
        try:
            req = urllib.request.Request(url, data=data, headers={
                "User-Agent": WEB_UA, "Accept-Language": "fr-FR,fr;q=0.9",
                "Content-Type": "application/x-www-form-urlencoded"} if data else {
                "User-Agent": WEB_UA, "Accept-Language": "fr-FR,fr;q=0.9"})
            with urllib.request.urlopen(req, timeout=12) as r:
                page = r.read().decode("utf-8", errors="ignore")
            res = parse_ddg(page, n) or parse_links(page, n)
            if res:
                return res
        except Exception as e:
            last = e
    if last and not isinstance(last, urllib.error.HTTPError):
        raise last
    return []


def parse_links(page, n=6):
    """Lecture de secours : tous les liens externes de la page de résultats (version « lite »)."""
    from html import unescape
    from urllib.parse import parse_qs, unquote, urlparse
    out, seen = [], set()
    for m in re.finditer(r'<a[^>]+href=["\']([^"\']+)["\'][^>]*>(.*?)</a>', page, re.S):
        href = unescape(m.group(1))
        if "uddg=" in href:
            href = unquote(parse_qs(urlparse(href).query).get("uddg", [href])[0])
        if href.startswith("//"):
            href = "https:" + href
        if not href.startswith("http") or "duckduckgo.com" in href or href in seen:
            continue
        title = unescape(re.sub(r"<[^>]+>", "", m.group(2))).strip()
        if len(title) < 3:
            continue
        seen.add(href)
        sn = ""
        tail = page[m.end():m.end() + 1500]
        s2 = re.search(r"class=['\"]result-snippet['\"][^>]*>(.*?)</td>", tail, re.S)
        if s2:
            sn = unescape(re.sub(r"<[^>]+>", "", s2.group(1))).strip()
        out.append((title, href, sn))
        if len(out) >= n:
            break
    return out


def parse_ddg(page, n=6):
    from html import unescape
    from urllib.parse import parse_qs, unquote, urlparse
    out = []
    blocks = re.split(r'<div[^>]+class="[^"]*result[ _]', page)
    for b in blocks:
        a = re.search(r'<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>(.*?)</a>', b, re.S)
        if not a:
            continue
        href = unescape(a.group(1))
        if "uddg=" in href:
            href = unquote(parse_qs(urlparse(href).query).get("uddg", [href])[0])
        if href.startswith("//"):
            href = "https:" + href
        if "duckduckgo.com/y.js" in href or not href.startswith("http"):
            continue                                            # publicités
        title = unescape(re.sub(r"<[^>]+>", "", a.group(2))).strip()
        sn = re.search(r'class="result__snippet"[^>]*>(.*?)</a>', b, re.S)
        snippet = unescape(re.sub(r"<[^>]+>", "", sn.group(1))).strip() if sn else ""
        out.append((title, href, snippet))
        if len(out) >= n:
            break
    return out


class PullWindow(QWidget):
    """Progression du téléchargement d'un modèle Ollama."""
    cancel = pyqtSignal()

    def __init__(self, comp, name):
        super().__init__(None, Qt.WindowType.Window)
        from PyQt6.QtWidgets import QProgressBar
        self.setWindowTitle(f"📥 Téléchargement — {name}")
        self.setStyleSheet("QWidget { background: #fffafc; color: #3d2733; font-size: 13px; }"
                           "QPushButton { background: #fff; border: 1px solid #e7cfdb; border-radius: 9px; "
                           "padding: 6px 14px; } QProgressBar { border: 1px solid #f1dfe8; border-radius: 7px; "
                           "background: #fff; text-align: center; height: 22px; } "
                           "QProgressBar::chunk { background: #e889b0; border-radius: 7px; }")
        self.resize(460, 170)
        lay = QVBoxLayout(self)
        t = QLabel(f"<b>{name}</b> — téléchargé dans Ollama, sur ton PC")
        lay.addWidget(t)
        self.bar = QProgressBar()
        self.bar.setRange(0, 0)                     # « en cours » tant qu'on ne connaît pas la taille
        lay.addWidget(self.bar)
        self.info = QLabel("Connexion à Ollama…")
        self.info.setStyleSheet("color: #8d7482;")
        lay.addWidget(self.info)
        row = QHBoxLayout()
        row.addStretch(1)
        self.btn = QPushButton("Annuler")
        self.btn.clicked.connect(self._cancel)
        row.addWidget(self.btn)
        lay.addLayout(row)
        self.done = False

    @staticmethod
    def _go(n):
        return f"{n / 1e9:.2f} Go" if n >= 1e9 else f"{n / 1e6:.0f} Mo"

    def update_progress(self, data):
        status, done, total, speed = data
        if total:
            self.bar.setRange(0, 1000)
            self.bar.setValue(int(1000 * done / total))
            self.bar.setFormat(f"{100 * done / total:.0f} %")
            eta = (total - done) / speed if speed > 1e5 else 0
            self.info.setText(f"{self._go(done)} / {self._go(total)}"
                              + (f" — {speed / 1e6:.1f} Mo/s" if speed > 1e5 else "")
                              + (f" — encore {int(eta // 60)} min {int(eta % 60):02d} s" if eta else ""))
        else:
            self.info.setText({"pulling manifest": "Préparation…", "verifying sha256 digest": "Vérification…",
                               "writing manifest": "Finalisation…", "success": "Terminé !"}.get(status, status or "…"))

    def finish(self, ok, msg=""):
        self.done = True
        self.bar.setRange(0, 1000)
        self.bar.setValue(1000 if ok else self.bar.value())
        self.bar.setFormat("Terminé ✓" if ok else "Arrêté")
        self.info.setText("✅ Le modèle est prêt." if ok else ("❌ " + msg if msg else "Arrêté."))
        self.btn.setText("Fermer")
        if ok:
            QTimer.singleShot(4000, self.close)

    def _cancel(self):
        if self.done:
            return self.close()
        self.btn.setEnabled(False)
        self.info.setText("Arrêt…")
        self.cancel.emit()

    def closeEvent(self, e):
        if not self.done:                            # fermer la fenêtre n'arrête pas le téléchargement
            self.hide()
            e.ignore()
            return
        super().closeEvent(e)


class MailWindow(QWidget):
    """Les mails non lus : lire à voix haute, résumer, marquer comme lu, ouvrir le webmail."""

    def __init__(self, comp, items):
        super().__init__(None, Qt.WindowType.Window)
        self.comp = comp
        self.items = list(items)
        self.setWindowTitle("📧 Mails non lus — " + comp.char.get("name", "Viki"))
        self.resize(720, 500)
        lay = QVBoxLayout(self)
        from PyQt6.QtWidgets import QListWidget, QSplitter, QTextEdit
        sp = QSplitter(Qt.Orientation.Vertical)
        self.list = QListWidget()
        self.view = QTextEdit()
        self.view.setReadOnly(True)
        sp.addWidget(self.list)
        sp.addWidget(self.view)
        sp.setSizes([200, 300])
        lay.addWidget(sp)
        row = QHBoxLayout()
        for lab, fn in (("🔊 Lire", self.read), ("📝 Résumer tout", self.summary),
                        ("✓ Marquer comme lu", self.mark), ("🌐 Webmail", self.webmail),
                        ("🔄 Actualiser", self.refresh)):
            b = QPushButton(lab)
            b.clicked.connect(fn)
            row.addWidget(b)
        lay.addLayout(row)
        self.list.currentRowChanged.connect(self.show_mail)
        self.fill()

    def fill(self):
        self.list.clear()
        for m in self.items:
            self.list.addItem(f"{m['de']}  —  {m['sujet']}   ({m.get('date', '')})")
        if self.items:
            self.list.setCurrentRow(0)
        else:
            self.view.setPlainText("Aucun mail non lu 🎉")

    def cur(self):
        i = self.list.currentRow()
        return self.items[i] if 0 <= i < len(self.items) else None

    def show_mail(self, i):
        m = self.cur()
        if m:
            self.view.setPlainText(f"De : {m['de']} <{m.get('adresse', '')}>\nSujet : {m['sujet']}\n"
                                   f"Date : {m.get('date', '')}\n\n{m.get('texte') or '(pas de texte)'}")

    def read(self):
        m = self.cur()
        if m:
            self.comp.mail_read(m)

    def summary(self):
        if self.items:
            self.comp.mail_summary(self.items)

    def mark(self):
        m = self.cur()
        if not m:
            return
        s = mails.load()
        i = self.list.currentRow()
        self.comp._bg(lambda: mails.mark_read(s, m["uid"]),
                      lambda r: (self.items.pop(i), self.fill()) if not isinstance(r, Exception)
                      else self.comp.say("Je n'ai pas pu le marquer comme lu : " + mails.explain(r)))

    def webmail(self):
        s = mails.load()
        url = mails.FOURNISSEURS.get(s.get("fournisseur", ""), (None,) * 6)[5]
        if url:
            from PyQt6.QtGui import QDesktopServices
            from PyQt6.QtCore import QUrl
            QDesktopServices.openUrl(QUrl(url))

    def refresh(self):
        s = mails.load()
        self.view.setPlainText("Je regarde…")

        def done(r):
            if isinstance(r, Exception):
                return self.view.setPlainText("Erreur : " + mails.explain(r))
            self.items = r
            self.fill()
        self.comp._bg(lambda: mails.unread(s, limit=25, body=True), done)


class ResultsWindow(QWidget):
    """Résultats (fichiers ou web) : double-clic pour ouvrir."""

    def __init__(self, comp):
        super().__init__(None, Qt.WindowType.Window)
        self.comp = comp
        self.resize(640, 460)
        lay = QVBoxLayout(self)
        self.summary = QLabel()
        self.summary.setWordWrap(True)
        self.summary.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
        self.summary.setStyleSheet("background: #fde7ef; border-radius: 8px; padding: 8px;")
        lay.addWidget(self.summary)
        self.list = QListWidget()
        self.list.itemDoubleClicked.connect(lambda it: self._open())
        lay.addWidget(self.list, 1)
        row = QHBoxLayout()
        self.b_open = QPushButton("Ouvrir")
        self.b_folder = QPushButton("Ouvrir le dossier")
        self.b_copy = QPushButton("Copier le chemin")
        close = QPushButton("Fermer")
        self.b_open.clicked.connect(self._open)
        self.b_folder.clicked.connect(self._folder)
        self.b_copy.clicked.connect(lambda: self.list.currentItem() and QApplication.clipboard().setText(
            self.list.currentItem().data(Qt.ItemDataRole.UserRole)))
        close.clicked.connect(self.close)
        for b in (self.b_open, self.b_folder, self.b_copy):
            row.addWidget(b)
        row.addStretch()
        row.addWidget(close)
        lay.addLayout(row)
        self.mode = "fichiers"

    def show_files(self, query, paths):
        self.mode = "fichiers"
        self.setWindowTitle(f"Fichiers trouvés : {query}")
        self.summary.setText(f"{len(paths)} résultat(s) pour « {query} ». Double-clic pour ouvrir."
                             if paths else f"Rien trouvé pour « {query} » (dossier perso et disques montés).")
        self.list.clear()
        from PyQt6.QtWidgets import QFileIconProvider
        from PyQt6.QtCore import QFileInfo
        icons = QFileIconProvider()
        home = str(Path.home())
        for pth in paths:
            p = Path(pth)
            try:
                when = datetime.datetime.fromtimestamp(p.stat().st_mtime).strftime("%d/%m/%Y")
            except OSError:
                when = ""
            it = QListWidgetItem(icons.icon(QFileInfo(pth)), f"{p.name}\n    {str(p.parent).replace(home, '~')}   ·   {when}")
            it.setData(Qt.ItemDataRole.UserRole, pth)
            self.list.addItem(it)
        if paths:
            self.list.setCurrentRow(0)
        self.b_folder.setText("Ouvrir le dossier")
        self.b_copy.setText("Copier le chemin")
        self._show()

    def show_web(self, query, results, summary):
        self.mode = "web"
        self.setWindowTitle(f"Recherche web : {query}")
        self.summary.setText(summary or (f"{len(results)} résultat(s) pour « {query} ». Double-clic pour ouvrir."
                                         if results else f"Aucun résultat pour « {query} »."))
        self.list.clear()
        for title, url, snip in results:
            it = QListWidgetItem(f"{title}\n    {url}\n    {snip[:160]}")
            it.setData(Qt.ItemDataRole.UserRole, url)
            it.setToolTip(snip)
            self.list.addItem(it)
        if results:
            self.list.setCurrentRow(0)
        self.b_folder.setText("Ouvrir la recherche complète")
        self.b_copy.setText("Copier le lien")
        self.query = query
        self._show()

    def _show(self):
        self.show()
        self.raise_()
        self.activateWindow()

    def _open(self):
        it = self.list.currentItem()
        if it:
            subprocess.Popen(["xdg-open", it.data(Qt.ItemDataRole.UserRole)], stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL, start_new_session=True)

    def _folder(self):
        if self.mode == "web":
            from urllib.parse import quote
            subprocess.Popen(["xdg-open", "https://duckduckgo.com/?q=" + quote(getattr(self, "query", ""))],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
            return
        it = self.list.currentItem()
        if not it:
            return
        pth = it.data(Qt.ItemDataRole.UserRole)
        if shutil.which("dolphin"):
            subprocess.Popen(["dolphin", "--select", pth], stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL, start_new_session=True)
        else:
            subprocess.Popen(["xdg-open", str(Path(pth).parent)], stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL, start_new_session=True)


class ChatWindow(QWidget):
    """Fenêtre de discussion (Ollama, en local)."""

    def __init__(self, comp):
        super().__init__(None, Qt.WindowType.Window)
        self.comp = comp
        self.resize(440, 560)
        lay = QVBoxLayout(self)
        self.view = QTextBrowser()
        self.view.setOpenExternalLinks(False)
        lay.addWidget(self.view, 1)
        self.status = QLabel()
        self.status.setStyleSheet("color: gray;")
        lay.addWidget(self.status)
        row = QHBoxLayout()
        self.input = QLineEdit()
        self.input.setPlaceholderText("Écris ton message puis Entrée…")
        self.send_btn = QPushButton("Envoyer")
        row.addWidget(self.input, 1)
        row.addWidget(self.send_btn)
        lay.addLayout(row)
        self.retry = QPushButton("Réessayer de trouver Ollama")
        lay.addWidget(self.retry)
        self.models_btn = QPushButton("Installer / choisir un modèle…")
        self.models_btn.clicked.connect(self.comp.open_models)
        lay.addWidget(self.models_btn)
        self.input.returnPressed.connect(self.submit)
        self.send_btn.clicked.connect(self.submit)
        self.retry.clicked.connect(self.comp.recheck_ollama)
        self.waiting = False
        self.reload()

    def reload(self):
        name = self.comp.char.get("name", "Viki")
        self.setWindowTitle(f"Discuter avec {name}")
        self.view.clear()
        hist = self.comp.chat_history or self.comp.memory.get("historique", [])
        for m in hist[-12:]:
            self.add("toi" if m["role"] == "user" else "elle", m["content"])
        self.refresh()

    def refresh(self):
        ok = self.comp.ollama_ok
        self.input.setEnabled(ok and not self.waiting)
        self.send_btn.setEnabled(ok and not self.waiting)
        self.retry.setVisible(not ok)
        if ok:
            self.status.setText(f"Cerveau : {self.comp.ia_name()}" + (" — en ligne" if self.comp.ia_remote()
                                                                         else " — tout reste sur ton PC"))
            if not self.waiting:
                self.input.setFocus()
        elif self.comp.ia_remote():
            running = True
            self.status.setText("IA en ligne choisie, mais il manque la clé ou le modèle : "
                                "Réglages → Discussion.")
        else:
            running = getattr(self.comp, "ollama_running", False)
            self.status.setText("Ollama est lancé mais aucun modèle n'est installé : clique sur "
                                "« Installer / choisir un modèle… »." if running
                                else "Ollama n'est pas lancé ou pas installé.")
            if self.view.toPlainText().strip() == "" and not running:
                self.view.setHtml(
                    "<p><b>Pour discuter avec elle, il faut Ollama</b> (un modèle de langage qui tourne "
                    "sur ton PC, rien n'est envoyé sur internet).</p>"
                    "<p>Clique sur « Installer / choisir un modèle… » : elle l'installe toute seule.</p>"
                    "<p>Ou, si tu préfères, branche une IA en ligne (ChatGPT, Claude, Gemini…) "
                    "dans Réglages → Discussion.</p>")

    def add(self, who, text):
        from html import escape
        name = escape(self.comp.char.get("name", "Elle"))
        if who == "toi":
            html = (f'<p align="right"><span style="background:#dbeafe; padding:4px;">'
                    f'{escape(text)}</span></p>')
        else:
            html = (f'<p align="left"><b style="color:#b0305a;">{name} :</b> '
                    f'<span style="background:#fde7ef; padding:4px;">{escape(text)}</span></p>')
        self.view.append(html)
        self.view.verticalScrollBar().setValue(self.view.verticalScrollBar().maximum())

    def submit(self):
        text = self.input.text().strip()
        if not text or self.waiting:
            return
        self.input.clear()
        self.add("toi", text)
        self.waiting = True
        self.status.setText(f"{self.comp.char.get('name', 'Elle')} réfléchit…")
        self.refresh()
        self.comp.send_chat(text)

    def on_answer(self, text):
        self.waiting = False
        self.add("elle", text)
        self.refresh()


class PhrasesDialog(QDialog):
    def __init__(self, phrases, name):
        super().__init__()
        self.setWindowTitle(f"Phrases de {name}")
        self.resize(560, 420)
        lay = QVBoxLayout(self)
        lay.addWidget(QLabel("Une phrase par ligne. Elle en choisit une au hasard.\n"
                             "{heure} est remplacé par l'heure, {nom} par son nom."))
        self.tabs = QTabWidget()
        self.edits = {}
        for key, label in PHRASE_TABS:
            ed = QPlainTextEdit("\n".join(phrases.get(key, [])))
            self.edits[key] = ed
            self.tabs.addTab(ed, label)
        lay.addWidget(self.tabs)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Save
                              | QDialogButtonBox.StandardButton.Cancel
                              | QDialogButtonBox.StandardButton.RestoreDefaults)
        bb.button(QDialogButtonBox.StandardButton.Save).setText("Enregistrer")
        bb.button(QDialogButtonBox.StandardButton.Cancel).setText("Annuler")
        bb.accepted.connect(self.accept)
        bb.rejected.connect(self.reject)
        bb.button(QDialogButtonBox.StandardButton.RestoreDefaults).setText("Rétablir l'onglet par défaut")
        bb.button(QDialogButtonBox.StandardButton.RestoreDefaults).clicked.connect(self._restore)
        lay.addWidget(bb)

    def _restore(self):
        key = PHRASE_TABS[self.tabs.currentIndex()][0]
        self.edits[key].setPlainText("\n".join(DEFAULT_PHRASES[key]))

    def result_data(self):
        out = {}
        for key, ed in self.edits.items():
            lines = [l.strip() for l in ed.toPlainText().splitlines() if l.strip()]
            out[key] = lines or list(DEFAULT_PHRASES[key])
        return out


# ---------------------------------------------------------------- fenêtre
class MenuCatcher(QWidget):
    """Fenêtre invisible posée sous un menu, sur tout l'écran : un clic dans le vide ferme le menu.
    Viki ne prend jamais le focus (et sous X11 elle est hors du gestionnaire de fenêtres) : sur certains
    systèmes le menu ne « voyait » donc pas les clics à côté, et seul Échap le fermait."""

    def __init__(self):
        f = (Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint | Qt.WindowType.Tool
             | Qt.WindowType.WindowDoesNotAcceptFocus)
        if QApplication.platformName() == "xcb":
            f |= Qt.WindowType.X11BypassWindowManagerHint
        super().__init__(None, f)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating)
        self.menus = []

    def arm(self, menu):
        if not menu.property("viki_catcher"):
            menu.setProperty("viki_catcher", True)
            menu.aboutToHide.connect(lambda m=menu: QTimer.singleShot(0, lambda: self._closed(m)))
        if menu not in self.menus:
            self.menus.append(menu)
        try:
            self.setGeometry(QApplication.primaryScreen().virtualGeometry())
        except Exception:
            return
        self.show()
        self.raise_()

    def _closed(self, menu):
        self.menus = [m for m in self.menus if m is not menu and m.isVisible()]
        if not self.menus:
            self.hide()

    def paintEvent(self, e):
        p = QPainter(self)
        p.fillRect(self.rect(), QColor(0, 0, 0, 1))       # presque invisible, mais reçoit les clics
        p.end()

    def _close_all(self):
        for m in list(self.menus):
            try:
                m.close()
            except RuntimeError:
                pass
        self.menus = []
        self.hide()

    def mousePressEvent(self, e):
        self._close_all()

    def wheelEvent(self, e):
        self._close_all()


