    # ---------- musique (MPRIS via playerctl, local)
    def _music_loop(self):
        pc = shutil.which("playerctl")
        if not pc:
            return
        while True:
            try:
                st = subprocess.run([pc, "status"], capture_output=True, text=True, timeout=3).stdout.strip()
                playing = st == "Playing"
                title = ""
                if playing:
                    title = subprocess.run([pc, "metadata", "title"], capture_output=True,
                                           text=True, timeout=3).stdout.strip()
                if playing and title and title != self.music_title and self.cfg.get("music_dance", True):
                    self.music_title = title
                    self.bridge.music_started.emit()
                self.music_playing = playing
            except Exception:
                pass
            time.sleep(3)

    def _on_music_started(self):
        self._auto_outfit()                           # tenue « musique »
        if random.random() < 0.4 and not self.bubble_text and not self._talking(time.monotonic()):
            self.say_from("musique")

    # ---------- batterie
    def _check_battery(self):
        try:
            for bat in Path("/sys/class/power_supply").glob("BAT*"):
                cap = int((bat / "capacity").read_text().strip())
                status = (bat / "status").read_text().strip()
                if status == "Discharging" and cap <= 15 and not self.battery_warned:
                    self.battery_warned = True
                    self.surprise_until = time.monotonic() + 1
                    self._spawn("exclam", 1, 0.3)
                    self.say_from("batterie")
                elif status != "Discharging":
                    self.battery_warned = False
        except Exception:
            pass

    # ---------- minuteur Pomodoro
    def start_pomodoro(self, minutes=25, mode="travail"):
        self.pomodoro = (mode, time.monotonic() + minutes * 60)
        self.pomo_len, self.pomo_said = minutes * 60, set()
        self.say(f"C'est parti pour {minutes} minutes de {mode} ! Je te préviens à la fin.")
        if mode == "travail":
            self._pomo_music(True)
        self._rebuild_menus()

    def stop_pomodoro(self):
        self.pomodoro = None
        self.say("Minuteur arrêté.")
        self._rebuild_menus()

    def _check_pomodoro(self):
        if not self.pomodoro:
            if self.tray:
                self.tray.setToolTip(self.char.get("name", "Viki"))
            return
        mode, end = self.pomodoro
        left = end - time.monotonic()
        if self.tray:
            self.tray.setToolTip(f"{self.char.get('name', 'Viki')} — {mode} : {max(0, int(left // 60))} min")
        if mode == "travail" and 0 < left and self.pomo_len >= 15 * 60:
            for key, when, txt in (("mi", self.pomo_len / 2, "Courage, tu es à mi-parcours ! Tu t'en sors très bien."),
                                   ("fin5", 5 * 60, "Plus que 5 minutes, on lâche rien !")):
                if left <= when and key not in self.pomo_said:
                    self.pomo_said.add(key)
                    if not self.bubble_text:
                        self.happy_until = time.monotonic() + 1.2
                        self.say(txt)
        if left <= 0:
            self.sleeping = False
            self.hop_start = time.monotonic()
            self._spawn("etoile", 3)
            if mode == "travail":
                st = self.cfg.setdefault("stats", {})
                st["pomodoros"] = st.get("pomodoros", 0) + 1
                self.say_from("pomodoro_fin")
                self.pomodoro = ("pause", time.monotonic() + 5 * 60)
                self._pomo_music(False)
                QTimer.singleShot(25000, self.do_ritual)
            else:
                self.say_from("pause_fin")
                self.pomodoro = None
            self._rebuild_menus()

    # ---------- mémoire (locale)
    def _load_memory(self):
        try:
            return json.loads(MEMORY_FILE.read_text())
        except Exception:
            return {"faits": [], "historique": []}

    def _save_memory(self):
        try:
            CONFIG_DIR.mkdir(parents=True, exist_ok=True)
            MEMORY_FILE.write_text(json.dumps(self.memory, indent=2, ensure_ascii=False))
        except Exception as e:
            print("Mémoire :", e, file=sys.stderr)

    def ask_name(self):
        name, ok = QInputDialog.getText(None, self.char.get("name", "Viki"),
                                        "Comment tu t'appelles ?", text=self.cfg.get("prenom", ""))
        if ok:
            self.cfg["prenom"] = name.strip()
            save_config(self.cfg)
            if name.strip():
                self.happy_until = time.monotonic() + 1.5
                self.say(f"Enchantée, {name.strip()} ! Je vais m'en souvenir.")

    def edit_memory(self):
        dlg = QDialog()
        dlg.setWindowTitle(f"Ce dont {self.char.get('name', 'elle')} se souvient")
        dlg.resize(520, 380)
        lay = QVBoxLayout(dlg)
        lay.addWidget(QLabel("Un souvenir par ligne. Tout est stocké uniquement sur ton PC\n"
                             f"({MEMORY_FILE})."))
        ed = QPlainTextEdit("\n".join(self.memory.get("faits", [])))
        lay.addWidget(ed)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        bb.button(QDialogButtonBox.StandardButton.Save).setText("Enregistrer")
        bb.button(QDialogButtonBox.StandardButton.Cancel).setText("Annuler")
        forget = bb.addButton("Tout oublier", QDialogButtonBox.ButtonRole.ResetRole)
        forget.clicked.connect(lambda: ed.setPlainText(""))
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)
        lay.addWidget(bb)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            self.memory["faits"] = [l.strip() for l in ed.toPlainText().splitlines() if l.strip()]
            if not self.memory["faits"]:
                self.memory["historique"] = []
                self.chat_history = []
            self._save_memory()

    def _extract_facts(self, text):
        """Demande au modèle local ce qu'il faut retenir du message (prénom, goûts…)."""
        prompt = ("Voici un message de l'utilisateur. Liste uniquement les informations durables "
                  "à retenir sur lui (prénom, goûts, métier, projets, animaux…), en phrases très "
                  "courtes à la 3e personne. Réponds en JSON : {\"faits\": [...]} (liste vide sinon).\n\n"
                  f"Message : {text}")
        try:
            facts = self.llm_json([{"role": "user", "content": prompt}]).get("faits", [])
            known = {f.lower() for f in self.memory.get("faits", [])}
            for f in facts:
                if isinstance(f, str) and f.strip() and f.strip().lower() not in known:
                    self.memory.setdefault("faits", []).append(f.strip())
            self.memory["faits"] = self.memory["faits"][-40:]
            self._save_memory()
        except Exception as e:
            print("Mémoire (extraction) :", e, file=sys.stderr)

    def _tidy_memory(self):
        """Une fois par semaine : elle fusionne les souvenirs en double et retire ce qui est dépassé."""
        faits = self.memory.get("faits", [])
        last = float(self.memory.get("range_le", 0) or 0)
        if len(faits) < 20 or time.time() - last < 7 * 86400 or not self.ollama_ok or self.ia_remote():
            return
        self.memory["range_le"] = time.time()
        self._save_memory()
        prompt = ("Voici des souvenirs sur l'utilisateur, du plus ancien au plus récent. Fusionne les doublons, "
                  "garde l'information la plus récente quand deux se contredisent, et reformule en phrases très "
                  "courtes à la 3e personne. Garde au maximum 25 souvenirs, n'en invente aucun. "
                  "Réponds en JSON : {\"faits\": [...]}.\n\n" + "\n".join(f"- {f}" for f in faits))

        def work():
            return self.llm_json([{"role": "user", "content": prompt}]).get("faits", [])

        def done(res):
            if isinstance(res, Exception) or not isinstance(res, list):
                return
            new = [f.strip() for f in res if isinstance(f, str) and f.strip()][:25]
            if len(new) >= min(8, len(faits) // 3):          # garde-fou : pas de mémoire vidée par erreur
                self.memory["faits_avant_rangement"] = faits
                self.memory["faits"] = new
                self._save_memory()
                print(f"Mémoire rangée : {len(faits)} -> {len(new)} souvenirs", file=sys.stderr)
        self._bg(work, done)

    def _hello(self):
        self._update_weather(announce=False)
        self._auto_outfit()
        self.react = ("salut", time.monotonic())
        self.happy_until = time.monotonic() + 1.2
        if self._is_birthday():
            self._spawn("coeur", 4)
            self._spawn("etoile", 3)
            self.say_from("anniversaire")
        else:
            self.say_from(greeting_key())
        QTimer.singleShot(4000, self._check_reminders)     # rappels manqués pendant l'absence
        if self.cfg.get("ghost"):                           # sinon on ne sait plus comment la rendre normale
            QTimer.singleShot(7000, lambda: self.say("Je suis en mode fantôme (transparente). Pour me rendre normale : "
                                                     "mon icône près de l'horloge → 👻 Sortir du mode fantôme, "
                                                     "ou dis « sors du mode fantôme »."))
        QTimer.singleShot(12000, self._git_morning)          # le point du matin sur les projets de code
        if not self.voice_model and not GUEST and not natural_voice_installed():
            QTimer.singleShot(9000, lambda: self.say("Je n'ai pas encore ma vraie voix : va dans Réglages → Voix "
                                                     "→ « Télécharger sa voix » (60 Mo, une seule fois)."))

    # ---------- personnage
    def _load_anim(self, img_dir):
        """Personnage animé (GIF, vidéo…) : ses images, et l'animation « elle parle » si elle existe."""
        self.vanim, self._anim_pix = None, {}
        t = self.__dict__.get("_anim_timer")
        if t is not None:
            t.stop()
        a = self.char.get("anim")
        if not a or not anime_perso or self.outfit:
            return
        try:
            repos = anime_perso.charger(Path(img_dir) / "anim", a.get("n", 0))
            if len(repos) < 2:
                return
            self.vanim = {"repos": repos, "fps": float(a.get("fps", 12)), "parle": [], "fps_parle": 12.0}
            ap = self.char.get("anim_parle")
            if ap:
                pl = anime_perso.charger(Path(img_dir) / "anim_parle", ap.get("n", 0))
                if len(pl) >= 2 and pl[0].size() == repos[0].size():
                    self.vanim["parle"], self.vanim["fps_parle"] = pl, float(ap.get("fps", 12))
            if t is None:
                t = self.__dict__["_anim_timer"] = QTimer(self)
                t.timeout.connect(self._anim_tick)
            t.start(int(1000 / max(2.0, min(30.0, max(self.vanim["fps"], self.vanim["fps_parle"])))))
        except Exception:
            log_error("personnage animé")
            self.vanim = None

    def _anim_tick(self):
        if self.vanim and self.isVisible() and not self.sleeping:
            self.update()

    def _anim_frame(self):
        """L'image de l'animation à afficher maintenant (mise à la taille une fois, puis gardée)."""
        a = self.vanim
        now = time.monotonic()
        talk = bool(a["parle"]) and self._talking(now)
        seq, fps, tag = (a["parle"], a["fps_parle"], "p") if talk else (a["repos"], a["fps"], "r")
        i = 0 if self.sleeping else int(now * fps) % len(seq)
        key = (tag, i, self.cw, self.ch)
        pm = self._anim_pix.get(key)
        if pm is None:
            if len(self._anim_pix) > 400:
                self._anim_pix.clear()
            pm = self._anim_pix[key] = self._scaled_pix(seq[i])
        return pm

    def _load_character(self):
        cdir = Path(self.cfg["character_dir"])
        if not (cdir / "character.json").exists():
            cdir = ASSETS_DIR
        self.char_dir = cdir
        self.char = json.loads((cdir / "character.json").read_text())
        self.char_base = dict(self.char)
        img_dir = cdir
        self.outfit = self._pick_outfit()
        if self.outfit:                       # tenue : autre image + son calibrage
            o = self.outfit
            for k in ("eyes", "mouth", "skin_sample", "zones", "cut_bottom", "image", "hitmask", "lash_color"):
                if k in o:
                    self.char[k] = o[k]
            img_dir = Path(o["_dir"])
        self.src = QPixmap(str(img_dir / self.char["image"]))
        self._src_size0 = (self.src.width(), self.src.height())
        self.geo = None
        hit_q = None
        self._load_anim(img_dir)
        if apparence and self.char.get("type") != "live2d" and not self.vanim:
            try:                              # coiffure, couleurs, silhouette, contours propres
                look = {} if self.outfit else self.cfg.get("looks", {}).get(apparence.look_key(cdir), {})
                q, geo, hit_q = apparence.process(img_dir / self.char["image"], cdir, look,
                                                  self.cfg.get("contours_propres", True), self.char,
                                                  img_dir / self.char.get("hitmask", self.char["image"]))
                if q is not None and not q.isNull() and q.height() == self.src.height():
                    self.src = QPixmap.fromImage(q)
                    if geo is not None and geo.active() and q.width() == geo.w:
                        self.geo = geo
                        self.char = apparence.shift_char(self.char, geo)
            except Exception:
                log_error("apparence")
        self.hit_src = QPixmap.fromImage(hit_q) if (self.geo and hit_q is not None) else \
            QPixmap(str(img_dir / self.char.get("hitmask", self.char["image"])))
        self.__dict__.pop("_src_img", None)
        img = self.src.toImage()
        sk = self.char.get("skin_sample")
        self.skin = img.pixelColor(sk["x"], sk["y"]) if sk else QColor("#f3c9b5")
        self.lash = QColor(self.char.get("lash_color", "#2a1414"))
        # teinte de peau locale sous chaque œil (paupières plus naturelles)
        self.eye_skin = []
        for e in self.char["eyes"]:
            rs = gs = bs = n = 0
            y = int(e["y"] + e["h"] * 0.5 + 3)
            for dx in range(-int(e["w"] * 0.3), int(e["w"] * 0.3) + 1, 2):
                for dy in (0, 2):
                    x, yy = int(e["x"] + dx), min(img.height() - 1, y + dy)
                    if 0 <= x < img.width():
                        col = img.pixelColor(x, yy)
                        if col.alpha() > 200 and col.lightness() > 120:
                            rs, gs, bs, n = rs + col.red(), gs + col.green(), bs + col.blue(), n + 1
            self.eye_skin.append(QColor(rs // n, gs // n, bs // n) if n else self.skin)
        self.irises = [analyse_eye(img, e, sk) for e, sk in zip(self.char["eyes"][:self.anim_eyes_n()],
                                                                self.eye_skin)]
        self.expr_patches = {}
        self._expr_now = ""
        if visuel and not self.outfit and not self.geo:
            for emo, rel in (self.char_base.get("expressions") or {}).items():
                pp = cdir / rel
                if pp.exists():
                    self.expr_patches[emo] = QImage(str(pp))
        self.gaze = QPointF(0, 0)
        self.next_glance = 0.0
        self.glance = QPointF(0, 0)
        self.phrases = load_phrases(cdir)
        e = self.char["eyes"]
        self.eye_dist = float(self.char.get("eye_dist") or 0) or \
            max(12.0, math.hypot(e[1]["x"] - e[0]["x"], e[1]["y"] - e[0]["y"]))
        pts = [(x["x"], x["y"]) for x in e] + [(self.char["mouth"]["x"], self.char["mouth"]["y"])]
        self.zones = list(self.char.get("zones") or [])
        have = {z["type"] for z in self.zones}
        if self.anim_eyes_n() == 2 and self.char.get("bouche", True) is not False:   # visage « humain »
            self.zones += [z for z in auto_face_zones(pts) if z["type"] not in have]
        self.zones = sorted(self.zones, key=zone_area)                    # la plus petite gagne
        try:
            self.relief = compute_relief(img, self.char["eyes"], self.char["mouth"])
        except Exception as ex:
            print("Relief 3D indisponible :", ex, file=sys.stderr)
            self.relief = None
        try:
            self.hairmask = compute_hairmask(img, self.char["eyes"], self.char["mouth"], self.skin)
        except Exception as ex:
            print("Détection des cheveux indisponible :", ex, file=sys.stderr)
            self.hairmask = None
        self.yaw = self.pitch = 0.0
        self.head_ang = 0.0
        self.hair = [0.0, 0.0, 0.0, 0.0]          # x, vitesse x, y, vitesse y (pixels écran)
        self._prev_motion = None

    def _fig_h(self):
        key = (id(self.src), self.src.cacheKey())
        if getattr(self, "_fig_key", None) != key:
            self._fig_key, self._fig_cache = key, figure_height(self.src)
        return self._fig_cache

    def host_size(self):
        """Hauteur à l'écran du personnage dessiné (en pixels logiques) : les invitées la copient."""
        return round(self._fig_h() * self.scale)

    def _sync_guest_sizes(self):
        if GUEST:
            return
        px = self.host_size()
        for cdir in self.cfg.get("invites", []):
            slug = re.sub(r"[^\w\-]", "", Path(cdir).name)
            f = BASE_CONFIG_DIR / "invites" / slug / "config.json"
            try:
                g = json.loads(f.read_text())
                g["taille_hote"] = px
                f.write_text(json.dumps(g, indent=2, ensure_ascii=False))
            except Exception:
                pass
            self._guest_send(slug, f"taille:{px}")

    def _apply_scale(self, scale, keep_anchor=True):
        if not GUEST and hasattr(self, "invite"):     # les invitées suivent (un peu après, une seule fois)
            t = getattr(self, "_size_sync", None)
            if t is None:
                t = self._size_sync = QTimer(self)
                t.setSingleShot(True)
                t.timeout.connect(self._sync_guest_sizes)
            if self.isVisible():
                t.start(400)
        anchor = None
        if keep_anchor and self.isVisible():
            g = self.geometry()
            anchor = QPoint(g.center().x(), g.bottom())
        screen_h = self.app.primaryScreen().availableGeometry().height()
        fit = (screen_h * 0.95 - BUBBLE_AREA) / max(1, self.src.height())
        self.scale = max(0.1, min(2.5, float(scale), fit))
        self.cfg["scale"] = self.scale
        self.cfg["scale_h"] = self.src.height()
        self.cw = round(self.src.width() * self.scale)
        self.ch = round(self.src.height() * self.scale)
        self.dpr = max(1.0, (self.app.screenAt(self.geometry().center()) or self.app.primaryScreen())
                       .devicePixelRatio())
        self.pix = self._scaled_pix(self.src)
        self._expr_pix = {}
        self.margin = int(self.ch * 0.05) + 14      # place pour pencher / danser
        self._build_mesh()
        self.W = max(MIN_WIDTH, self.cw + 2 * self.margin, self.cw + 2 * 66)   # 66 : la place des jauges sur le côté
        self.scene = None
        if lieux and self.cfg.get("lieu") in lieux.LIEUX:
            if not getattr(self, "lieu_obj", None) or self.lieu_obj.kind != self.cfg["lieu"]:
                self.lieu_obj = lieux.Lieu(self.cfg["lieu"])
            self.W = max(self.W, int(max(560, self.cw * 2.4)))
        else:
            self.lieu_obj = None
        old_w = getattr(self, "_old_W", None)
        if old_w is None or old_w != self.W or not hasattr(self, "char_cx"):
            self.char_cx = self.W / 2
        self._old_W = self.W
        self.H = BUBBLE_AREA + self.ch + 2
        self.setFixedSize(self.W, self.H)
        if self.lieu_obj:                    # cadre du décor : un peu de ciel au-dessus de sa tête
            top = max(8, BUBBLE_AREA - max(40, int(self.ch * 0.12)))
            self.scene = QRectF(2, top, self.W - 4, self.H - top - 2)
        hit = self.hit_src.scaled(self.cw, self.ch, Qt.AspectRatioMode.IgnoreAspectRatio,
                                  Qt.TransformationMode.FastTransformation)
        himg = solid_alpha(hit.toImage())
        # zone de clic généreuse : silhouette élargie, toutes ses inclinaisons et ses sauts
        pad = max(12, int(0.03 * max(self.cw, self.ch)))
        canvas = QImage(self.W, self.H, QImage.Format.Format_ARGB32)
        canvas.fill(Qt.GlobalColor.transparent)
        cp = QPainter(canvas)
        for ang in (-5.0, -2.5, 0.0, 2.5, 5.0):
            for hop in (0, -HOP_HEIGHT // 2, -HOP_HEIGHT):
                for dx in (-pad, 0, pad):
                    for dy in (-pad, 0, pad):
                        cp.save()
                        cp.translate(self.char_cx + dx, BUBBLE_AREA + self.ch + hop + dy)
                        cp.rotate(ang)
                        cp.translate(-self.cw / 2, -self.ch)
                        cp.drawImage(0, 0, himg)
                        cp.restore()
        self.has_shadow = not self.char.get("cut_bottom", False)
        if self.has_shadow:
            cp.fillRect(QRect(int(self.char_cx - self.cw * 0.35), self.H - 16, int(self.cw * 0.7), 16),
                        QColor(0, 0, 0, 255))
        cp.end()
        self.char_region = QRegion(QBitmap.fromImage(solid_alpha(canvas).createAlphaMask()))
        self.char_rects = image_rects(canvas)
        if anchor is not None:
            self.move(anchor.x() - self.W // 2, anchor.y() - self.H + 1)
        if self.isVisible():
            self._clamp_on_screen()
        self._update_mask()

    # ---------- effet 3D : maillage déformé selon le relief
    def _depth_at(self, u, v):
        mw, mh, vals = self.relief
        x, y = min(mw - 1.001, max(0.0, u * (mw - 1))), min(mh - 1.001, max(0.0, v * (mh - 1)))
        x0, y0 = int(x), int(y)
        fx, fy = x - x0, y - y0
        a = vals[y0 * mw + x0] * (1 - fx) + vals[y0 * mw + x0 + 1] * fx
        b = vals[(y0 + 1) * mw + x0] * (1 - fx) + vals[(y0 + 1) * mw + x0 + 1] * fx
        return a * (1 - fy) + b * fy

    def _map_at(self, m, u, v):
        mw, mh, vals = m
        x, y = min(mw - 1.001, max(0.0, u * (mw - 1))), min(mh - 1.001, max(0.0, v * (mh - 1)))
        x0, y0 = int(x), int(y)
        fx, fy = x - x0, y - y0
        a = vals[y0 * mw + x0] * (1 - fx) + vals[y0 * mw + x0 + 1] * fx
        b = vals[(y0 + 1) * mw + x0] * (1 - fx) + vals[(y0 + 1) * mw + x0 + 1] * fx
        return a * (1 - fy) + b * fy

    def find_rig(self):
        """rig.json du personnage : dans son dossier, sinon celui fourni avec le logiciel
        s'il a été fait pour la même image (même nom et même taille)."""
        if not marionnette:
            return None
        p = marionnette.find_rig(self.char_dir)
        if p:
            return p
        for d in (ASSETS_DIR, APP_DIR / "assets"):
            q = marionnette.find_rig(d)
            if not q:
                continue
            try:
                rj = json.loads(q.read_text(encoding="utf-8"))
                cv = rj.get("canvas", {})
                same_name = rj.get("name", "").lower() == self.char_base.get("name", "").lower()
                ratio = cv.get("height", 0) / max(1, cv.get("width", 1))
                w0, h0 = getattr(self, "_src_size0", (self.src.width(), self.src.height()))
                same_shape = abs(ratio - h0 / max(1, w0)) < 0.02
                if same_name and same_shape:
                    return q
            except Exception:
                pass
        return None

    def import_rig(self, path=None):
        """Importer une marionnette (.zip ou dossier contenant rig.json) pour le personnage actuel."""
        if not path:
            path, _ = QFileDialog.getOpenFileName(None, "Choisis le rig.json ou le .zip de la marionnette",
                                                  str(Path.home()), "Marionnette (rig.json *.zip)")
        if not path:
            return
        dest = Path(self.char_dir) / "marionnette"
        try:
            import tempfile, zipfile
            src = Path(path)
            if src.suffix.lower() == ".zip":
                tmp = Path(tempfile.mkdtemp())
                with zipfile.ZipFile(src) as z:
                    z.extractall(tmp)
                found = next(tmp.rglob("rig.json"), None)
                if not found:
                    raise ValueError("pas de rig.json dans ce .zip")
                src = found
            folder = src.parent
            if dest.exists():
                shutil.rmtree(dest)
            shutil.copytree(folder, dest)
        except Exception as e:
            QMessageBox.warning(None, "Marionnette", f"Impossible d'importer la marionnette :\n{e}")
            return
        self.cfg["marionnette"] = True
        save_config(self.cfg)
        self._build_mesh()
        self.update()
        self.say("Ça y est, je bouge les bras et la tête pour de vrai !" if self.puppet else
                 "J'ai copié la marionnette, mais je n'arrive pas à l'utiliser…")

    def _build_puppet(self):
        """Mode marionnette : rig.json dans le dossier du personnage (tête, bras, buste animés)."""
        self.puppet = None
        if not marionnette or not self.cfg.get("marionnette", True):
            return
        if getattr(self, "outfit", None):          # le rig est fait pour l'image de base
            return
        path = self.find_rig()
        if not path:
            return
        try:
            w, h = self.src.width(), self.src.height()
            geo = getattr(self, "geo", None)
            try:
                rig = marionnette.Rig(path, self._src_size0[0] if geo else w, h, geo=geo)
            except TypeError:
                rig = marionnette.Rig(path, w, h)
            img = self.src.toImage().convertToFormat(QImage.Format.Format_ARGB32)
            import numpy as _np
            a = _np.frombuffer(img.constBits().asstring(img.sizeInBytes()), _np.uint8).reshape(
                h, img.bytesPerLine())[:, :w * 4].reshape(h, w, 4)[:, :, 3]

            def visible(x0, y0, x1, y1, m=6):
                ya, yb = max(0, int(y0) - m), min(h, int(y1) + m + 1)
                xa, xb = max(0, int(x0) - m), min(w, int(x1) + m + 1)
                return bool((a[ya:yb, xa:xb] > 3).any())
            gw = 16 if self._q().get("gw", 12) <= 10 else 22
            grid = rig.build_grid(visible, cols=gw, rows=int(gw * 1.6))
            self.puppet = (rig, grid)
            self._pup_key = None
        except Exception as e:
            print("Marionnette :", e, file=sys.stderr)
            self.puppet = None

    def _draw_puppet(self, p, t):
        rig, grid = self.puppet
        now = time.monotonic()
        light = not self._q()["anim"]
        force = 0.0 if (light or self.sleeping) else float(self.cfg.get("marionnette_force", 1.0))
        walking = ((now - self.walk["start"]) * math.pi * 1.8) if self.walk else 0.0
        mo = None
        if self.react and marionnette and self.react[0] in getattr(marionnette, "MOTIONS", {}):
            mo = (self.react[0], now - self.react[1])
        pose = rig.pose(t, self.gaze.x(), force, walking, 1.0 if self._talking(now) else 0.0, motion=mo,
                        idle=not self.battery_saving()) if hasattr(rig, "_pose") else \
            rig.pose(t, self.gaze.x(), force, walking, 1.0 if self._talking(now) else 0.0)
        key = (round(pose["breath"], 4), round(pose["head"], 1), round(pose["arm_left"], 1),
               round(pose["arm_right"], 1), round(pose.get("skirt", 0), 1), round(pose.get("sway", 0), 1),
               self._expr_now, self.scale)
        pad = self._mesh_pad if hasattr(self, "_mesh_pad") else int(0.12 * max(self.cw, self.ch)) + 6
        old = getattr(self, "_pup_key", None)
        if old != key and (old is None or now - getattr(self, "_pup_t", 0) >= self._q()["mesh_dt"]):
            self._pup_t = now
            sc, dpr = self.scale, self.dpr
            pts, off, ang, hp = rig.deform(grid, pose)
            cache = QPixmap(int((self.cw + 2 * pad) * dpr), int((self.ch + 2 * pad) * dpr))
            cache.setDevicePixelRatio(dpr)
            cache.fill(Qt.GlobalColor.transparent)
            pix = self._cur_pix()
            cp = QPainter(cache)
            cp.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
            cp.translate(pad, pad)
            b = grid["bottom"] * sc
            if b < self.ch:                                   # bas du corps : immobile, un seul bloc
                cp.drawPixmap(QRectF(0, b, self.cw, self.ch - b), pix,
                              QRectF(0, b * dpr, self.cw * dpr, (self.ch - b) * dpr))
            xs, ys = grid["xs"], grid["ys"]
            for i, j in grid["cells"]:
                a = QPolygonF([QPointF(xs[i] * sc, ys[j] * sc), QPointF(xs[i + 1] * sc, ys[j] * sc),
                               QPointF(xs[i + 1] * sc, ys[j + 1] * sc), QPointF(xs[i] * sc, ys[j + 1] * sc)])
                q = QPolygonF([QPointF(pts[j][i][0] * sc, pts[j][i][1] * sc),
                               QPointF(pts[j][i + 1][0] * sc, pts[j][i + 1][1] * sc),
                               QPointF(pts[j + 1][i + 1][0] * sc, pts[j + 1][i + 1][1] * sc),
                               QPointF(pts[j + 1][i][0] * sc, pts[j + 1][i][1] * sc)])
                tr = QTransform()
                ok = QTransform.quadToQuad(a, q, tr)
                cw_ = (xs[i + 1] - xs[i]) * sc
                ch_ = (ys[j + 1] - ys[j]) * sc
                if not ok or abs(tr.m13()) * cw_ > 0.05 or abs(tr.m23()) * ch_ > 0.05:
                    # case trop tordue (bras qui frôle le corps) : simple transformation affine
                    b0, b1, b3 = q[0], q[1], q[3]
                    ux, uy = (b1.x() - b0.x()) / cw_, (b1.y() - b0.y()) / cw_
                    vx, vy = (b3.x() - b0.x()) / ch_, (b3.y() - b0.y()) / ch_
                    x0, y0 = xs[i] * sc, ys[j] * sc
                    tr = QTransform(ux, uy, vx, vy, b0.x() - x0 * ux - y0 * vx, b0.y() - x0 * uy - y0 * vy)
                e = 0.6                                       # léger chevauchement : pas de fines lignes
                src_r = QRectF(xs[i] * sc - e, ys[j] * sc - e, cw_ + 2 * e, ch_ + 2 * e)
                cp.save()
                cp.setTransform(tr, True)
                cp.drawPixmap(src_r, pix, QRectF(src_r.x() * dpr, src_r.y() * dpr,
                                                 src_r.width() * dpr, src_r.height() * dpr))
                cp.restore()
            cp.end()
            self._pup_cache, self._pup_key = cache, key
            self._pup_head = (QPointF(*off), ang, QPointF(*hp))
        p.drawPixmap(-pad, -pad, self._pup_cache)
        return self._pup_head

    def _build_live2d(self):
        """Personnage Live2D : le modèle est dessiné hors écran, à la taille de la fenêtre."""
        typ = self.char_base.get("type")
        info = self.char_base if typ in ("live2d", "spine") else None
        if not info or not (live2d_rendu if typ == "live2d" else spine_rendu):
            self.l2d = None
            return False
        try:
            old = getattr(self, "l2d", None)
            if typ == "spine":
                path = str(Path(self.char_dir) / info["spine"])
                key = (path, info.get("idle"), info.get("skin"))
                m = old[0] if old and getattr(old[0], "_key", None) == key else spine_rendu.SpineModel(
                    path, Path(self.char_dir) / info["atlas"], info.get("idle"), info.get("skin"))
                m._key = key
            else:
                path = str(Path(self.char_dir) / info["live2d"])
                if not (old and old[0].path == path):
                    try:
                        live2d_rendu.complete_model_json(path)   # physique / mouvements oubliés
                    except Exception:
                        pass
                if not info.get("l2d_scale") and not info.get("_recadre"):
                    self._refit_model(info)                 # anciens imports : on recadre une fois
                m = old[0] if old and old[0].path == path else live2d_rendu.Live2DModel(
                    path, info.get("l2d_scale", 1.0))
            x0, y0, x1, y1 = info["crop"]
            f = self.cw * self.dpr / max(1, x1 - x0)
            m.resize(info["canvas"][0] * f, info["canvas"][1] * f)
            if old and old[0] is not m:
                try:
                    old[0].close()                                 # ancien modèle libéré proprement
                except Exception:
                    pass
            m.random_moves = bool(self.cfg.get("mouv_hasard", True))
            m.on_sound = self._model_sound
            try:
                m.set_voice_pool(Path(self.char_dir) / ("spine" if typ == "spine" else "live2d"))
            except Exception as e:
                print("Voix du modèle :", e, file=sys.stderr)
            self.l2d = (m, f, (x0, y0, x1, y1))
            self._l2d_img, self._l2d_t = None, 0.0
            return True
        except Exception as e:
            print("Live2D :", e, file=sys.stderr)
            self.l2d = None
            if not getattr(self, "_l2d_warned", False):
                self._l2d_warned = True
                QTimer.singleShot(1500, lambda: self.say(
                    "Je n'arrive pas à afficher mon modèle animé… J'utilise mon image fixe pour l'instant."))
            return False

    def _model_sound(self, path, reason="clic"):
        """Voix / son livré avec un mouvement du modèle."""
        if not self.cfg.get("voix_modele", True) or self.is_muted():
            return
        if reason in ("hasard", "repos") and not self.cfg.get("voix_modele_hasard", True):
            return
        if self.player and self.player.poll() is None:          # elle parle déjà : on ne coupe pas
            return
        p = Path(path)
        try:
            ext = p.suffix.lower()
            if ext in (".mp3", ".m4a", ".aac") and not shutil.which("pw-play"):
                tool = shutil.which("ffplay") or shutil.which("mpv")
                if not tool:
                    return
                v = int(100 * max(0.05, min(1.5, float(self.cfg.get("volume", 0.35)))))
                cmd = ([tool, "-nodisp", "-autoexit", "-loglevel", "quiet", "-volume", str(v), str(p)]
                       if tool.endswith("ffplay") else [tool, "--no-video", "--really-quiet", f"--volume={v}", str(p)])
            else:
                cmd = self._play_cmd(str(p))
            self.player = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            if ext == ".wav":                                    # la bouche suit le son
                try:
                    self.lip_env, dur = wav_envelope(str(p))
                    self.lip_start = time.monotonic()
                except Exception:
                    pass
        except Exception as e:
            print("Son du modèle :", e, file=sys.stderr)

    # ---------- extraits de voix (référence pour la voix naturelle)
    def voice_refs_dir(self):
        d = DATA_DIR / "voices" / "references"
        d.mkdir(parents=True, exist_ok=True)
        return d

    def list_voice_refs(self):
        d = self.voice_refs_dir()
        return sorted((p for p in d.iterdir() if p.suffix.lower() in (".wav", ".mp3", ".flac", ".ogg", ".m4a")),
                      key=lambda p: p.name.lower())

    def add_voice_refs(self, paths=None, use=False):
        if not paths:
            paths, _ = QFileDialog.getOpenFileNames(
                None, "Extraits de voix (10 à 30 s, une seule personne, sans musique)", str(Path.home()),
                "Audio (*.wav *.mp3 *.flac *.ogg *.m4a)")
        added = []
        for src in paths or []:
            src = Path(src)
            dest = self.voice_refs_dir() / src.name
            k = 2
            while dest.exists() and dest.resolve() != src.resolve():
                dest = dest.with_name(f"{src.stem} ({k}){src.suffix}")
                k += 1
            try:
                if dest.resolve() != src.resolve():
                    shutil.copy2(src, dest)
                added.append(dest)
            except Exception as e:
                self.say(f"Je n'ai pas pu ajouter {src.name} : {str(e)[:80]}")
        if added:
            if use or not (self.cfg.get("voice_ref") and Path(self.cfg["voice_ref"]).exists()):
                self.use_voice_ref(added[0])
            else:
                self.say(f"{len(added)} extrait{'s' if len(added) > 1 else ''} de voix ajouté{'s' if len(added) > 1 else ''} !")
        return added

    def use_voice_ref(self, path):
        self.cfg["voice_ref"] = str(path)
        self._ref_warned = ""
        self._save_char_voice()                   # retenu pour ce personnage (sinon perdu en changeant de perso)
        save_config(self.cfg)
        self._rebuild_menus()
        threading.Thread(target=lambda: self._prepared_ref(str(path)), daemon=True).start()   # prêt d'avance
        if self.cfg.get("voice_engine") in NAT_ENGINES and self.natural_ready:
            self.say("Voilà ma nouvelle voix. Qu'est-ce que tu en penses ?")
        elif natural_voice_installed():
            self.say("C'est noté ! Choisis la voix légère ou naturelle dans Réglages → Voix pour que je l'imite "
                     "(Piper, lui, ne sait pas imiter une voix).")
        else:
            self.say("C'est noté ! Il servira avec la voix légère ou naturelle (Réglages → Voix pour l'installer).")

    def _prepared_ref(self, ref):
        """Extrait propre pour l'imitation : WAV mono 24 kHz, 25 s max, sans le silence du début, volume égalisé.
        (Les MP3/M4A et les extraits trop longs faisaient échouer l'imitation.) Gardé en cache."""
        if not ref or not Path(ref).exists():
            return ref
        ff = shutil.which("ffmpeg")
        if not ff:
            return ref
        try:
            st = Path(ref).stat()
            import hashlib
            clean = bool(self.cfg.get("voix_nettoyer_extrait", True))
            h = hashlib.sha1(f"v3|{int(clean)}|{ref}|{st.st_size}|{st.st_mtime}".encode()).hexdigest()[:16]
            out = self.voice_refs_dir() / ".prets" / f"{h}.wav"
            lock = self.__dict__.setdefault("_ref_lock", threading.Lock())
            with lock:                              # pas deux préparations en même temps (fichier à moitié écrit)
                return self._prepare_ref_file(ff, ref, out)
        except Exception as e:
            print("Extrait de voix :", e, file=sys.stderr)
        return ref

    def _prepare_ref_file(self, ff, ref, out):
        if out.exists() and out.stat().st_size > 1000:
            return str(out)
        out.parent.mkdir(parents=True, exist_ok=True)
        tmp = out.with_suffix(".tmp.wav")
        try:
            r = subprocess.run([ff, "-y", "-loglevel", "error", "-i", ref, "-vn", "-ac", "1", "-ar", "24000",
                                "-af", "silenceremove=start_periods=1:start_threshold=-45dB,highpass=f=60"
                                       + (",afftdn=nr=14:nf=-40,agate=threshold=0.012:ratio=2.5:release=220"
                                          if self.cfg.get("voix_nettoyer_extrait", True) else "") + ",volume=0dB",
                                "-t", "20", str(tmp)], capture_output=True, timeout=120)
            if r.returncode == 0 and tmp.exists() and tmp.stat().st_size > 1000:
                os.replace(tmp, out)               # le fichier n'apparaît qu'une fois complet
                return str(out)
            print("Extrait de voix (ffmpeg) :", r.stderr.decode(errors="ignore")[-200:], file=sys.stderr)
        except Exception as e:
            print("Extrait de voix :", e, file=sys.stderr)
        return ref

    def play_voice_ref(self, path):
        cmd = self._play_cmd(str(path))
        if Path(path).suffix.lower() in (".mp3", ".m4a") and (shutil.which("ffplay") or shutil.which("mpv")):
            tool = shutil.which("ffplay") or shutil.which("mpv")
            cmd = ([tool, "-nodisp", "-autoexit", "-loglevel", "quiet", str(path)] if tool.endswith("ffplay")
                   else [tool, "--no-video", "--really-quiet", str(path)])
        subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

    def delete_voice_ref(self, path):
        p = Path(path)
        if p.resolve().parent != self.voice_refs_dir().resolve():
            return
        p.unlink(missing_ok=True)
        if self.cfg.get("voice_ref") == str(p):
            self.cfg["voice_ref"] = ""
            save_config(self.cfg)

    def record_voice_ref(self, seconds=20, done=None):
        """Enregistre un extrait au micro (lis un texte à voix haute, calmement)."""
        rec = shutil.which("pw-record") or shutil.which("arecord")
        if not rec:
            return self.say("Je ne trouve pas d'outil pour enregistrer le micro (pw-record).")
        n = 1
        while (self.voice_refs_dir() / f"Mon enregistrement {n}.wav").exists():
            n += 1
        out = self.voice_refs_dir() / f"Mon enregistrement {n}.wav"
        cmd = ([rec, "--rate", "24000", "--channels", "1", "--format", "s16", str(out)] if rec.endswith("pw-record")
               else [rec, "-q", "-f", "S16_LE", "-r", "24000", "-c", "1", str(out)])
        self.say(f"J'enregistre pendant {seconds} secondes : lis un texte à voix haute, calmement… C'est parti !")

        def work():
            try:
                p = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                time.sleep(seconds + 2.5)                     # + le temps de la phrase d'annonce
                p.terminate()
                p.wait(timeout=5)
            except Exception as e:
                print("Enregistrement :", e, file=sys.stderr)

            def fin(_t):
                ok = out.exists() and out.stat().st_size > 24000 * 2 * 3
                self.say("C'est enregistré ! Tu le trouves dans tes extraits de voix." if ok
                         else "L'enregistrement n'a pas marché… Vérifie ton micro (Réglages → Micro).")
                if done:
                    done(out if ok else None)
            self.bridge.ai_done.emit(fin, "")
        threading.Thread(target=work, daemon=True).start()

    def _refit_model(self, info=None):
        """Refait l'aperçu et le cadre d'un modèle animé (pour qu'il ne soit plus coupé)."""
        f = Path(self.char_dir) / "character.json"
        info = info if info is not None else json.loads(f.read_text())
        try:
            if info.get("type") == "spine" and spine_rendu:
                prev = spine_rendu.render_preview(Path(self.char_dir) / info["spine"],
                                                  Path(self.char_dir) / info["atlas"],
                                                  Path(self.char_dir) / "character.png",
                                                  idle=info.get("idle"), skin=info.get("skin"))
            elif info.get("type") == "live2d" and live2d_rendu:
                prev = live2d_rendu.render_preview(Path(self.char_dir) / info["live2d"],
                                                   Path(self.char_dir) / "character.png")
                info["l2d_scale"] = prev.get("l2d_scale", 1.0)
            else:
                return False
            info.update(canvas=prev["canvas"], crop=prev["crop"], eyes=prev["eyes"], mouth=prev["mouth"],
                        _recadre=2)
            f.write_text(json.dumps(info, ensure_ascii=False, indent=2))
            self.char_base.update(info)
            self.char.update({k: info[k] for k in ("canvas", "crop", "eyes", "mouth") if k in info})
            return True
        except Exception as e:
            print("Recadrage du modèle :", e, file=sys.stderr)
            return False

    def refit_model(self):
        self.say("Je me recadre…")
        QApplication.processEvents()
        if self._refit_model():
            self.l2d = None
            self.switch_character(self.char_dir, greet=False)
            self.say("Voilà, on me voit en entier maintenant !")
        else:
            self.say("Je n'ai pas réussi à me recadrer…")

    def play_model_motion(self, key):
        """Joue un mouvement du modèle choisi dans les réglages."""
        if not getattr(self, "l2d", None):
            return
        m = self.l2d[0]
        if isinstance(key, tuple):
            m.play_motion(*key)
        else:
            m.play(key)

    def model_motions(self):
        """[(libellé, clé)] : mouvements du modèle animé affiché."""
        if not getattr(self, "l2d", None):
            return []
        m = self.l2d[0]
        if hasattr(m, "motions"):
            return [(f"{n}" + (f"  ({g})" if g and g.lower() not in n.lower() else ""), (g, i))
                    for g, i, n in m.motions]
        return [(a, a) for a in m.sk.anim_names]

    def _draw_l2d(self, p, t):
        m, f, (x0, y0, x1, y1) = self.l2d
        now = time.monotonic()
        if self._l2d_img is None or now - self._l2d_t >= 1 / 40:
            self._l2d_t = now
            smile = 1.0 if now < self.happy_until else 0.0
            blink = self._blink_amount(now)
            eyes = 0.0 if self.sleeping else (1.0 if now < self.surprise_until else
                                              (1.0 - blink if blink > 0.02 else None))
            try:
                self._l2d_img = m.frame(look=(self.gaze.x(), -self.gaze.y()), mouth=self._mouth_open(now),
                                        eyes=eyes, smile=smile)
            except Exception as e:
                print("Live2D (image) :", e, file=sys.stderr)
                self.l2d = None
                p.drawPixmap(0, 0, self.pix)
                return QPointF(0, 0), 0.0, QPointF(0, 0)
        p.drawImage(QRectF(0, 0, self.cw, self.ch), self._l2d_img,
                    QRectF(x0 * f, y0 * f, (x1 - x0) * f, (y1 - y0) * f))
        return QPointF(0, 0), 0.0, QPointF(0, 0)

    def _build_mesh(self):
        self.mesh = None
        old = getattr(self, "l2d", None)
        if self._build_live2d():
            self.puppet = None
            return
        if old:                                             # on quitte un modèle animé : on le libère
            try:
                old[0].close()
            except Exception:
                pass
        self._build_puppet()
        if not self.relief or self.__dict__.get("vanim"):          # animé : c'est le fichier qui bouge, pas de relief
            return
        sc = self.scale
        e, m = self.char["eyes"], self.char["mouth"]
        ed = self.eye_dist * sc                                   # écart des yeux à l'écran
        ecx = (e[0]["x"] + e[1]["x"]) / 2 * sc
        ecy = (e[0]["y"] + e[1]["y"]) / 2 * sc
        fcx, fcy = ecx, (ecy + m["y"] * sc) / 2                   # centre du visage
        piv = QPointF(ecx, m["y"] * sc + 0.9 * ed)                # cou : pivot de la tête
        # grille plus fine autour de la tête
        gw = self._q()["gw"] if hasattr(self, "hw") else 12
        top, bot = max(0.0, ecy - 2.4 * ed), min(float(self.ch), piv.y() + 0.8 * ed)
        ys = sorted(set([0.0, float(self.ch)]
                        + [top + (bot - top) * k / 10 for k in range(11)]
                        + [self.ch * k / 12 for k in range(13)]))
        ys = [y for i, y in enumerate(ys) if i == 0 or y - ys[i - 1] > 3]
        cut = self.char.get("cut_bottom", False)
        verts = []
        for y in ys:
            v = y / self.ch
            row = []
            for i in range(gw + 1):
                x = self.cw * i / gw
                u = i / gw
                d = self._map_at(self.relief, u, v) - 0.35          # >0 : avance, <0 : recule
                wv = max(0.12, 1 - v) ** 0.8 if not cut else max(0.25, 1 - 0.7 * v)
                r = math.hypot(x - fcx, (y - fcy) * 0.9) / ed
                wh = 1.0 if r < 1.5 else max(0.0, 1 - (r - 1.5) / 1.1)
                if y > piv.y():
                    wh *= max(0.0, 1 - (y - piv.y()) / (0.6 * ed))
                hm = self._map_at(self.hairmask, u, v) if self.hairmask else 0.0
                hm = max(0.0, min(1.0, (hm - 0.3) / 0.45))
                dangle = max(0.15, min(1.0, (y - (ecy - 1.5 * ed)) / (3.0 * ed)))   # pointes > racines
                row.append((x, y, d * wv, wh, hm * dangle))
            verts.append(row)
        cells = []
        for j in range(len(verts) - 1):
            for i in range(gw):
                x0, y0 = verts[j][i][0], verts[j][i][1]
                x1, y1 = verts[j + 1][i + 1][0], verts[j + 1][i + 1][1]
                cells.append((i, j, QRectF(x0, y0, x1 - x0, y1 - y0)))
        fu, fv = fcx / self.cw, fcy / self.ch
        wf = max(0.12, 1 - fv) ** 0.8 if not cut else max(0.25, 1 - 0.7 * fv)
        cell_w = self.cw / gw
        min_h = min(verts[j + 1][0][1] - verts[j][0][1] for j in range(len(verts) - 1))
        self.mesh = {"verts": verts, "cells": cells, "pivot": piv, "ed": ed,
                     "face": (self._map_at(self.relief, fu, fv) - 0.35) * wf,
                     # au-delà, des sommets voisins pourraient se croiser (effet « déchiré »)
                     "hair_lim": max(2.0, min(0.3 * ed, 0.45 * cell_w, 1.2 * min_h))}
        self._mesh_key = None
        self._mesh_pad = int(0.12 * max(self.cw, self.ch)) + 6

    def _physics(self, now, t, rot, dx, hop):
        """Tête indépendante + cheveux à ressort, mis à jour à chaque image."""
        if not self.mesh or not self.cfg.get("head_hair_anim", True):
            self.head_ang = 0.0
            self.hair = [0.0, 0.0, 0.0, 0.0]
            return
        ed = self.mesh["ed"]
        # --- inclinaison de la tête
        tgt = self.gaze.x() * 3.5
        if self._talking(now):
            tgt += 1.8 * math.sin(t * 2.6)
        if self.sleeping:
            tgt = 8.0
        elif now < self.happy_until:
            tgt += 3.0
        elif now < self.sad_until or self.cfg.get("mood", 70) < 30:
            tgt -= 2.5
        if self.react:
            kind, st = self.react
            d = now - st
            if kind in ("cheveux", "joue", "caresse"):
                tgt += 6 * math.sin(d * 6) * math.exp(-d * 1.8)
            elif kind == "regarde":
                tgt += 5 * math.sin(d * math.pi / 0.9)
            elif kind in ("fredonne", "pieds"):
                tgt += 4 * math.sin(d * 7)
        self.head_ang += (tgt - self.head_ang) * 0.12
        # --- cheveux : inertie quand le corps, la tête ou la fenêtre bougent
        lever = 2.2 * ed
        motion = (self.x() + self.char_cx + dx + math.radians(rot + self.head_ang) * lever, self.y() + hop)
        if self._prev_motion is None:
            self._prev_motion = motion
        vx, vy = motion[0] - self._prev_motion[0], motion[1] - self._prev_motion[1]
        self._prev_motion = motion
        hx, hvx, hy, hvy = self.hair
        # élan limité : un grand glisser de fenêtre ne doit pas « arracher » les cheveux
        cap = 0.12 * ed
        vx = max(-cap, min(cap, vx))
        vy = max(-cap, min(cap, vy))
        breeze = 0.03 * ed * math.sin(t * 0.9) if self._q()["breeze"] else 0.0
        hvx += -vx * 0.5 - 0.16 * (hx - breeze)
        hvy += -vy * 0.4 - 0.2 * hy
        hvx *= 0.84
        hvy *= 0.82
        lim = self.mesh.get("hair_lim", 0.3 * ed)       # jamais plus qu'une fraction de case
        hx = max(-lim, min(lim, hx + hvx))
        hy = max(-lim * 0.6, min(lim * 0.6, hy + hvy))
        self.hair = [hx, hvx, hy, hvy]

    def _draw_body(self, p, t):
        """Dessine le personnage déformé : relief 3D, tête qui bouge, cheveux.
        Renvoie (décalage du visage, angle de la tête, pivot) en pixels de l'image d'origine."""
        if getattr(self, "l2d", None):
            return self._draw_l2d(p, t)
        if getattr(self, "puppet", None):
            return self._draw_puppet(p, t)
        light = not self._q()["anim"]                     # PC très chargé : image simple
        relief_on = (self.cfg.get("relief_3d", True) and self.mesh and not self.sleeping
                     and not (self.drag and self.drag[2]) and not light)
        hh_on = self.cfg.get("head_hair_anim", True) and self.mesh and not light
        gx, gy = (self.gaze.x(), self.gaze.y()) if relief_on else (0.0, 0.0)
        idle = 0.0          # (balancement permanent retiré : il forçait un redessin constant)
        self.yaw += (max(-1.0, min(1.0, gx * 0.9 + idle)) - self.yaw) * 0.12
        self.pitch += (max(-1.0, min(1.0, gy * 0.6)) - self.pitch) * 0.12
        ang = self.head_ang if hh_on else 0.0
        hx, hy = (self.hair[0], self.hair[2]) if hh_on else (0.0, 0.0)
        still = (abs(self.yaw) < 0.015 and abs(self.pitch) < 0.015 and abs(ang) < 0.08
                 and abs(hx) < 0.3 and abs(hy) < 0.3)
        if not self.mesh or still:
            p.drawPixmap(0, 0, self._cur_pix())
            return QPointF(0, 0), 0.0, QPointF(0, 0)
        k = 0.06 * self.cw * float(self.cfg.get("relief_force", 1.0))
        key = (round(self.yaw * 40) / 40, round(self.pitch * 40) / 40, round(ang * 2) / 2,
               round(hx), round(hy), k, self._expr_now)                            # cache : redessin seulement si ça bouge
        ax, ay = key[0] * k, key[1] * k * 0.7
        piv = self.mesh["pivot"]
        th = math.radians(key[2])
        ca, sa = math.cos(th), math.sin(th)
        pad = self._mesh_pad
        # redessin du maillage limité à ~15 fois/s (le reste du temps : image en cache)
        now_m = time.monotonic()
        stale = self._mesh_key != key
        if stale and self._mesh_key is not None and now_m - getattr(self, "_mesh_t", 0) < self._q()["mesh_dt"]:
            stale = False
            key = self._mesh_key
            ax, ay = key[0] * k, key[1] * k * 0.7
            th = math.radians(key[2])
            ca, sa = math.cos(th), math.sin(th)
        if stale:
            self._mesh_t = now_m
            dpr = self.dpr
            cache = QPixmap(int((self.cw + 2 * pad) * dpr), int((self.ch + 2 * pad) * dpr))
            cache.setDevicePixelRatio(dpr)
            cache.fill(Qt.GlobalColor.transparent)
            pix = self._cur_pix()
            cp = QPainter(cache)
            # sans anticrénelage : les cases se touchent exactement (pas de lignes visibles)
            cp.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
            cp.translate(pad, pad)
            V = self.mesh["verts"]
            pts = []
            for row in V:
                r2 = []
                for (x, y, wr, wh, wa) in row:
                    nx, ny = x + ax * wr, y + ay * wr
                    if wh > 0:                                 # rotation de la tête autour du cou
                        rx, ry = nx - piv.x(), ny - piv.y()
                        nx += (piv.x() + rx * ca - ry * sa - nx) * wh
                        ny += (piv.y() + rx * sa + ry * ca - ny) * wh
                    r2.append(QPointF(nx + key[3] * wa, ny + key[4] * wa))
                pts.append(r2)
            for i, j, src in self.mesh["cells"]:
                a = QPolygonF([QPointF(V[j][i][0], V[j][i][1]), QPointF(V[j][i + 1][0], V[j][i + 1][1]),
                               QPointF(V[j + 1][i + 1][0], V[j + 1][i + 1][1]),
                               QPointF(V[j + 1][i][0], V[j + 1][i][1])])
                b = QPolygonF([pts[j][i], pts[j][i + 1], pts[j + 1][i + 1], pts[j + 1][i]])
                tr = QTransform()
                if not QTransform.quadToQuad(a, b, tr):
                    continue
                cp.save()
                cp.setTransform(tr, True)
                cp.drawPixmap(src, pix, QRectF(src.x() * dpr, src.y() * dpr, src.width() * dpr,
                                               src.height() * dpr))
                cp.restore()
            cp.end()
            self._mesh_cache, self._mesh_key = cache, key
        p.drawPixmap(-pad, -pad, self._mesh_cache)
        f = self.mesh["face"] if relief_on else 0.0
        return (QPointF(ax * f / self.scale, ay * f / self.scale), key[2],
                QPointF(piv.x() / self.scale, piv.y() / self.scale))

    # ---------- tenues
    def list_outfits(self, cdir=None):
        tdir = Path(cdir or self.char_dir) / "tenues"
        out = []
        if tdir.exists():
            for d in sorted(tdir.iterdir()):
                try:
                    o = json.loads((d / "tenue.json").read_text())
                    o["_dir"], o["_slug"] = str(d), d.name
                    out.append(o)
                except Exception:
                    pass
        return out

    def _season(self):
        m = datetime.date.today().month
        return "hiver" if m in (12, 1, 2) else "ete" if m in (6, 7, 8) else "mi"

    def _pick_outfit(self):
        outfits = self.list_outfits()
        mode = self.cfg.get("tenue", "auto")
        if mode == "base" or not outfits:
            return None
        if mode != "auto":
            return next((o for o in outfits if o["_slug"] == mode), None)
        lieu = self.cfg.get("lieu", "")
        weather = getattr(self, "weather", "soleil")
        hour = datetime.datetime.now().hour
        outdoor = lieu and lieux and lieu not in lieux.INTERIEUR
        now = datetime.datetime.now()
        tests = [("lieu:" + lieu, bool(lieu)),
                 ("jeu", self.cfg.get("profil") == "jeu"),
                 ("concentration", self.in_focus()),
                 ("musique", bool(getattr(self, "music_playing", False))),
                 ("pluie", weather in ("pluie", "orage") and (outdoor or not lieu)),
                 ("nuit", hour >= 22 or hour < 7),
                 ("soir", 19 <= hour < 22),
                 ("matin", 7 <= hour < 10),
                 ("weekend", now.weekday() >= 5),
                 ("halloween", (now.month == 10 and now.day >= 24) or (now.month == 11 and now.day == 1)),
                 ("noel", now.month == 12 and 15 <= now.day <= 27),
                 ("hiver", self._season() == "hiver"),
                 ("ete", self._season() == "ete")]
        for quand, ok in tests:
            if ok:
                for o in outfits:
                    if o.get("quand") == quand:
                        return o
        return None

    def change_outfit(self, mode=None, announce=True):
        if mode is not None:
            self.cfg["tenue"] = mode
            save_config(self.cfg)
        old = self.outfit["_slug"] if self.outfit else ""
        old_h, old_scale = self.src.height(), self.scale
        self._load_character()
        new = self.outfit["_slug"] if self.outfit else ""
        if new == old and mode is None:
            return
        g = self.geometry()
        anchor = QPoint(g.center().x(), g.bottom())
        self._apply_scale(old_scale * old_h / max(1, self.src.height()), keep_anchor=False)
        self.move(anchor.x() - self.W // 2, anchor.y() - self.H + 1)
        self._clamp_on_screen()
        self._rebuild_menus()
        if announce:
            self.react = ("salut", time.monotonic())
            self._spawn("etoile", 3)
            self.say_from("tenue")

    def next_outfit(self):
        """Armoire : passe à la tenue suivante."""
        slugs = ["base"] + [o["_slug"] for o in self.list_outfits()]
        cur = self.outfit["_slug"] if self.outfit else "base"
        nxt = slugs[(slugs.index(cur) + 1) % len(slugs)] if cur in slugs else "base"
        if len(slugs) == 1:
            self.say("Je n'ai qu'une tenue pour l'instant… Ajoute-m'en dans clic droit, Tenues !")
            return
        self.change_outfit(nxt)

    def _auto_outfit(self):
        if self.cfg.get("tenue", "auto") == "auto" and self.list_outfits():
            want = self._pick_outfit()
            cur = self.outfit["_slug"] if self.outfit else ""
            if (want["_slug"] if want else "") != cur:
                self.change_outfit()

    def add_outfit(self, path=None):
        self._import_mode = "tenue"
        self.new_character(path)

    def set_outfit_when(self, slug, quand):
        """Change le moment où une tenue est mise (soir, musique, mode jeu…)."""
        f = (Path(self.char_dir) / "tenues" / slug / "tenue.json")
        try:
            data = json.loads(f.read_text())
            data["quand"] = quand
            f.write_text(json.dumps(data, indent=2, ensure_ascii=False))
        except Exception as e:
            return self.say(f"Je n'ai pas pu changer ça : {str(e)[:80]}")
        if self.cfg.get("tenue", "auto") == "auto":
            self._auto_outfit()
        self._rebuild_menus()

    def delete_outfit(self, slug):
        d = (Path(self.char_dir) / "tenues" / slug).resolve()
        if d.parent != (Path(self.char_dir) / "tenues").resolve():
            return
        if QMessageBox.question(None, "Supprimer", "Supprimer cette tenue ?") != QMessageBox.StandardButton.Yes:
            return
        shutil.rmtree(d, ignore_errors=True)
        if self.cfg.get("tenue") == slug:
            self.cfg["tenue"] = "auto"
        self.change_outfit(self.cfg.get("tenue", "auto"), announce=False)

    def _finish_new_outfit(self, img):
        img = tidy_image(img)
        k = img.height() / max(1, self.src.height())
        e, m = self.char_base["eyes"], self.char_base["mouth"]
        ne, mouth = self.anim_eyes_n(), self.char_base.get("bouche", True) is not False
        pts = [(x["x"] * k, x["y"] * k) for x in e[:ne]] + ([(m["x"] * k, m["y"] * k)] if mouth else [])
        if not pts:
            pts = [((e[0]["x"] + e[1]["x"]) / 2 * k, e[0]["y"] * k)]
        dlg = CharacterDialog(img, "Nouvelle tenue", "", pts, outfit=True, face_mode=(ne, mouth))
        dlg.setWindowTitle("Nouvelle tenue — vérifie les yeux et la bouche")
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        labels = [lab for _, lab in TENUE_QUAND]
        lab, ok = QInputDialog.getItem(None, "Quand la porter ?", "Elle mettra cette tenue :", labels, 0, False)
        if not ok:
            return
        quand = TENUE_QUAND[labels.index(lab)][0]
        data = dlg.result_data()
        name = data["name"]
        slug = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-") or "tenue"
        tdir = Path(self.char_dir) / "tenues"
        d = tdir / slug
        n = 2
        while d.exists():
            d = tdir / f"{slug}-{n}"
            n += 1
        d.mkdir(parents=True)
        img.save(str(d / "character.png"))
        make_hitmask(img).save(str(d / "hitmask.png"))
        tenue = {"name": name, "quand": quand, "image": "character.png", "hitmask": "hitmask.png",
                 "eyes": data["eyes"], "mouth": data["mouth"], "skin_sample": data["skin_sample"],
                 "zones": data["zones"], "cut_bottom": img.text("cut") == "1"}
        (d / "tenue.json").write_text(json.dumps(tenue, indent=2, ensure_ascii=False))
        self.change_outfit(d.name if quand == "manuel" else "auto")

    def _place_initially(self):
        pos = self.cfg.get("pos")
        screen = self.app.primaryScreen().availableGeometry()
        if pos:
            self.move(int(pos[0]), int(pos[1]))
        else:
            self.move(screen.right() - self.W - 30, screen.bottom() - self.H)
        self._clamp_on_screen()

    def _clamp_on_screen(self):
        """Garde tout le personnage visible (utile après un changement de taille ou d'image)."""
        scr = self.app.screenAt(self.geometry().center()) or self.app.primaryScreen()
        a = scr.availableGeometry()
        top_char = self.y() + BUBBLE_AREA // 2          # la zone de bulle peut dépasser un peu
        x = min(max(self.x(), a.left() - self.margin), a.right() - self.W + self.margin)
        y = self.y()
        if self.y() + self.H > a.bottom() + 1:
            y = a.bottom() + 1 - self.H
        if top_char < a.top():
            y = a.top() - BUBBLE_AREA // 2
        if (x, y) != (self.x(), self.y()):
            self.move(x, y)

    def set_ghost(self, on, told=False):
        """Mode fantôme : à moitié transparente et les clics la traversent. On explique toujours comment en sortir,
        car on ne peut plus cliquer sur elle."""
        self.cfg["ghost"] = bool(on)
        save_config(self.cfg)
        self._apply_flags()
        self._rebuild_menus()
        if on:
            self.say("Mode fantôme : je suis transparente et tes clics me traversent. Pour me rendre normale : "
                     "clic sur mon icône près de l'horloge → 👻 Sortir du mode fantôme, ou dis-moi "
                     "« sors du mode fantôme ».")
        elif not told:
            self.say("Me revoilà en entier ! Tu peux de nouveau cliquer sur moi.")

    def _apply_flags(self, show=True):
        # KDE cache les fenêtres « outil » d'une appli inactive : c'est ce qui la faisait
        # disparaître au clic. En X11 (run.sh), au premier plan, on la place donc hors du
        # gestionnaire de fenêtres : elle reste visible et au-dessus, sans jamais voler le focus.
        f = Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowDoesNotAcceptFocus
        managed = QApplication.platformName() == "xcb" and self.cfg.get("fenetre_geree")
        if managed:
            # fenêtre normale gérée par KDE : on peut lui glisser des fichiers dessus
            f |= Qt.WindowType.WindowStaysOnTopHint
        elif QApplication.platformName() == "xcb" and self.cfg["on_top"]:
            f |= Qt.WindowType.X11BypassWindowManagerHint | Qt.WindowType.WindowStaysOnTopHint
        elif self.cfg["on_top"]:
            f |= Qt.WindowType.Tool | Qt.WindowType.WindowStaysOnTopHint
        else:
            f |= Qt.WindowType.Tool
        if self.cfg["ghost"]:
            f |= Qt.WindowType.WindowTransparentForInput
        self.setWindowFlags(f)
        self.setWindowOpacity(0.55 if self.cfg["ghost"] else 1.0)
        if managed:
            xin = self.__dict__.get("xin") or X11InputShape()
            self.__dict__["xin"] = xin
            if xin.ok:
                xin.managed_props(int(self.winId()))
        if show:
            self.show()
            QTimer.singleShot(50, self._update_mask)      # nouvelle fenêtre native : on réapplique

    # ---------- masque (les clics passent à travers le vide)
    def _bubble_rect(self):
        if self.__dict__.get("_think") is not None and self._think_visible(time.monotonic()):
            return self._think_rect()
        if not self.bubble_text:
            return None
        font = self._bubble_font()
        fm = QFontMetrics(font)
        maxw = self.W - 24
        lo, hi = 4.0, None                                 # la barre en colonne est ouverte : on l'évite
        b = self.__dict__.get("input_box")
        if b is not None and getattr(b, "colonne", False) and b.isVisible():
            bl = b.x() - self.x()
            if bl >= self.char_cx:
                hi = bl - 6.0
            else:
                lo = max(lo, bl + b.width() + 6.0)
            maxw = max(140, min(maxw, int((hi if hi is not None else self.W - 4) - lo)))
        rb = self.__dict__.get("ronds_bar")                # longue colonne de ronds qui monte jusqu'à la bulle
        if rb is not None and rb.isVisible() and rb.y() - self.y() < BUBBLE_AREA + int(self.ch * 0.02) - 10:
            bl = rb.x() - self.x()
            if bl >= self.char_cx:
                hi = min(hi, bl - 6.0) if hi is not None else bl - 6.0
            else:
                lo = max(lo, bl + rb.width() + 6.0)
            maxw = max(140, min(maxw, int((hi if hi is not None else self.W - 4) - lo)))
        br = fm.boundingRect(QRect(0, 0, maxw - 28, 1000),
                             Qt.TextFlag.TextWordWrap, self.bubble_text)
        w = min(maxw, br.width() + 28)
        h = min(BUBBLE_AREA - 30, br.height() + 20)
        head_y = BUBBLE_AREA + int(self.ch * 0.02)
        x = min(max(4.0, self.char_cx - w / 2), self.W - w - 4)
        if hi is not None:
            x = max(4.0, min(x, hi - w))
        x = max(x, min(lo, self.W - w - 4))
        return QRectF(x, head_y - h - 22, w, h)

    def _update_mask(self):
        xin = self.__dict__.get("xin")
        if xin and xin.ok and self.isVisible() and not self.cfg.get("ghost"):
            if self.__dict__.get("_had_mask"):
                self.clearMask()
                self._had_mask = False
            dpr = self.devicePixelRatioF()
            if self.__dict__.get("big_motion"):
                rects = [(0, 0, self.W, self.H)]
            elif self.__dict__.get("scene"):
                sc = self.scene.toAlignedRect()
                rects = [(sc.x(), sc.y(), sc.width(), sc.height())]
            else:
                rects = list(self.char_rects)
                hr = self._held_rect() if self.__dict__.get("_objs") is not None else None
                if hr:
                    hr = hr.toAlignedRect()
                    rects.append((hr.x(), hr.y(), hr.width(), hr.height()))
                b = self._bubble_rect()
                if b:
                    br = b.toAlignedRect().adjusted(-4, -4, 4, 18)
                    rects.append((br.x(), br.y(), br.width(), br.height()))
                rr = self._rings_rect()
                if rr:
                    rr = rr.toAlignedRect()
                    rects.append((rr.x(), rr.y(), rr.width(), rr.height()))
                pet = self.__dict__.get("pet")
                if pet and pet.x is not None:
                    pr = pet.rect().toAlignedRect().adjusted(-4, -4, 4, 4)
                    rects.append((pr.x(), pr.y(), pr.width(), pr.height()))
            if dpr != 1:
                rects = [(x * dpr, y * dpr, w * dpr, h * dpr) for x, y, w, h in rects]
            try:
                xin.apply(int(self.winId()), rects)
                return
            except Exception as e:
                print("Zone de clic X11 :", e, file=sys.stderr)
                xin.ok = False
        self._had_mask = True
        if self.__dict__.get("scene") and not self.__dict__.get("big_motion"):
            r = QRegion(self.scene.toAlignedRect())
            b = self._bubble_rect()
            if b:
                r = r.united(QRegion(b.toAlignedRect().adjusted(-2, -2, 2, 16)))
            self.setMask(r)
            return
        if self.__dict__.get("big_motion"):
            # pendant un grand mouvement (danse, inclinaison) : toute la fenêtre
            self.setMask(QRegion(self.rect()))
            return
        r = QRegion(self.char_region)
        b = self._bubble_rect()
        if b:
            r = r.united(QRegion(b.toAlignedRect().adjusted(-2, -2, 2, 16)))
        rr = self._rings_rect()
        if rr:
            r = r.united(QRegion(rr.toAlignedRect()))
        pet = self.__dict__.get("pet")
        if pet and pet.x is not None:
            r = r.united(QRegion(pet.rect().toAlignedRect().adjusted(-4, -4, 4, 4)))
        self.setMask(r)

    # ---------- animation
    def _tick(self):
        now = time.monotonic()
        if self.blink_start is None and now >= self.next_blink:
            self.blink_start = now
        if self.blink_start is not None and now - self.blink_start > 0.16:
            self.blink_start = None
            # parfois un double clignement
            self.next_blink = now + (0.25 if random.random() < 0.15 else random.uniform(2.5, 6))
        if self.bubble_text and now > self.bubble_until and not self._talking(now):
            self.bubble_text = ""
            self._update_mask()
        if now - self.__dict__.get("_res_chk", 0) > 3:      # petits ronds des ressources : on (re)lance la mesure
            self._res_chk = now
            if self._res_wanted():
                self._start_res_watch()
        self._rings_watch(now)
        rk = self._rings_rect()
        tv = (self._think_visible(now), (self._res or {}).keys().__len__(),
              None if rk is None else (round(rk.x()), round(rk.width())))
        if tv != self.__dict__.get("_think_state"):          # bulle « je réfléchis » apparue / changée
            self._think_state = tv
            self._update_mask()
        # petit sourire de temps en temps
        if not self.sleeping and now > self.next_smile:
            mood = self.cfg.get("mood", 70)
            if mood >= 30:
                self.happy_until = now + 1.1
                if mood > 85:
                    self._spawn("coeur", 1, 0.5)
            self.next_smile = now + (random.uniform(20, 60) if mood > 85 else random.uniform(40, 120))
        # danse sur la musique
        if (self.music_playing and self.cfg.get("music_dance", True) and not self.react
                and not self.drag and not self._talking(now) and now > self.next_music_move):
            if self.sleeping:
                self.sleeping = False
            self.react = (random.choice(["fredonne", "pieds", "fredonne"]), now)
            self.happy_until = now + 1.5
            self._spawn("note", 2)
            self.next_music_move = now + REACT_LEN.get(self.react[0], 1.8) + random.uniform(0.2, 1.5)
        # s'endort quand on la laisse seule longtemps
        if (self.cfg.get("sleepy") and not self.sleeping and not self._talking(now)
                and not self.bubble_text and now - self.last_interaction > 20 * 60):
            self.sleeping = True
        # inclinaison quand on la traîne
        target = max(-7.0, min(7.0, -self.drag_vx * 0.35))
        self.drag_tilt += (target - self.drag_tilt) * 0.2
        self.drag_vx *= 0.75
        # elle se penche doucement vers la souris (sous Wayland/KDE : position donnée par KWin)
        cur = curseur.pos() if curseur else QCursor.pos()
        g = self.geometry()
        dxm = cur.x() - g.center().x()
        near = abs(dxm) < 700 and abs(cur.y() - g.center().y()) < 600
        target = max(-2.2, min(2.2, dxm / 300)) if (near and not self.sleeping) else 0.0
        self.lean += (target - self.lean) * 0.05
        # regard : vers la souris si elle est proche, sinon coups d'œil au hasard
        h = self._head_point()
        hx, hy = g.left() + h.x(), g.top() + h.y()
        vx, vy = cur.x() - hx, cur.y() - hy
        dist = math.hypot(vx, vy)
        if dist < 900 and dist > 1:
            k = min(1.0, dist / 250)
            tgt = QPointF(vx / dist * k, vy / dist * k)
        else:
            if now > self.next_glance:
                self.next_glance = now + random.uniform(1.5, 5)
                self.glance = random.choice([QPointF(0, 0), QPointF(0, 0),
                                             QPointF(random.uniform(-1, 1), random.uniform(-0.6, 0.6))])
                fr = self._friend_dir(hx, hy)
                if fr is not None and random.random() < 0.55:
                    self.glance = fr
            tgt = self.glance
            if now < getattr(self, "look_friend_until", 0):
                fr = self._friend_dir(hx, hy)
                if fr is not None:
                    tgt = fr
        self.gaze = QPointF(self.gaze.x() + (tgt.x() - self.gaze.x()) * 0.18,
                            self.gaze.y() + (tgt.y() - self.gaze.y()) * 0.18)
        if cur != self._cursor[0]:
            self._cursor = (cur, now)
        if self.sq:
            self._sq_pump()
        if self.is_speaking(now):
            self.speak_end = now
        pet_active = False
        if self.pet:
            pet_active = self.pet.update(1.0 / max(1, self._fps_now), self.W, BUBBLE_AREA + self.ch - 2,
                                         max(14.0, self.ch * 0.045), self.sleeping, now)
            if abs(self.pet.x - getattr(self, "_pet_mask_x", -1e9)) > self.pet.size * 0.6:
                self._pet_mask_x = self.pet.x
                self.mask_timer.start(60)
        self._perch_moving = False
        if self.perch_target and not self.drag and not self.walk:
            tx, ty = self.perch_target
            dx_, dy_ = tx - self.x(), ty - self.y()
            if abs(dx_) > 1 or abs(dy_) > 1:
                if abs(dx_) + abs(dy_) > 250 and self.hop_start is None:
                    self.hop_start = now
                def step(d):
                    st = round(d * 0.25)
                    return st if st else (1 if d > 0 else -1 if d < 0 else 0)
                self.move(self.x() + step(dx_), self.y() + step(dy_))
                self._perch_moving = True
        # promenade le long de l'écran
        self._walk_step(now)
        self._run_actions(now)
        # petites animations quand elle s'ennuie
        if (now > self.next_idle_anim and not self.sleeping and not self.react
                and not self._talking(now) and not self.drag):
            self._idle_anim(now)
        # particules
        self.particles = [q for q in self.particles if now - q["born"] < q["life"]]
        big = (bool(self.react) or abs(self.drag_tilt) > 0.4 or bool(self.drag and self.drag[2])
               or bool(self.particles) or self.yawn_start is not None)
        if big != self.big_motion:
            self.big_motion = big
            self._update_mask()
        # cadence adaptative : fluide quand il se passe quelque chose, économe au repos
        active = (big or bool(getattr(self, "l2d", None)) or pet_active or bool(self.sq) or self._perch_moving or self.walk or self.actions or self._talking(now) or self.blink_start is not None or now < self.happy_until
                  or abs(self.hair[1]) > 0.15 or abs(self.hair[3]) > 0.15
                  or abs(self.gaze.x() - getattr(self, "_last_gx", 0)) > 0.03
                  or (self.music_playing and self.cfg.get("music_dance", True))
                  or (self.lieu_obj is not None and (self.lieu_obj.ball["y"] > 0 or abs(self.lieu_obj.ball["vu"]) > 0.02)))
        self._last_gx = self.gaze.x()
        self._adapt(now)
        fps = self._q()["fps"]
        want = fps[0] if active else fps[1]
        if self.fs_hidden:
            want = 2                       # caché derrière un jeu plein écran : presque rien
        if want != self._fps_now:
            self._fps_now = want
            self.anim.setInterval(1000 // want)
        self.update()

    def _walk_step(self, now):
        if self.lieu_obj:
            self.lieu_obj.update(1.0 / max(1, self._fps_now))
        if self.walk:
            if self.drag or self.sleeping or self.mic_proc:
                self._end_walk()
                return
            w = self.walk
            k = min(1.0, (now - w["start"]) / w["dur"])
            ease = k * k * (3 - 2 * k)
            x = w["x0"] + (w["x1"] - w["x0"]) * ease
            if w.get("inner"):
                self.char_cx = x
            else:
                self.move(int(x), self.y())
            if k >= 1.0:
                then = w.get("then")
                self._end_walk()
                if self.actions:
                    self.next_walk = time.monotonic() + random.uniform(20, 60)
                if then and self.scene:
                    self._use_object(then, by_her=True)
            return
        if (self.scene and now > self.next_walk and not self.drag and not self.sleeping
                and not self.react and not self._talking(now) and not self.mic_proc and not self.bubble_text
                and not (self.input_box and self.input_box.isVisible())):
            self._visit_object(now)
            return
        if self.scene:
            return
        if (not self.cfg.get("walk") or now < self.next_walk or self.drag or self.sleeping
                or self.react or self._talking(now) or self.mic_proc or self.bubble_text
                or (self.input_box and self.input_box.isVisible())):
            return
        scr = (self.app.screenAt(self.geometry().center()) or self.app.primaryScreen()).availableGeometry()
        lo, hi = scr.left() - self.margin, scr.right() - self.W + self.margin
        if hi - lo < 120:
            self.next_walk = now + 60
            return
        for _ in range(8):
            x1 = random.randint(lo, hi)
            if abs(x1 - self.x()) > 140:
                break
        dist = abs(x1 - self.x())
        self.walk = {"x0": self.x(), "x1": x1, "start": now, "dur": max(1.5, dist / 75.0)}

    def _end_walk(self):
        inner = self.walk and self.walk.get("inner")
        self.walk = None
        self.next_walk = time.monotonic() + (random.uniform(20, 60) if inner else random.uniform(30, 120))
        self.react = ("atterrissage", time.monotonic())
        self.cfg["pos"] = [self.x(), self.y()]

    def _talking(self, now):
        return self.lip_env and now - self.lip_start < len(self.lip_env) / FPS

    def _mouth_open(self, now):
        if not self._talking(now):
            return 0.0
        i = int((now - self.lip_start) * FPS)
        v = self.lip_env[i] if i < len(self.lip_env) else 0
        return 0 if v < 0.12 else min(1.0, v)

    def _blink_amount(self, now):
        if self.blink_start is None:
            return 0.0
        d = (now - self.blink_start) / 0.16
        return max(0.0, 1 - abs(d * 2 - 1))

    def paintEvent(self, e):
        t0 = time.perf_counter()
        self._paint(e)
        ms = (time.perf_counter() - t0) * 1000
        self.frame_ms = self.frame_ms * 0.9 + ms * 0.1

    def _paint(self, _):
        now = time.monotonic()
        t = now - self.t0
        self._expr_now = self._pick_expr(now)
        p = QPainter(self)
        p.setRenderHints(QPainter.RenderHint.Antialiasing
                         | QPainter.RenderHint.SmoothPixmapTransform)

        if self.sleeping:
            breath = 1.4 * math.sin(t * 2 * math.pi / 6.0)
        else:
            breath = math.sin(t * 2 * math.pi / 4.2)
        sway = math.sin(t * 2 * math.pi / 7.3)
        hop = dx = 0.0
        rot = sway * 0.7 + self.drag_tilt + self.lean
        sy = 1.0
        sx = 1.0
        talking = self._talking(now)
        if talking:                      # elle hoche un peu la tête en parlant
            mo = self._mouth_open(now)
            rot += 0.5 * math.sin(t * 3.1)
            sy += 0.005 * mo
        if self.walk:                    # petits pas
            ph = (now - self.walk["start"]) * 2 * math.pi * 1.8
            hop = -5 * abs(math.sin(ph))
            rot += 1.8 * math.sin(ph) + (1.5 if self.walk["x1"] > self.walk["x0"] else -1.5)
        if now < self.angry_until:       # elle trépigne
            dx += 2.5 * math.sin(t * 40)
        if self.hop_start is not None:
            d = now - self.hop_start
            if d < 0.9:
                hop = -HOP_HEIGHT * math.exp(-d * 4) * abs(math.sin(d * 11))
            else:
                self.hop_start = None
        if self.react:
            kind, st = self.react
            d = now - st
            if d > REACT_LEN.get(kind, 1.8):
                self.react = None
            elif kind == "tete":        # petite caresse : elle se tasse un peu
                sy -= 0.03 * abs(math.sin(d * 6)) * math.exp(-d * 1.5)
            elif kind == "cheveux":     # elle penche la tête d'un côté à l'autre
                rot += 2.2 * math.sin(d * 7) * math.exp(-d * 2)
            elif kind == "main":        # coucou : balancement rapide
                rot += 1.8 * math.sin(d * 14) * math.exp(-d * 2.5)
            elif kind == "epaule":      # sursaut
                hop = -HOP_HEIGHT * 1.4 * math.exp(-d * 4) * abs(math.sin(d * 9))
            elif kind == "pieds":       # petite danse
                k = 1 - d / 1.8
                dx = 9 * math.sin(d * 9) * k
                hop = -6 * abs(math.sin(d * 9)) * k
                rot += 2 * math.sin(d * 9) * k
            elif kind == "joue":        # timide : elle se tortille
                rot += 1.5 * math.sin(d * 5) * math.exp(-d)
                sy -= 0.015 * math.exp(-d * 2)
            elif kind == "nez":         # boop : petit recul rapide
                rot += 1.2 * math.sin(d * 25) * math.exp(-d * 5)
                sy -= 0.02 * math.exp(-d * 6)
            elif kind == "bras":        # elle se tourne un peu
                rot += 2.5 * math.sin(d * 4) * math.exp(-d * 1.5)
            elif kind == "accessoire":  # fière : petit saut et pose
                hop = -HOP_HEIGHT * 0.8 * math.exp(-d * 5) * abs(math.sin(d * 10))
                rot += 1.5 * math.sin(d * 3) * math.exp(-d)
            elif kind == "etirement":   # s'étire vers le haut
                k = math.sin(math.pi * min(1.0, d / 1.8))
                sy += 0.045 * k
                sx -= 0.012 * k
            elif kind == "regarde":     # regarde à gauche puis à droite
                rot += 2.0 * math.sin(d * math.pi / 0.9) * (1 if d < 1.8 else 0)
            elif kind == "fredonne":    # se balance en rythme
                rot += 1.6 * math.sin(d * 7)
                hop = -3 * abs(math.sin(d * 7))
            elif kind == "vertige":     # tourne de l'œil
                k = math.exp(-d * 1.2)
                rot += 3.5 * math.sin(d * 9) * k
                dx += 5 * math.cos(d * 9) * k
            elif kind == "atterrissage":
                sy -= 0.06 * math.exp(-d * 6) * abs(math.cos(d * 14))
                sx += 0.03 * math.exp(-d * 6) * abs(math.cos(d * 14))
            elif kind == "salut":       # coucou en arrivant
                rot += 2.2 * math.sin(d * 12) * math.exp(-d * 1.8)
                hop = -HOP_HEIGHT * 0.6 * math.exp(-d * 4) * abs(math.sin(d * 8))
            elif kind == "caresse":
                sy -= 0.02 * abs(math.sin(d * 5))
                rot += 0.8 * math.sin(d * 5)
            elif kind == "assise":      # elle s'assoit un moment
                k = min(1.0, d / 0.4) * min(1.0, max(0.0, (REACT_LEN["assise"] - d) / 0.4))
                sy -= 0.07 * k
                hop += 0.05 * self.ch * k

        base_x, base_y = self.char_cx, BUBBLE_AREA + self.ch
        if self.scene:
            frame = QPainterPath()
            frame.addRoundedRect(self.scene, 16, 16)
            p.save()
            p.setClipPath(frame)
            self.lieu_obj.draw_back(p, self.scene, t, datetime.datetime.now().hour)
            p.restore()
        if self.has_shadow:                 # ombre au sol, plus petite quand elle saute
            k = max(0.5, 1 + hop / 60)
            c = QPointF(base_x + dx, base_y - 3)
            gsh = QRadialGradient(c, self.cw * 0.34 * k)
            gsh.setColorAt(0, QColor(0, 0, 0, int(95 * k)))
            gsh.setColorAt(1, QColor(0, 0, 0, 0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(gsh)
            p.drawEllipse(c, self.cw * 0.34 * k, 7 * k)
        self._draw_objects(p, front=False)
        p.save()
        p.translate(base_x + dx, base_y + hop)
        p.rotate(rot)
        p.scale((1 + 0.004 * breath) * sx, (1 + 0.008 * breath) * sy)
        p.translate(-self.cw / 2, -self.ch)
        self._physics(now, t, rot, dx, hop)
        face_off, head_ang, piv = self._draw_body(p, t)
        p.scale(self.scale, self.scale)          # repère = pixels de l'image d'origine
        p.translate(face_off)                    # le visage suit le relief…
        if head_ang:                             # … et l'inclinaison de la tête
            p.translate(piv)
            p.rotate(head_ang)
            p.translate(-piv)
        if not getattr(self, "l2d", None):         # Live2D : yeux et bouche dessinés par le modèle
            expr = self._expr_now
            if not expr:
                self._draw_irises(p)
            if expr != "timide":
                self._draw_blush(p, now)
            yawn = 0.0
            if self.yawn_start is not None:
                d = now - self.yawn_start
                if d > 2.4:
                    self.yawn_start = None
                else:
                    yawn = math.sin(math.pi * d / 2.4)
            if self.sleeping:
                self._draw_eyes(p, 1.0)
                self._draw_zzz(p, t)
            elif expr:                                  # l'image d'expression a déjà ses yeux
                pass
            elif now < self.dizzy_until:
                self._draw_dizzy_eyes(p, t)
            elif now < self.happy_until:
                self._draw_eyes(p, 1.0, happy=True)
            elif yawn > 0:
                self._draw_eyes(p, min(1.0, 0.4 + yawn))
            elif now < self.wink_until:
                self._draw_eyes(p, 1.0, only=self.wink_eye)
            else:
                droop = 0.3 if (self.cfg.get("mood", 70) < 30 or now < self.sad_until) else 0.0
                self._draw_eyes(p, max(droop, self._blink_amount(now)))
            if expr and not talking:
                pass
            elif yawn > 0 and not talking:
                self._draw_mouth(p, min(1.6, yawn * 1.6), round_o=True)
            elif not talking and now < self.surprise_until:
                self._draw_mouth(p, 0.6, round_o=True)
            else:
                self._draw_mouth(p, self._mouth_open(now))
        if self.fete and self.cfg.get("fetes", True) and not (self.char.get("kawaii") and self.fete in
                                                              ("noel", "halloween") and self.outfit):
            e = self.char["eyes"]
            extras.draw_fete(p, self.fete, (e[0]["x"] + e[1]["x"]) / 2, (e[0]["y"] + e[1]["y"]) / 2,
                             self.eye_dist, t)
        p.restore()
        if self.pet:
            self.pet.draw(p, now)

        self._draw_objects(p, front=True)
        if self.scene:
            p.save()
            p.setClipPath(frame)
            self.lieu_obj.draw_front(p, self.scene, t, datetime.datetime.now().hour,
                                     self.char.get("cut_bottom", False))
            self.lieu_obj.draw_weather(p, self.scene, t, datetime.datetime.now().hour)
            p.restore()
            p.setPen(QPen(QColor(255, 255, 255, 200), 3))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(frame)
        self._draw_particles(p, now)
        self._draw_rings(p)
        if self._think_visible(now):                 # « … » remplacé par la bulle « je réfléchis »
            self._draw_thinking(p, now)
        elif self.bubble_text:
            self._draw_bubble(p)
        p.end()

    def _head_point(self):
        e = self.char["eyes"]
        return QPointF(self.char_cx - self.cw / 2 + (e[0]["x"] + e[1]["x"]) / 2 * self.scale,
                       BUBBLE_AREA + (e[0]["y"] + e[1]["y"]) / 2 * self.scale)

    def _spawn(self, kind, n=1, spread=1.0):
        if self.cfg.get("a11y_mouvement") or (self.battery_saving() and n > 1):
            n = 1 if not self.cfg.get("a11y_mouvement") else 0
        h = self._head_point()
        d = self.eye_dist * self.scale
        now = time.monotonic()
        for _ in range(n):
            self.particles.append({
                "kind": kind, "born": now + random.uniform(0, 0.4 * (n > 1)),
                "life": random.uniform(1.2, 1.9),
                "x": h.x() + random.uniform(-1.4, 1.4) * d * spread,
                "y": h.y() - d * random.uniform(0.6, 1.4),
                "vx": random.uniform(-12, 12), "vy": random.uniform(-45, -25),
                "size": d * random.uniform(0.35, 0.55) + 6,
                "t": {"note": random.choice(["♪", "♫"]), "etoile": "✦", "exclam": "!",
                      "spirale": "@"}.get(kind, "?"),
            })
        self.big_motion = True
        self._update_mask()

    def _spawn_at(self, kind, x, y, n=1, fall=False):
        if self.cfg.get("a11y_mouvement"):
            return
        now = time.monotonic()
        d = self.eye_dist * self.scale
        for _ in range(n):
            self.particles.append({
                "kind": kind, "born": now + random.uniform(0, 0.3 * (n > 1)),
                "life": random.uniform(1.4, 2.2),
                "x": x + random.uniform(-0.6, 0.6) * d, "y": y + random.uniform(-0.3, 0.3) * d,
                "vx": random.uniform(-25, 25),
                "vy": random.uniform(25, 55) if fall else random.uniform(-60, -30),
                "size": d * random.uniform(0.3, 0.45) + 6,
                "t": {"note": "♪", "etoile": "✦", "exclam": "!"}.get(kind, "?"),
            })
        self.big_motion = True
        self._update_mask()

    def _draw_particles(self, p, now):
        for q in self.particles:
            age = now - q["born"]
            if age < 0:
                continue
            k = age / q["life"]
            x = q["x"] + q["vx"] * age + 4 * math.sin(age * 5)
            y = q["y"] + q["vy"] * age
            a = int(255 * (1 - k) * min(1.0, age * 6))
            s = q["size"] * (0.7 + 0.3 * min(1.0, age * 4))
            kind = q["kind"]
            p.save()
            p.translate(x, y)
            if kind == "coeur":
                path = QPainterPath()
                path.moveTo(0, s * 0.35)
                path.cubicTo(-s * 0.6, -s * 0.05, -s * 0.35, -s * 0.55, 0, -s * 0.2)
                path.cubicTo(s * 0.35, -s * 0.55, s * 0.6, -s * 0.05, 0, s * 0.35)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(255, 80, 120, a))
                p.drawPath(path)
            elif kind == "flocon":
                p.setPen(QPen(QColor(255, 255, 255, a), 1.6))
                for k2 in range(3):
                    p.rotate(60)
                    p.drawLine(QPointF(-s * 0.3, 0), QPointF(s * 0.3, 0))
            elif kind == "feuille":
                p.rotate(age * 140 + q["x"] % 90)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(110, 170, 70, a))
                p.drawEllipse(QRectF(-s * 0.35, -s * 0.16, s * 0.7, s * 0.32))
            elif kind == "goutte":
                path = QPainterPath()
                path.moveTo(0, -s * 0.4)
                path.quadTo(s * 0.3, s * 0.05, 0, s * 0.3)
                path.quadTo(-s * 0.3, s * 0.05, 0, -s * 0.4)
                p.setPen(QPen(QColor(60, 120, 200, a), 1))
                p.setBrush(QColor(150, 200, 255, a))
                p.drawPath(path)
            elif kind == "colere":
                pen = QPen(QColor(220, 40, 40, a), max(2.0, s * 0.12))
                pen.setCapStyle(Qt.PenCapStyle.RoundCap)
                p.setPen(pen)
                r = s * 0.35
                for sxn, syn in ((-1, -1), (1, -1), (-1, 1), (1, 1)):
                    p.drawArc(QRectF(sxn * r * 0.6 - r * 0.5, syn * r * 0.6 - r * 0.5, r, r),
                              0, 16 * 360 // 4)
            elif kind == "emoji":
                f = QFont()
                f.setPixelSize(int(s))
                p.setFont(f)
                p.setOpacity(a / 255)
                p.drawText(QPointF(-s * 0.5, s * 0.35), q["t"])
            else:
                f = QFont()
                f.setBold(True)
                f.setPixelSize(int(s))
                p.setFont(f)
                col = {"note": QColor(120, 80, 200, a), "etoile": QColor(255, 190, 40, a),
                       "exclam": QColor(230, 60, 60, a), "spirale": QColor(120, 120, 220, a)}.get(
                    kind, QColor(80, 80, 80, a))
                p.setPen(col)
                p.drawText(QPointF(-s * 0.3, s * 0.35), q["t"])
            p.restore()

    def _draw_blush(self, p, now):
        if now >= self.blush_until:
            return
        a = min(1.0, (self.blush_until - now) / 0.8)
        d = self.eye_dist
        p.setPen(Qt.PenStyle.NoPen)
        for e in self.char["eyes"][:self.anim_eyes_n()]:
            c = QPointF(e["x"], e["y"] + d * 0.42)
            g = QRadialGradient(c, d * 0.32)
            g.setColorAt(0, QColor(255, 90, 110, int(110 * a)))
            g.setColorAt(1, QColor(255, 90, 110, 0))
            p.setBrush(g)
            p.drawEllipse(c, d * 0.34, d * 0.18)

    def _draw_zzz(self, p, t):
        d = self.eye_dist
        e = self.char["eyes"][1] if self.char["eyes"][1]["x"] > self.char["eyes"][0]["x"] else self.char["eyes"][0]
        f = QFont()
        f.setBold(True)
        for i in range(3):
            ph = (t * 0.35 + i / 3) % 1.0
            f.setPixelSize(max(8, int(d * (0.35 + 0.25 * ph))))
            p.setFont(f)
            p.setPen(QColor(90, 110, 200, int(230 * (1 - ph))))
            p.drawText(QPointF(e["x"] + d * (0.9 + 0.6 * ph), e["y"] - d * (0.6 + 1.4 * ph)), "z")

    def _draw_irises(self, p):
        if not self.cfg.get("eye_follow", True):
            return
        for ir in self.irises:
            if not ir:
                continue
            dx, dy = self.gaze.x() * ir["max_dx"], self.gaze.y() * ir["max_dy"]
            if abs(dx) < 0.15 and abs(dy) < 0.15:
                continue                      # regard droit : l'image d'origine suffit
            p.save()
            p.setClipPath(ir["clip"], Qt.ClipOperation.IntersectClip)
            box = QRectF(ir["box"])
            p.fillPath(ir["clip"], ir["sclera"].darker(104))
            p.drawImage(QPointF(box.left(), box.top()), ir["patch"])      # iris d'origine estompé
            p.fillPath(ir["clip"], QColor(ir["sclera"].red(), ir["sclera"].green(),
                                          ir["sclera"].blue(), 150))
            p.drawImage(QPointF(box.left() + dx, box.top() + dy), ir["patch"])
            shade = QLinearGradient(0, box.top(), 0, box.center().y())   # ombre de la paupière
            shade.setColorAt(0, QColor(self.lash.red(), self.lash.green(), self.lash.blue(), 110))
            shade.setColorAt(1, QColor(self.lash.red(), self.lash.green(), self.lash.blue(), 0))
            p.fillRect(box, shade)
            p.restore()

    def anim_eyes_n(self):
        """Combien d'yeux on anime (clignement, regard…) : 2, 1 (de profil) ou 0 (mascotte, objet…)."""
        try:
            return max(0, min(2, int(self.char.get("yeux", 2))))
        except (TypeError, ValueError):
            return 2

    def _draw_dizzy_eyes(self, p, t):
        for e, skin in zip(self.char["eyes"][:self.anim_eyes_n()], self.eye_skin):
            rect = QRectF(e["x"] - e["w"] / 2 - 1, e["y"] - e["h"] / 2 - 1, e["w"] + 2, e["h"] + 2)
            path = QPainterPath()
            path.addEllipse(rect)
            p.save()
            p.setClipPath(path)
            p.fillRect(rect, QColor(250, 245, 245))
            p.restore()
            pen = QPen(self.lash, 1.6)
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            sp = QPainterPath()
            r0 = min(rect.width(), rect.height()) / 2 - 1
            for i in range(60):            # spirale qui tourne
                a = i * 0.35 + t * 8
                r = r0 * i / 60
                pt = QPointF(rect.center().x() + r * math.cos(a), rect.center().y() + r * math.sin(a) * 0.8)
                sp.moveTo(pt) if i == 0 else sp.lineTo(pt)
            p.drawPath(sp)
            p.drawEllipse(rect)

    def _draw_eyes(self, p, c, happy=False, only=None):
        if happy:
            for e, skin in zip(self.char["eyes"][:self.anim_eyes_n()], self.eye_skin):
                rect = QRectF(e["x"] - e["w"] / 2 - 1, e["y"] - e["h"] / 2 - 1, e["w"] + 2, e["h"] + 2)
                path = QPainterPath()
                path.addEllipse(rect)
                p.save()
                p.setClipPath(path)
                p.fillRect(rect, skin)
                p.restore()
                pen = QPen(self.lash, 2.4)
                pen.setCapStyle(Qt.PenCapStyle.RoundCap)
                p.setPen(pen)
                p.setBrush(Qt.BrushStyle.NoBrush)
                arc = QPainterPath(QPointF(rect.left() + 2, rect.center().y() + rect.height() * 0.2))
                arc.quadTo(QPointF(rect.center().x(), rect.top() - rect.height() * 0.15),
                           QPointF(rect.right() - 2, rect.center().y() + rect.height() * 0.2))
                p.drawPath(arc)
            return
        if c <= 0.02:
            return
        for i, (e, skin) in enumerate(zip(self.char["eyes"][:self.anim_eyes_n()], self.eye_skin)):
            if only is not None and i != only:
                continue
            rect = QRectF(e["x"] - e["w"] / 2 - 1, e["y"] - e["h"] / 2 - 1, e["w"] + 2, e["h"] + 2)
            path = QPainterPath()
            path.addEllipse(rect)
            lid_y = rect.top() + rect.height() * c
            p.save()
            p.setClipPath(path)
            p.fillRect(QRectF(rect.left(), rect.top(), rect.width(), lid_y - rect.top()), skin)
            p.restore()
            pen = QPen(self.lash, 2.2 if c > 0.8 else 1.6)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            curve = QPainterPath(QPointF(rect.left() + 1, lid_y - 1))
            sag = 3 * c
            curve.quadTo(QPointF(rect.center().x(), lid_y + sag), QPointF(rect.right() - 1, lid_y - 1))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(curve)

    def _draw_mouth(self, p, o, round_o=False):
        if o <= 0.05 or self.char.get("bouche", True) is False:
            return
        m = self.char["mouth"]
        h = m["max_open"] * o
        w = m["w"] * (0.55 + 0.3 * o)
        if round_o:
            w = h * 0.85
        r = QRectF(m["x"] - w / 2, m["y"] - h * 0.35, w, h)
        p.setPen(QPen(QColor("#b0646a"), 0.8))
        p.setBrush(QColor("#5c1d25"))
        p.drawEllipse(r)
        if h > 4:
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#c0606a"))
            p.drawEllipse(QRectF(r.left() + w * 0.25, r.bottom() - h * 0.4, w * 0.5, h * 0.35))

    def _bubble_font(self):
        f = QFont()
        f.setPointSizeF(float(self.cfg.get("bubble_size", 10.5)) * float(self.cfg.get("a11y_texte", 1) or 1))
        return f

    def _draw_bubble(self, p):
        r = self._bubble_rect()
        path = QPainterPath()
        path.addRoundedRect(r, 14, 14)
        tail = QPainterPath()
        cx = r.center().x() + 10
        tail.moveTo(cx - 9, r.bottom() - 1)
        tail.lineTo(cx + 4, r.bottom() + 14)
        tail.lineTo(cx + 9, r.bottom() - 1)
        path = path.united(tail)
        bg, border, fg, thick = BUBBLE_THEMES.get(self.cfg.get("bubble_theme", "classique"),
                                                   BUBBLE_THEMES["classique"])
        p.setPen(QPen(QColor(*border), thick))
        p.setBrush(QColor(*bg))
        p.drawPath(path)
        p.setPen(QColor(*fg))
        p.setFont(self._bubble_font())
        p.drawText(r.adjusted(14, 10, -14, -10),
                   Qt.TextFlag.TextWordWrap | Qt.AlignmentFlag.AlignCenter, self.bubble_text)

    # ---------- parole
    REFORM = {"spontanees", "matin", "midi", "apres_midi", "soir", "nuit", "clic", "content", "boude", "matin_cafe",
              "midi_faim", "nuit_dodo", "reveil", "caresse", "zone_pieds", "musique"}

    def say_from(self, key):
        lines = self.phrases.get(key) or DEFAULT_PHRASES.get(key) or ["…"]
        lines = [l for l in lines if "je te donne l'heure" not in l] or lines      # phrase retirée (inutile)
        B = getattr(self, "brain", None)
        text = B.pick(lines) if B and self.cfg.get("anti_repetition", True) and len(lines) > 1 else random.choice(lines)
        lng = (self.cfg.get("langue", "fr") or "fr")[:2]
        if (B and key in self.REFORM and self.cfg.get("phrases_ia", True) and not self.battery_saving() and self.ollama_ok and not self.ia_remote()
                and not self.is_muted() and random.random() < 0.5 and "{" not in text and lng == "fr"):
            return self._reformulate(text, key)
        if i18n and lng != "fr":                 # phrase toute faite : dans la langue parlée
            text = i18n.tr_to(text, lng)
        prenom = self.cfg.get("prenom", "").strip()
        text = (text.replace("{heure}", heure_txt()).replace("{nom}", self.char.get("name", ""))
                .replace("{titre}", getattr(self, "music_title", "") or "ce morceau")
                .replace("{rappel}", getattr(self, "current_reminder", "") or "ton rappel")
                .replace("{meteo}", self._meteo())
                .replace("{plat}", random.choice(PLATS)))
        if "{prenom}" in text:
            text = text.replace(" {prenom}", f" {prenom}" if prenom else "").replace("{prenom}", prenom)
        elif prenom and key in ("matin", "midi", "apres_midi", "soir", "nuit", "clic", "reveil") \
                and random.random() < 0.4 and " !" in text:
            text = text.replace(" !", f", {prenom} !", 1)
        self.say(text)

    def _reformulate(self, text, key):
        """Même idée, autres mots, selon le moment : l'IA locale reformule (sinon la phrase d'origine)."""
        B = self.brain
        act = cerveau.CAT_TXT.get(B.cat, "") if B else ""
        persona = self.char.get("persona") or "une jeune femme joyeuse et bienveillante"
        prompt = (f"Tu es {self.char.get('name', 'Viki')}, {persona}, compagne de bureau. Nous sommes le {date_txt()}, il est {heure_txt()}"
                  + (f", et en ce moment {act}" if act else "") + ". Reformule cette petite phrase à ta façon, "
                  "en gardant la même idée, en une seule phrase courte, en français, sans émoji ni guillemets : "
                  + text)
        sid = self.speech_id

        def done(r):
            r = (r or "").strip().strip('"«» ').splitlines()[0] if r else ""
            if self.speech_id != sid:
                return
            if not r or len(r) > 160 or (B and B.recently(r)) or re.search(r"\b(?:reformul|phrase)\b", r, re.I):
                r = text
            self.say(r)
        self.ask_ai(prompt, done, timeout=25)

    def say(self, text):
        text = text.strip()
        if not text:
            return
        if i18n:                                 # phrases de Viki dans la langue parlée (l'IA, elle, répond déjà dans la langue)
            text = i18n.tr_to(text, self.cfg.get("langue", "fr")).strip() or text
        if getattr(self, "brain", None) and text != "…":
            self.brain.said(text)
        if text != "…" and len(text) > 2:                # tout ce qu'elle dit (pour « Ce qu'elle t'a dit »)
            h = self.__dict__.setdefault("historique", [])
            if not h or h[-1][1] != text:
                h.append((time.time(), text))
                del h[:-150]
        self.say_emotion = self._apply_emotion() if self.emotion else ""
        self.speech_id += 1
        sid = self.speech_id
        self.sq = []
        self._stop_audio()
        self.bubble_text = text if len(text) < 260 else text[:257] + "…"
        self.bubble_until = time.monotonic() + (max(3.0, len(text) * 0.07) + 2.5) * float(self.cfg.get("a11y_bulle", 1) or 1)
        self._update_mask()
        if getattr(self, "reader_active", False):  # elle lit un livre : on ne coupe pas sa lecture
            return
        if self.is_muted():                      # muet : la bulle seulement, pas de son
            self.lip_env, dur = fake_envelope(text)
            self.lip_start = time.monotonic()
            return
        parts = split_speech(text) if self._natural_on(text) else []
        voice_on = self.cfg["voice"] or self.cfg.get("a11y_voix")
        if voice_on and len(parts) > 1:      # voix naturelle : elle commence dès la 1re phrase
            for p in parts:
                self.queue_speech(p)
            return
        if voice_on and (self.piper and (self.voice_model or self.has_voice(self.cfg.get("langue", "fr")))
                         or self.espeak):
            self.synth_pending = (sid, time.monotonic())
            threading.Thread(target=self._synth, args=(sid, text), daemon=True).start()
        else:
            self.lip_env, dur = fake_envelope(text)
            self.lip_start = time.monotonic()

    def _piper_speaker_args(self):
        """Argument --speaker pour les voix Piper multi-voix (UPMC)."""
        spk = int(self.cfg.get("piper_speaker", -1))
        if spk >= 0 and self.voice_model and Path(self.voice_model).name == "fr_FR-upmc-medium.onnx":
            return ["--speaker", str(spk)]
        return []

    def _synth(self, sid, text):
        out = str(self.tmpdir / f"say{sid}.wav")
        ok, used = self._synth_file(text, out)
        if ok:
            try:
                self._env_cache = {sid: wav_envelope(out)}     # calcul lourd : ici, pas dans l'interface
            except Exception:
                self._env_cache = {}
        self.bridge.audio_ready.emit(sid, text, out if ok else "")

    def _synth_file(self, text, out):
        """Fabrique le fichier audio d'une phrase. Renvoie (réussi ?, moteur utilisé)."""
        txt = clean_for_tts(text)
        ok = False
        used = ""
        try:
            tts_lang = getattr(self, "_tts_lang", None)      # ex. : l'actu lue dans la langue de l'interface
            if self._natural_on(txt) and tts_lang in (None, "fr"):
                ok = self._synth_natural(txt, out)
                used = "naturelle" if ok else ""
                if ok:
                    self._voice_fx(out)                # vitesse et hauteur réglées : aussi pour ces voix
            lang = tts_lang or self.cfg.get("langue", "fr")
            model, spk_args = self.voice_model, self._piper_speaker_args()
            if voix and lang != "fr" and not voix.looks_french(txt):
                lp, lsp = voix.voice_for(lang, self.cfg, VOICE_DIRS)
                if lp:
                    model, spk_args = lp, (["--speaker", str(lsp)] if lsp >= 0 else [])
                    txt = re.sub(r"\[[^\]]*\]", "", txt).strip() or txt     # pas la correction en français
                else:
                    model = None          # pas de voix pour cette langue : la voix française lirait mal, espeak la lit
            elif voix and lang != "fr":
                lang = "fr"               # phrase en français : voix française (ou espeak en français)
            if not ok and self.piper and model:
                pitch = float(self.cfg.get("voix_hauteur", 1.0)) if voix else 1.0
                cmd = [self.piper, "-m", piper_model(model), "-f", out] + spk_args + (voix.piper_args(self.cfg, pitch) if voix else [])
                r = subprocess.run(cmd, input=txt.encode(), capture_output=True, timeout=60)
                ok = r.returncode == 0 and Path(out).exists()
                if not ok and voix:                     # vieux Piper sans ces options : on réessaie sans
                    r = subprocess.run([self.piper, "-m", piper_model(model), "-f", out] + spk_args, input=txt.encode(),
                                       capture_output=True, timeout=60)
                    ok = r.returncode == 0 and Path(out).exists()
                    pitch = 1.0
                if ok and voix and abs(pitch - 1) > 0.01:
                    try:
                        voix.pitch_shift(out, pitch)
                    except Exception as e:
                        print("Hauteur de voix :", e, file=sys.stderr)
                if not ok:
                    print("Piper :", r.stderr.decode(errors="ignore")[-400:], file=sys.stderr)
            if not ok and self.espeak:
                cmd, env = espeak_cmd(self.espeak, lang, out, txt)
                r = subprocess.run(cmd, capture_output=True, timeout=60, env=env)
                ok = r.returncode == 0
                used = "espeak" if ok else ""
        except Exception as e:
            print("Synthèse vocale impossible :", e, file=sys.stderr)
        if ok and used != "naturelle":
            self._voice_fx(out, pitch_speed=False)     # Piper gère vitesse et hauteur ; timbre, bruit, ambiance ici
        if used == "espeak" and not self.fallback_warned:
            self.fallback_warned = True
            print("Attention : voix de secours espeak utilisée (Piper absent ou incomplet).",
                  file=sys.stderr)
        return ok, used

    # ---------- voix naturelle (serveur Chatterbox local)
    def _default_ref(self):
        ref = self.cfg.get("voice_ref") or ""
        if ref and Path(ref).exists():
            return ref
        np_ = natural_python(kind=self._nk()) or natural_python()
        extra = [Path(np_).parents[2] / "voices"] if np_ else []
        d = next((v / "extrait_defaut.wav" for v in VOICE_DIRS + extra if (v / "extrait_defaut.wav").exists()),
                 DATA_DIR / "voices" / "extrait_defaut.wav")
        return str(d) if d.exists() else ""

    def _natural_on(self, text):
        """Voix naturelle pour ce texte ? En mode léger : les très longs textes passent à Piper,
        et après 10 min sans parler elle libère la mémoire (rechargée à la phrase suivante)."""
        if self.cfg.get("voice_engine") not in NAT_ENGINES:
            return False
        if not self.natural_ready:
            if getattr(self, "_nat_asleep", False) and not getattr(self, "_nat_waking", False):
                self._nat_waking = True
                self._start_natural()            # se recharge ; Piper parle en attendant
            return False
        if self.cfg.get("natural_mode", "leger") == "leger" and len(text) > 600 and self.piper:
            return False
        return True

    def _natural_idle_check(self):
        if self.cfg.get("voice_engine") not in NAT_ENGINES or self.cfg.get("natural_mode", "leger") != "leger":
            return
        last = getattr(self, "_nat_last", time.monotonic())
        if self.natural_ready and time.monotonic() - last > 600 and not self.sq:
            self.natural_ready = False
            threading.Thread(target=self._kill_natural_server, daemon=True).start()
            self._nat_asleep = True
            self._nat_waking = False
            print("Voix naturelle : mise en veille (mémoire libérée)", file=sys.stderr)

    def _nk(self):
        """Moteur avancé en cours (« naturelle » ou « legere »)."""
        e = self.cfg.get("voice_engine")
        return e if e in NAT_ENGINES else "naturelle"

    def _synth_natural(self, txt, out):
        self._nat_last = time.monotonic()
        self._nat_asleep = False
        e = float(self.cfg.get("expressivity", 0.5))
        emo = getattr(self, "say_emotion", "")
        if emo in ("joie", "surprise"):
            e = min(1.0, e + 0.2)
        elif emo in ("triste", "boude"):
            e = max(0.25, e - 0.15)
        ref = self._prepared_ref(self._default_ref())
        body = json.dumps({"text": txt, "out": out, "ref": ref,
                           "exaggeration": e, "cfg": 0.5 if e <= 0.6 else 0.35}).encode()
        try:
            req = urllib.request.Request(NAT_ENGINES[self._nk()]["url"] + "/tts", data=body,
                                         headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=180) as r:
                res = json.load(r)
            if res.get("ref_error") and getattr(self, "_ref_warned", "") != ref:
                self._ref_warned = ref
                msg = res["ref_error"]
                low = msg.lower()
                gated = self._nk() == "legere" and any(k in low for k in (
                    "gated", "401", "403", "access", "cloning", "clone", "token", "unauthorized", "authenticat"))
                self.bridge.bg_done.emit(lambda _: self.say(
                    "Pour imiter ton extrait avec la voix légère, il faut d'abord accepter les conditions de Kyutai "
                    "sur Hugging Face (gratuit, une seule fois) : Réglages → Voix → Voix légère → « Imiter ton "
                    "extrait de voix ». En attendant, je parle avec la voix Estelle." if gated else
                    "Je n'arrive pas à imiter ton extrait de voix, je garde ma voix par défaut. "
                    "Essaie un autre extrait (10 à 30 s, une seule voix, sans musique)."), None)
                print("Extrait de voix refusé :", msg, file=sys.stderr)
            return res.get("ok") and Path(out).exists()
        except Exception as ex:
            print("Voix naturelle :", ex, file=sys.stderr)
            return False

    def _start_natural(self, restart=False):
        kind = self._nk()
        if not natural_voice_installed(kind):
            return
        self.natural_ready = False
        self.natural_note = ""
        self.natural_error = ""
        if restart:
            self._kill_natural_server()

        def run():
            h = self._natural_health()
            if h and h.get("error"):              # vieux serveur en échec : on le remplace
                self._kill_natural_server()
                h = None
            if not h:
                CONFIG_DIR.mkdir(parents=True, exist_ok=True)
                log = open(CONFIG_DIR / NAT_ENGINES[kind]["log"], "a")
                log.write(f"\n===== {datetime.datetime.now():%d/%m %H:%M:%S} démarrage =====\n")
                log.flush()
                env = dict(os.environ,
                           HSA_OVERRIDE_GFX_VERSION=os.environ.get("HSA_OVERRIDE_GFX_VERSION", "10.3.0"),
                           COMPAGNON_VOIX_DEVICE=self.cfg.get("natural_device", "auto"),
                           OMP_NUM_THREADS=str(max(2, min(8, (os.cpu_count() or 4) // 2))),
                           MKL_NUM_THREADS=str(max(2, min(8, (os.cpu_count() or 4) // 2))))
                if kind == "legere":
                    env.update(VIKI_LEGERE_LANGUE=self.cfg.get("legere_langue", "french"),
                               VIKI_LEGERE_QUANT="1" if self.cfg.get("legere_int8", True) else "0",
                               VIKI_LEGERE_STEPS=str(int(self.cfg.get("legere_finesse", 1))),
                               VIKI_LEGERE_CACHE=str(DATA_DIR / "voices" / "cache_legere"))
                    if hf_token():                 # accès au modèle qui sait imiter une voix
                        env["HF_TOKEN"] = hf_token()
                ram = float(self.hw[1] or 16)
                # Chatterbox + bibliothèques ROCm dépassent 7 Go : trop serré, Linux les recharge sans
                # arrêt depuis le disque (voix qui rame) ou tue le programme pendant le chargement.
                cap = min(max(ram - 2.5, 4.0), max(9.0, ram * 0.6)) if kind == "naturelle" else \
                    min(max(ram - 2.5, 3.0), 5.0)
                for k in ("LD_LIBRARY_PATH", "PYTHONHOME", "PYTHONPATH", "PYTHONNOUSERSITE",
                          "QT_PLUGIN_PATH", "SSL_CERT_FILE"):   # rien de l'AppImage pour ce Python-là
                    env.pop(k, None)
                if os.environ.get("APPIMAGE") and os.environ.get("COMPAGNON_ORIG_LD"):
                    env["LD_LIBRARY_PATH"] = os.environ["COMPAGNON_ORIG_LD"]
                self.natural_proc = subprocess.Popen(
                    isolated([natural_python(kind=kind), str(APP_DIR / NAT_ENGINES[kind]["script"])], cap, "voix",
                             swap=True),
                    stdout=log, stderr=log, env=env, start_new_session=True, preexec_fn=_no_core_dump)
            for _ in range(1200):             # jusqu'à 10 min (1er chargement + essai sur processeur)
                h = self._natural_health()
                if h and h.get("ready"):
                    self.natural_ready = True
                    self._nat_waking = False
                    self._nat_last = time.monotonic()
                    self.natural_note = h.get("note", "")
                    self.natural_device_name = h.get("device", "")
                    self.bridge.natural_state.emit(True)
                    return
                if h and h.get("error"):
                    self.natural_error = h["error"]
                    print("Voix naturelle en échec :", h["error"], file=sys.stderr)
                    break
                if self.natural_proc and self.natural_proc.poll() is not None:
                    self.natural_error = "le programme de la voix s'est arrêté (plantage)"
                    break
                time.sleep(0.5)
            self.bridge.natural_state.emit(False)
        threading.Thread(target=run, daemon=True).start()

    def _kill_natural_server(self):
        if self.natural_proc and self.natural_proc.poll() is None:
            self.natural_proc.terminate()
            try:
                self.natural_proc.wait(timeout=5)
            except Exception:
                self.natural_proc.kill()
        self.natural_proc = None
        # serveur lancé par une session précédente
        for e in NAT_ENGINES.values():
            subprocess.run(["pkill", "-f", str(APP_DIR / e["script"])],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        time.sleep(0.5)

    def _natural_health(self):
        try:
            with urllib.request.urlopen(NAT_ENGINES[self._nk()]["url"] + "/health", timeout=1) as r:
                return json.load(r)
        except Exception:
            return None

    def _natural_watchdog_bg(self):
        if self.cfg.get("voice_engine") in NAT_ENGINES and self.natural_ready and not self._natural_health():
            QTimer.singleShot(0, self._natural_watchdog)

    def _natural_watchdog(self):
        """Toutes les 30 s : si le serveur de voix est mort, on le relance (3 fois/heure max)."""
        if self.cfg.get("voice_engine") not in NAT_ENGINES or not self.natural_ready:
            return
        if self._natural_health():
            return
        now = time.monotonic()
        self.natural_restarts = [t for t in getattr(self, "natural_restarts", []) if now - t < 3600]
        self.natural_ready = False
        if len(self.natural_restarts) >= 3:
            self.say("Ma voix naturelle plante trop souvent, je reprends l'autre voix pour l'instant.")
            return
        self.natural_restarts.append(now)
        print("Voix naturelle : serveur arrêté, redémarrage…", file=sys.stderr)
        self._start_natural(restart=True)

    def _on_natural_state(self, ok):
        if hasattr(self, "menu"):
            self._rebuild_menus()
        if ok:
            if self.natural_note:
                self.say(f"Ma voix naturelle est prête, mais {self.natural_note}.")
            elif not getattr(self, "natural_restarts", []):
                self.say("Ma nouvelle voix est prête ! Ça sonne mieux comme ça ?")
        elif self.cfg.get("voice_engine") in NAT_ENGINES:
            err = getattr(self, "natural_error", "")
            hint = ""
            if "filigrane" in err or "setuptools" in err:
                hint = " Il manque setuptools : regarde le journal de la voix."
            elif self.cfg.get("natural_device", "auto") != "cpu":
                hint = " Essaie Voix, puis « Voix naturelle sur le processeur »."
            self.say("Je n'ai pas réussi à charger ma voix naturelle, je garde l'autre." + hint)

    def show_error_log(self):
        self._show_text_file(ERR_LOG, "Journal des erreurs",
                             "(aucune erreur enregistrée — tant mieux !)")

    def _show_text_file(self, path, title, empty):
        try:
            lines = Path(path).read_text(errors="ignore").splitlines()[-200:]
        except Exception:
            lines = []
        dlg = QDialog()
        dlg.setWindowTitle(title)
        dlg.resize(780, 480)
        lay = QVBoxLayout(dlg)
        ed = QPlainTextEdit("\n".join(lines) or empty)
        ed.setReadOnly(True)
        ed.moveCursor(ed.textCursor().MoveOperation.End)
        lay.addWidget(ed)
        row = QHBoxLayout()
        cp = QPushButton("Copier")
        cp.clicked.connect(lambda: QApplication.clipboard().setText(ed.toPlainText()))
        clr = QPushButton("Vider")
        clr.clicked.connect(lambda: (Path(path).write_text(""), ed.setPlainText(empty)))
        close = QPushButton("Fermer")
        close.clicked.connect(dlg.accept)
        row.addWidget(cp)
        row.addWidget(clr)
        row.addStretch()
        row.addWidget(close)
        lay.addLayout(row)
        dlg.exec()

    def show_voice_log(self):
        try:
            lines = (CONFIG_DIR / NAT_ENGINES[self._nk()]["log"]).read_text(errors="ignore").splitlines()[-120:]
        except Exception:
            lines = ["(journal vide : la voix naturelle n'a pas encore été lancée)"]
        dlg = QDialog()
        dlg.setWindowTitle("Journal de la voix naturelle")
        dlg.resize(760, 480)
        lay = QVBoxLayout(dlg)
        ed = QPlainTextEdit("\n".join(lines))
        ed.setReadOnly(True)
        ed.moveCursor(ed.textCursor().MoveOperation.End)
        lay.addWidget(ed)
        row = QHBoxLayout()
        cp = QPushButton("Copier")
        cp.clicked.connect(lambda: QApplication.clipboard().setText(ed.toPlainText()))
        close = QPushButton("Fermer")
        close.clicked.connect(dlg.accept)
        row.addWidget(cp)
        row.addStretch()
        row.addWidget(close)
        lay.addLayout(row)
        dlg.exec()

    def _set_natural_device(self, dev):
        self.cfg["natural_device"] = dev
        save_config(self.cfg)
        if self.cfg.get("voice_engine") in NAT_ENGINES:
            self.say("Je relance ma voix naturelle…")
            self._start_natural(restart=True)
        self._rebuild_menus()

    def _stop_natural(self):
        self.natural_ready = False
        if self.natural_proc and self.natural_proc.poll() is None:
            self.natural_proc.terminate()
        self.natural_proc = None

    def _set_engine(self, engine):
        self.cfg["voice_engine"] = engine
        self._save_char_voice()
        save_config(self.cfg)
        if engine in NAT_ENGINES:
            self._stop_natural()
            threading.Thread(target=self._kill_natural_server, daemon=True).start()   # l'autre moteur s'arrête
            QTimer.singleShot(1500, self._start_natural)
            self.say("D'accord ! Je prépare ma nouvelle voix, ça peut prendre une minute…" if engine == "naturelle"
                     else "D'accord ! Je charge ma voix légère, quelques secondes…")
        else:
            self._stop_natural()
            self.say("Je reprends ma voix habituelle.")
        self._rebuild_menus()

    def _set_expressivity(self, v):
        self.cfg["expressivity"] = v
        save_config(self.cfg)
        self._rebuild_menus()

    def _choose_voice_ref(self, path=None):
        if not path:
            path, _ = QFileDialog.getOpenFileName(
                None, "Extrait de voix (10 à 30 s, une seule personne, sans musique)", str(Path.home()),
                "Audio (*.wav *.mp3 *.flac *.ogg)")
        if path:
            self.add_voice_refs([path], use=True)

    def _reset_voice_ref(self):
        self.cfg["voice_ref"] = ""
        self._save_char_voice()
        save_config(self.cfg)
        self.say("Je reprends ma voix par défaut.")
        self._rebuild_menus()

    # ---------- langues et voix
    def set_theme(self, name):
        """Couleurs des fenêtres (réglages, manga, lecture…)."""
        if not themes:
            return
        self.cfg["theme"] = name
        save_config(self.cfg)
        themes.install(self.app, name, self.cfg.get("theme_couleur", ""))
        if name in ("perso", "perso_sombre") and not self.cfg.get("theme_couleur"):
            return QTimer.singleShot(0, self.pick_theme_color)
        self._reopen_settings()

    def pick_theme_color(self):
        from PyQt6.QtWidgets import QColorDialog
        col = QColorDialog.getColor(QColor(self.cfg.get("theme_couleur") or "#5b8def"), None, "Ma couleur")
        if not col.isValid():
            return
        self.cfg["theme_couleur"] = col.name()
        if self.cfg.get("theme") not in ("perso", "perso_sombre"):
            self.cfg["theme"] = "perso"
        save_config(self.cfg)
        themes.install(self.app, self.cfg["theme"], col.name())
        self._reopen_settings()

    def _theme_tick(self):
        """« Automatique » / « comme mon bureau » : le thème suit l'heure ou le bureau."""
        if not themes or self.cfg.get("theme", "nuit") not in ("auto", "systeme"):
            return
        before = themes.effective()
        if themes.install(self.app, self.cfg["theme"], self.cfg.get("theme_couleur", "")) != before:
            self._reopen_settings()

    def _reopen_settings(self):
        sw = getattr(self, "settings_win", None)
        if sw and sw.isVisible() and hasattr(sw, "current_page"):
            page = sw.current_page()
            QTimer.singleShot(0, lambda: self.open_settings(page))

    def set_menu_language(self, code):
        """Langue des menus et fenêtres (pas celle dans laquelle elle parle)."""
        if not i18n:
            return
        self.cfg["langue_menus"] = code
        save_config(self.cfg)
        i18n.install(self.app, code)
        page = None
        sw = getattr(self, "settings_win", None)
        if sw and sw.isVisible() and hasattr(sw, "current_page"):
            page = sw.current_page()
        try:
            self._rebuild_menus()                          # clic droit et menu de l'icône
        except Exception:
            pass
        if page is not None:
            QTimer.singleShot(0, lambda: self.open_settings(page))
        if code == "fr":
            self.say("Les menus sont de nouveau en français. (Certains textes déjà ouverts changeront au "
                     "prochain redémarrage.)")

    def set_language(self, code, mode="naturel"):
        if not voix or code not in voix.LANGUES:
            return
        self.cfg["langue"] = code
        self.cfg["langue_mode"] = mode
        save_config(self.cfg)
        self._restart_stt()
        self.chat_history = []
        self._rebuild_menus()
        if code == "fr":
            return self.say("D'accord, on repasse en français !")
        nom = voix.LANGUES[code][1]
        path, _ = voix.voice_for(code, self.cfg, VOICE_DIRS)
        hello = {"en": "Okay! Let's talk in English. How are you today?", "es": "¡Vale! Hablemos en español. ¿Qué tal?",
                 "de": "Okay! Sprechen wir Deutsch. Wie geht's dir?", "it": "Va bene! Parliamo italiano. Come stai?",
                 "pt": "Combinado! Vamos falar português. Tudo bem?"}.get(code)
        if not path:
            if voix.VOIX_DEFAUT.get(code) and self.cfg.get("voice", True):
                self.ask_yes(f"D'accord, je te réponds en {nom} ! Je télécharge ma voix en {nom} (environ 60 Mo, "
                             "une seule fois) ? (oui / non)", lambda: self.install_voice(code))
            else:
                self.say(f"D'accord, je te réponds en {nom} ! Pour cette langue, je parle avec ma voix de secours.")
        elif hello:
            self.say(hello)
        else:
            self.say(f"D'accord, on parle {nom} !")

    def set_lang_voice(self, code, stem, speaker=-1):
        if code == "fr":
            return self._set_piper_voice(stem, speaker)
        self.cfg.setdefault("voix_langue", {})[code] = {"voice": stem, "speaker": speaker}
        save_config(self.cfg)
        self._rebuild_menus()

    def try_voice(self, stem, text):
        """Essayer une voix sans la choisir."""
        path = next((p for s, p in voix.installed_voices(VOICE_DIRS) if s == stem), None) if voix else None
        if not path or not self.piper:
            return self.say("Je ne trouve pas cette voix.")
        out = str(self.tmpdir / "essai_voix.wav")

        def work():
            pitch = float(self.cfg.get("voix_hauteur", 1.0))
            r = subprocess.run([self.piper, "-m", piper_model(path), "-f", out] + voix.piper_args(self.cfg, pitch),
                               input=text.encode(), capture_output=True, timeout=60)
            if r.returncode == 0:
                voix.pitch_shift(out, pitch)
                subprocess.Popen(self._play_cmd(out), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        threading.Thread(target=work, daemon=True).start()

    def open_voice_catalog(self, code=None):
        if not voix:
            return self.say("Il me manque le fichier voix.py pour ça.")
        self.voice_cat = voix.VoiceCatalog(self, DATA_DIR / "voices", VOICE_DIRS, code)
        self.voice_cat.show()

    def set_voice_param(self, key, value):
        self.cfg[key] = value
        self._save_char_voice()
        save_config(self.cfg)

    AMBIANCES = {
        "": ("Aucune (voix nette)", ""),
        "piece": ("Petite pièce", "aecho=0.8:0.5:35:0.22"),
        "salle": ("Grande salle", "aecho=0.8:0.6:70|120:0.32|0.18"),
        "radio": ("Radio", "highpass=f=300,lowpass=f=3600,acompressor=threshold=-24dB:ratio=4,volume=1.4"),
        "telephone": ("Téléphone", "highpass=f=450,lowpass=f=3000,volume=1.3"),
    }

    def voice_filters(self, pitch_speed=True):
        """Chaîne de filtres ffmpeg : vitesse / hauteur (voix légère et naturelle), timbre grave ↔ doux,
        réduction du bruit, ambiance. "" = rien à faire."""
        f = []
        if pitch_speed:
            p = float(self.cfg.get("voix_hauteur", 1.0) or 1.0)
            s = float(self.cfg.get("voix_vitesse", 1.0) or 1.0)
            if abs(p - 1) >= 0.01:
                f.append("asetrate={SR}*%.4f,aresample={SR}" % p)
            if abs(s / p - 1) >= 0.01:
                f.append("atempo=%.4f" % max(0.5, min(2.0, s / p)))
        t = float(self.cfg.get("voix_timbre", 0.0) or 0.0)
        if t < -0.02:                               # plus grave, plus chaude
            g = -t
            f.append(f"bass=g={7 * g:.1f}:f=140,treble=g={-4 * g:.1f}:f=5000")
        elif t > 0.02:                              # plus douce : moins de graves lourds, aigus adoucis
            f.append(f"highpass=f={70 + 110 * t:.0f},equalizer=f=3200:t=q:w=1.4:g={-4 * t:.1f},"
                     f"treble=g={-5 * t:.1f}:f=6500,acompressor=threshold=-22dB:ratio={1 + 1.5 * t:.2f}"
                     f":attack=15:release=180")
        n = int(self.cfg.get("voix_bruit", 0) or 0)
        if n == 1:
            f.append("afftdn=nr=10:nf=-42")
        elif n >= 2:
            f.append("afftdn=nr=22:nf=-36")
        amb = self.AMBIANCES.get(self.cfg.get("voix_ambiance", ""), ("", ""))[1]
        if amb:
            f.append(amb)
        if f:
            f.append("alimiter=limit=0.95:level=disabled")      # jamais de saturation
        return ",".join(f)

    def _voice_fx(self, path, pitch_speed=True):
        """Applique vitesse / hauteur / timbre / bruit / ambiance au fichier (ffmpeg)."""
        ff = shutil.which("ffmpeg")
        chain = self.voice_filters(pitch_speed)
        if not ff or not chain:
            return
        try:
            with wave.open(path, "rb") as w:
                sr = w.getframerate()
            tmp = path + ".fx.wav"
            r = subprocess.run([ff, "-y", "-loglevel", "error", "-i", path, "-af", chain.replace("{SR}", str(sr)),
                                "-ar", str(sr), "-ac", "1", tmp], capture_output=True, timeout=60)
            if r.returncode == 0 and os.path.getsize(tmp) > 100:
                os.replace(tmp, path)
            else:
                print("Effets de voix :", r.stderr.decode(errors="ignore")[-200:], file=sys.stderr)
        except Exception as e:
            print("Effets de voix :", e, file=sys.stderr)

    def sound_diagnostic(self):
        """Cherche ce qui fait grésiller le son du PC (et pas seulement le sien) et propose de le réparer."""
        self.say("Je vérifie le son…")

        def work():
            found = []
            if shutil.which("wpctl"):
                r = subprocess.run(["wpctl", "get-volume", "@DEFAULT_AUDIO_SINK@"], capture_output=True, text=True,
                                   timeout=5)
                m = re.search(r"([\d.]+)", r.stdout or "")
                if m and float(m.group(1)) > 1.0:
                    found.append(("vol", f"le son du PC est à {float(m.group(1)) * 100:.0f} % : au-dessus de 100 %, "
                                         "TOUT sature et grésille"))
            if shutil.which("pactl"):
                r = subprocess.run(["pactl", "list", "cards"], capture_output=True, text=True, timeout=8)
                for block in (r.stdout or "").split("\nCard #"):
                    name = re.search(r"Name:\s*(\S+)", block)
                    prof = re.search(r"Active Profile:\s*(\S+)", block)
                    if name and prof and "bluez" in name.group(1) and re.search(r"head|hfp|hsp", prof.group(1), re.I):
                        good = re.search(r"\n\s*(a2dp[\w-]*):", block)
                        found.append(("bt", "ton casque Bluetooth est en mode « appel » (qualité téléphone, son "
                                            "grésillant), sûrement parce qu'un micro est ouvert",
                                      name.group(1), good.group(1) if good else "a2dp-sink"))
            if float(self.cfg.get("volume", 0.35)) > 1.0:
                found.append(("viki", f"mon volume est réglé à {float(self.cfg['volume']) * 100:.0f} %"))
            if abs(float(self.cfg.get("voix_hauteur", 1.0)) - 1) > 0.01 or \
                    abs(float(self.cfg.get("voix_vitesse", 1.0)) - 1) > 0.01:
                found.append(("perso", "ma vitesse ou ma hauteur ont été modifiées pour ce personnage"))
            if float(self.cfg.get("voix_variation", 0.667)) > 0.9:
                found.append(("expr", "l'expressivité de Piper est au maximum (ça peut faire trembler la voix)"))
            return found

        def done(found):
            if isinstance(found, Exception):
                return self.say(f"Je n'ai pas pu vérifier le son : {str(found)[:80]}")
            if not found:
                return self.say("Je ne vois rien d'anormal dans les réglages du son. Si ça grésille aussi avec "
                                "une vidéo ou de la musique, c'est le PC ou le casque ; sinon, dis-moi quelle voix.")
            self.say("J'ai trouvé : " + " ; ".join(f[1] for f in found) + ". Je répare ?")
            acts = []
            for f in found:
                if f[0] == "vol":
                    acts.append(("🔊 Remettre le son du PC à 100 %", lambda: subprocess.Popen(
                        ["wpctl", "set-volume", "@DEFAULT_AUDIO_SINK@", "1.0"])))
                elif f[0] == "bt":
                    acts.append(("🎧 Repasser le casque en qualité musique", lambda c_=f[2], p_=f[3]: (
                        subprocess.Popen(["pactl", "set-card-profile", c_, p_]),
                        self.cfg.get("wake") and self.say("Si ça revient, coupe l'écoute continue : elle garde le "
                                                          "micro ouvert et force le casque en mode appel."))))
                elif f[0] == "viki":
                    acts.append(("Remettre mon volume à 35 %", lambda: self.set_voice_param("volume", 0.35)))
                elif f[0] in ("perso", "expr"):
                    acts.append(("Remettre ma voix par défaut (vitesse, hauteur, expressivité)", lambda: [
                        self.set_voice_param(k, v) for k, v in (("voix_vitesse", 1.0), ("voix_hauteur", 1.0),
                                                                ("voix_variation", 0.667))]))
            seen, uniq = set(), []
            for a in acts:
                if a[0] not in seen:
                    seen.add(a[0])
                    uniq.append(a)
            uniq.append(("▶ Me faire parler pour tester", lambda: self.say("Un, deux, trois, je teste ma voix. "
                                                                           "Est-ce que c'est mieux comme ça ?")))
            self._drop_menu("🔧 Son", uniq)
        self._bg(work, done)

    VOICE_KEYS = ("piper_voice", "piper_speaker", "voix_vitesse", "voix_hauteur", "voix_variation", "voix_pause",
                  "voice_engine", "voice_ref", "voix_timbre", "voix_bruit", "voix_ambiance", "voix_nettoyer_extrait")

    def _save_char_voice(self):
        """Chaque personnage garde sa propre voix."""
        d = str(Path(self.char_dir).resolve())
        self.cfg.setdefault("voix_perso", {})[d] = {k: self.cfg[k] for k in self.VOICE_KEYS if k in self.cfg}

    def _load_char_voice(self):
        d = str(Path(self.char_dir).resolve())
        saved = (self.cfg.get("voix_perso") or {}).get(d)
        if saved:
            self.cfg.update(saved)
            self.voice_model = find_voice_model(self.cfg.get("piper_voice", "")) or self.voice_model

    def rename_character(self, cdir, name=None):
        cdir = Path(cdir)
        f = cdir / "character.json"
        try:
            info = json.loads(f.read_text())
        except Exception as e:
            return QMessageBox.warning(None, "Renommer", f"Impossible de lire ce personnage : {e}")
        old = info.get("name", "")
        if name is None:
            name, ok = QInputDialog.getText(None, "Renommer", f"Nouveau prénom pour {old} :", text=old)
            if not ok:
                return
        name = (name or "").strip()[:40]
        if not name or name == old:
            return
        info["name"] = name
        try:
            f.write_text(json.dumps(info, ensure_ascii=False, indent=2))
        except Exception as e:
            return QMessageBox.warning(None, "Renommer", f"Impossible d'enregistrer : {e}")
        if cdir.resolve() == Path(self.char_dir).resolve():
            self.char["name"] = self.char_base["name"] = name
            self.setWindowTitle(name)
            if getattr(self, "tray", None):
                self.tray.setToolTip(name)
            self.chat_history = []
            self.say(f"J'adore ! À partir de maintenant, appelle-moi {name}.")
        else:
            self.say(f"C'est noté : {old} s'appelle maintenant {name}." +
                     (" Elle le saura à son prochain passage." if str(cdir) in map(str, self.cfg.get("invites", []))
                      else ""))
        self._restart_stt()                      # le mot de réveil change aussi
        self._rebuild_menus()

    def _set_piper_voice(self, stem, speaker=-1):
        self.cfg["piper_voice"] = stem
        self.cfg["piper_speaker"] = speaker
        save_config(self.cfg)
        self.voice_model = find_voice_model(stem)
        if self.cfg.get("voice_engine") not in NAT_ENGINES:
            self.say("Voilà ma nouvelle voix ! Tu l'aimes bien ?")
        self._rebuild_menus()

    def _on_audio_ready(self, sid, text, path):
        if self.synth_pending and self.synth_pending[0] == sid:
            self.synth_pending = 0
        if sid != self.speech_id:
            return
        now = time.monotonic()
        if path and self.player_cmd:
            try:
                cached = getattr(self, "_env_cache", {}).get(sid)
                self.lip_env, dur = cached if cached else wav_envelope(path)
                cmd = self._play_cmd(path)
                self.player = subprocess.Popen(cmd, stdout=subprocess.DEVNULL,
                                               stderr=subprocess.DEVNULL)
                self.lip_start = time.monotonic()
                self.bubble_until = max(self.bubble_until, now + dur + 2.0)
                return
            except Exception as e:
                print("Lecture audio impossible :", e, file=sys.stderr)
        self.lip_env, dur = fake_envelope(text)
        self.lip_start = now

    def _play_cmd(self, path):
        v = max(0.05, min(1.5, float(self.cfg.get("volume", 0.35))))
        if self.player_cmd == "pw-play":
            return ["pw-play", "--volume", f"{v:.2f}", path]
        if self.player_cmd == "paplay":
            return ["paplay", f"--volume={int(v * 65536)}", path]
        return [self.player_cmd, path]

    def _stop_audio(self):
        if self.player and self.player.poll() is None:
            self.player.terminate()
        self.player = None
        self.lip_env = []

    # ---------- Ollama (optionnel)
    def _check_ollama(self, retry=True):
        if self.ia_remote():                      # IA en ligne : prête dès qu'elle a une clé
            conf = ia_api.conf_from()
            self.bridge.ollama_status.emit(ia_api.ready(conf), conf["modele"])
            return
        try:
            with urllib.request.urlopen(OLLAMA_URL + "/api/tags", timeout=2) as r:
                models = [m["name"] for m in json.load(r).get("models", [])]
            self.ollama_running = True
            if not models:
                self.ollama_models = []
                self.bridge.ollama_status.emit(False, "")
                return
            self.ollama_models = models
            want = self.cfg.get("ollama_model")
            model = want if want in models else models[0]
            self.bridge.ollama_status.emit(True, model)
        except Exception:
            if retry and start_ollama_local():     # installé mais pas lancé : on le démarre
                time.sleep(6)
                return self._check_ollama(retry=False)
            self.ollama_running = False
            self.bridge.ollama_status.emit(False, "")

