    def ouvrir_service(self, nom, url, appli=""):
        """Ouvre l'appli si elle est installée (Spotify, Deezer…), sinon le site, dans ton navigateur."""
        if appli and shutil.which(appli):
            try:
                subprocess.Popen([appli], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
                return self.say(f"J'ouvre {nom} ! 🎶")
            except Exception:
                pass
        from PyQt6.QtGui import QDesktopServices
        from PyQt6.QtCore import QUrl
        QDesktopServices.openUrl(QUrl(url))
        self.say(f"J'ouvre {nom} ! 🍿")

    def open_services(self):
        """🍿 La fenêtre « Mes services », à côté d'elle (tuiles avec image)."""
        try:
            import services_fenetre
        except Exception:
            log_error("fenêtre des services")
            return self._menu_services_liste()
        w = self.__dict__.get("services_win")
        if w is None:
            w = self.services_win = services_fenetre.SalonWin(self, sys.modules[__name__])
        w.montrer()

    def menu_services(self):
        return self.open_services()

    def _menu_services_liste(self):
        m = QMenu()
        cache = set(self.cfg.get("services_caches", []))
        for titre, liste_ in self.SERVICES:
            t = m.addAction(("🎬  " if titre == "Vidéo" else "🎵  ") + titre)
            t.setEnabled(False)
            for nom, url, app in liste_:
                if nom in cache:
                    continue
                m.addAction("      " + nom, lambda n=nom, u=url, a=app: self.ouvrir_service(n, u, a))
            m.addSeparator()
        perso = m.addMenu("⚙️  Choisir ceux que j'affiche")
        for _t, liste_ in self.SERVICES:
            for nom, _u, _a in liste_:
                a = perso.addAction(nom)
                a.setCheckable(True)
                a.setChecked(nom not in cache)
                a.toggled.connect(lambda on, n=nom: self._service_visible(n, on))
        self._menu_services_ref = m
        m.popup(QCursor.pos())

    def _service_visible(self, nom, on):
        c = [x for x in self.cfg.get("services_caches", []) if x != nom]
        if not on:
            c.append(nom)
        self.cfg["services_caches"] = c
        save_config(self.cfg)

    def pause_yeux(self):
        self.say("Pause des yeux 👀 Regarde quelque chose de loin, à plus de 6 mètres, pendant 20 secondes.")
        QTimer.singleShot(21000, lambda: self.say("C'est bon ! Tes yeux te remercient. Cligne plusieurs fois, "
                                                  "ça les hydrate."))

    def etirements(self):
        etapes = list(forme.ETIREMENTS) if forme else []
        self.say("On s'étire ensemble ! Une minute, tout doucement. Suis-moi 🙆")

        def suite(i=0):
            if i >= len(etapes):
                self._spawn("etoile", 4)
                return self.say("Et voilà ! Tu te sens plus léger ? On recommence quand tu veux.")
            nom, txt = etapes[i]
            self.happy_until = time.monotonic() + 1.5
            self.say(f"{nom} : {txt}")
            QTimer.singleShot(12000, lambda: suite(i + 1))
        QTimer.singleShot(3500, suite)

    def _forme_tick(self, now, mono, q):
        """Routines, eau, yeux et planning : gentiment, jamais en concentration ni en jeu."""
        if self.cfg.get("profil") == "jeu":
            return False
        today = now.date().isoformat()
        hm = now.strftime("%H:%M")
        # routine du matin / du soir, à son heure (une fois)
        if self.cfg.get("routines_on", True):
            for quand, r in forme.routines(self.cfg).items():
                h = r.get("heure") or ""
                if not h or not r.get("items") or q.get("routine_" + quand) == today:
                    continue
                t = now.replace(hour=int(h[:2]), minute=int(h[3:5]), second=0)
                if 0 <= (now - t).total_seconds() < 40 * 60:
                    q["routine_" + quand] = today
                    if len(forme.fait_du_jour(self.cfg, quand)) < len(r["items"]):
                        self.say("C'est l'heure de ta routine du " + quand + " ! " +
                                 ("On commence la journée du bon pied ? ☀️" if quand == "matin" else
                                  "On prépare une bonne nuit ? 🌙"))
                        self.open_routine(quand)
                        return True
        # planning : la journée le matin, puis chaque activité un quart d'heure avant
        if forme.planning(self.cfg):
            evs = forme.du_jour(self.cfg, now.date())
            if evs and q.get("planning_jour") != today and 8 <= now.hour < 12:
                q["planning_jour"] = today
                self.say("Aujourd'hui : " + ", ".join((e["txt"] + (f" à {e['heure']}" if e.get("heure") else ""))
                                                       for e in evs) + ". 🗓️")
                return True
            dits = q.setdefault("planning_dits", {})
            for e in evs:
                if not e.get("heure"):
                    continue
                t = now.replace(hour=int(e["heure"][:2]), minute=int(e["heure"][3:5]), second=0)
                cle = today + e["heure"] + e["txt"]
                if 0 <= (t - now).total_seconds() <= 15 * 60 and cle not in dits:
                    dits[cle] = 1
                    for k in list(dits)[:-30]:
                        dits.pop(k, None)
                    self.say(f"Dans un quart d'heure : {e['txt']} ({e['heure']}) !")
                    self.notifier(f"{e['heure']} · {e['txt']}", "⏰", "planning")
                    return True
        if not self.cfg.get("sante_rappels", True) or not (9 <= now.hour < 22) or mono - self.last_interaction > 15 * 60:
            return False
        # un verre d'eau, toutes les ~80 min d'activité, tant que l'objectif n'est pas atteint
        last = getattr(self, "_eau_last", None)
        if last is None:
            self._eau_last = mono
        elif mono - last > 80 * 60 and forme.eau_du_jour(self.cfg) < int(self.cfg.get("sante_eau_objectif", 8)):
            self._eau_last = mono
            self.say(random.choice(["Un petit verre d'eau ? 💧 (dis-moi « j'ai bu » et je compte)",
                                    "Pense à boire un peu d'eau 💧", "Hydratation ! Un verre d'eau, ça te dit ? 💧"]))
            return True
        # pause des yeux, toutes les ~45 min devant l'écran
        ly = getattr(self, "_yeux_last", None)
        if ly is None:
            self._yeux_last = mono
        elif mono - ly > 45 * 60:
            self._yeux_last = mono
            self.say("Petite pause des yeux ? Regarde au loin 20 secondes 👀 (ou dis « pause des yeux »)")
            return True
        return False

    def _forme_command(self, text, ta):
        if re.search(r"\b(?:ma |la |mes )?routines?\b(?: du (matin|soir))?", ta) and \
                re.search(r"\b(?:routine|routines)\b", ta) and not re.search(r"\bajoute\b", ta):
            m = re.search(r"\b(matin|soir)\b", ta)
            self.open_routine(m.group(1) if m else None)
            return True
        m = re.search(r"\bj'?ai bu\b(?:.*?\b(\d+|deux|trois)\b)?|\b(?:un|1) verre d'?eau\b.*\b(?:bu|fait)\b", ta)
        if m:
            n = {"deux": 2, "trois": 3}.get(m.group(1) or "", int(m.group(1)) if (m.group(1) or "").isdigit() else 1)
            v = forme.boire(self.cfg, n)
            save_config(self.cfg)
            obj = int(self.cfg.get("sante_eau_objectif", 8))
            self._spawn("coeur", 2)
            self.say(f"Noté ! {v} verre{'s' if v > 1 else ''} sur {obj} aujourd'hui 💧" +
                     (" Objectif atteint, bravo !" if v >= obj else ""))
            return True
        if re.search(r"\bpause (?:des |pour les )?yeux\b|\brepose(?:r)? mes yeux\b", ta):
            self.pause_yeux()
            return True
        if re.search(r"\b(?:etire[- ]toi|on s'?etire|etirements?|s'?etirer)\b", ta) and \
                not re.search(r"\bmuscu\b", ta):
            self.etirements()
            return True
        if re.search(r"\b(?:pauses? sante|mon eau|combien (?:j'?ai|de verres))\b", ta):
            self.open_sante()
            return True
        if re.search(r"\b(?:mon planning|ma semaine|planning de la semaine|qu'?est[- ]ce que j'?ai cette semaine)\b", ta):
            self.open_planning()
            return True
        if re.search(r"^(?:ajoute|rajoute|note|planifie|programme|mets)(?:[- ]moi)?\b", ta) and \
                re.search(r"\b(?:lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche|demain)s?\b", ta) and \
                not re.search(r"\b(?:courses|liste|rappel|minuteur)\b", ta):
            r = forme.lire_ajout(text)
            if r:
                r["couleur"] = forme.COULEURS[len(forme.planning(self.cfg)) % len(forme.COULEURS)]
                forme.planning(self.cfg).append(r)
                save_config(self.cfg)
                j = forme.JOURS[r["jour"]]
                self.say(f"C'est noté : {r['txt']} " + (f"tous les {j}s" if r["chaque"] else f"{j}") +
                         (f" à {r['heure']}" if r["heure"] else "") + " 🗓️")
                w = self.__dict__.get("planning_win")
                if w is not None and w.isVisible():
                    w.remplir()
                return True
        if re.search(r"\b(?:muscu|musculation|seance de sport|entrainement|workout|faire du sport|on fait du sport|"
                     r"sport a la maison)\b", ta):
            self.open_muscu()
            self.say("On se bouge ! Choisis ta séance 💪")
            return True
        return False

    # ---------- créer un personnage kawaii avec l'IA d'images
    KAWAII = {"lapin": ("🐰 Lapine", "bunny ear hoodie"), "chat": ("🐱 Chatte", "cat ear hoodie"),
              "renard": ("🦊 Renarde", "fox ear hoodie with fluffy tail"), "ours": ("🐻 Ourson", "bear onesie with round ears"),
              "sorciere": ("🔮 Petite sorcière", "little witch hat with a star and a cape"),
              "idole": ("🎤 Idole", "idol stage outfit with ribbons and a microphone"),
              "astronaute": ("🚀 Astronaute", "cute pastel astronaut suit"),
              "dragon": ("🐉 Petit dragon", "dragon hoodie with tiny wings and horns"),
              "fee": ("🧚 Fée", "fairy dress with small translucent wings"),
              "cuisine": ("🧁 Pâtissière", "baker apron with a cupcake")}
    KAWAII_CHEVEUX = [("Rose", "pink"), ("Lavande", "lavender"), ("Blond", "blonde"), ("Noir", "black"),
                      ("Châtain", "brown"), ("Blanc", "white"), ("Bleu ciel", "sky blue"), ("Roux", "ginger")]

    def creer_kawaii(self):
        """Un personnage kawaii unique : tu choisis, l'IA d'images le dessine, Viki le détoure et l'installe."""
        if not atelier:
            return self.say("Il me manque l'atelier d'images pour ça.")
        try:
            from actu_fenetre import Boite
        except Exception:
            return
        from PyQt6.QtWidgets import QComboBox, QLineEdit
        b = Boite(None, "Créer un personnage kawaii", "Choisis son style : je le dessine avec l'IA d'images, je retire "
                  "le fond et je l'installe. Il sera unique !", [("Annuler", False, "non"), ("Le créer ✨", True, "oui")],
                  "🎀")
        ty = b.ajouter_champ("Son style :", QComboBox())
        for k, (lab, _en) in self.KAWAII.items():
            ty.addItem(lab, k)
        ch = b.ajouter_champ("Ses cheveux :", QComboBox())
        for lab, en in self.KAWAII_CHEVEUX:
            ch.addItem(lab, en)
        co = b.ajouter_champ("La couleur de sa tenue :", QComboBox())
        for lab, en in (("Rose pastel", "pastel pink"), ("Lilas", "lilac"), ("Menthe", "mint green"),
                        ("Bleu ciel", "baby blue"), ("Crème", "cream"), ("Noir", "black"), ("Rouge", "red"),
                        ("Jaune citron", "lemon yellow")):
            co.addItem(lab, en)
        nm = b.ajouter_champ("Son prénom :", QLineEdit())
        nm.setPlaceholderText("Mochi, Kiko, Nami…")
        b.exec()
        if not b.valeur:
            return
        k = ty.currentData()
        prompt = (f"chibi kawaii mascot character, full body, standing, front view, centered, wearing a "
                  f"{co.currentData()} {self.KAWAII[k][1]}, {ch.currentData()} hair, big sparkling eyes, rosy cheeks, "
                  f"gentle smile, simple plain white background, clean lineart, soft pastel colors, cute anime style, "
                  f"high quality, no text, no watermark")
        self._kawaii_nom = nm.text().strip() or self.KAWAII[k][0].split(" ", 1)[1]
        w = self.open_studio(prompt, fmt=1, auto=True) or getattr(self, "studio", None)
        w = getattr(self, "studio", None)
        if w is None:
            return
        w.apres = self._kawaii_pret
        if self.cfg.get("image_moteur") not in ("ligne", "local"):
            self.say("Choisis où créer l'image dans l'atelier, puis clique sur « Créer » : je m'occupe du reste !")
        else:
            self.say(f"Je dessine {self._kawaii_nom}… Ça prend un petit moment ! 🎨")

    def _kawaii_pret(self, path):
        self.say(f"Voilà {getattr(self, '_kawaii_nom', 'ton personnage')} ! Je retire le fond et je l'installe…")
        self._nom_propose = getattr(self, "_kawaii_nom", "")
        self.new_character(str(path))

    # ---------- couleurs du fond d'écran
    def couleurs_fond(self, on=True, annonce=True):
        """Viki prend la couleur de ton fond d'écran (fenêtres, menus, ronds). on=False : on revient au thème d'avant."""
        if not (themes and fond_couleurs):
            return
        if not on:
            self.cfg["couleurs_fond"] = False
            self.cfg["theme"] = self.cfg.pop("theme_avant_fond", None) or "nuit"
            save_config(self.cfg)
            themes.install(self.app, self.cfg["theme"], self.cfg.get("theme_couleur", ""))
            self._accent_menus("")
            self._rebuild_menus()
            return annonce and self.say("D'accord, je reprends mes couleurs habituelles.")
        p = fond_couleurs.chemin_fond(self.cfg)
        if not p:
            self.cfg["couleurs_fond"] = False
            save_config(self.cfg)
            return annonce and self.say("Je ne trouve pas ton fond d'écran sur ce bureau. Choisis l'image dans "
                                        "Réglages → Apparence, et je prends ses couleurs.")
        col = fond_couleurs.couleur_dominante(p)
        if not col:
            return annonce and self.say("Je n'arrive pas à lire l'image de ton fond d'écran.")
        if not self.cfg.get("couleurs_fond") or not str(self.cfg.get("theme", "")).startswith("perso"):
            if not str(self.cfg.get("theme", "")).startswith("perso"):
                self.cfg["theme_avant_fond"] = self.cfg.get("theme", "nuit")
        sombre = bool(themes.THEMES.get(themes.effective(), (0, 0, 0, False))[3]) if themes.effective() in themes.THEMES \
            else True
        self.cfg.update(couleurs_fond=True, theme="perso_sombre" if sombre else "perso", theme_couleur=col,
                        fond_vu=f"{p}|{int(p.stat().st_mtime)}")
        save_config(self.cfg)
        themes.install(self.app, self.cfg["theme"], col)
        self._accent_menus(col)
        self._rebuild_menus()
        rb = self.__dict__.get("ronds_bar")
        if rb is not None:
            rb.update()
        if annonce:
            self.say("Voilà, je me suis accordée aux couleurs de ton fond d'écran ! 🎨")

    def _accent_menus(self, col):
        """La couleur de sélection des menus et l'anneau des ronds suivent le fond d'écran."""
        defaut = {"ios": ("#3b82f6", (59, 130, 246, 235)), "graphite": ("#0a84ff", (100, 168, 255, 235))}
        for k, (sel, ring) in defaut.items():
            st = RONDS_STYLES[k]
            if col:
                c = QColor(col)
                st["menu_sel"], st["ring"] = col, (c.red(), c.green(), c.blue(), 235)
            else:
                st["menu_sel"], st["ring"] = sel, ring

    def _fond_tick(self):
        """Toutes les 10 min : si le fond d'écran a changé, Viki change de couleur avec lui."""
        if not (self.cfg.get("couleurs_fond") and fond_couleurs):
            return
        if time.monotonic() - getattr(self, "_fond_t", -1e9) < 600:
            return
        self._fond_t = time.monotonic()
        try:
            p = fond_couleurs.chemin_fond(self.cfg)
            if p and f"{p}|{int(p.stat().st_mtime)}" != self.cfg.get("fond_vu"):
                self.couleurs_fond(True, annonce=False)
        except Exception:
            log_error("couleurs du fond")

    # ---------- notifications : ce qui est important est gardé, rien n'est raté
    def notifier(self, txt, ico="🔔", action=""):
        n = self.cfg.setdefault("notifs", [])
        txt = str(txt).strip()
        if i18n:
            txt = i18n.tr_to(txt, self.cfg.get("langue", "fr"))
        if n and n[-1].get("txt") == txt and time.time() - n[-1].get("t", 0) < 3600:
            return
        n.append({"t": time.time(), "txt": txt[:300], "ico": ico, "action": action, "lu": False})
        del n[:-100]
        save_config(self.cfg)
        rb = self.__dict__.get("ronds_bar")
        if rb is not None:
            rb.update()

    def notifs_non_lues(self):
        return sum(1 for n in self.cfg.get("notifs", []) if not n.get("lu"))

    def notif_action(self, action):
        fn = {"rappels": lambda: self.say(self._reminders_text()), "maj": lambda: self.check_update(quiet=False),
              "pc": getattr(self, "disks_health", None), "suivis": getattr(self, "open_follow", None),
              "liste": getattr(self, "open_liste", None), "actu": lambda: self.tell_news("")}.get(action)
        if fn:
            fn()

