    # ---------- 🔲 traduire une zone de l'écran
    def translate_zone(self):
        try:
            import zone as _zone
        except Exception:
            log_error("zone")
            return self.say("Il me manque le fichier zone.py.")
        self.bubble_text = ""
        self.hide()
        rb = self.__dict__.get("ronds_bar")
        rb_vis = rb is not None and rb.isVisible()
        if rb_vis:
            rb.hide()

        def shoot():
            return pratique.screenshot() if pratique else ""

        def got(p):
            self.show()
            if rb_vis:
                rb.show()
            img = QImage(p) if isinstance(p, str) and p else QImage()
            if img.isNull():
                try:
                    img = QApplication.primaryScreen().grabWindow(0).toImage()
                except Exception:
                    img = QImage()
            try:
                os.unlink(p) if isinstance(p, str) and "viki_ecran" in p else None
            except Exception:
                pass
            if img.isNull():
                return self.say("Je n'arrive pas à faire de capture d'écran (installe « spectacle », « grim » ou "
                                "« gnome-screenshot »).")
            sel = _zone.Selecteur(img)
            self._zone_sel = sel
            sel.choisi.connect(self._zone_choisie)
            sel.annule.connect(lambda: self.say("D'accord, j'annule."))
            sel.showFullScreen() if not IS_WIN else sel.show()
            sel.raise_()
            sel.activateWindow()
        QTimer.singleShot(250, lambda: self._bg(shoot, got))      # le temps qu'elle disparaisse de l'écran

    def _zone_choisie(self, crop, r):
        import zone as _zone
        p = os.path.join(str(self.tmpdir), "zone.png")
        crop.save(p)
        res = self.__dict__.get("zone_res")
        if res is None:
            res = self.zone_res = _zone.Resultat()
            res.b_encore.clicked.connect(lambda: (res.hide(), self.translate_zone()))
        res.montrer(r, "⏳ " + (i18n.tr("Je lis et je traduis…") if i18n else "Je lis et je traduis…"))
        self.look_image(p, "traduire", afficher=lambda titre, t: res.montrer(r, t, titre))

    def signaler_bug(self):
        try:
            import rapport
            r = rapport.ouvrir(None, sys.modules[__name__], self)
        except Exception:
            log_error("signaler un bug")
            return self.say("Je n'arrive pas à préparer le rapport, désolée.")
        if r == "github":
            self.say("J'ai ouvert la page GitHub, déjà remplie. Vérifie et clique sur « Submit new issue ». "
                     "Le rapport complet est aussi copié. Merci ! 💜")
        elif r == "copie":
            self.say("Le rapport est copié : colle-le où tu veux (Ctrl+V).")

    # ---------- regarder une image : la décrire, traduire son texte, en faire un prompt
    def look_image(self, path, mode="decrire", question="", afficher=None):
        if not self.ia_remote() and not self.vision_models():
            return self.ask_yes("Pour regarder une image, il me faut une IA qui voit les images (qwen3-vl:4b, "
                                "3,3 Go, elle reste sur ton PC). Je la télécharge ? (oui / non)",
                                lambda: self.pull_vision_model("qwen3-vl:4b"))
        img = QImage(str(path))
        if img.isNull():
            return self.say("Je n'arrive pas à ouvrir cette image.")
        if max(img.width(), img.height()) > 1600:
            img = img.scaled(1600, 1600, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
        buf = QBuffer()
        buf.open(QBuffer.OpenModeFlag.WriteOnly)
        img.save(buf, "PNG")
        import base64
        b64 = base64.b64encode(bytes(buf.data())).decode()
        langue = {"fr": "français", "en": "anglais", "es": "espagnol", "de": "allemand", "it": "italien",
                  "ru": "russe", "zh": "chinois", "ja": "japonais", "hi": "hindi"}.get(
            (i18n.lang() if i18n else "fr") or "fr", "français")
        prompts = {
            "decrire": f"Décris cette image en {langue}, clairement, en 4 à 6 phrases : ce qu'on voit, l'ambiance, les "
                       "détails importants. Ne devine pas l'identité des personnes réelles.",
            "traduire": f"Lis tout le texte visible sur cette image et traduis-le en {langue}. Présente chaque bout de "
                        "texte ainsi : « original » → traduction, une ligne par bulle ou par bloc, dans l'ordre de "
                        "lecture. S'il n'y a aucun texte, dis-le simplement.",
            "prompt": "Write ONE prompt in English to recreate this image with an image generator (Stable Diffusion / "
                      "Flux): subject, composition, style, colors, lighting, camera framing, details. Comma-separated "
                      "keywords, one line, no explanation. Never name real people, brands or copyrighted characters: "
                      "describe them generically.",
            "question": f"Réponds en {langue} à cette question sur l'image : {question}",
        }
        titres = {"decrire": "👁️ Ce que je vois", "traduire": "🔤 Le texte de l'image", "prompt": "✨ Prompt pour la "
                  "recréer", "question": "💬 Ma réponse"}
        self.say({"decrire": "Je regarde l'image…", "traduire": "Je lis le texte de l'image…",
                  "prompt": "J'écris un prompt pour la recréer…"}.get(mode, "Je regarde…"))
        self.react = ("regarde", time.monotonic())
        if not self.ia_remote():
            self.vision_ready()

        def ask():
            msgs = [{"role": "user", "content": prompts[mode], "images": [b64]}]
            if self.ia_remote():
                txt = ia_api.request(ia_api.conf_from(), msgs, timeout=180, max_tokens=700)
            else:
                body = {"model": self.cfg.get("manga_vision") or self.vision_models()[0], "stream": False,
                        "messages": msgs, "options": {"temperature": 0.3}, "keep_alive": "2m"}
                with self._ollama_open(body, 240) as r:
                    txt = json.load(r)["message"]["content"]
            return re.sub(r"<think>.*?</think>", "", txt or "", flags=re.S).strip()

        def then(t):
            if isinstance(t, Exception) or not t:
                return self.say("Je n'ai pas réussi à regarder l'image" +
                                (f" : {str(t)[:80]}" if isinstance(t, Exception) else "."))
            if afficher:                                   # ex. traduction d'une zone : à côté de la zone
                afficher(titres.get(mode, "👁️"), t)
                self.say(t if len(t) < 140 else t[:130].rsplit(" ", 1)[0] + "…")
                return
            if mode == "prompt":
                t = t.strip().strip('"').strip()
                self._show_text(titres[mode], t, "Copie-le, ou ouvre l'atelier d'images : je l'y mets.")
                QApplication.clipboard().setText(t)
                self.say("Voilà ton prompt ! Je l'ai copié. Dis « crée-la » ou ouvre l'atelier pour la recréer.")
                self._dernier_prompt = t
                return
            self._show_text(titres.get(mode, "👁️"), t, "")
            self.say(t if len(t) < 260 else t[:250].rsplit(" ", 1)[0] + "… (la suite est dans la fenêtre)")
        self._bg(ask, then)

    # ---------- modèles et mods
    def open_modeles(self, onglet="modeles"):
        """La fenêtre « Modèles et mods » : tout ce qui est installé, et les mods."""
        if not modeles_fenetre:
            return self.open_models()
        w = getattr(self, "modeles_win", None)
        if w is None:
            ctx = dict(voice_dirs=VOICE_DIRS, data_dir=DATA_DIR, ollama=OLLAMA_URL, atelier=atelier, voix=voix,
                       ia_api=ia_api, ajout_ia=ajout_ia)
            w = self.modeles_win = modeles_fenetre.ModelesMods(self, ctx)
        w.montrer(onglet)

    def _mods_donnees(self):
        """Ce que les mods actifs apportent : voix, personnages, répliques, thèmes."""
        global _MOD_CHAR_DIRS
        base = str(mods.DIR)
        VOICE_DIRS[:] = [d for d in VOICE_DIRS if not str(d).startswith(base)] + mods.dossiers_voix(self.cfg)
        _MOD_CHAR_DIRS = mods.dossiers_personnages(self.cfg)
        self._mod_repliques = mods.repliques(self.cfg)
        if themes:
            for k in [k for k in themes.THEMES if k.startswith("mod_")]:
                themes.THEMES.pop(k, None)
            for t in mods.themes(self.cfg):
                themes.THEMES[t["id"]] = ("🧩 " + t["nom"], themes._hue_of(t["couleur"]), 1.0, t["sombre"], None)

    def _mods_code_demarrer(self):
        try:
            mods.demarrer(self)
            if mods.ronds(self.cfg) or mods.menus():
                self._rebuild_menus()
                rb = self.__dict__.get("ronds_bar")
                if rb is not None:
                    rb._relayout()
        except Exception:
            log_error("mods (démarrage)")

    def mods_appliquer(self):
        """Après avoir activé, désactivé, installé ou supprimé un mod."""
        try:
            self._mods_donnees()
            if themes:
                themes.install(self.app, self.cfg.get("theme", "nuit"), self.cfg.get("theme_couleur", ""))
        except Exception:
            log_error("mods")
        self._rebuild_menus()
        rb = self.__dict__.get("ronds_bar")
        if rb is not None:
            try:
                rb._relayout()
            except Exception:
                pass

    def run_rond_mod(self, rid):
        r = mods.ronds(self.cfg).get(rid) if mods else None
        if not r:
            return
        if r.get("fn"):
            return mods._sur(r["mod"], r["fn"])
        t, val = r["type"], r["valeur"]
        if t == "phrase":
            return self.handle_message(val)
        if t == "lien":
            from PyQt6.QtGui import QDesktopServices
            from PyQt6.QtCore import QUrl
            if val.startswith(("https://", "http://")):
                QDesktopServices.openUrl(QUrl(val))
            return
        if t == "dossier":
            p = Path(val).expanduser()
            if not p.is_absolute():
                p = Path(r["dossier"]) / val
            return self._open_path(p)
        if t == "appli":                    # lancer un programme = comme du code : seulement si tu as dit oui
            m = next((x for x in mods.installes() if x["id"] == r["mod"]), None)
            if not m or not m["code"] or not mods.code_autorise(self.cfg, m):
                return self.say("Ce rond veut lancer un programme. Pour ça, son mod doit contenir du code que tu as "
                                "autorisé.")
            import shlex
            subprocess.Popen(shlex.split(val), cwd=r["dossier"], stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL, start_new_session=True)

    def _on_ollama_status(self, ok, model):
        if ok and not getattr(self, "_warmed_once", False):
            self._warmed_once = True
            QTimer.singleShot(3000, self.warm_ollama)
        changed = ok != self.ollama_ok
        self.ollama_ok = ok
        if ok and not self.ia_remote():
            self.cfg["ollama_model"] = model
        for a in self.chat_actions:
            a.setText("Discuter avec elle…" if ok else "Discuter avec elle… (IA à installer)")
        if self.chat_win:
            self.chat_win.refresh()
        if changed and hasattr(self, "tray_menu"):
            QTimer.singleShot(0, self._rebuild_menus)

    def recheck_ollama(self):
        if self.chat_win:
            self.chat_win.status.setText("Recherche d'Ollama…")
        threading.Thread(target=self._check_ollama, daemon=True).start()

    def _set_model(self, model):
        self.cfg["ollama_model"] = model
        save_config(self.cfg)
        self.check_brain(model)
        if self.chat_win:
            self.chat_win.refresh()
        self._rebuild_menus()

    def check_brain(self, model=None, quiet_ok=True):
        """Prévient si le modèle choisi comme cerveau ne sait pas discuter (modèle d'images…)."""
        model = model or self.cfg.get("ollama_model", "")
        if not ajout_ia or not model or self.ia_remote():
            return

        def done(pb):
            if isinstance(pb, Exception) or not pb:
                return
            self.say(f"Attention : « {model} » ne peut pas me servir de cerveau, {pb}. "
                     "Change-le dans Réglages → Discussion → Modèle utilisé.")
        self._bg(lambda: ajout_ia.brain_problem(model), done)

    def _apply_emotion(self):
        now = time.monotonic()
        emo, self.emotion = self.emotion, ""
        if getattr(self, "l2d", None) and emo:
            self.l2d[0].emote(emo)
        if emo == "joie":
            self.happy_until = now + 1.5
            self._spawn("coeur", 1, 0.6)
            self._mood(+2)
        elif emo == "surprise":
            self.surprise_until = now + 1.0
            self._spawn("exclam", 1, 0.3)
            self.hop_start = now
        elif emo == "triste":
            self.sad_until = now + 5
        elif emo == "boude":
            self.angry_until = now + 1.0
            self._spawn("colere", 1, 0.3)
        elif emo == "timide":
            self.blush_until = now + 4
            self.react = ("joue", now)
        return emo

    # ---------- écrire directement sur elle
    def reset_input_box(self):
        """Reconstruit la barre d'écriture (après un changement de réglage)."""
        b, self.input_box = self.input_box, None
        if b is not None:
            vis = b.isVisible()
            b.close()
            b.deleteLater()
            if vis:
                QTimer.singleShot(0, self.open_input)

    def start_ronds(self):
        """La colonne de ronds à côté d'elle (si c'est le choix dans les réglages)."""
        if self.cfg.get("barre_place", "ronds") == "ronds":
            if self.ronds_bar is None:
                self.ronds_bar = RondsBar(self)
            self.ronds_bar._relayout()
            self.ronds_bar.follow()
            if self.cfg.get("ronds_affichage", "clic") == "clic" and not self.cfg.get("ronds_astuce"):
                self.cfg["ronds_astuce"] = True
                save_config(self.cfg)
                QTimer.singleShot(4000, lambda: self.say("Astuce : clique sur moi pour faire apparaître mes "
                                                         "raccourcis. Ils se rangent tout seuls quand tu ne "
                                                         "t'en sers plus !"))
        elif self.ronds_bar is not None:
            self.ronds_bar.hide()

    def set_profil(self, k):
        ico, nom, _aide, vals = PROFILS[k]
        self.cfg.update(vals)
        self.cfg["profil_actif"] = k
        save_config(self.cfg)
        self._rebuild_menus()
        self.say("Profil travail : je me fais discrète. Appelle-moi si tu as besoin !" if k == "travail" else
                 "Profil détente : on papote et on joue quand tu veux !")

    def run_rond_perso(self, rid):
        d = (self.cfg.get("ronds_perso") or {}).get(rid) or {}
        t, val = d.get("type"), (d.get("valeur") or "").strip()
        if not val:
            return self.edit_rond_perso(rid)
        if t == "phrase":
            b = self.__dict__.get("input_box")
            txt = b.edit.text().strip() if b is not None and b.isVisible() else ""
            if txt:
                b.edit.clear()
            else:
                try:
                    txt = (QApplication.clipboard().text() or "").strip()
                except Exception:
                    txt = ""
            self._user_ask = time.monotonic()
            if not txt:
                return self.handle_message(val)
            return self.handle_message(f"{val}\n\n« {txt[:6000]} »")
        try:
            if t == "appli":
                import shlex
                env = dict(os.environ)
                if os.environ.get("APPIMAGE"):
                    env["LD_LIBRARY_PATH"] = os.environ.get("COMPAGNON_ORIG_LD", "")
                subprocess.Popen(shlex.split(val), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                 start_new_session=True, env=env)
            else:
                self._open_path(Path(val).expanduser())
        except Exception as e:
            self.say(f"Je n'ai pas réussi à l'ouvrir : {str(e)[:80]}")

    def edit_rond_perso(self, rid=None, after=None):
        perso = dict(self.cfg.get("ronds_perso") or {})
        d = dict(perso.get(rid) or {"ico": "⭐", "nom": "", "type": "phrase", "valeur": ""})
        dlg = QDialog()
        dlg.setWindowTitle("Mon rond")
        f = QFormLayout(dlg)
        ico, nom, val = QLineEdit(d["ico"]), QLineEdit(d["nom"]), QLineEdit(d["valeur"])
        ico.setMaxLength(4)
        ico.setFixedWidth(60)
        nom.setPlaceholderText("Ex : Japonais poli")
        typ = QComboBox()
        for lab, k in (("💬 Une consigne pour elle (sur le texte copié)", "phrase"),
                       ("🚀 Lancer un programme", "appli"), ("📂 Ouvrir un fichier ou un dossier", "dossier")):
            typ.addItem(lab, k)
        typ.setCurrentIndex(max(0, typ.findData(d["type"])))
        aide = QLabel()
        aide.setWordWrap(True)

        def maj():
            k = typ.currentData()
            val.setPlaceholderText({"phrase": "Ex : Traduis en japonais, avec un ton poli",
                                    "appli": "Ex : firefox    ou    steam", "dossier": "Ex : ~/Documents/cours"}[k])
            aide.setText({"phrase": "Au clic, elle applique ta consigne au texte que tu as copié (ou écrit dans la "
                                    "barre). Sans texte, elle répond juste à la consigne.",
                          "appli": "Écris la commande qui lance le programme, comme dans un terminal.",
                          "dossier": "Le chemin du fichier ou du dossier à ouvrir."}[k])
        typ.currentIndexChanged.connect(maj)
        maj()
        f.addRow("Icône (un emoji)", ico)
        f.addRow("Nom", nom)
        f.addRow("Ce rond sert à", typ)
        f.addRow("Quoi", val)
        f.addRow(aide)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)
        f.addRow(bb)
        if not dlg.exec() or not val.text().strip():
            return
        if rid is None:
            n = 1
            while f"perso{n}" in perso:
                n += 1
            rid = f"perso{n}"
        perso[rid] = {"ico": ico.text().strip() or "⭐", "nom": nom.text().strip() or "Mon rond",
                      "type": typ.currentData(), "valeur": val.text().strip()}
        self.cfg["ronds_perso"] = perso
        rb = self.ronds_bar
        ids = rb.ids() if rb is not None else list(self.cfg.get("ronds") or RONDS_DEFAUT)
        if rid not in ids:
            k = len(ids) if after is None else after + 1
            ids = ids[:k] + [rid] + ids[k:]
        self.cfg["ronds"] = ids
        save_config(self.cfg)
        if rb is not None:
            rb._relayout()
            rb.follow()

    def delete_rond_perso(self, rid):
        perso = dict(self.cfg.get("ronds_perso") or {})
        perso.pop(rid, None)
        self.cfg["ronds_perso"] = perso
        self.cfg["ronds"] = [i for i in (self.cfg.get("ronds") or RONDS_DEFAUT) if i != rid]
        save_config(self.cfg)
        if self.ronds_bar is not None:
            self.ronds_bar._relayout()

    def drop_on_rond(self, rid, paths):
        """Un fichier lâché sur un rond : 🌐 = on travaille sur son texte, 🖥️ = elle regarde l'image."""
        p = Path(paths[0])
        if rid in ("ecran",) and p.is_file() and self._file_kind(p) == "image":
            return self.handle_drop(paths)
        if rid in ("texte", "traduire", "corriger") and p.is_file() and self._file_kind(p) == "texte":
            txt = self._read_text_file(p)
            if txt and txt.strip():
                txt = txt.strip()
                if rid in ("traduire", "corriger"):
                    return self.text_tool(rid, txt[:12000])
                self.say(f"« {p.name} » : j'en fais quoi ?")
                return self._drop_menu(f"📄 {p.name}", [
                    ("📄 Le résumer", lambda: self.text_tool("resumer", txt[:12000])),
                    ("🌐 Le traduire", lambda: self.text_tool("traduire", txt[:12000])),
                    ("💡 L'expliquer simplement", lambda: self.text_tool("expliquer", txt[:12000])),
                    ("✏️ Le corriger", lambda: self.text_tool("corriger", txt[:12000]))])
        self.handle_drop(paths)

    def open_tor(self):
        try:
            import tor_viki
            w = self.__dict__.get("tor_win")
            if w is None:
                w = self.__dict__["tor_win"] = tor_viki.make_window(self)
            w.show()
            w.raise_()
            w.activateWindow()
        except Exception as e:
            log_error("tor")
            self.say(f"Je n'ai pas pu ouvrir Tor : {str(e)[:80]}")

    def toggle_ronds(self):
        """Un clic sur elle : les ronds apparaissent. Un autre clic ne les cache plus (on clique souvent sur elle
        pour jouer : ils clignotaient) ; ils se rangent tout seuls quand on ne s'en sert plus."""
        if time.monotonic() - self.__dict__.get("_skip_toggle", 0) < 0.6:
            return
        rb = self.ronds_bar
        if rb is None or self.cfg.get("barre_place", "ronds") != "ronds" \
                or self.cfg.get("ronds_affichage", "clic") != "clic":
            return
        rb.shown = True
        rb.last_use = time.monotonic()
        rb.follow()

    def _ronds_res(self):
        rb = self.__dict__.get("ronds_bar")
        return rb is not None and rb.isVisible() and "ressources" in rb.ids()

    def open_input(self):
        if not self.input_box:
            self.input_box = InputBox(self)
        self.input_box.open()

    # ---------- émotes
    def _spawn_emoji(self, ch, n=2):
        k = len(self.particles)
        self._spawn("emoji", n, 0.9)
        for q in self.particles[k:]:
            q["t"] = ch
            q["size"] *= 1.35
            q["life"] += 0.6

    def react_emote(self, text):
        """Elle réagit à une émote : petite émotion, animation et l'émote qui flotte au-dessus d'elle."""
        found = [m.group(0) for m in EMOJI_RE.finditer(text)]
        if not found:
            return False
        e = found[0]
        key = e if e in EMOTES else e.rstrip("\ufe0f")
        if key not in EMOTES:
            key = next((k for k in EMOTES if k.rstrip("\ufe0f") == key), None)
        self.last_interaction = time.monotonic()
        self.sleeping = False
        self._spawn_emoji(e, 3)
        if key:
            emo, anim, lines = EMOTES[key]
            if anim:
                self.react = (anim, time.monotonic())
            if emo:
                self.emotion = emo
            if key in ("🎵",):
                self._spawn("note", 2)
            elif key in ("✨", "🎉"):
                self._spawn("etoile", 3)
            self.say(random.choice(lines))
        else:
            self.emotion = "joie"
            self.say(random.choice(["Hihi !", "Joli !", "J'aime bien cette émote !"]))
        if extras:
            self.add_xp(1)
        return True

    # ---------- outils de texte (traduire, corriger…)
    def text_tool(self, kind, text="", lang=None, from_box=False):
        self._user_ask = time.monotonic()
        return self._text_tool(kind, text, lang, from_box)

    def _text_tool(self, kind, text="", lang=None, from_box=False):
        src = (text or "").strip()
        le = getattr(self, "last_error", None)
        if not src and kind == "erreur" and le and time.monotonic() - le[0] < 3600:
            src = f"$ {le[1]}\n{le[2]}"
            from_box = False
        if not src:
            src = (QApplication.clipboard().text() or "").strip()
            from_box = False
        if not src:
            self.say("Écris le texte dans la barre, ou copie-le d'abord avec Ctrl+C, puis reclique.")
            return
        model = self.tools_model()
        if not self.ollama_ok and not model:
            self.recheck_ollama()
            self.say_from("sans_ia")
            return
        src = src if kind in ("erreur", "revue", "code") else src[:6000]
        if kind == "traduire":
            cible = (f"Traduis le texte en {lang}." if lang else
                     "Si le texte est en français, traduis-le en anglais ; sinon, traduis-le en français.")
            consigne = cible + " Garde le ton et la mise en forme. Réponds uniquement avec la traduction."
        elif kind == "corriger":
            consigne = ("Corrige l'orthographe, la grammaire, la conjugaison et la ponctuation du texte, "
                        "sans changer son sens, sa langue ni son style. Réponds uniquement avec le texte corrigé.")
        elif kind == "reformuler":
            consigne = ("Reformule le texte pour qu'il soit clair, naturel et poli, dans la même langue. "
                        "Réponds uniquement avec le texte reformulé.")
        elif kind == "resumer":
            consigne = "Résume le texte en français, en quelques phrases courtes. Réponds uniquement avec le résumé."
        elif kind == "expliquer":
            consigne = ("Explique simplement en français, comme à un ami, ce que veut dire ce texte "
                        "(mots difficiles, idée principale). Sois bref.")
        elif kind == "revue":
            src = src[:24000]
            consigne = ("Relis ce code comme un développeur expérimenté. En français et de façon concise : "
                        "liste les bugs probables, les erreurs de logique, les problèmes de sécurité et les cas "
                        "oubliés, du plus grave au moins grave, avec le numéro de ligne ou la fonction concernée "
                        "et une correction courte. S'il n'y a rien de grave, dis-le simplement.")
        elif kind == "code":
            src = src[:24000]
            consigne = ("Explique ce code en français, simplement : à quoi il sert, comment il est organisé "
                        "(fonctions ou parties principales), et les points qui méritent attention. Reste bref.")
        elif kind == "erreur":
            src = src[-6000:]
            consigne = ("Voici une erreur de programme (sortie de terminal, traceback ou message de compilateur). "
                        "En français et brièvement : 1) ce qui ne va pas, en une ou deux phrases simples ; "
                        "2) la cause la plus probable (fichier et ligne si on les voit) ; "
                        "3) comment corriger, avec la commande ou le bout de code à changer si c'est clair. "
                        "Si plusieurs erreurs s'enchaînent, concentre-toi sur la première vraie cause.")
        else:  # mail
            consigne = ("Transforme le texte en un e-mail poli et bien écrit, dans la même langue, "
                        "avec un objet, une formule d'appel et une formule de politesse. "
                        "Réponds uniquement avec l'e-mail.")
        system = ("Tu es un outil d'écriture précis. Tu suis la consigne à la lettre, sans introduction, "
                  "sans guillemets autour du résultat et sans commentaire.")
        prompt = f"{consigne}\n\nTexte :\n{src}"
        self.say(random.choice({"traduire": ["Je traduis…", "Une seconde, je traduis !"],
                                "corriger": ["Je corrige ça…", "Voyons les fautes…"],
                                "resumer": ["Je lis et je résume…"],
                                "expliquer": ["Je regarde ça…"],
                                "erreur": ["Voyons ce bug…", "Je regarde cette erreur…"]}.get(kind, ["Je m'en occupe…"])))
        if model and manga and kind == "traduire" and manga.is_translator_model(model):
            if re.search(r"[\u3040-\u30ff]", src):
                src_code = "ja"
            elif re.search(r"[\uac00-\ud7af]", src):
                src_code = "ko"
            elif re.search(r"[\u4e00-\u9fff]", src):
                src_code = "zh"
            elif voix and voix.looks_french(src):
                src_code = "fr"
            else:
                src_code = "en"
            dst = lang or ("anglais" if src_code == "fr" else "français")
            system, prompt = "", manga.translategemma_prompt(src, src_code, dst)
        self.ask_ai(prompt, lambda out, k=kind, fb=from_box: self._text_tool_done(k, out, fb),
                    system=system, timeout=600 if model else 300, model=model)

    def tools_model(self):
        """Modèle Ollama choisi pour traduire / corriger / résumer ("" = son cerveau habituel)."""
        m = self.cfg.get("outils_modele", "")
        return m if m and m in self.ollama_list() else ""

    def set_tools_model(self, m):
        self.cfg["outils_modele"] = m
        save_config(self.cfg)
        self.say(f"D'accord, je traduis et je corrige avec « {m} »." if m else
                 "D'accord, je traduis avec mon cerveau habituel.")

    def _text_tool_done(self, kind, out, from_box):
        out = (out or "").strip().strip("«»\"").strip()
        if not out:
            self.emotion = "triste"
            m = self.tools_model() or ("" if self.ia_remote() else self.cfg.get("ollama_model", ""))
            self.say("Oups, je n'ai pas réussi" + (f" avec « {m} »" if m else "") +
                     ". Réessaie, ou choisis un autre modèle (flèche du bouton Traduire → Modèle).")
            return
        QApplication.clipboard().setText(out)
        title = OUTILS_TEXTE.get(kind, ("", "Résultat"))[1]
        box = self.input_box
        if from_box and box and box.isVisible() and kind in ("traduire", "corriger", "reformuler", "mail") \
                and "\n" not in out:
            box.edit.setText(out)        # le résultat remplace le texte de la barre
        else:
            self._show_text(title, out, "Copié dans le presse-papiers ✓ (Ctrl+V pour le coller)")
        self.emotion = "joie"
        if kind in ("resumer", "expliquer", "erreur", "revue", "code") and len(out) < 400:
            self.say(out)
        else:
            self.say(random.choice(["Voilà ! C'est copié, tu n'as plus qu'à coller.",
                                    "C'est fait, et c'est déjà copié !"]))

    def handle_message(self, text):
        """Message tapé dans le petit champ : commandes rapides d'abord, sinon discussion."""
        self.last_interaction = time.monotonic()
        self._user_ask = time.monotonic()
        if getattr(self, "learn", None):
            self.learn.note_message(text)
        self.sleeping = False
        self.cfg["stats"]["messages"] = self.cfg["stats"].get("messages", 0) + 1
        if extras:
            self.add_xp(2)
        if self.pending_confirm:
            act, until = self.pending_confirm
            self.pending_confirm = None
            if time.monotonic() < until and re.match(r"^\s*(oui|ouais|ok|vas[- ]y|d'accord|confirme|yes)\b",
                                                     text, re.I):
                self._power(act, confirmed=True)
                return
            if re.match(r"^\s*(non|annule|stop|pas maintenant)\b", text, re.I):
                self.say("D'accord, j'annule.")
                return
        if getattr(self, "reader_active", False) and re.match(r"^\s*(stop|arr[eê]te|chut|tais|pause)", text, re.I):
            self.reader_win.pause()
            self.say("D'accord, je mets le livre en pause.")
            return
        if self.reading and re.match(r"^\s*(stop|arr[eê]te|chut|tais)", text, re.I):
            self.stop_reading()
            self.say("D'accord, j'arrête de lire.")
            return
        if self.game:
            r = self.game.answer(text)
            if r:
                reply, emo, done = r
                self.emotion = emo
                if done:
                    self.game = None
                if emo == "joie":
                    self._spawn("etoile", 2)
                self.say(reply)
                return
        if time.monotonic() < self.journal_until and len(text) > 3 and not re.match(
                r"^\s*(chut|tais|stop|annule)", text, re.I):
            self.journal_until = 0.0
            self.journal_write(text)
            return
        if only_emojis(text) and self.react_emote(text):
            return
        tt = parse_text_tool(text)
        if tt:
            self.text_tool(tt[0], tt[1], tt[2], from_box=False)
            return
        if self._pending_yes_check(text):
            return
        if getattr(self, "brain", None) and self._brain_message(text):
            return
        if self._local_command(text):
            self._brain_after(text, True)
            return
        acts = self.parse_order(text)
        if acts:
            self._brain_after(text, True)
            self.queue(acts, random.choice(["D'accord !", "Tout de suite !", "C'est parti !"]))
            return
        if getattr(self, "brain", None) and self._brain_after(text, False):
            return
        t = text.lower()
        looks_like_order = bool(self._find_objects(" " + t + " ")) or any(
            re.search(pat, " " + t + " ") for _, pat in VERBES)
        if self.ollama_ok and looks_like_order:
            self.say("…")
            threading.Thread(target=self._plan_with_ai, args=(text,), daemon=True).start()
            return
        subj = vieprivee.wiki_subject(text) if vieprivee and self.cfg.get("wiki_proposer", True) else None
        if subj:
            fn = lambda s=subj: self.open_wiki(s)
            if self.ollama_ok:
                self.ask_yes(f"Tu veux que j'ouvre Wikipédia sur « {subj} » pour en savoir plus ?", fn, delay=9000)
            else:
                return self.ask_yes(f"Je n'ai pas la réponse par cœur, mais je peux ouvrir Wikipédia sur « {subj} ». "
                                    "Je l'ouvre ?", fn)
        if self.ollama_ok:
            if self.chat_win and self.chat_win.isVisible():
                self.chat_win.add("toi", text)
                self.chat_win.waiting = True
                self.chat_win.refresh()
            self.send_chat(text)
        else:
            self.recheck_ollama()
            self.say_from("sans_ia")

    # ---------- micro : reconnaissance vocale locale (faster-whisper)
    def _stt_python(self):
        cands = [DATA_DIR / ".venv-piper" / "bin" / "python", APP_DIR / ".venv-piper" / "bin" / "python",
                 Path(natural_python() or APP_DIR / ".venv-voix" / "bin" / "python")]
        if PORTABLE or IS_WIN:                         # l'AppImage / le .exe embarquent la reconnaissance vocale
            return sys.executable
        for cand in cands:
            if cand.exists():
                return str(cand)
        return None

    def _check_stt(self):
        if IS_WIN and plateforme.whispercpp_exe(APP_DIR):
            self.stt_installed = True
            return
        if IS_WIN:
            try:
                import faster_whisper  # noqa: F401
                self.stt_installed = True
            except Exception:
                self.stt_installed = False
            return
        py = self._stt_python()
        if not py:
            self.stt_installed = False
            return
        r = subprocess.run([py, "-c", "import faster_whisper"], capture_output=True)
        self.stt_installed = r.returncode == 0

    def install_stt(self):
        if IS_WIN:
            self.say("La reconnaissance vocale est déjà incluse dans la version Windows.")
            return
        py = self._stt_python()
        uv = shutil.which("uv") or next((str(c) for c in (Path.home() / ".local/bin/uv",
                                                        Path.home() / ".local/share/viki/uv/bin/uv") if c.exists()), None)
        if not py or not uv:
            QMessageBox.information(None, "Micro", "Il faut d'abord la voix Piper (bash install.sh), "
                                    "qui installe aussi l'outil « uv ».")
            return
        self.say("J'installe ce qu'il faut pour t'entendre, ça prend une ou deux minutes…")

        def work():
            env = dict(os.environ, VIRTUAL_ENV=str(Path(py).parent.parent))
            r = subprocess.run([uv, "pip", "install", "faster-whisper"], capture_output=True, text=True, env=env)
            self._check_stt()
            if self.stt_installed:
                self.bridge.stt_info.emit("C'est prêt ! Clique sur le micro et parle-moi. "
                                          "La toute première fois, je télécharge mon oreille (environ 480 Mo).")
            else:
                print("Installation micro :", r.stderr[-800:], file=sys.stderr)
                self.bridge.stt_info.emit("L'installation du micro a échoué, regarde le terminal.")
        threading.Thread(target=work, daemon=True).start()

    def toggle_mic(self):
        if self.mic_proc:
            self._stop_recording()
            return
        if self.stt_installed is False:
            r = QMessageBox.question(None, "Micro", "Pour que je t'entende, il faut installer la "
                                     "reconnaissance vocale locale (faster-whisper, rien ne part sur "
                                     "internet).\n\nL'installer maintenant ?")
            if r == QMessageBox.StandardButton.Yes:
                self.install_stt()
            return
        rec = shutil.which("pw-record") or shutil.which("arecord")
        if not rec:
            self.say("Je ne trouve pas d'outil pour enregistrer le micro (pw-record).")
            return
        self._mic_err = ""
        self.mic_file = str(self.tmpdir / f"micro{int(time.time())}.wav")
        if rec.endswith("pw-record"):
            cmd = [rec, "--rate", "16000", "--channels", "1", "--format", "s16", self.mic_file]
        else:
            cmd = [rec, "-q", "-f", "S16_LE", "-r", "16000", "-c", "1", self.mic_file]
        self._stop_audio()
        self.mic_proc = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        self.sleeping = False
        self.react = ("regarde", time.monotonic())
        self.bubble_text = "● Je t'écoute… (reclique sur le micro pour terminer)"
        self.bubble_until = time.monotonic() + 40
        self._update_mask()
        if self.input_box:
            self.input_box._mic_style(True)
        threading.Thread(target=self._warm_stt, daemon=True).start()     # charge l'oreille en avance
        self._mic_timer = QTimer.singleShot(30000, lambda: self.mic_proc and self._stop_recording())

    def _stop_recording(self):
        proc, self.mic_proc = self.mic_proc, None
        if proc is not None and getattr(proc, "stderr_text", ""):
            try:
                with open(MIC_LOG, "a") as log:
                    log.write(proc.stderr_text + "\n")
            except Exception:
                pass
        if self.input_box:
            self.input_box._mic_style(False)
        if not proc:
            return
        try:
            proc.send_signal(2)            # SIGINT : l'enregistreur termine proprement le fichier
            proc.wait(timeout=3)
        except Exception:
            proc.kill()
        self.bubble_text = "…"
        self.bubble_until = time.monotonic() + 60
        self._update_mask()
        threading.Thread(target=self._transcribe, args=(self.mic_file,), daemon=True).start()

    def _warm_stt(self):
        with self.stt_lock:
            if self.stt_proc and self.stt_proc.poll() is None:
                return True
            py = self._stt_python()
            if not py:
                return False
            cores, ram = self.hw
            size = self.cfg.get("stt_model", "auto")
            if size not in ("tiny", "base", "small"):
                size = "small" if (ram >= 14 and cores >= 12) else "base" if ram >= 6 else "tiny"
            env = dict(os.environ, COMPAGNON_WHISPER=os.environ.get("COMPAGNON_WHISPER", size),
                       COMPAGNON_LANGUE=self.cfg.get("langue", "fr"),
                       COMPAGNON_NOMS=", ".join(self._all_names()),
                       COMPAGNON_MODELS=str(MODELS_WHISPER))
            CONFIG_DIR.mkdir(parents=True, exist_ok=True)
            log = open(MIC_LOG, "a")
            log.write(f"\n=== {datetime.datetime.now():%d/%m %H:%M:%S} chargement de l'oreille ({size}) avec {py}\n")
            log.flush()
            if IS_WIN and plateforme.whispercpp_exe(APP_DIR):
                # whisper.cpp : petit programme à part, robuste sur tous les processeurs
                self.stt_proc = plateforme.WhisperCppSTT(env, APP_DIR, DATA_DIR / "models" / "whisper.cpp")
            elif IS_WIN:
                # programme séparé : si la reconnaissance plante, elle seule s'arrête (pas tout le compagnon)
                env["COMPAGNON_COMPUTE"] = self.cfg.get("stt_compute", "int8")
                env["PYTHONIOENCODING"] = "utf-8"
                self.stt_proc = subprocess.Popen(self._ecoute_cmd(), stdin=subprocess.PIPE, env=env,
                                                 stdout=subprocess.PIPE, stderr=log, text=True,
                                                 encoding="utf-8")
            else:
                self.stt_proc = subprocess.Popen(isolated([py, str(APP_DIR / "ecoute.py")],
                                                          {"small": 2.5, "base": 1.5, "tiny": 1.0}[size], "oreille"),
                                                 stdin=subprocess.PIPE, env=env,
                                                 stdout=subprocess.PIPE, stderr=log, text=True)
            first = [True]

            def slow_note():
                have = ((DATA_DIR / "models" / "whisper.cpp" / plateforme.WCPP_MODELS.get(size, "")).exists()
                        if IS_WIN else (MODELS_WHISPER / f"models--Systran--faster-whisper-{size}").exists())
                if first[0] and not have:
                    self.bridge.stt_info.emit("La première fois, je télécharge mon oreille (quelques centaines "
                                              "de Mo)… patiente un peu.")
            threading.Timer(6, slow_note).start()
            line = self.stt_proc.stdout.readline()
            first[0] = False
            log.write(("oreille prête" if '"ready": true' in line else "oreille : échec " + line.strip()[:300])
                      + f" ({self.cfg.get('stt_compute', 'int8')})\n")
            log.flush()
            try:
                ok = json.loads(line).get("ready", False)
            except Exception:
                ok = False
            if not ok and IS_WIN and not line.strip() and self.cfg.get("stt_compute", "int8") == "int8" \
                    and not plateforme.whispercpp_exe(APP_DIR):
                # plantage au chargement (certains processeurs) : on réessaie en mode « float32 »
                try:
                    self.stt_proc.kill()
                except Exception:
                    pass
                self.stt_proc = None
                self.cfg["stt_compute"] = "float32"
                save_config(self.cfg)
                log.write("l'oreille a planté en int8 : nouvel essai en float32\n")
                log.flush()
                self.stt_lock.release()
                try:
                    return self._warm_stt()
                finally:
                    self.stt_lock.acquire()
            if not ok:
                print("Micro :", line.strip(), file=sys.stderr)
                self.stt_error = (line.strip() or self._mic_log_tail()
                                  or "l'oreille s'est arrêtée au chargement (plantage)")
                try:
                    self.stt_proc.kill()
                except Exception:
                    pass
                self.stt_proc = None
            return ok

    def test_mic(self):
        """Test complet : enregistre 4 s, mesure le volume, puis essaie de comprendre."""
        rec = shutil.which("pw-record") or shutil.which("arecord")
        if not rec:
            self.say("Je ne trouve pas d'outil pour enregistrer (pw-record). Installe : sudo pacman -S pipewire-audio")
            return
        if self.stt_installed is False:
            self.say("La reconnaissance vocale n'est pas installée : je l'installe maintenant.")
            self.install_stt()
            return
        if self.listener:
            self.listener.stop()
        path = str(self.tmpdir / "test_micro.wav")
        cmd = ([rec, "--rate", "16000", "--channels", "1", "--format", "s16", path] if rec.endswith("pw-record")
               else [rec, "-q", "-f", "S16_LE", "-r", "16000", "-c", "1", path])
        self._stop_audio()
        try:
            proc = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, text=True)
        except Exception as e:
            self.say(f"Impossible de lancer l'enregistrement : {e}")
            return
        self.bubble_text = "🎤 Test : dis une phrase maintenant… (4 secondes)"
        self.bubble_until = time.monotonic() + 6
        self._update_mask()
        threading.Thread(target=self._warm_stt, daemon=True).start()

        def stop():
            try:
                proc.send_signal(2)
                proc.wait(timeout=3)
            except Exception:
                proc.kill()
            err = (proc.stderr.read() or "").strip() if proc.stderr else getattr(proc, "stderr_text", "")
            dur, lvl = self.wav_level(path)
            with open(MIC_LOG, "a") as log:
                log.write(f"\n=== test du micro : {dur:.1f} s, volume {lvl:.4f}, outil {rec}\n{err[-600:]}\n")
            if dur < 0.3:
                self.say("L'enregistrement n'a rien donné." + (f" Erreur : {err[-150:]}" if err else
                         " Le micro est peut-être pris par une autre appli."))
                return
            if lvl < 0.002:
                self.say("J'enregistre bien, mais je n'entends que du silence. " + (
                    "Vérifie Paramètres Windows → Confidentialité → Microphone : « Autoriser les applications "
                    "de bureau à accéder au micro » doit être activé, et le bon micro choisi dans Son."
                    if IS_WIN else "Va dans les paramètres du son et choisis le bon micro comme périphérique "
                    "d'entrée par défaut."))
                return
            self.say(f"Je t'entends bien (volume {min(100, int(lvl * 1000))} %) ! Je vérifie si je te comprends…")

            def work():
                if not self._warm_stt():
                    self.bridge.stt_info.emit(self._stt_error_text())
                    return
                with self.stt_lock:
                    try:
                        self.stt_proc.stdin.write(path + "\n")
                        self.stt_proc.stdin.flush()
                        res = json.loads(self.stt_proc.stdout.readline())
                    except Exception as e:
                        res = {"error": repr(e)}
                txt = res.get("text", "")
                self.bridge.stt_info.emit(f"J'ai entendu : « {txt} ». Le micro marche !" if txt else
                                          "Je t'entends mais je n'ai pas compris de mots… "
                                          + (res.get("error", "")[:120] or "Parle un peu plus fort ou plus près."))
                if self.cfg.get("wake") and extras:
                    self.bridge.ai_done.emit(lambda _t: self.set_wake(self.cfg["wake"], announce=False), "")
            threading.Thread(target=work, daemon=True).start()
        QTimer.singleShot(4000, stop)

    def _restart_stt(self):
        """L'oreille écoute dans une seule langue : on la relance quand la langue change."""
        with self.stt_lock:
            if self.stt_proc and self.stt_proc.poll() is None:
                try:
                    self.stt_proc.kill()
                except Exception:
                    pass
            self.stt_proc = None

    def download_files(self, files, dest, label, done_msg, unzip=False):
        """Télécharge des fichiers (seulement quand tu le demandes) dans le dossier de données."""
        self.say(f"Je télécharge {label}… (ça utilise internet une seule fois)")

        def work():
            err = ""
            try:
                Path(dest).mkdir(parents=True, exist_ok=True)
                for url, name in files:
                    tmp = Path(dest) / (name + ".part")
                    req = urllib.request.Request(url, headers={"User-Agent": "compagnon-bureau"})
                    with urllib.request.urlopen(req, timeout=60) as r, open(tmp, "wb") as f:
                        shutil.copyfileobj(r, f, 1 << 20)
                    if unzip:
                        import zipfile
                        with zipfile.ZipFile(tmp) as z:
                            z.extractall(dest)
                        tmp.unlink()
                        for exe in Path(dest).rglob("realesrgan-ncnn-vulkan"):
                            exe.chmod(0o755)
                    else:
                        tmp.rename(Path(dest) / name)
            except Exception as e:
                err = str(e)

            def fin(_t):
                if err:
                    self.say(f"Le téléchargement a échoué : {err[:120]}")
                else:
                    self.voice_model = self.voice_model or find_voice_model(self.cfg.get("piper_voice", ""))
                    self.say(done_msg)
                    self._rebuild_menus()
            self.bridge.ai_done.emit(fin, "")
        threading.Thread(target=work, daemon=True).start()

    def has_voice(self, code):
        """Une vraie voix (Piper) pour cette langue ?"""
        if not voix:
            return bool(self.voice_model)
        if code == "fr":
            return bool(self.voice_model)
        return bool(voix.voice_for(code, self.cfg, VOICE_DIRS)[0])

    def install_voice(self, code=None, then_say=True):
        """Télécharge la voix de la langue (Hugging Face, ~60 Mo, une seule fois) — seulement quand tu le demandes.
        Essaie chaque voix prévue, la version v1.0.0 d'abord."""
        code = code or self.cfg.get("langue", "fr")
        cands = (voix.VOIX_DEFAUT.get(code) if voix else None) or []
        nom = voix.LANGUES[code][1] if voix and code in voix.LANGUES else code
        if not cands:
            return self.say(f"Il n'existe pas encore de jolie voix libre en {nom} : je garde ma voix de secours "
                            "pour cette langue.") if then_say else None
        dest = DATA_DIR / "voices"
        self.say(f"Je télécharge ma voix en {nom} (environ 60 Mo, une seule fois)…")
        think = self.thinking("🔊 Je télécharge ma voix", jauges=False)

        def work():
            dest.mkdir(parents=True, exist_ok=True)
            last = ""
            for chemin, stem in cands:
                for base in voix.HF_REVS:
                    try:
                        for ext in (".onnx.json", ".onnx"):
                            tmp = dest / (stem + ext + ".part")
                            req = urllib.request.Request(base + chemin + "/" + stem + ext,
                                                         headers={"User-Agent": "Viki-compagnon"})
                            with urllib.request.urlopen(req, timeout=60) as r, open(tmp, "wb") as f:
                                shutil.copyfileobj(r, f, 1 << 20)
                        for ext in (".onnx.json", ".onnx"):
                            (dest / (stem + ext + ".part")).rename(dest / (stem + ext))
                        return stem
                    except Exception as e:
                        last = str(e)
                        for ext in (".onnx.json", ".onnx"):
                            (dest / (stem + ext + ".part")).unlink(missing_ok=True)
            raise RuntimeError(last or "aucune voix trouvée")

        def done(r):
            think.end()
            if isinstance(r, Exception):
                log_error("voix " + code, r)
                return self.say(f"Je n'ai pas pu télécharger ma voix : {str(r)[:100]}. Je garde ma voix de secours.")
            if code == "fr":
                self.cfg["piper_voice"] = r
                self.voice_model = find_voice_model(r)
            else:
                self.cfg.setdefault("voix_langue", {})[code] = {"voice": r, "speaker": -1}
            save_config(self.cfg)
            self._rebuild_menus()
            hello = {"fr": "Voilà, j'ai ma vraie voix ! Ça te plaît ?", "en": "Here's my real voice! Do you like it?",
                     "es": "¡Ya tengo mi voz de verdad! ¿Te gusta?", "de": "Jetzt habe ich meine echte Stimme!",
                     "it": "Ecco la mia vera voce! Ti piace?", "pt": "Agora tenho minha voz de verdade!",
                     "ru": "Вот мой настоящий голос! Нравится?", "zh": "这是我真正的声音！你喜欢吗？",
                     "hi": "यह मेरी असली आवाज़ है! तुम्हें पसंद आई?"}.get(code)
            if then_say and hello:
                self.say(hello)
        self._bg(work, done)

    def _propose_voice(self):
        """Pas de vraie voix pour la langue parlée : on le propose une fois (oui / non)."""
        code = self.cfg.get("langue", "fr")
        if not self.cfg.get("assistant_fait") or not self.cfg.get("voice", True) or self.has_voice(code) \
                or not voix or not voix.VOIX_DEFAUT.get(code):
            return
        cle = "voix_proposee_" + code
        if self.cfg.get(cle):
            return
        self.cfg[cle] = True
        save_config(self.cfg)
        self.ask_yes("Pour l'instant j'ai une voix de robot 🤖 Je télécharge ma vraie voix (environ 60 Mo, une "
                     "seule fois) ? (oui / non)", lambda: self.install_voice(code))

