    def _drop_voice(self, p):
        """Voix Piper : .onnx (+ .onnx.json à côté) ou .zip qui les contient."""
        import tempfile, zipfile
        dest = DATA_DIR / "voices"
        dest.mkdir(parents=True, exist_ok=True)
        try:
            if p.suffix.lower() == ".zip":
                tmp = Path(tempfile.mkdtemp())
                with zipfile.ZipFile(p) as z:
                    for member in z.namelist():
                        if member.startswith("/") or ".." in Path(member).parts:
                            raise ValueError("archive suspecte")
                    z.extractall(tmp)
                models = list(tmp.rglob("*.onnx"))
            elif p.is_dir():
                models = list(p.rglob("*.onnx"))
            else:
                models = [p if p.suffix.lower() == ".onnx" else Path(str(p)[:-5])]
            done = []
            for m in models:
                cfgf = Path(str(m) + ".json")
                if not (m.exists() and cfgf.exists()):
                    continue
                shutil.copy2(m, dest / m.name)
                shutil.copy2(cfgf, dest / cfgf.name)
                done.append(m.stem)
            if not done:
                return self.say("Il me faut les deux fichiers de la voix : le .onnx et le .onnx.json à côté.")
        except Exception as e:
            return self.say(f"Je n'ai pas pu installer cette voix : {str(e)[:100]}")
        stem = done[0]
        code = next((c for c, v in voix.LANGUES.items() if stem.startswith(v[2])), "fr") if voix else "fr"
        self.set_lang_voice(code, stem, -1)
        self.say("Nouvelle voix installée ! Elle te plaît ?" if code == "fr" else
                 f"Voix installée pour le {voix.LANGUES[code][1]} !")

    def mouseDoubleClickEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton:
            if self.sleeping:
                self._wake_up()
            rb = self.ronds_bar                           # double-clic : les ronds restent là, avec la zone d'écriture
            if rb is not None and self.cfg.get("ronds_affichage", "clic") == "clic":
                rb.shown, rb.last_use = True, time.monotonic()
                rb.follow()
                self._skip_toggle = time.monotonic()
            self.open_input()

    # ---------- zones et réactions
    # zones cliquables des modèles Live2D / Spine -> réactions du compagnon
    AREA_KINDS = (("head", "tete"), ("atama", "tete"), ("hair", "cheveux"), ("face", "joue"), ("cheek", "joue"),
                  ("hand", "main"), ("arm", "main"), ("foot", "pieds"), ("leg", "pieds"), ("shoe", "pieds"),
                  ("shoulder", "epaule"), ("body", "bras"), ("acc", "accessoire"), ("hat", "accessoire"))
    AREA_SKIP = ("chest", "breast", "bust", "mune", "oppai", "skirt", "pants", "hip", "butt", "thigh", "crotch")

    def _model_click(self, pos):
        """Clic sur un modèle animé : sa zone cliquable décide du mouvement et de la réaction.
        Renvoie True si le clic a été traité."""
        m, f, (x0, y0, x1, y1) = self.l2d
        lx = (pos.x() - (self.char_cx - self.cw / 2)) / max(1, self.cw)
        ly = (pos.y() - BUBBLE_AREA) / max(1, self.ch)
        if not (0 <= lx <= 1 and 0 <= ly <= 1):
            return False
        px = (x0 + lx * (x1 - x0)) * f
        py = (y0 + ly * (y1 - y0)) * f
        try:
            area = m.hit(px, py)
        except Exception:
            area = None
        if not area:
            return False
        a = area.lower()
        if any(k in a for k in self.AREA_SKIP):          # zones qu'on ne fait pas réagir
            self._react(None)
            return True
        kind = next((k for key, k in self.AREA_KINDS if key in a), None)
        m.tap_area(area)
        self._area_tapped = True                         # le geste de la zone est déjà lancé
        try:
            self._react(kind)
        finally:
            self._area_tapped = False
        return True

    def _zone_at(self, pos):
        ix = (pos.x() - (self.char_cx - self.cw / 2)) / self.scale
        iy = (pos.y() - BUBBLE_AREA) / self.scale
        for z in self.zones:
            if zone_contains(z, ix, iy):
                return z
        return None

    # ---------- muet
    def is_muted(self):
        u = self.cfg.get("mute_until", 0)
        if u == -1:
            return True
        if u and time.time() < u:
            return True
        if u:
            self.cfg["mute_until"] = 0                   # fin du muet temporaire
        return False

    def mute_label(self):
        """« muette jusqu'à 15 h 20 » / « muette jusqu'à ce que tu me réactives » / ""."""
        u = self.cfg.get("mute_until", 0)
        if not self.is_muted():
            return ""
        if u == -1:
            return "jusqu'à ce que tu me réactives"
        return "jusqu'à " + datetime.datetime.fromtimestamp(u).strftime("%H h %M")

    def toggle_mute(self):
        self.set_mute(0 if self.is_muted() else 60)

    def set_mute(self, minutes):
        """minutes : 0 = réactiver le son, -1 = muet jusqu'à réactivation, sinon durée."""
        self._stop_audio()
        self.cfg["mute_until"] = 0 if minutes == 0 else -1 if minutes < 0 else time.time() + minutes * 60
        self._was_muted = minutes != 0
        save_config(self.cfg)
        self._rebuild_menus()
        if minutes == 0:
            self.say("Je peux reparler ! Tu m'as manqué.")
        else:
            self.bubble_text = ("🔇 Chut… je me tais " + self.mute_label() + ".\n"
                                "Pour me réentendre : clic droit → 🔊 Réactiver sa voix, ou dis « tu peux reparler ».")
            self.bubble_until = time.monotonic() + 6
            self._update_mask()

    # ---------- fichiers et web
    def find_files(self, terms, exts, open_first=False, folder=False, days=0):
        if not self.cfg.get("file_search", True):
            self.say("La recherche de fichiers est désactivée (clic droit, Outils).")
            return
        what = " ".join(x for x in terms if not x.startswith("@") and "|" not in x) or \
            ("captures d'écran" if any("capture" in x for x in terms) else
             "téléchargements récents" if "@telechargements" in terms else "fichiers récents" if days else "fichiers")
        self.say(f"Je cherche « {what} » dans tes fichiers…")
        self.react = ("regarde", time.monotonic())

        def work():
            try:
                res = search_files(terms, exts, folder, days=days,
                                   extra_roots=self.cfg.get("recherche_dossiers", []),
                                   hidden=True if self.cfg.get("recherche_cachee") else None)
            except Exception:
                log_error("Recherche de fichiers")
                res = []
            self.bridge.files_found.emit(what, res, open_first)
        threading.Thread(target=work, daemon=True).start()

    def _on_files_found(self, what, paths, open_first):
        if open_first and paths:
            subprocess.Popen(["xdg-open", paths[0]], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                             start_new_session=True)
            self.happy_until = time.monotonic() + 1.2
            self.say(f"Je t'ouvre « {Path(paths[0]).name} » !")
            return
        if not self.results_win:
            self.results_win = ResultsWindow(self)
        self.results_win.show_files(what, paths)
        if paths:
            self.happy_until = time.monotonic() + 1.2
            self._spawn("etoile", 2)
            self.say(f"Trouvé ! {len(paths)} résultat{'s' if len(paths) > 1 else ''}. "
                     f"Le plus probable : « {Path(paths[0]).name} ».")
        else:
            self.sad_until = time.monotonic() + 2
            self.say("Je n'ai rien trouvé… Essaie avec un autre mot du nom du fichier ?")

    def web_lookup(self, query):
        if not self.cfg.get("web", True):
            self.say("Le mode web est désactivé (clic droit, Outils).")
            return
        self.say(f"Je cherche « {query} » sur internet…")
        self.react = ("regarde", time.monotonic())

        def work():
            try:
                res = web_search(query)
            except Exception as e:
                print("Recherche web :", e, file=sys.stderr)
                res = None
            summary = ""
            if res and self.ollama_ok:
                extraits = "\n".join(f"- {t} : {sn}" for t, _, sn in res[:5])
                prompt = (f"Question : {query}\nRésultats de recherche (titres et extraits) :\n{extraits}\n\n"
                          "Réponds à la question en 2 ou 3 phrases courtes, en français, avec tes propres mots "
                          "(ne recopie pas les extraits mot pour mot). Si les extraits ne suffisent pas, "
                          "dis-le simplement.")
                try:
                    summary = self.llm([{"role": "user", "content": prompt}])
                except Exception as e:
                    print("Résumé web :", e, file=sys.stderr)
            self.bridge.web_found.emit(query, res, summary)
        threading.Thread(target=work, daemon=True).start()

    def _on_web_found(self, query, results, summary):
        if not results:                             # pas de réseau, site bloqué ou rien de lisible : navigateur
            from urllib.parse import quote
            subprocess.Popen(["xdg-open", "https://duckduckgo.com/?q=" + quote(query)],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
            self.say("Je n'ai pas pu lire les résultats moi-même, je t'ouvre la recherche dans ton navigateur.")
            return
        if not self.results_win:
            self.results_win = ResultsWindow(self)
        self.results_win.show_web(query, results, summary)
        self._spawn("etoile", 2)
        if summary:
            self.say(summary)
        elif results:
            self.say(f"Voilà ce que j'ai trouvé ! Le premier résultat : « {results[0][0]} ».")
        else:
            self.say("Je n'ai rien trouvé sur internet pour ça…")

