    # ---------- le « cerveau » : Ollama en local, ou une IA en ligne choisie dans les réglages
    def ia_remote(self):
        return bool(ia_api) and ia_api.is_remote()

    def ia_name(self):
        if self.ia_remote():
            c = ia_api.conf_from()
            return f"{c['nom']} · {c['modele']}"
        return "Ollama · " + self.cfg.get("ollama_model", "")

    def _ia_err(self, e):
        if self.ia_remote():
            return ia_api.explain_error(e)
        return "Ollama ne répond pas"

    THINKERS = r"^(qwen3|qwq|deepseek-r1|gpt-oss|magistral|phi4-reasoning|cogito|smollm3)"

    def _ollama_open(self, body, timeout):
        """Appel à Ollama. Les modèles qui « réfléchissent avant de répondre » (Qwen3, DeepSeek-R1…) peuvent
        mettre des minutes en silence : on coupe cette réflexion (sinon Viki abandonne ou reçoit une réponse vide)."""
        body = dict(body)
        if re.match(self.THINKERS, body.get("model", ""), re.I) and "think" not in body:
            body["think"] = False
        def send(b):
            req = urllib.request.Request(OLLAMA_URL + "/api/chat", data=json.dumps(b).encode(),
                                         headers={"Content-Type": "application/json"})
            return urllib.request.urlopen(req, timeout=timeout)
        try:
            return send(body)
        except urllib.error.HTTPError as e:
            msg = self._ollama_error_text(e)
            if e.code in (400, 500) and body.pop("think", None) is not None and "memory" not in msg.lower():
                try:                                   # Ollama ancien / modèle sans l'option « think »
                    return send(body)
                except urllib.error.HTTPError as e2:
                    msg = self._ollama_error_text(e2)
            raise RuntimeError(self.ollama_explain(msg, body.get("model", ""))) from None

    @staticmethod
    def _ollama_error_text(e):
        try:
            raw = e.read().decode("utf-8", "ignore")
            return (json.loads(raw).get("error") or raw)[:400]
        except Exception:
            return f"HTTP {getattr(e, 'code', '?')}"

    @staticmethod
    def ollama_explain(msg, model=""):
        """Message d'erreur d'Ollama -> explication simple (en gardant le message d'origine à la fin)."""
        low = (msg or "").lower()
        m = f"« {model} »" if model else "le modèle"
        if re.search(r"unknown (model )?architecture|unsupported model|newer version|upgrade|requires.*ollama", low):
            why = (f"ton Ollama est trop ancien pour {m} : mets-le à jour (sous Arch : sudo pacman -Syu ollama "
                   "— ou ollama-rocm pour ta carte AMD), puis relance-le")
        elif re.search(r"memory|out of memory|oom|cudamalloc|hipmalloc|vram|unable to allocate", low):
            why = (f"pas assez de mémoire pour charger {m}. Essaie un modèle plus petit (translategemma:4b), "
                   "ferme les programmes gourmands, ou coupe la voix naturelle le temps de traduire")
        elif re.search(r"runner process (has )?terminated|exit status|llama runner|signal: killed|segmentation", low):
            why = (f"{m} a planté au chargement (souvent la mémoire de la carte graphique est pleine). "
                   "Essaie un modèle plus petit, ou redémarre Ollama")
        elif re.search(r"not found|no such|pull", low):
            why = f"{m} n'est pas installé dans Ollama : retélécharge-le"
        elif re.search(r"unsupported|does not support|template|format", low):
            why = f"{m} n'accepte pas cette façon de lui parler : choisis un autre modèle"
        else:
            why = f"Ollama a eu un problème avec {m}"
        return f"{why}. (Ollama : {msg[:200]})"

    # ---------- « elle réfléchit » (+ ce que ça demande au PC)
    class _Thinking:
        def __init__(self, comp, titre=None, jauges=True):
            self.c, self.done = comp, False
            c = comp
            with c._think_lock:
                if c._think["n"] == 0:
                    c._think.update(t0=time.monotonic(), show=True, titre=None)
                if titre:
                    c._think["titre"] = titre
                c._think["n"] += 1          # aussi quand elle réfléchit d'elle-même (souvenirs, idées…)
            if jauges and c._think["show"] and c.cfg.get("bulle_reflexion", True):
                c._start_res_watch()

        def end(self):
            if self.done:
                return
            self.done = True
            with self.c._think_lock:
                self.c._think["n"] = max(0, self.c._think["n"] - 1)

        def __enter__(self):
            return self

        def __exit__(self, *a):
            self.end()

    def thinking(self, titre=None, jauges=True):
        return self._Thinking(self, titre, jauges)

    def think_preview(self, secs=5):
        """Montre la bulle « je réfléchis » quelques secondes (bouton « Voir la bulle » des réglages)."""
        t = self.thinking()
        if self.bubble_text not in ("", "…"):
            self.bubble_text = ""
        self._preview_think = t
        QTimer.singleShot(int(secs * 1000), lambda: t.end())

    def _start_res_watch(self):
        """Mesure processeur / mémoire / carte graphique, seulement pendant la réflexion (rien le reste du temps)."""
        if getattr(self, "_res_thread", None) and self._res_thread.is_alive():
            return

        def run():
            while self._res_wanted():
                try:
                    r = {}
                    if gestionpc and not IS_WIN:
                        r["cpu"] = gestionpc.cpu_percent(0.6)[0]
                        m = gestionpc.mem()
                        r["ram"], r["ram_tot"] = m["utilise"], m["total"]
                        g = gestionpc.gpu()
                        if g and g.get("vram_total"):
                            r["vram"], r["vram_tot"] = g["vram"], g["vram_total"]
                        if g and g.get("pct") is not None:
                            r["gpu"] = g["pct"]
                    self._res = r
                except Exception:
                    self._res = None
                time.sleep(0.4)
            self._res = None
        self._res_thread = threading.Thread(target=run, daemon=True)
        self._res_thread.start()

    def _res_wanted(self):
        mode = self.cfg.get("ressources_ronds", "toujours")
        if mode == "jamais" or IS_WIN:
            return False
        b = self.__dict__.get("input_box")
        if b is not None and getattr(b, "colonne", False) and b.isVisible():
            return True
        if self._ronds_res():
            return True
        if mode == "toujours" and self.isVisible():
            return True
        return self._think["n"] > 0

    @staticmethod
    def res_items(res):
        """[(valeur 0-1, nom, détail)] pour processeur, mémoire, carte graphique."""
        res = res or {}
        out = []
        if res.get("cpu") is not None:
            out.append((res["cpu"] / 100, "Proc.", f"Processeur : {res['cpu']:.0f} %"))
        if res.get("ram_tot"):
            out.append((res["ram"] / res["ram_tot"], "Mém.",
                        f"Mémoire : {res['ram'] / 2 ** 30:.1f}/{res['ram_tot'] / 2 ** 30:.0f} Go".replace(".", ",")))
        g = res.get("gpu")
        if g is not None or res.get("vram_tot"):
            v = g / 100 if g is not None else res["vram"] / res["vram_tot"]
            d = f"Carte graphique : {g:.0f} %" if g is not None else "Carte graphique"
            if res.get("vram_tot"):
                d += f" · {res['vram'] / 2 ** 30:.1f}/{res['vram_tot'] / 2 ** 30:.0f} Go".replace(".", ",")
            out.append((v, "Carte", d))
        return [(max(0.0, min(1.0, v)), n, d) for v, n, d in out]

    @staticmethod
    def paint_ring(p, c, R, v, txt="", th=3.5, disc=True, txt_col=None, track=None):
        col = QColor("#4caf50") if v < 0.5 else QColor("#f0a030") if v < 0.8 else QColor("#e5534b")
        if disc:
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(255, 255, 255, 238))
            p.drawEllipse(c, R + 3, R + 3)
        rect = QRectF(c.x() - R, c.y() - R, 2 * R, 2 * R)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(QColor(*track) if track else QColor(0, 0, 0, 45), th))
        p.drawEllipse(rect)
        pen = QPen(col, th)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(pen)
        p.drawArc(rect, 90 * 16, -int(360 * 16 * max(0.02, v)))
        if txt:
            f = QFont()
            f.setPixelSize(max(8, int(R * 0.6)))
            f.setBold(True)
            p.setFont(f)
            p.setPen(QColor(*txt_col) if txt_col else QColor(46, 22, 36))
            p.drawText(rect, Qt.AlignmentFlag.AlignCenter, txt)

    @staticmethod
    def paint_label(p, x, y, txt, px=10, align_right=False, centre=False):
        """Petit texte blanc entouré de foncé : lisible sur tous les fonds."""
        if i18n:
            txt = i18n.tr(txt)
        f = QFont()
        f.setPixelSize(px)
        f.setBold(True)
        fm = QFontMetrics(f)
        tw = fm.horizontalAdvance(txt)
        path = QPainterPath()
        path.addText(x - tw if align_right else x - tw / 2 if centre else x, y + fm.ascent() / 2 - 1, f, txt)
        p.setPen(QPen(QColor(40, 25, 35, 210), 3))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255))
        p.drawPath(path)

    def _rings_mode(self):
        """Ce qu'on montre à ses pieds : None, « mini » ou « deplie »."""
        mode = self.cfg.get("ressources_ronds", "toujours")
        if mode == "jamais" or not self._res or not self.res_items(self._res):
            return None
        b = self.__dict__.get("input_box")
        if b is not None and getattr(b, "colonne", False) and b.isVisible():
            return None                                   # barre ouverte : les ronds sont sous le panneau
        if self._ronds_res() or self.cfg.get("barre_place", "ronds") == "ronds":
            return None                                   # dans le rond 📊, jamais sur elle ni à ses pieds
        now = time.monotonic()
        if self._think["n"] > 0 or now < self.__dict__.get("_rings_open_until", 0):
            return "deplie"
        return "mini" if mode == "toujours" else None

    def _rings_center(self):
        """Les jauges ne doivent jamais couvrir le personnage : en ligne à côté de ses pieds (du côté opposé à
        ses ronds), sinon en colonne sur le côté, sinon en dessous."""
        self._rings_col = False
        try:
            br = self.char_region.boundingRect()
        except Exception:
            return QPointF(self.char_cx, self.H - 22.0)
        deplie = self._rings_mode() == "deplie"
        n = max(1, len(self.res_items(self._res))) if deplie else 1
        w = 44 * n if deplie else 30
        y = min(self.H - 22.0, br.bottom() - 22.0)
        rb = self.__dict__.get("ronds_bar")
        ronds_a_droite = rb is not None and rb.isVisible() and getattr(rb, "droite", True)
        cotes = ("g", "d") if ronds_a_droite else ("d", "g")
        for cote in cotes:                                   # en ligne, à côté
            if cote == "d" and br.right() + 12 + w <= self.W - 2:
                return QPointF(br.right() + 12 + w / 2, y)
            if cote == "g" and br.left() - 12 - w >= 2:
                return QPointF(br.left() - 12 - w / 2, y)
        if deplie:                                           # en colonne, à côté (prend moins de largeur)
            for cote in cotes:
                if cote == "d" and br.right() + 8 + 44 <= self.W - 2:
                    self._rings_col = True
                    return QPointF(br.right() + 8 + 22, y)
                if cote == "g" and br.left() - 8 - 44 >= 2:
                    self._rings_col = True
                    return QPointF(br.left() - 8 - 22, y)
        if br.bottom() + 46 <= self.H:
            return QPointF(self.char_cx, br.bottom() + 30.0)
        return QPointF(self.char_cx, min(self.H - 22.0, br.bottom() - 14.0))

    def _rings_rect(self):
        if self.__dict__.get("jauges_win") is not None:
            return None
        m = self._rings_mode()
        if m is None:
            return None
        c = self._rings_center()
        if m == "mini":
            return QRectF(c.x() - 15, c.y() - 15, 30, 30)
        n = len(self.res_items(self._res))
        if getattr(self, "_rings_col", False):
            return QRectF(c.x() - 22, c.y() - 58 * (n - 1) - 38, 44, 58 * n)
        w = 44 * n
        return QRectF(c.x() - w / 2, c.y() - 38, w, 58)

    def _draw_rings(self, p):
        if self.__dict__.get("jauges_win") is not None:
            return                                         # elles sont dans leur propre fenêtre, à côté d'elle
        m = self._rings_mode()
        if m is None:
            return
        items = self.res_items(self._res)
        c = self._rings_center()
        if m == "mini":
            v, nom, _d = max(items, key=lambda t: t[0])         # ce qui travaille le plus
            self.paint_ring(p, QPointF(c.x(), c.y()), 10, v, "", th=3)
            return
        n = len(items)
        col = getattr(self, "_rings_col", False)
        for i, (v, nom, _d) in enumerate(items):
            cc = QPointF(c.x(), c.y() - 58 * (n - 1 - i)) if col else QPointF(c.x() - 22 * (n - 1) + 44 * i, c.y())
            self.paint_ring(p, cc, 15, v, f"{v * 100:.0f}%", th=3.5)
            self.paint_label(p, cc.x() - 14, cc.y() - 27, nom, 10)

    def _rings_watch(self, now):
        """Survol du petit rond : il se déplie. Quelque chose à fond longtemps : une phrase, une fois."""
        r = self._rings_rect()
        if r is not None:
            cur = curseur.pos() if curseur else QCursor.pos()
            loc = QPointF(cur.x() - self.x(), cur.y() - self.y())
            if r.adjusted(-6, -6, 6, 6).contains(loc):
                self._rings_open_until = now + 4
        if self._think["n"] > 0 or not self._res:
            self.__dict__["_hot_since"] = {}
            return
        hot = self.__dict__.setdefault("_hot_since", {})
        last = self.__dict__.setdefault("_hot_said", {})
        for v, nom, _d in self.res_items(self._res):
            if v < 0.95:
                hot.pop(nom, None)
                continue
            t0 = hot.setdefault(nom, now)
            if now - t0 > 8 and now - last.get(nom, -1e9) > 900 and not self.bubble_text:
                last[nom] = now
                self._rings_open_until = now + 8
                self.say({"Carte": "Ta carte graphique est à fond. Si ça rame, ferme un jeu ou choisis une IA plus "
                                   "petite.",
                          "Mém.": "La mémoire de ton PC est presque pleine : ferme des programmes ou des onglets "
                                  "que tu n'utilises pas.",
                          "Proc.": "Ton processeur est à fond depuis un moment : un programme travaille beaucoup."}
                         .get(nom, "Ton PC est à fond !"))

    def _think_visible(self, now):
        t = self._think
        return (t["n"] > 0 and t["show"] and now - t["t0"] > 0.3 and self.bubble_text in ("", "…")
                and self.cfg.get("bulle_reflexion", True))

    def _think_rect(self, nrows=None):
        if nrows is None:
            nrows = 0
        w, h = 248, 30 + 24 * nrows
        if self._think.get("titre"):                 # titre long (« Je cherche des restaurants… ») : plus large
            f = QFont()
            f.setPixelSize(12)
            f.setBold(True)
            w = max(w, min(self.W - 8, QFontMetrics(f).horizontalAdvance(self._think["titre"] + "...  (10 s)") + 28))
        head_y = BUBBLE_AREA + int(self.ch * 0.02)
        x = min(max(4.0, self.char_cx - w / 2), self.W - w - 4)
        return QRectF(x, max(2.0, head_y - h - 22), w, h)

    def _draw_thinking(self, p, now):
        """Petite bulle : « Je réfléchis… (6 s) » + 3 jauges avec des mots simples."""
        secs = int(now - self._think["t0"])
        res = {}                       # les ressources sont maintenant dans les petits ronds
        rows = []
        T = i18n.tr if i18n else (lambda x: x)

        def word(v, mots):
            return T(mots[0] if v < 0.5 else mots[1] if v < 0.8 else mots[2])
        if res.get("cpu") is not None:
            v = res["cpu"] / 100
            rows.append(("⚙️ " + T("Processeur"), v, f"{res['cpu']:.0f} % · {word(v, ('tranquille', 'occupé', 'à fond'))}"))
        if res.get("ram_tot"):
            v = res["ram"] / res["ram_tot"]
            rows.append(("🧮 " + T("Mémoire"), v, (f"{res['ram'] / 2 ** 30:.1f}".replace(".", ",") +
                                         f"/{res['ram_tot'] / 2 ** 30:.0f} Go · "
                                         f"{word(v, ('ça va', 'remplie', 'pleine'))}")))
        if res.get("vram_tot"):
            v = res["vram"] / res["vram_tot"]
            rows.append(("🎮 " + T("Carte graph."), v, (f"{res['vram'] / 2 ** 30:.1f}".replace(".", ",") +
                                              f"/{res['vram_tot'] / 2 ** 30:.0f} Go · "
                                              f"{word(v, ('ça va', 'remplie', 'pleine'))}")))
        r = self._think_rect(len(rows))
        w = r.width()
        bg, border, fg, thick = BUBBLE_THEMES.get(self.cfg.get("bubble_theme", "classique"),
                                                   BUBBLE_THEMES["classique"])
        path = QPainterPath()
        path.addRoundedRect(r, 12, 12)
        p.setPen(QPen(QColor(*border), thick))
        p.setBrush(QColor(*bg))
        p.drawPath(path)
        for i, rr in enumerate((5, 3.5)):                          # petites bulles de pensée
            p.drawEllipse(QPointF(r.center().x() + 6 - i * 9, r.bottom() + 8 + i * 9), rr, rr)
        f = QFont()
        f.setPixelSize(12)
        f.setBold(True)
        p.setFont(f)
        p.setPen(QColor(*fg))
        dots = "." * (1 + int(now * 2.5) % 3)
        titre = T(self._think.get("titre") or "🧠 Je réfléchis")
        txt = f"{titre}{dots}  ({secs} s)" if secs else f"{titre}{dots}"
        txt = QFontMetrics(f).elidedText(txt, Qt.TextElideMode.ElideMiddle, int(w - 20))
        p.drawText(QRectF(r.left() + 10, r.top() + 6, w - 20, 16), Qt.AlignmentFlag.AlignCenter, txt)
        f.setPixelSize(10)
        y = r.top() + 26
        for lab, v, txt in rows:
            f.setBold(True)
            p.setFont(f)
            p.setPen(QColor(*fg))
            p.drawText(QRectF(r.left() + 10, y, w - 20, 13), Qt.AlignmentFlag.AlignLeft, lab)
            f.setBold(False)
            p.setFont(f)
            p.drawText(QRectF(r.left() + 10, y, w - 20, 13), Qt.AlignmentFlag.AlignRight, txt)
            col = QColor("#4caf50") if v < 0.5 else QColor("#f0a030") if v < 0.8 else QColor("#e5534b")
            bar = QRectF(r.left() + 10, y + 14, w - 20, 5)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(0, 0, 0, 40))
            p.drawRoundedRect(bar, 2.5, 2.5)
            p.setBrush(col)
            p.drawRoundedRect(QRectF(bar.left(), bar.top(), bar.width() * max(0.02, min(1.0, v)), 5), 2.5, 2.5)
            y += 24

    def llm(self, messages, timeout=120, json_mode=False, model=None):
        """Réponse complète (texte), à appeler dans un fil. model : un modèle Ollama précis (sinon le cerveau)."""
        with self.thinking():
            return self._llm(messages, timeout, json_mode, model)

    def _llm(self, messages, timeout=120, json_mode=False, model=None):
        if self.ia_remote() and not model:
            txt = ia_api.request(ia_api.conf_from(), messages, timeout=timeout)
        else:
            body = {"model": model or self.cfg["ollama_model"], "stream": False, "messages": messages,
                    "keep_alive": self._keep_alive() if not model else "10m"}
            if json_mode:
                body["format"] = "json"
            with self._ollama_open(body, timeout) as r:
                txt = json.load(r)["message"]["content"]
        return re.sub(r"<think>.*?</think>", "", txt or "", flags=re.S).strip()

    def llm_json(self, messages, timeout=120):
        txt = self.llm(messages, timeout=timeout, json_mode=True)
        if ia_api:
            return ia_api.extract_json(txt)
        return json.loads(txt)

    def _llm_pieces(self, payload):
        """Morceaux de réponse au fil de l'eau : (texte, fini)."""
        if self.ia_remote():
            yield from ia_api.stream(ia_api.conf_from(), payload["messages"])
            return
        with self._ollama_open(payload, 180) as r:
            for line in r:
                if not line.strip():
                    continue
                obj = json.loads(line)
                yield (obj.get("message") or {}).get("content", ""), bool(obj.get("done"))

    def set_ia_provider(self, pid):
        s = ia_api.load_settings()
        s["fournisseur"] = pid
        ia_api.save_settings(s)
        self.chat_history = self.chat_history[-12:]
        self.recheck_ollama()

    def ask_ai(self, prompt, cb, system="", timeout=180, model=None):
        """Demande à l'IA dans un fil ; cb(texte) est rappelé dans l'interface ("" = échec)."""
        def work():
            msgs = ([{"role": "system", "content": system}] if system else []) + [{"role": "user", "content": prompt}]
            txt = ""
            try:
                txt = self.llm(msgs, timeout=timeout, model=model)
            except Exception as e:
                print("IA :", self._ia_err(e), file=sys.stderr)
            self.bridge.ai_done.emit(cb, txt)
        threading.Thread(target=work, daemon=True).start()

    def _show_text(self, title, text, info=""):
        if not self.text_win:
            self.text_win = extras.TextWindow()
        self.text_win.show_text(title, text, info)

    def _extra_command(self, text, ta):
        now = time.monotonic()
        if mods and mods.commande(text, ta):             # une commande ajoutée par un mod
            return True
        if forme and self._forme_command(text, ta):
            return True
        if re.search(r"\b(?:tradui[st]|traduire|lis)\b.{0,25}\b(?:zone|partie|morceau|bout)\b.{0,15}\becran\b", ta):
            self.translate_zone()
            return True
        if re.search(r"\b(?:signale[rz]?|rapporte[rz]?)\b.{0,12}\bbug\b|\bbug report\b", ta):
            self.signaler_bug()
            return True
        m_sv = re.search(r"\b(?:ouvre|lance|mets?|va sur|allume)(?:[- ]moi)?\s+(netflix|disney\+?|disney plus|prime video|"
                         r"amazon prime|crunchyroll|adn|twitch|canal\+?|canal plus|apple tv|paramount|arte|france\.?tv|"
                         r"spotify|deezer|youtube music|apple music|soundcloud|qobuz|tidal|max)\b", ta)
        if m_sv:
            cle = m_sv.group(1).replace(" plus", "+").replace("amazon prime", "prime video").replace("francetv",
                                                                                                     "france.tv")
            for _t, liste_ in self.SERVICES:
                for nom, url, app in liste_:
                    if _sa_simple(nom) == _sa_simple(cle) or _sa_simple(nom).startswith(_sa_simple(cle)):
                        self.ouvrir_service(nom, url, app)
                        return True
        if re.search(r"\b(?:cree|creer|fais|fabrique|invente|dessine)\w*\b.*\bpersonnages?\b.*\b(?:kawaii|mignon|chibi)", ta):
            self.creer_kawaii()
            return True
        if fond_couleurs and re.search(r"\b(?:couleurs?|teinte)\b.*\b(?:fond d'?ecran|wallpaper|bureau)\b", ta) and \
                re.search(r"\b(?:prends?|mets?|accorde|suis|utilise|adapte|comme)\b", ta):
            self.couleurs_fond(True)
            return True
        if aujourdhui and re.search(r"\b(?:mes|les|tes) notif(?:ication)?s?\b|\bqu'?est[- ]ce que j'?ai rate\b|"
                                    r"\bce que tu m'?as dit\b", ta):
            self.open_notifs()
            return True
        if aujourdhui and re.search(r"^(?:et )?(?:(?:mon |le )?(?:resume|programme|point) (?:du jour|d'?aujourd'?hui)|"
                                    r"aujourd'?hui ?\??|quoi de prevu aujourd'?hui)\b", ta):
            self.open_aujourdhui()
            return True
        if getattr(self, "_dernier_prompt", "") and re.search(r"^(?:cree|recree|fais|dessine)[- ]la\b", ta):
            self.open_studio(self._dernier_prompt)
            return True
        if modeles_fenetre and re.search(r"\b(?:mes |les |tes )?(?:modeles|mods)\b", ta) and \
                re.search(r"\b(?:ouvre|montre|affiche|voir|gere|liste)\w*\b", ta):
            self.open_modeles("mods" if re.search(r"\bmods?\b", ta) else "modeles")
            return True
        if vieprivee and self._privacy_command(text, ta):
            return True
        if re.search(r"\b(?:sors|sortir|quitte|desactive|enleve|arrete|coupe|stop)\w* (?:du |le |de )?mode fantome\b|"
                     r"\b(?:redeviens|reviens|sois) (?:normale?|opaque|visible)\b|\bt'?es (?:toute? )?transparente?\b|"
                     r"\b(?:tu es|elle est) (?:toute? )?transparente?\b|\bplus transparente?\b", ta):
            if self.cfg.get("ghost"):
                self.set_ghost(False)
            else:
                self.say("Je ne suis pas en mode fantôme. Si je te parais transparente, c'est peut-être la "
                         "transparence de ton bureau (effets de KDE) ou une image de personnage avec un fond transparent.")
            return True
        if re.search(r"\b(?:active|mets|passe)\w* (?:le |en )?mode fantome\b", ta):
            self.set_ghost(True)
            return True
        if ajout_ia and re.search(r"\b(?:ajoute|ajouter|importe|importer|glisse|installe|installer)\w* (?:une |un |la |le |"
                                  r"cette |ce |mon |ma |nouvelle |nouveau |autre )*(?:ia|intelligence artificielle|"
                                  r"modele (?:d'ia|telecharge|gguf|safetensors))\b", ta):
            self.open_add_ai()
            self.say("Glisse le fichier de l'IA dans la fenêtre : je regarde à quoi elle sert et je l'installe.")
            return True
        if apparence and self._look_command(text, ta):
            return True
        if marionnette and self._move_command(ta):
            return True
        if (pratique or fun) and self._fun_command(text, ta):
            return True
        if self._devpc_command(text, ta):            # développeur / gestion du PC (avant les autres commandes)
            return True
        if streamer and re.search(r"\b(?:arrete|stop|quitte|coupe)\w*\b.*\b(?:mode streamer|le chat|stream)\b", ta):
            if getattr(self, "stream", None):
                self.stop_streamer()
                return True
        elif streamer and re.search(r"\b(?:mode streamer|lis (?:le|mon) chat|lance le stream)\b", ta):
            m = re.search(r"(?:chaine|chaîne|chat de|twitch\.tv/)\s*@?([A-Za-z0-9_]{3,25})", text, re.I)
            self.start_streamer(m.group(1) if m else None)
            return True
        if plus and self._plus_command(text, ta):
            return True
        if media and self._media_command(text, ta):
            return True
        if (vie or devplus) and self._vie_dev_command(text, ta):
            return True
        if quotidien and self._quotidien_command(text, ta):
            return True
        if quotidien and re.search(r"\b(?:defi fait|j'?ai (?:fait|reussi) (?:mon|le) defi)\b", ta):
            self.defi_done()
            return True
        if quotidien and re.search(r"\b(?:mon defi|le defi de la semaine|c'?est quoi (?:mon|le) defi)\b", ta):
            self.defi_status()
            return True
        if quotidien and re.search(r"\bquiz de la semaine\b|\bquiz sur ce qu'?on a appris\b", ta):
            self.week_quiz()
            return True
        if quotidien and re.search(r"\b(?:ajoute|mets?)\b.*\b(?:ingredients|ca|la recette)\b.*\bcourses\b", ta):
            self.meal_to_shopping()
            return True
        if suivi and re.search(r"\bouvre (?:l'?|le dernier )?article\b", ta):
            self.open_last_article()
            return True
        if suivi and re.search(r"\b(?:les actus|actualites|quoi de neuf|mes suivis|sorties? cine|au cinema)\b", ta):
            self.open_follow()
            return True
        if securite and re.search(r"\b(?:securite|securise|pirate|piratage|virus|hacke)\b", ta) and \
                re.search(r"\b(?:verifie|analyse|regarde|controle|scanne|est-ce|est ce|suis|ai ete|j'ai|mon pc|"
                          r"bilan|probleme)\b", ta):
            if re.search(r"\b(?:j'?ai ete|je suis|on m'a|je crois que|aide)\b.*\b(?:pirate|hacke|virus)", ta):
                self._show_text("🛡️ En cas de problème", securite.GUIDE, "Les étapes, dans l'ordre. Garde ton calme.")
                return self.say("Pas de panique ! D'abord : coupe internet, puis change ton mot de passe mail depuis "
                                "ton téléphone. Je t'ai mis toutes les étapes dans la fenêtre.") or True
            self.security_check()
            return True
        if securite and re.search(r"\bprotege\w* (?:mes|les) cles\b", ta):
            self.protect_secrets()
            return True
        if re.search(r"\b(?:notre semaine|resume de (?:la|notre|ma) semaine|bilan de notre semaine)\b", ta):
            self.week_digest()
            return True
        if re.search(r"\bexporte\w*\b.*\b(?:personnage|perso|toi)\b", ta):
            self.export_pack()
            return True
        L = getattr(self, "learn", None)
        if L:
            if re.search(r"\b(qu'?est[- ]ce que tu (as )?appris|ce que tu (as )?appris sur moi|tu me connais|"
                         r"tes habitudes|mes habitudes)\b", ta):
                lines = L.summary()
                self.say(" ".join(lines[:3]))
                self._show_text("Ce qu'elle a appris sur toi", "\n".join(lines),
                                "Tout est sur ton PC. Réglages → Discussion pour retirer une règle ou tout oublier.")
                return True
            if re.search(r"\boublie (tout )?ce que tu as appris|oublie mes habitudes\b", ta):
                L.reset()
                self.say("D'accord, j'oublie mes habitudes avec toi. On repart de zéro !")
                return True
            rule = L.parse_rule(ta, text)
            if rule:
                L.add_rule(*rule)
                self.emotion = "timide" if rule[0] == "evite" else "joie"
                self.say(random.choice(["C'est noté, je m'en souviendrai.", "D'accord, je retiens !",
                                        "Promis, je fais attention."]) if rule[0] == "evite" else
                         random.choice(["Hihi, alors je continuerai !", "C'est noté, ça me fait plaisir !"]))
                return True
            if L.note_length_feedback(ta):
                if L.s["longueur"] == "court" or re.search(r"\b(trop long|plus court|moins long)\b", ta):
                    self.say("D'accord, je ferai plus court.")
                    return True
                return False             # « développe » : elle retient, et répond en développant
        # jeux
        g = extras.parse_game(text)
        if g:
            self.start_game(g)
            return True
        # notes et courses
        n = extras.parse_notes(text)
        if n:
            self._notes_cmd(*n)
            return True
        # minuteurs et pomodoro
        pm = extras.parse_pomodoro(text)
        if pm:
            if pm[0] == "stop":
                self.stop_pomodoro()
            else:
                self.start_pomodoro(pm[1], "travail")
            return True
        tm = extras.parse_timer(text)
        if tm:
            self.add_timer(*tm)
            return True
        if re.search(r"\b(combien de temps (il )?reste|mes minuteurs|le minuteur)\b", ta) and (self.timers or self.pomodoro):
            parts = [f"{lab or 'minuteur'} : {extras.fmt_duree(end - now)}" for end, lab in self.timers if end > now]
            if self.pomodoro:
                parts.append(f"{self.pomodoro[0]} : {extras.fmt_duree(self.pomodoro[1] - now)}")
            self.say("Il reste " + " ; ".join(parts) + ".")
            return True
        if re.search(r"\b(arrete|annule|stop)\b.*\bminuteurs?\b", ta):
            self.timers = []
            self.say("J'ai arrêté les minuteurs.")
            return True
        # presse-papiers
        c = extras.parse_clip_cmd(text)
        if c:
            act, lang = c
            if act == "menu":
                txt = QApplication.clipboard().text()
                if txt.strip():
                    if not self.clip_popup:
                        self.clip_popup = extras.ClipPopup(self)
                    self.clip_popup.popup(txt)
                    self.say("Qu'est-ce que je fais avec ton texte ?")
                else:
                    self.say("Ton presse-papiers est vide.")
            else:
                self.clip_action(act, lang)
            return True
        # agenda
        if re.search(r"\b(mon agenda|mon calendrier|mes rendez[- ]vous|qu'?est[- ]ce que j'ai (de prevu )?"
                     r"(aujourd'hui|demain|cette semaine)|j'ai quoi (aujourd'hui|demain))\b", ta):
            self.agenda_say("demain" if "demain" in ta else "semaine" if "semaine" in ta else "aujourd'hui")
            return True
        # état du PC, mises à jour, rangement
        if re.search(r"\b(comment va (le|mon|ton) (pc|ordi|ordinateur)|etat du (pc|systeme)|temperature|"
                     r"espace disque|place sur (le|mon) disque)\b", ta):
            self.say(extras.pc_status_text(extras.pc_status()))
            return True
        if re.search(r"\b(mises? a jour|updates?)\b", ta) and re.search(r"(y a|ya|il y a|verifie|regarde|des|dispo)", ta):
            self.say("Je regarde s'il y a des mises à jour (ça utilise internet)…")
            threading.Thread(target=lambda: self.bridge.updates_done.emit(extras.check_updates()), daemon=True).start()
            return True
        if re.search(r"\b(range|ranger|trie|trier|nettoie)\b.*\b(telechargements|downloads)\b", ta):
            self.tidy_downloads()
            return True
        if mails and re.search(r"\b(mes (mails?|e-?mails?|courriels?)|j'?ai (des|un|de nouveaux?|du) "
                               r"(mails?|e-?mails?|courriels?|courrier)|nouveaux? (mails?|courriels?)|"
                               r"boite (mail|aux lettres))\b", ta):
            if re.search(r"resume", ta):
                self.mail_check(read=False, open_win=False)
                s = mails.load()
                self._bg(lambda: mails.unread(s, limit=8, body=True),
                         lambda res: self.mail_summary(res) if res and not isinstance(res, Exception)
                         else self.say("Aucun mail non lu à résumer."))
            else:
                self.mail_check()
            return True
        if re.search(r"\b(fais le point|le point) (sur )?(mes projets|git|le code|mon code)|etat de mes projets|"
                     r"mes depots git\b", ta):
            self.git_report()
            return True
        if re.search(r"^(on joue|joue avec moi|jouons|on fait un jeu|jouer)\b", ta):
            self.play_menu()
            return True
        if outils and (re.search(r"\b(nettoie|nettoyer|nettoyage|menage|vide|vider)\b.*\b(pc|ordi|ordinateur|"
                                 r"systeme|disque|cache|corbeille)\b", ta)
                       or re.search(r"\b(libere|liberer|fais|faire) (de la |un peu de )?place\b", ta)):
            self.open_cleaner()
            return True
        if outils and re.search(r"\b(range|ranger|reorganise|reorganiser|trie|trier|classe|classer)\b.*"
                                r"\b(dossiers?|bureau|fichiers|documents|images|photos)\b", ta):
            kind = ("DESKTOP" if "bureau" in ta else "DOCUMENTS" if "documents" in ta else
                    "PICTURES" if re.search(r"images|photos", ta) else None)
            self.open_tidy(outils.user_dir(kind) if kind else None)
            return True
        if outils and re.search(r"(je m'?ennuie|on fait quoi|quoi faire|propose[- ]moi (un truc|une activite|"
                                r"des activites|quelque chose)|idees? d'activites?)", ta):
            self.show_activities()
            return True
        if re.search(r"\bannule (le )?(dernier )?rangement\b", ta):
            self.undo_tidy()
            return True
        # journal
        if re.search(r"^(mon journal|montre[- ]moi mon journal|lis[- ]moi mon journal)$", ta):
            self.show_journal()
            return True
        if re.search(r"^(ecris dans mon journal|journal :|cher journal)", ta):
            rest = re.sub(r"^(?:[ée]cris dans mon journal|journal :|cher journal)\s*:?\s*", "", text.strip(), flags=re.I)
            if rest:
                self.journal_write(rest)
            else:
                self.journal_until = now + 600
                self.say("Je t'écoute, raconte-moi ta journée !")
            return True
        # contrôle du PC
        pcc = extras.parse_pc_control(text)
        if pcc:
            self.pc_control(*pcc)
            return True
        # lecture à voix haute
        if re.search(r"\b(lis|lire|relis)[- ]?(moi)?\b.*\b(presse[- ]papiers?|ce que j'ai copie|le texte copie|a voix haute)", ta):
            txt = QApplication.clipboard().text().strip()
            if txt:
                self.read_aloud(txt[:6000])
            else:
                self.say("Ton presse-papiers est vide.")
            return True
        if lecture and re.search(r"\b(mode lecture|lis[- ]moi un livre|lire un livre|ouvre (un|mon) livre|"
                                 r"mes livres)\b", ta):
            self.open_reader()
            return True
        if lecture and re.search(r"\b(reprends?|continue)\b.*\b(lecture|livre|histoire du livre)\b", ta):
            self.resume_reading()
            return True
        if self.reading and re.match(r"^(arrete de lire|stop la lecture)", ta):
            self.stop_reading()
            return True
        # histoire du soir
        m = re.search(r"\braconte[- ]?(moi)?\s+(une|un petite?|une petite)?\s*histoire(?:\s+(?:sur|de|avec|d')\s*(.+))?", ta)
        if m:
            sujet = re.search(r"histoire\s+(?:sur|de|avec|d')\s*(.+)$", text, re.I)
            self.tell_story(sujet.group(1).strip(" ?!.") if sujet else "")
            return True
        # dictée
        if re.match(r"^(dictee|mode dictee|prends une dictee)$", ta):
            self.start_dictation()
            return True
        m = re.match(r"^(?:tape|ecris|écris)\s*(?::|que)\s*(.+)$", text.strip(), re.I)
        if m and not re.search(r"dans mon journal", ta):
            self.type_text(m.group(1).strip())
            return True
        # concentration
        if mise_a_jour and re.search(r"\b(mises? a jour de (toi|viki)|(es[- ]tu|t'es|tu es) a jour|nouvelle version de toi|"
                                     r"verifie (tes|les) mises? a jour|mets[- ]toi a jour)\b", ta):
            self.check_update()
            return True
        if re.search(r"\b(installe ton cerveau|installe une ia (locale|sur mon pc)|ia locale)\b", ta):
            self.open_models()
            return True
        if re.search(r"\b(mode concentration|je dois me concentrer|mode focus|laisse[- ]moi travailler|"
                     r"je (bosse|travaille|revise|code|etudie)\b.*\d+\s*(h|heures?|min|minutes?))\b", ta):
            d = re.search(r"(\d+)\s*(h|heures?|min|minutes?)", ta)
            mins = (int(d.group(1)) * (60 if d.group(2).startswith("h") else 1)) if d else 60
            self.set_focus(mins)
            return True
        if re.search(r"\b(fin de la concentration|arrete la concentration|stop concentration)\b", ta):
            self.set_focus(0)
            return True
        # langues
        if voix:
            noms = {"anglais": "en", "english": "en", "espagnol": "es", "allemand": "de", "italien": "it",
                    "portugais": "pt", "neerlandais": "nl", "polonais": "pl", "russe": "ru", "ukrainien": "uk",
                    "turc": "tr", "suedois": "sv", "arabe": "ar", "chinois": "zh", "francais": "fr"}
            m = re.search(r"\b(?:parlons|on parle|parle[- ]moi en|parle en|reponds[- ]moi en|reponds en|mode|"
                          r"repasse en|pratiquons|pratiquer l'?|let'?s speak)\s+(?:l'|le |en )?(" +
                          "|".join(noms) + r")\b", ta)
            if m:
                code = noms[m.group(1)]
                prat = bool(re.search(r"pratiqu|practice", ta)) or (code == "en" and "parlons" in ta)
                self.set_language(code, "pratique" if prat else "naturel")
                return True
        elif re.search(r"\b(parlons anglais|mode anglais|let'?s speak english|practice english|on parle anglais)\b", ta):
            self.cfg["langue"] = "en"
            save_config(self.cfg)
            self._restart_stt()
            self.chat_history = []
            self.say("Okay! Let's speak English together. How are you today?")
            return True
        # le chat
        if self.pet and re.search(r"\b(caresse|calin|nourris|joue avec) (le|ton|ta) (chat|chaton|minou)", ta):
            self.pet_poke()
            return True
        # écoute continue
        if re.search(r"^(ecoute[- ]moi|mode conversation|on discute a voix haute)", ta):
            self.set_wake("conversation")
            return True
        if re.search(r"^(arrete d'ecouter|n'ecoute plus|stop ecoute|fin de la conversation)", ta):
            self.set_wake("")
            return True
        # discussion entre personnages
        if self.cfg.get("invites") and re.search(r"\b(discutez|parlez entre vous|faites la conversation|"
                                                  r"discute avec)\b", ta):
            m = re.search(r"\b(?:de|sur|a propos de)\s+(.+)$", text, re.I)
            self.start_duo(m.group(1) if m else "")
            return True
        return False

    # ---------- notes et courses
    def _notes_cmd(self, action, data):
        mem = self.memory
        if action == "note_add":
            mem.setdefault("notes", []).append({"txt": data, "date": datetime.datetime.now().strftime("%d/%m %H:%M")})
            self._save_memory()
            self.happy_until = time.monotonic() + 1
            self.say(random.choice(["C'est noté !", "Je l'écris dans mes notes !", "Noté, je n'oublierai pas."]))
        elif action == "courses_add":
            have = {extras.sans_accents(x["txt"]) for x in mem.get("courses", [])}
            new = [it for it in data if extras.sans_accents(it) not in have]
            mem.setdefault("courses", []).extend({"txt": it} for it in new)
            self._save_memory()
            self.say(("J'ajoute " + ", ".join(new) + " à la liste de courses !") if new
                     else "C'est déjà sur la liste !")
        elif action == "courses_remove":
            keys = [extras.sans_accents(x) for x in data]
            before = len(mem.get("courses", []))
            mem["courses"] = [x for x in mem.get("courses", [])
                              if not any(k in extras.sans_accents(x["txt"]) for k in keys)]
            self._save_memory()
            self.say("Je l'enlève de la liste !" if len(mem["courses"]) < before else "Ce n'était pas sur la liste.")
        elif action == "courses_clear":
            mem["courses"] = []
            self._save_memory()
            self.say("Liste de courses vidée !")
        elif action == "notes_clear":
            mem["notes"] = []
            self._save_memory()
            self.say("J'ai effacé toutes tes notes.")
        elif action in ("courses_show", "notes_show"):
            key = "courses" if action == "courses_show" else "notes"
            items = [x["txt"] for x in mem.get(key, []) if not x.get("ok")]
            if not items:
                self.say("Ta liste de courses est vide !" if key == "courses" else "Tu n'as aucune note.")
            else:
                self.say(("À acheter : " if key == "courses" else "Tes notes : ") + " ; ".join(items[:6])
                         + (f" … et {len(items) - 6} autres." if len(items) > 6 else "."))
            self.open_notes(key)

    def open_notes(self, key="notes"):
        if not self.notes_win:
            self.notes_win = extras.NotesWindow(self)
        self.notes_win.open(key)

    # ---------- minuteurs
    def add_timer(self, secs, label=""):
        end = time.monotonic() + secs
        self.timers.append((end, label))
        QTimer.singleShot(int(secs * 1000), lambda e=end, l=label: self._timer_done(e, l))
        self.happy_until = time.monotonic() + 1
        self.say(f"Minuteur lancé : {extras.fmt_duree(secs)}" + (f" pour {label}" if label else "") + ". Je te préviens !")

    def _timer_done(self, end, label):
        if (end, label) not in self.timers:
            return
        self.timers.remove((end, label))
        self.sleeping = False
        self.show()
        self.hop_start = time.monotonic()
        self.surprise_until = time.monotonic() + 1.2
        self._spawn("exclam", 1, 0.3)
        self.say("Drriing ! " + (f"C'est l'heure : {label} !" if label else "Le minuteur est terminé !"))
        try:
            subprocess.Popen(["notify-send", "-a", self.char.get("name", "Viki"), "Minuteur",
                              label or "Terminé !"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass

    # ---------- presse-papiers
    def _on_clipboard(self):
        self._clip_remember()
        if not self.cfg.get("clip_watch", False) or self.fs_hidden or not self.isVisible() or self.in_focus():
            return
        cb = QApplication.clipboard()
        if cb.ownsClipboard():
            return
        txt = cb.text()
        if len(txt.strip()) < 80 or txt == self.last_clip or len(txt) > 20000:
            return
        self.last_clip = txt
        if re.search(r"^\s*(/|~/|https?://)\S+\s*$", txt) or txt.count("\n") > 400:
            return
        if not self.clip_popup:
            self.clip_popup = extras.ClipPopup(self)
        self.clip_popup.popup(txt)

    def clip_action(self, act, lang="", text=None):
        text = text if text is not None else QApplication.clipboard().text()
        if not text.strip():
            self.say("Ton presse-papiers est vide.")
            return
        if act == "lire":
            self.read_aloud(text[:6000])
            return
        if not self.ollama_ok:
            self.say("Pour résumer, traduire ou corriger, il me faut un modèle de discussion (Ollama).")
            return
        noms = {"resumer": "Résumé", "traduire": "Traduction", "corriger": "Texte corrigé"}
        self.say({"resumer": "Je lis ton texte et je le résume…", "traduire": "Je traduis…",
                  "corriger": "Je relis et je corrige…"}[act])
        self.react = ("regarde", time.monotonic())

        def done(res):
            if not res:
                self.say("Oups, je n'ai pas réussi… (l'IA ne répond pas)")
                return
            self._show_text(noms[act], res, "Résultat (tu peux le copier) :")
            self.happy_until = time.monotonic() + 1.2
            if act == "resumer" and len(res) < 240:
                self.say(res)
            else:
                self.say("C'est prêt ! Je te l'ai mis dans une fenêtre.")
        self.ask_ai(extras.clip_prompt(act, text, lang), done)

    # ---------- agenda
    def agenda_files(self):
        files = list(self.cfg.get("agenda_files", []))
        if pratique and self.cfg.get("agendas_web"):
            files += pratique.cal_files(self.cfg["agendas_web"])
        if self.cfg.get("agenda_auto", True):
            if not hasattr(self, "_auto_ics") or time.time() - self._auto_ics[0] > 3600:
                self._auto_ics = (time.time(), extras.find_ics_files())
            files += [f for f in self._auto_ics[1] if f not in files]
        return files

    def add_agenda_file(self, paths=None):
        if not paths:
            paths, _ = QFileDialog.getOpenFileNames(None, "Calendriers (.ics)", str(Path.home()),
                                                    "Calendriers (*.ics)")
        if paths:
            self.cfg["agenda_files"] = sorted(set(self.cfg.get("agenda_files", []) + paths))
            save_config(self.cfg)
            self.agenda.refresh(self.agenda_files())
            self._rebuild_menus()
            self.agenda_say("aujourd'hui")

    def agenda_say(self, quand):
        files = self.agenda_files()
        if not files:
            self.say("Je ne trouve pas de calendrier. Ajoute un fichier .ics (clic droit, Agenda).")
            return
        self.agenda.refresh(files)
        today = datetime.date.today()
        if quand == "semaine":
            a = datetime.datetime.combine(today, datetime.time())
            items = self.agenda.between(a, a + datetime.timedelta(days=7))
            if not items:
                self.say("Rien de prévu cette semaine dans ton agenda.")
            else:
                self.say("Cette semaine : " + " ; ".join(
                    o.strftime("%d/%m") + ("" if allday else o.strftime(" %Hh%M")) + " " + s
                    for o, s, allday in items[:6]) + ".")
            return
        d = today + datetime.timedelta(days=1 if quand == "demain" else 0)
        self.say(extras.agenda_text(self.agenda.day(d), quand))

    def _check_agenda(self):
        files = self.agenda_files()
        if not files:
            return
        self.agenda.refresh(files)
        now = datetime.datetime.now()
        avance = int(self.cfg.get("agenda_avance", 15))
        for o, summary, allday in self.agenda.between(now, now + datetime.timedelta(minutes=avance + 1)):
            key = f"{o.isoformat()}|{summary}"
            if allday or key in self.agenda_warned:
                continue
            self.agenda_warned.add(key)
            mins = max(0, int((o - now).total_seconds() // 60))
            self.sleeping = False
            self.hop_start = time.monotonic()
            self._spawn("exclam", 1, 0.3)
            self.say(f"Dans {mins} minute{'s' if mins > 1 else ''} : {summary} ({o.strftime('%Hh%M')}) !"
                     if mins else f"C'est maintenant : {summary} !")
            try:
                subprocess.Popen(["notify-send", "-a", self.char.get("name", "Viki"), "Agenda",
                                  f"{o.strftime('%Hh%M')} {summary}"], stdout=subprocess.DEVNULL,
                                 stderr=subprocess.DEVNULL)
            except Exception:
                pass
            return
        # résumé du jour, le matin, quand tu es là
        today = now.date().isoformat()
        if (now.hour >= 7 and self.agenda_day_said != today and time.monotonic() - self._cursor[1] < 120
                and not self.bubble_text and self.cfg["chatty"]):
            self.agenda_day_said = today
            items = self.agenda.day(now.date())
            if items:
                self.say(extras.agenda_text(items, "aujourd'hui"))

    # ---------- surveillance du PC
    def _check_pc(self):
        if time.monotonic() < self._next_pc:
            return
        self._next_pc = time.monotonic() + 60
        if self.cfg.get("updates_check") and time.time() - self.cfg.get("updates_last", 0) > 6 * 3600:
            self.cfg["updates_last"] = time.time()
            def auto_check():          # nombre négatif = vérification automatique (discrète)
                self.bridge.updates_done.emit(-1 - (extras.check_updates() or 0))
            threading.Thread(target=auto_check, daemon=True).start()
        if not self.cfg.get("pc_watch", True):
            return
        st = extras.pc_status()
        now = time.time()

        def warn(key, delay, text):
            if now - self.pc_warned.get(key, 0) > delay:
                self.pc_warned[key] = now
                self.sleeping = False
                self.surprise_until = time.monotonic() + 1
                self._spawn("exclam", 1, 0.3)
                self.say(text)
                self.notifier(text, "🖥️", "pc")
                return True
            return False
        for name in ("système", "perso"):
            if name in st and (st[name][0] < 5 or st[name][1] < 4):
                if warn("disque" + name, 12 * 3600, f"Attention, ton disque {name} est presque plein : "
                        f"plus que {st[name][0]:.1f} Go ! Tu veux que je range tes téléchargements ?"):
                    return
        g = st.get("gpu") or {}
        hot = g.get("junction", 0) >= 105 or g.get("edge", 0) >= 92
        self._gpu_hot = getattr(self, "_gpu_hot", 0) + 1 if hot else 0
        if self._gpu_hot >= 2 and warn("gpu", 3600, "Ta carte graphique chauffe beaucoup "
                                       f"({g.get('edge', g.get('junction', 0)):.0f} °C) ! Vérifie l'aération."):
            return
        if (st.get("cpu") or 0) >= 95 and warn("cpu", 3600, f"Ton processeur est à {st['cpu']:.0f} °C, c'est chaud !"):
            return

    def _on_updates(self, n):
        auto = n is not None and n < 0
        if auto:
            n = -1 - n
            if n < 20:                 # en automatique, elle ne dit rien pour quelques paquets
                return
        if n is None and IS_WIN:
            self.say("Sous Windows, les mises à jour passent par Windows Update (Paramètres → Windows Update).")
        elif n is None:
            self.say("Pour vérifier les mises à jour, il me faut « checkupdates » (sudo pacman -S pacman-contrib)."
                     if shutil.which("pacman") else "Je n'arrive pas à vérifier les mises à jour sur ce système : "
                     "utilise ton gestionnaire de logiciels (Discover, GNOME Logiciels…).")
        elif n == 0:
            self.say("Tout est à jour, rien à installer !")
        else:
            self.say(f"Il y a {n} mise{'s' if n > 1 else ''} à jour disponible{'s' if n > 1 else ''}. "
                     "Tu peux les installer avec « " + ((gestionpc.update_command() or "").split(";")[0]
                                                         if gestionpc else "sudo pacman -Syu") + " » quand tu veux.")

    # ---------- rangement des téléchargements
    def tidy_downloads(self):
        if outils:
            return self.open_tidy(outils.user_dir("DOWNLOAD"))
        folder = extras.downloads_dir()
        if not folder:
            self.say("Je ne trouve pas ton dossier Téléchargements.")
            return
        plan = extras.plan_tidy(folder)
        if not plan:
            self.say("Ton dossier Téléchargements est déjà bien rangé !")
            return
        box = QMessageBox(QMessageBox.Icon.Question, "Ranger les téléchargements",
                          f"Je range {len(plan)} fichier{'s' if len(plan) > 1 else ''} dans des sous-dossiers de\n"
                          f"{folder}\n\n{extras.tidy_summary(plan)}.\n\nRien n'est supprimé, et tu pourras "
                          "annuler (clic droit, Outils).",
                          QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        box.setDetailedText("\n".join(f"{Path(s).name}  →  {Path(d).parent.name}/" for s, d in plan))
        if box.exec() != QMessageBox.StandardButton.Yes:
            self.say("D'accord, je ne touche à rien.")
            return
        done = extras.apply_tidy(plan, CONFIG_DIR / "rangement.json")
        self.happy_until = time.monotonic() + 1.5
        self._spawn("etoile", 3)
        self._rebuild_menus()
        self.say(f"Et voilà, {len(done)} fichier{'s' if len(done) > 1 else ''} rangé{'s' if len(done) > 1 else ''} !")

    # ---------- nettoyage, rangement, activités (outils.py)
    def open_cleaner(self):
        if not outils:
            return self.say("Il me manque le fichier outils.py pour ça.")
        self.say("Je regarde ce qui prend de la place sur ton PC…")
        self.react = ("regarde", time.monotonic())
        self.clean_dlg = outils.CleanDialog(self)
        self.clean_dlg.show()

    def cleanup_done(self, freed):
        self.emotion = "joie"
        self._spawn("etoile", 3)
        self.say(f"Tout propre ! J'ai libéré {outils.human(freed)}." if freed > 1 << 20 else
                 "C'est fait, ton PC est tout propre !")
        if extras:
            self.add_xp(3)

    def open_tidy(self, folder=None):
        if not outils:
            return self.say("Il me manque le fichier outils.py pour ça.")
        self.tidy_dlg = outils.TidyDialog(self, folder, CONFIG_DIR / "rangement.json")
        self.tidy_dlg.show()
        self.say("Choisis le dossier à ranger, je te montre ce que je ferais avant de toucher à quoi que ce soit.")

    def tidy_done(self, n):
        self.happy_until = time.monotonic() + 1.5
        self._spawn("etoile", 3)
        self._rebuild_menus()
        self.say(f"Et voilà, {n} fichier{'s' if n > 1 else ''} rangé{'s' if n > 1 else ''} ! "
                 "Tu peux tout annuler si ça ne te plaît pas." if n else "Il n'y avait rien à ranger.")
        if extras and n:
            self.add_xp(2)

    def activity_ideas(self):
        recent = getattr(self, "_recent_ideas", [])
        ideas = outils.suggest(3, self.weather or "", recent=recent)
        self._recent_ideas = (recent + [t for t, _ in ideas])[-9:]
        return ideas

    def show_activities(self):
        if not outils:
            return self.say("Il me manque le fichier outils.py pour ça.")
        ideas = self.activity_ideas()
        self.emotion = "joie"
        self.say("J'ai des idées ! " + ideas[0][0] if ideas else "Hmm… on discute un peu ?")
        self.activity_win = outils.ActivityWindow(self, ideas, ai=self.ollama_ok)
        self.activity_win.show()

    def activity_ai(self):
        if not self.ollama_ok:
            return self.say_from("sans_ia")
        faits = "; ".join(self.memory.get("faits", [])[-15:]) or "rien de particulier"
        prompt = (f"Nous sommes le {date_txt()}, il est {heure_txt()}, la météo : {self.weather or 'inconnue'}. Ce que je sais de "
                  f"l'utilisateur : {faits}. Propose-lui 3 activités concrètes, saines et sympas pour maintenant "
                  "(pas forcément sur l'ordinateur), adaptées à ses goûts. Une par ligne, une phrase courte "
                  "chacune, en français, sans numéro ni introduction.")
        self.say("Laisse-moi réfléchir à des idées rien que pour toi…")

        def done(txt):
            lines = [re.sub(r"^[\s\-•*\d.)]+", "", l).strip() for l in (txt or "").splitlines()]
            lines = [l for l in lines if len(l) > 8][:3]
            if not lines:
                return self.say("Je n'ai pas d'idée là… réessaie dans un instant ?")
            win = getattr(self, "activity_win", None)
            if win and win.isVisible():
                win.fill([(l, "") for l in lines])
            self.say(lines[0])
        self.ask_ai(prompt, done)

    def do_activity(self, act):
        if act.startswith("jeu:"):
            self.start_game(act[4:])
        elif act == "histoire":
            self.tell_story()
        elif act == "pomodoro":
            self.start_pomodoro(25, "travail")
        elif act == "etirement":
            self._play_anim("etirement")
            self.say("Allez, bras en l'air… on s'étire bien… et on relâche ! Ça fait du bien, non ?")
        elif act == "danse":
            self._play_anim("pieds")
            self.say("C'est parti, on danse !")
        elif act == "journal":
            self.show_journal()
        elif act == "ranger":
            self.open_tidy()
        elif act.startswith("minuteur:"):
            self.add_timer(int(act.split(":")[1]) * 60, "activité")
            self.say("Top chrono ! Je te préviens quand c'est fini.")
        elif act == "anglais":
            self._extra_command("parlons anglais", "parlons anglais")
        elif act == "courses":
            self.open_notes("courses")

    def undo_tidy(self):
        n = extras.undo_tidy(CONFIG_DIR / "rangement.json")
        self._rebuild_menus()
        self.say(f"J'ai remis {n} fichier{'s' if n > 1 else ''} à leur place." if n else "Il n'y a rien à annuler.")

    # ---------- activité
    def _activity_loop(self):
        game, game_start, said = "", 0.0, set()
        cat, cat_start = "", time.monotonic()
        night_said = ""
        last_title, plays, pos_prev, loop_said = "", {}, 0.0, set()
        pc = shutil.which("playerctl")
        while True:
            time.sleep(20)
            if not self.cfg.get("activite", True):
                continue
            try:
                now = time.monotonic()
                g = extras.running_game()
                if g and g != game:
                    game, game_start, said = g, now, set()
                elif not g and game:
                    d = now - game_start
                    if d > 30 * 60:
                        self.bridge.activity.emit(random.choice([
                            f"Tu as joué {extras.fmt_duree(d)} à {game} ! C'était bien ?",
                            f"Fini {game} ? {extras.fmt_duree(d)} de jeu, quand même !"]))
                    game = ""
                if game:
                    d = now - game_start
                    for hrs in (2, 3, 4):
                        if d > hrs * 3600 and hrs not in said:
                            said.add(hrs)
                            self.bridge.activity.emit(f"Ça fait {hrs} heures que tu joues à {game} ! "
                                                      "Pense à boire un peu d'eau et à t'étirer.")
                else:
                    cls, title = extras.active_window()
                    c = extras.categorize(cls, title)
                    if c != cat:
                        cat, cat_start = c, now
                    elif c == "travail" and now - cat_start > 90 * 60:
                        cat_start = now
                        self.bridge.activity.emit("Tu travailles depuis une heure et demie… Une petite pause ? "
                                                  "Tu l'as bien méritée !")
                    elif c == "video" and now - cat_start > 25 * 60 and "video" not in said:
                        said.add("video")
                        self.bridge.activity.emit("Tu regardes quoi de beau ? Ça a l'air bien !")
                h = datetime.datetime.now()
                tonight = h.date().isoformat()
                if 1 <= h.hour < 5 and night_said != tonight and now - self._cursor[1] < 300:
                    night_said = tonight
                    self.bridge.activity.emit(f"Il est déjà {h.hour} h du matin… Tu devrais aller dormir, "
                                              "je veille sur ton bureau !")
                if pc and self.music_playing:
                    title = self.music_title
                    try:
                        pos = float(subprocess.run([pc, "position"], capture_output=True, text=True,
                                                   timeout=3).stdout.strip() or 0)
                    except Exception:
                        pos = 0.0
                    if title != last_title or (pos + 10 < pos_prev):
                        plays[title] = plays.get(title, 0) + 1
                        last_title = title
                        if plays[title] == 3 and title and title not in loop_said:
                            loop_said.add(title)
                            self.bridge.activity.emit(f"C'est la troisième fois qu'on écoute « {title} » ! "
                                                      "Tu l'adores, hein ?")
                    pos_prev = pos
            except Exception:
                pass

    def _on_activity(self, text):
        if self._brain_quiet():
            return
        if (not self.cfg["chatty"] or self.bubble_text or self.sleeping or self.fs_hidden or self.in_focus()
                or (self.is_muted() and self.cfg.get("mute_bubbles"))):
            return
        L = getattr(self, "learn", None)
        if L:
            if not L.allows("activite"):
                return
            L.note_spont("activite")
        self.say(text)

    # ---------- journal du soir
    def _check_journal(self):
        if not self.cfg.get("journal", True) or self.sleeping or self.bubble_text or not self.cfg["chatty"]:
            return
        now = datetime.datetime.now()
        today = now.date().isoformat()
        if not (20 <= now.hour < 23) or today in self.memory.get("journal", {}) \
                or self.cfg.get("journal_asked") == today:
            return
        if time.monotonic() - self._cursor[1] > 180 or self.fs_hidden:
            return
        self.cfg["journal_asked"] = today
        save_config(self.cfg)
        self.journal_until = time.monotonic() + 15 * 60
        self.happy_until = time.monotonic() + 1
        self.say(random.choice(["Alors, comment s'est passée ta journée ? Raconte-moi !",
                                "Tu me racontes ta journée ? Double-clique sur moi pour m'écrire.",
                                "C'était comment aujourd'hui ? J'ai envie de savoir !"]))

    def journal_write(self, text):
        if vie:
            sc = vie.parse_mood(text)
            if sc:
                try:
                    vie.set_mood(vie.load(), sc, text[:120])
                except Exception:
                    pass
        today = datetime.date.today().isoformat()
        j = self.memory.setdefault("journal", {})
        j[today] = (j.get(today, "") + " " + text).strip()[:2000]
        for k in sorted(j)[:-120]:          # garde les 120 derniers jours
            del j[k]
        self._save_memory()
        self.happy_until = time.monotonic() + 1.2
        if self.ollama_ok:
            self.send_chat("(Je te raconte ma journée) " + text)
        else:
            self.say(random.choice(["Merci de m'avoir raconté, je le garde dans ton journal.",
                                    "C'est noté dans ton journal. Repose-toi bien ce soir !"]))

    def _journal_context(self):
        j = self.memory.get("journal", {})
        if not j:
            return ""
        last = sorted(j)[-3:]
        return ("Ce qu'il t'a raconté de ses derniers jours : " + " ; ".join(
            f"{k[8:10]}/{k[5:7]} : {j[k][:160]}" for k in last) + ". ")

    def show_journal(self):
        j = self.memory.get("journal", {})
        txt = "\n\n".join(f"— {datetime.date.fromisoformat(k).strftime('%A %d/%m/%Y')}\n{j[k]}"
                           for k in sorted(j, reverse=True)) if j else "Ton journal est vide pour l'instant."
        self._show_text("Mon journal", txt, "Ce que tu m'as raconté, jour après jour (reste sur ton PC).")

    # ---------- fêtes
    def _update_fete(self):
        f = extras.fete_du_jour(birthday=self.cfg.get("anniversaire", "")) if self.cfg.get("fetes", True) else ""
        if f != self.fete:
            self.fete = f
            self.update()
        today = datetime.date.today().isoformat()
        if f and self.fete_said != today and f != "anniversaire" and self.cfg["chatty"] and not self.bubble_text \
                and not GUEST and time.monotonic() - self._cursor[1] < 300:
            self.fete_said = today
            self._spawn("coeur" if f == "valentin" else "etoile", 3)
            self.say(random.choice(extras.FETE_PHRASES.get(f, ["C'est la fête !"])))

    # ---------- petit chat
    def set_pet(self, color):
        self.cfg["pet"] = color
        save_config(self.cfg)
        self.pet = extras.Pet(color) if color else None
        self._update_mask()
        self._rebuild_menus()
        if color:
            self.say(random.choice(["Regarde qui est là ! Mon petit chat !", "Mon minou est arrivé !"]))

    def pet_poke(self):
        now = time.monotonic()
        self.pet.poke(now)
        if self.pet.x is not None:
            self._spawn_at("coeur", self.pet.x, self.pet.floor - self.pet.size * 1.6, 2)
        self.last_interaction = now
        if random.random() < 0.5 and not self.bubble_text:
            self.happy_until = now + 1.2
            self.say(random.choice(["Il t'aime bien, tu sais !", "Il ronronne, regarde !",
                                    "Doucement, il est timide… Hihi.", "C'est le roi du bureau !"]))

    # ---------- jeux
    def start_game(self, kind):
        self.stat("jeux")
        if getattr(self, "learn", None):
            self.learn.note_game(kind)
        if kind == "morpion":
            if not self.morpion:
                self.morpion = extras.MorpionWindow(self)
            self.morpion.show()
            self.morpion.raise_()
            self.morpion.activateWindow()
            self.say("Un morpion ? Je te préviens, je suis forte ! Tu commences.")
            return
        self.game = extras.Game(kind)
        self.happy_until = time.monotonic() + 1.2
        self.say(self.game.intro())
        QTimer.singleShot(300, self.open_input)

    def game_event(self, what):
        if what == "gagne":
            self.happy_until = time.monotonic() + 2
            self._spawn("etoile", 3)
            self.say(random.choice(["J'ai gagné ! Hihi, une autre ?", "Victoire ! Tu veux ta revanche ?"]))
        elif what == "perdu":
            self.sad_until = time.monotonic() + 2
            self.say(random.choice(["Oh non, tu m'as battue !", "Bien joué… je vais me concentrer !"]))
        else:
            self.say("Match nul ! On est trop fortes toutes les deux.")

    # ---------- écoute continue : mot d'éveil et conversation
    def set_wake(self, mode, announce=True):
        if self.listener:
            self.listener.stop()
            self.listener = None
        self.cfg["wake"] = mode
        save_config(self.cfg)
        self._rebuild_menus()
        if not mode:
            if announce:
                self.say("D'accord, je n'écoute plus.")
            return
        if self.stt_installed is False:
            self.cfg["wake"] = ""
            save_config(self.cfg)
            self.toggle_mic()                 # propose l'installation de la reconnaissance vocale
            return
        self.listener = extras.VoiceListener(self._on_segment, self._listener_pause, self.tmpdir)
        if not self.listener.start():
            self.say(self.listener.error)
            self.listener = None
            return
        threading.Thread(target=self._warm_stt, daemon=True).start()
        self.warm_ollama()
        self.name_re = extras.name_pattern(self.char.get("name", "Viki"))
        if announce:
            name = self.char.get("name", "moi")
            self.say(f"Je t'écoute ! Dis « {name} » puis ta demande." if mode == "nom"
                     else "Mode conversation : parle-moi quand tu veux, je t'écoute. Dis « arrête d'écouter » pour finir.")

    def _listener_pause(self):
        now = time.monotonic()
        return (self.mic_proc is not None or now - self.speak_end < 0.8 or self.fs_hidden
                or self.is_speaking(now))

    def _on_segment(self, path):
        def work():
            if not self._warm_stt():
                return
            with self.stt_lock:
                try:
                    self.stt_proc.stdin.write(path + "\n")
                    self.stt_proc.stdin.flush()
                    res = json.loads(self.stt_proc.stdout.readline())
                except Exception:
                    res = {}
            try:
                os.unlink(path)
            except OSError:
                pass
            txt = (res.get("text") or "").strip()
            if txt and not extras.HALLU.search(txt):
                self.bridge.heard.emit(txt)
        threading.Thread(target=work, daemon=True).start()

    def _all_names(self):
        """Son prénom et ceux de ses amies invitées (pour bien les reconnaître à l'oral)."""
        names = [self.char.get("name", "")]
        for cdir in self.cfg.get("invites", []):
            try:
                names.append(json.loads((Path(cdir) / "character.json").read_text()).get("name", ""))
            except Exception:
                pass
        return [n for n in names if n]

    def _guest_by_name(self, name):
        for cdir in self.cfg.get("invites", []):
            try:
                if json.loads((Path(cdir) / "character.json").read_text()).get("name") == name:
                    return re.sub(r"[^\w\-]", "", Path(cdir).name)
            except Exception:
                pass
        return None

    def _on_heard(self, text):
        mode = self.cfg.get("wake")
        now = time.monotonic()
        try:
            with open(MIC_LOG, "a") as log:
                log.write(f"entendu : {text}\n")
        except Exception:
            pass
        if not mode:
            return
        target = getattr(self, "wake_target", None)
        found = extras.match_name(text, self._all_names())
        if found:
            name, rest = found
            slug = None if name == self.char.get("name") else self._guest_by_name(name)
        elif mode == "conversation" or now < self.wake_follow_until:
            slug, rest = (target if now < self.wake_follow_until else None), text
            self.wake_follow_until = 0.0
            if slug:
                self._guest_send(slug, "msg:" + rest)
            else:
                self._heard_command(rest)
            return
        else:
            return
        if slug:                                   # on parle à son amie
            self.wake_target = slug
            if len(rest) < 2:
                self.wake_follow_until = now + 9
                self._guest_send(slug, "ecoute")
            else:
                self._guest_send(slug, "msg:" + rest)
            return
        self.wake_target = None
        if len(rest) < 2:
            self.sleeping = False
            self.hop_start = now
            self.react = ("regarde", now)
            self.wake_follow_until = now + 9
            self.say(random.choice(["Oui ?", "Je t'écoute !", "Oui, dis-moi ?"]))
        else:
            self._heard_command(rest)

    def _heard_command(self, text):
        self.bubble_text = f"« {text} »"
        self.bubble_until = time.monotonic() + 3
        self._update_mask()
        if self.cfg.get("wake") == "conversation" and re.search(r"^(au revoir|bonne nuit|a plus|ciao)\b",
                                                                extras.sans_accents(text)):
            self.set_wake("", announce=False)
            self.say("À plus tard ! J'arrête d'écouter.")
            return
        self.handle_message(text)

    # ---------- plusieurs personnages
    def _guest_send(self, slug, msg, on_reply=None, timeout=30000):
        s = QLocalSocket(self)
        s.connectToServer(f"{INSTANCE_BASE}-{slug}")
        if not s.waitForConnected(400):
            s.deleteLater()
            if on_reply:
                on_reply(None)
            return False
        s.write(msg.encode())
        s.flush()
        if not on_reply:
            s.waitForBytesWritten(300)
            s.disconnectFromServer()
            s.deleteLater()
            return True
        done = [False]

        def finish(reply):
            if done[0]:
                return
            done[0] = True
            try:
                s.disconnectFromServer()
                s.deleteLater()
            except RuntimeError:
                pass
            on_reply(reply)
        s.readyRead.connect(lambda: finish(bytes(s.readAll()).decode(errors="ignore")))
        QTimer.singleShot(timeout, lambda: finish(None))
        return True

    def _guest_leave(self):
        s = QLocalSocket()
        s.connectToServer(INSTANCE_BASE)
        if s.waitForConnected(400):
            s.write(("renvoye:" + str(self.cfg.get("character_dir", ""))).encode())
            s.flush()
            s.waitForBytesWritten(300)
        self.quit()

    def _guest_alive(self, slug):
        s = QLocalSocket()
        s.connectToServer(f"{INSTANCE_BASE}-{slug}")
        ok = s.waitForConnected(300)
        s.abort()
        return ok

    def invite(self, cdir):
        cdir = str(cdir)
        if Path(cdir).resolve() == Path(self.cfg["character_dir"]).resolve():
            self.say("C'est moi, ça ! Choisis quelqu'un d'autre.")
            return
        slug = re.sub(r"[^\w\-]", "", Path(cdir).name) or "invite"
        gdir = BASE_CONFIG_DIR / "invites" / slug
        gdir.mkdir(parents=True, exist_ok=True)
        gfile = gdir / "config.json"
        scr = self.app.primaryScreen().availableGeometry()
        gx = self.x() + int(self.W * 0.85)                 # à côté d'elle, du côté où il y a de la place
        if gx + self.W > scr.right():
            gx = max(scr.left(), self.x() - int(self.W * 0.85))
        try:
            gcfg = json.loads(gfile.read_text())
        except Exception:
            gcfg = {k: self.cfg.get(k) for k in ("voice", "volume", "piper_voice", "piper_speaker", "ollama_model",
                                                 "bubble_theme", "bubble_size", "chatty", "sleepy", "prenom",
                                                 "eye_follow", "music_dance", "perf", "walk", "anniversaire")
                    if k in self.cfg}
            gcfg.update({"voice_engine": "piper", "lieu": "", "wake": "", "clip_watch": False, "pet": "",
                         "activite": False, "journal": False, "agenda_auto": False, "pc_watch": False,
                         "invites": [], "scale": 0,
                         "pos": [gx, self.y()]})
        gcfg["character_dir"] = cdir
        self._guest_voice(gcfg)
        gfile.write_text(json.dumps(gcfg, indent=2, ensure_ascii=False))
        if cdir not in self.cfg.setdefault("invites", []):
            self.cfg["invites"].append(cdir)
            save_config(self.cfg)
        self._launch_guest(slug)
        self._restart_stt()
        self._rebuild_menus()
        try:
            gname = json.loads((Path(cdir) / "character.json").read_text()).get("name", "mon amie")
        except Exception:
            gname = "mon amie"
        self.happy_until = time.monotonic() + 1.5
        self.say(f"Youpi, {gname} vient nous voir !")

    def _default_friend(self):
        amies = ASSETS_DIR / "amies"
        mine = Path(self.cfg["character_dir"]).resolve()
        for d in sorted(amies.glob("*/character.json")) if amies.exists() else []:
            if d.parent.resolve() != mine and str(d.parent) not in self.cfg.get("invites", []):
                self.invite(str(d.parent))
                QTimer.singleShot(9000, lambda: self.start_duo("leur rencontre avec l'utilisateur"))
                return

    def _guest_voice(self, gcfg):
        """Une autre voix féminine que l'héroïne pour l'invitée, si une autre voix est installée."""
        if gcfg.get("voix_choisie"):
            return False
        mine_v = (self.cfg.get("piper_voice", ""), int(self.cfg.get("piper_speaker", -1)))
        for stem, label, spk in piper_voice_choices():
            if (stem, spk) != mine_v and not re.search(r"masculine|homme", label, re.I):
                gcfg["piper_voice"], gcfg["piper_speaker"] = stem, spk
                gcfg["voix_choisie"] = True
                return True
        return False

    def _launch_guest(self, slug):
        if self._guest_alive(slug):
            return
        gfile = BASE_CONFIG_DIR / "invites" / slug / "config.json"
        try:
            gcfg = json.loads(gfile.read_text())
            if self._guest_voice(gcfg):
                gfile.write_text(json.dumps(gcfg, indent=2, ensure_ascii=False))
        except Exception:
            pass
        try:
            g = json.loads(gfile.read_text())
            g["taille_hote"] = self.host_size()
            gfile.write_text(json.dumps(g, indent=2, ensure_ascii=False))
        except Exception:
            pass
        env = dict(os.environ, COMPAGNON_PROFIL=slug)
        cmd = [sys.executable] if plateforme.FROZEN else [sys.executable, str(Path(__file__).resolve())]
        subprocess.Popen(cmd, env=env, stdout=subprocess.DEVNULL,
                         stderr=open(BASE_CONFIG_DIR / f"invite-{slug}.log", "w"), start_new_session=True)

    def _relaunch_guests(self):
        for cdir in self.cfg.get("invites", []):
            if Path(cdir).exists():
                self._launch_guest(re.sub(r"[^\w\-]", "", Path(cdir).name))

    def dismiss(self, cdir):
        slug = re.sub(r"[^\w\-]", "", Path(cdir).name)
        self._guest_send(slug, "quitter")
        if Path(cdir).resolve().parent == (ASSETS_DIR / "amies").resolve():
            self.cfg["amies_auto"] = False           # tu l'as renvoyée : elle ne revient plus toute seule
        self.cfg["invites"] = [c for c in self.cfg.get("invites", []) if c != cdir]
        save_config(self.cfg)
        self._rebuild_menus()
        self.say("À bientôt ! Elle reviendra quand tu veux.")

    def start_duo(self, topic=""):
        if self.duo:
            return
        guests = [c for c in self.cfg.get("invites", []) if Path(c).exists()]
        if not guests:
            self.say("Invite d'abord un autre personnage (clic droit, Personnage, Inviter).")
            return
        cdir = random.choice(guests)
        slug = re.sub(r"[^\w\-]", "", Path(cdir).name)
        if not self._guest_alive(slug):
            self._launch_guest(slug)
            self.say("Attends, elle arrive…")
            return
        try:
            gchar = json.loads((Path(cdir) / "character.json").read_text())
        except Exception:
            gchar = {}
        na, nb = self.char.get("name", "A"), gchar.get("name", "B")
        self.duo = {"slug": slug, "lines": [], "i": 0, "names": (na, nb)}

        def canned():
            lines = random.choice(extras.DIALOGUES_SIMPLES)
            return [(w, t.replace("{A}", na).replace("{B}", nb)) for w, t in lines]
        if not self.ollama_ok:
            self.duo["lines"] = canned()
            self._duo_next()
            return
        sujets = ["ce qu'elles feraient si elles pouvaient sortir de l'écran", "leur goûter préféré",
                  "la musique", "la météo du jour", "un rêve bizarre", "un jeu vidéo", "les chats",
                  "ce que fait l'utilisateur en ce moment", "les vacances", "un film qu'elles aimeraient voir"]
        prenom = self.cfg.get("prenom", "")
        souvenir = ""
        if fun and not topic:
            B = getattr(self, "brain", None)
            recent = self.cfg.get("duo_sujets", [])
            topic = fun.duo_topic(self.cfg, B.cat if B else "", fun.season(), getattr(self, "fete", ""),
                                  recent=recent)
            self.cfg["duo_sujets"] = (recent + [topic])[-8:]
            if recent:
                souvenir = (f" La dernière fois, elles ont parlé de « {recent[-1]} » : elles peuvent y faire "
                            "un petit clin d'œil, sans le répéter.")
            if B and B.cat in ("code", "jeu", "video", "musique") and B.title:
                souvenir += f" (Activité de l'utilisateur : {B.title[:60]}.)"
        prompt = (f"Écris un court dialogue naturel, amusant et gentil (5 à 7 répliques) entre {na} "
                  f"({self.char.get('persona', 'une jeune femme joyeuse')}) et {nb} "
                  f"({gchar.get('persona', 'une jeune femme joyeuse')}), deux amies qui vivent sur le bureau "
                  f"de l'ordinateur de {prenom or 'leur utilisateur'}. Sujet : {topic or random.choice(sujets)}. "
                  f"Format strict : une réplique par ligne, sous la forme « {na}: texte » ou « {nb}: texte ». "
                  "Répliques courtes (20 mots maximum), en français, sans émojis, sans didascalies. "
                  "Elles se répondent vraiment (questions, petites taquineries, rires), comme deux vraies amies."
                  + souvenir)
        self.say("…")

        def got(txt):
            lines = extras.parse_dialogue(txt, na, nb) if txt else []
            self.duo["lines"] = lines if len(lines) >= 2 else canned()
            self._duo_next()
        self.ask_ai(prompt, got, timeout=120)

    def _duo_next(self):
        d = self.duo
        if not d:
            return
        if d["i"] == 0 and not d.get("approached"):
            d["approached"] = True
            delay = self._approach_friend(d["slug"])
            self._guest_send(d["slug"], "anim:salut")
            self._play_anim("salut")
            QTimer.singleShot(int(delay * 1000) + 900, self._duo_next)
            return
        self.look_friend_until = time.monotonic() + 6
        if d["i"] >= len(d["lines"]):
            self.duo = None
            if self.level() >= 7 and random.random() < 0.5:     # elles dansent ensemble
                self._react("pieds")
                self._guest_send(d["slug"], "anim:pieds")
            return
        who, text = d["lines"][d["i"]]
        d["i"] += 1
        if who == "A":
            self.say(text)
            start = time.monotonic()
            tm = QTimer(self)

            def check():
                now = time.monotonic()
                if (now - start > 1.0 and not self.is_speaking(now)) or now - start > 40:
                    tm.stop()
                    tm.deleteLater()
                    QTimer.singleShot(450, self._duo_next)
            tm.timeout.connect(check)
            tm.start(200)
        else:
            def replied(r):
                if r is None:
                    self.duo = None
                    return
                QTimer.singleShot(450, self._duo_next)
            if not self._guest_send(d["slug"], "dire:" + text, replied, timeout=45000):
                self.duo = None

    # =========================================================== qualité visuelle
    def _scaled_pix(self, img):
        dpr = getattr(self, "dpr", 1.0)
        if isinstance(img, QImage):
            img = QPixmap.fromImage(img)
        pm = img.scaled(int(round(self.cw * dpr)), int(round(self.ch * dpr)), Qt.AspectRatioMode.IgnoreAspectRatio,
                        Qt.TransformationMode.SmoothTransformation)
        pm.setDevicePixelRatio(dpr)
        return pm

    def _pick_expr(self, now):
        if not self.expr_patches or self.sleeping:
            return ""
        for emo, until in (("boude", self.angry_until), ("surprise", self.surprise_until),
                           ("triste", self.sad_until), ("timide", self.blush_until), ("joie", self.happy_until)):
            if now < until and emo in self.expr_patches:
                return emo
        return ""

    def _cur_pix(self):
        if self.__dict__.get("vanim"):
            return self._anim_frame()
        emo = self._expr_now
        if not emo:
            return self.pix
        pm = self._expr_pix.get(emo)
        if pm is None:
            try:
                pm = self._scaled_pix(visuel.compose(self.src.toImage(), self.expr_patches[emo]))
            except Exception:
                log_error("Expression")
                pm = self.pix
            self._expr_pix[emo] = pm
        return pm

    def add_expression(self, emo):
        if not visuel:
            return
        path, _ = QFileDialog.getOpenFileName(None, f"Image « {visuel.EXPRESSIONS.get(emo, emo)} »",
                                              str(Path.home()), "Images (*.png *.jpg *.jpeg *.webp)")
        if not path:
            return
        cdir = Path(self.char_dir)
        self.say("Je regarde cette expression et je la cale sur mon visage…")
        base = QImage(str(cdir / self.char_base["image"]))
        eyes, mouth = self.char_base["eyes"], self.char_base["mouth"]

        def work():
            err = ""
            try:
                src = QImage(path)
                if src.isNull():
                    raise RuntimeError("image illisible")
                if not src.hasAlphaChannel():
                    out = str(self.tmpdir / f"expr_{emo}.png")
                    if has_rembg():
                        remove_background(path, out)
                        src = QImage(out)
                    else:
                        src = visuel.simple_cutout(src)
                if src.width() * 1.0 / max(1, src.height()) > 0 and abs(src.height() - base.height()) > 2:
                    pass
                patch = visuel.align_expression(base, src, eyes, mouth)
                (cdir / "expressions").mkdir(exist_ok=True)
                patch.save(str(cdir / "expressions" / f"{emo}.png"))
            except Exception as e:
                err = str(e)
            self.bridge.ai_done.emit(lambda _t: self._expression_added(emo, err), "")
        threading.Thread(target=work, daemon=True).start()

    def _expression_added(self, emo, err):
        if err:
            self.say(f"Je n'ai pas réussi à caler cette expression : {err}")
            return
        cfile = Path(self.char_dir) / "character.json"
        data = json.loads(cfile.read_text())
        data.setdefault("expressions", {})[emo] = f"expressions/{emo}.png"
        cfile.write_text(json.dumps(data, indent=2, ensure_ascii=False))
        self._load_character()
        self._apply_scale(self.scale)
        now = time.monotonic()
        setattr(self, {"joie": "happy_until", "triste": "sad_until", "boude": "angry_until",
                       "surprise": "surprise_until", "timide": "blush_until"}[emo], now + 3)
        self.say("Voilà ma nouvelle expression ! Comment tu me trouves ?")

    def remove_expression(self, emo):
        cfile = Path(self.char_dir) / "character.json"
        data = json.loads(cfile.read_text())
        rel = (data.get("expressions") or {}).pop(emo, None)
        if rel:
            (Path(self.char_dir) / rel).unlink(missing_ok=True)
        cfile.write_text(json.dumps(data, indent=2, ensure_ascii=False))
        self._load_character()
        self._apply_scale(self.scale)

    def sharpen_character(self):
        if not visuel or not visuel.find_upscaler():
            QMessageBox.information(None, "Netteté", "Il faut d'abord installer l'outil de netteté (Real-ESRGAN, "
                                    "local, utilise ta carte graphique) :\n\n    bash installer_nettete.sh")
            return
        cdir = Path(self.char_dir)
        if self.char_base.get("nettete"):
            self.say("Je suis déjà en haute qualité !")
            return
        self.say("Je me refais une beauté en haute définition… (une minute environ)")

        def work():
            err = ""
            try:
                visuel.upscale_character(cdir, make_hitmask)
            except Exception as e:
                err = str(e)
            self.bridge.ai_done.emit(lambda _t: self._sharpened(err), "")
        threading.Thread(target=work, daemon=True).start()

    def _sharpened(self, err):
        if err:
            self.say(f"La netteté n'a pas marché : {err[:160]}")
            return
        old_h = self.src.height()
        self._load_character()
        self._apply_scale(self.scale * old_h / max(1, self.src.height()))
        self._spawn("etoile", 4)
        self.happy_until = time.monotonic() + 2
        self.say("Tadaa ! Je suis toute nette maintenant !")

    def unsharpen_character(self):
        if visuel and visuel.undo_upscale(self.char_dir):
            old_h = self.src.height()
            self._load_character()
            self._apply_scale(self.scale * old_h / max(1, self.src.height()))
            self.say("Je suis revenue comme avant.")

    # =========================================================== messages réguliers
    def _check_messages(self):
        """Messages que tu as programmés : toutes les X minutes, ou chaque jour à une heure."""
        msgs = self.cfg.get("messages_reguliers", [])
        if not msgs:
            return
        now = time.time()
        dt = datetime.datetime.now()
        changed = False
        for m in msgs:
            if not m.get("actif", True) or not m.get("txt", "").strip():
                continue
            due = False
            if m.get("type") == "heure":
                hh, mm = [int(x) for x in m.get("heure", "09:00").split(":")]
                today = dt.date().isoformat()
                if m.get("fait") != today and (dt.hour, dt.minute) >= (hh, mm) and \
                        (dt.hour * 60 + dt.minute) - (hh * 60 + mm) < 30:
                    m["fait"] = today
                    due = True
            else:
                every = max(1, int(m.get("minutes", 60))) * 60
                last = float(m.get("dernier", 0) or 0)
                if not last:
                    m["dernier"] = now
                    changed = True
                elif now - last >= every:
                    m["dernier"] = now
                    due = True
            if due:
                changed = True
                if self.in_focus() and m.get("type") != "heure":
                    continue
                self.sleeping = False
                self.hop_start = time.monotonic()
                self._spawn("etoile", 1, 0.4)
                self.say(m["txt"].replace("{prenom}", self.cfg.get("prenom", "") or "toi"))
                try:
                    subprocess.Popen(["notify-send", "-a", self.char.get("name", "Viki"),
                                      self.char.get("name", "Viki"), m["txt"]],
                                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                except Exception:
                    pass
                break
        if changed:
            save_config(self.cfg)

    # =========================================================== amitié
    def level(self):
        return extras.niveau(int(self.cfg.get("amitie_xp", 0)))[0] if extras else 1

    def add_xp(self, n):
        today = datetime.date.today().isoformat()
        first = self.cfg.get("amitie_jour") != today
        if first:
            self.cfg["amitie_jour"] = today
            n += 10
        before = self.level()
        self.cfg["amitie_xp"] = int(self.cfg.get("amitie_xp", 0)) + n
        after = self.level()
        if after > before:
            QTimer.singleShot(2500, lambda: self._level_up(after))
        elif first and after >= 5 and not GUEST:
            QTimer.singleShot(5000, lambda: (not self.bubble_text) and (self._spawn("etoile", 3),
                                                                       self.say(random.choice(extras.CADEAUX))))
        if after >= 6 and not self.cfg.get("surnom"):
            self.cfg["surnom"] = random.choice(extras.SURNOMS)

    def _level_up(self, lvl):
        self.hop_start = time.monotonic()
        self.happy_until = time.monotonic() + 2.5
        self._spawn("coeur", 4)
        self._spawn("etoile", 4)
        txt = f"On passe au niveau {lvl} : « {extras.NIVEAUX[lvl - 1]} » !"
        if lvl in extras.NIVEAU_DEBLOQUE:
            txt += " Nouveau : " + extras.NIVEAU_DEBLOQUE[lvl]
        self.say(txt)

    def _friendship_context(self):
        if not extras:
            return ""
        lvl = self.level()
        txt = f"Votre amitié est au niveau {lvl}/10 ({extras.NIVEAUX[lvl - 1]}) : sois d'autant plus complice. "
        if lvl >= 6 and self.cfg.get("surnom"):
            txt += f"Tu l'appelles parfois affectueusement « {self.cfg['surnom']} ». "
        return txt

    # =========================================================== notifications
    def _start_notifs(self):
        if self.notif_watch:
            return
        self.notif_watch = extras.NotifWatcher(lambda a, s_, b: self.bridge.notif.emit(a, s_, b))
        if not self.notif_watch.start():
            self.notif_watch = None

    def set_notif_mode(self, mode):
        self.cfg["notif_lire"] = mode
        save_config(self.cfg)
        if mode:
            self._start_notifs()
        elif self.notif_watch:
            self.notif_watch.stop()
            self.notif_watch = None

    def _on_notif(self, app, summary, body):
        mode = self.cfg.get("notif_lire", "")
        if not mode or self.in_focus() or self.fs_hidden:
            return
        a = (app or "").lower()
        ignore = [x.strip().lower() for x in self.cfg.get("notif_ignore", "").split(",") if x.strip()]
        if a in (self.char.get("name", "").lower(), "compagnon", "notify-send") or any(i and i in a for i in ignore):
            return
        now = time.monotonic()
        key = f"{app}|{summary}"
        if now - self._notif_last[0] < 12 or (key == self._notif_last[1] and now - self._notif_last[0] < 60):
            return
        self._notif_last = (now, key)
        self.sleeping = False
        self.react = ("regarde", now)
        self._spawn("exclam", 1, 0.3)
        self.say(extras.notif_phrase(app, summary, body, mode))

    # =========================================================== contrôle du PC
    def pc_control(self, act, val):
        def bg(fn, done):
            threading.Thread(target=lambda: self.bridge.ai_done.emit(done, str(fn())), daemon=True).start()
        if act.startswith("volume_"):
            a = act.split("_")[1]
            bg(lambda: extras.volume(a, val), lambda r: self.say(
                "Son du PC coupé." if a == "muet" else "Son du PC remis !" if a == "son" else
                ("C'est fait !" if r == "-1" else f"Volume à {r} %." if r != "None" else
                 "Je n'arrive pas à régler le volume (wpctl manquant).")))
        elif act.startswith("lum_"):
            a = act.split("_")[1]
            self.say("Je règle la luminosité…")
            bg(lambda: extras.brightness(a, val), lambda r: self.say(
                f"Luminosité à {r} %." if r != "None" else
                "Je n'arrive pas à régler la luminosité : installe « ddcutil » pour un écran de bureau "
                "(ou « brightnessctl » pour un portable)."))
        elif act == "verrou":
            self.say("Je verrouille ! À tout de suite.")
            QTimer.singleShot(1500, lambda: subprocess.Popen(["loginctl", "lock-session"],
                                                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL))
        elif act == "veille":
            self.say("Bonne pause ! Je mets le PC en veille.")
            QTimer.singleShot(2500, lambda: subprocess.Popen(["systemctl", "suspend"], stdout=subprocess.DEVNULL,
                                                             stderr=subprocess.DEVNULL))
        elif act == "annule_extinction":
            if self.shutdown_plan:
                self.shutdown_plan = None
                self.say("Extinction annulée, on reste ensemble !")
            else:
                self.say("Il n'y avait pas d'extinction prévue.")
        elif act in ("eteindre", "redemarrer"):
            if val > 0:
                when = time.time() + val * 60
                self.shutdown_plan = (act, when, False)
                h = datetime.datetime.fromtimestamp(when).strftime("%Hh%M")
                self.say(f"D'accord : {'extinction' if act == 'eteindre' else 'redémarrage'} à {h}. "
                         "Dis « annule l'extinction » si tu changes d'avis.")
            else:
                self.pending_confirm = (act, time.monotonic() + 30)
                self.say(f"Tu es sûr de vouloir {'éteindre' if act == 'eteindre' else 'redémarrer'} le PC "
                         "maintenant ? Réponds « oui » pour confirmer.")
                QTimer.singleShot(200, self.open_input)

    def _power(self, act, confirmed=False):
        self.say("Bonne nuit ! À bientôt." if act == "eteindre" else "Je redémarre, à tout de suite !")
        self.quit_later = True
        cmd = ["systemctl", "poweroff" if act == "eteindre" else "reboot"]
        QTimer.singleShot(4000, lambda: subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL))

    def _check_shutdown(self):
        if not self.shutdown_plan:
            return
        act, when, warned = self.shutdown_plan
        left = when - time.time()
        if left <= 0:
            self.shutdown_plan = None
            self._power(act)
        elif left < 75 and not warned:
            self.shutdown_plan = (act, when, True)
            self.sleeping = False
            self._spawn("exclam", 1, 0.3)
            self.say(f"Attention, le PC {'s’éteint' if act == 'eteindre' else 'redémarre'} dans une minute ! "
                     "Pense à enregistrer. (« annule l'extinction » pour annuler)")

    # =========================================================== lecture à voix haute, histoires
    def read_aloud(self, text, intro=""):
        parts = extras.split_for_reading(text)
        if not parts:
            return
        self.reading = parts
        if intro:
            self.reading.insert(0, intro)
        self._read_next()

    def _read_next(self):
        if not self.reading:
            return
        self.say(self.reading.pop(0))
        start = time.monotonic()
        tm = QTimer(self)

        def check():
            now = time.monotonic()
            if not self.reading and tm.isActive() is False:
                return
            if (now - start > 1.0 and not self.is_speaking(now)) or now - start > 60:
                tm.stop()
                tm.deleteLater()
                if self.reading:
                    QTimer.singleShot(250, self._read_next)
        tm.timeout.connect(check)
        tm.start(200)
        self._read_timer = tm

    def stop_reading(self):
        self.reading = []
        self._stop_audio()
        if getattr(self, "reader_active", False):
            self.reader_win.pause()

    # ---------- mode lecture (livres)
    def open_reader(self, path=None, autoplay=False):
        if not lecture:
            return self.say("Il me manque le fichier lecture.py pour lire des livres.")
        self.sleeping = False
        w = getattr(self, "reader_win", None)
        if w is None:
            w = self.reader_win = lecture.make_window(self)
        w.show()
        w.raise_()
        w.activateWindow()
        if path:
            w.open_book(path, autoplay=autoplay)
        elif not w.book:
            last = lecture.load_state().get("dernier", "")
            if last and Path(last).exists():
                w.open_book(last)
            else:
                self.say("Choisis un livre : EPUB, PDF, texte… Je te le lis !")
                QTimer.singleShot(300, w.open_book)

    def resume_reading(self):
        last = lecture.load_state().get("dernier", "") if lecture else ""
        if not last or not Path(last).exists():
            return self.open_reader()
        w = getattr(self, "reader_win", None)
        if w and w.book and w.path == last:
            w.show()
            return w.play()
        self.open_reader(last, autoplay=True)

    def synth_reading(self, text, out, speed=1.0, natural=False):
        """Une phrase de livre : Piper avec la vitesse de lecture (ou la voix naturelle si choisie)."""
        txt = clean_for_tts(text)
        if not txt:
            return False
        self.stat("phrases_lues")
        if natural and self.natural_ready and self._synth_natural(txt, out):
            self._voice_fx(out)
            return True
        model, spk = self.voice_model, self._piper_speaker_args()
        dlg = self._dialogue_voice(text)                  # une autre voix pour les dialogues
        pitch_k = 1.0
        if dlg:
            model, spk, pitch_k = dlg
        if self.piper and model:
            cfg = dict(self.cfg)
            cfg["voix_vitesse"] = float(self.cfg.get("voix_vitesse", 1.0)) * float(speed)
            cfg["voix_pause"] = 0.1
            pitch = (float(cfg.get("voix_hauteur", 1.0)) if voix else 1.0) * pitch_k
            cmd = [self.piper, "-m", piper_model(model), "-f", out] + spk + (voix.piper_args(cfg, pitch) if voix else [])
            try:
                r = subprocess.run(cmd, input=txt.encode(), capture_output=True, timeout=90)
                if r.returncode == 0 and Path(out).exists():
                    if voix and abs(pitch - 1) > 0.01:
                        voix.pitch_shift(out, pitch)
                    self._voice_fx(out, pitch_speed=False)
                    return True
            except Exception as e:
                print("Lecture (Piper) :", e, file=sys.stderr)
        return self._synth_file(text, out)[0]

    DIALOGUE = re.compile(r'^\s*[«“"—–-]|[»”"]\s*[.!?…]?\s*$')

    def _dialogue_voice(self, text):
        """Phrase de dialogue d'un livre (« … », — …) -> (modèle, args locuteur, facteur de hauteur) ou None.
        Réglage « lecture_dialogues » : "" = une seule voix, "auto" = une autre voix installée (ou la sienne
        un peu plus grave), "fichier|locuteur" = une voix précise."""
        mode = self.cfg.get("lecture_dialogues", "auto")
        if not mode or not self.DIALOGUE.search(text or ""):
            return None
        mine = Path(self.voice_model).stem if self.voice_model else ""
        if mode == "auto":
            others = [v for v in piper_voice_choices() if v[0] != mine]
            pref = next((v for v in others if any(k in v[1].lower() for k in ("masculine", "tom", "pierre"))),
                        others[0] if others else None)
            if not pref:
                return (self.voice_model, self._piper_speaker_args(), 0.9) if self.voice_model else None
            stem, _lab, spk = pref
        else:
            stem, _, spk = mode.partition("|")
            spk = int(spk or -1)
        m = find_voice_model(stem)
        if not m or Path(m).stem != stem:
            return None
        return (str(m), ["--speaker", str(spk)] if spk >= 0 else [], 1.0)

    def envelope(self, path):
        return wav_envelope(path)

    def save_cfg(self):
        save_config(self.cfg)

    def tell_story(self, sujet=""):
        self.stat("histoires")
        self.sleeping = False
        if self.ollama_ok:
            self.say("Installe-toi bien… je t'invente une histoire.")
            self.ask_ai(extras.story_prompt(sujet), lambda txt: self.read_aloud(
                txt or random.choice(extras.HISTOIRES)), timeout=240)
        else:
            self.read_aloud(random.choice(extras.HISTOIRES), "Installe-toi bien, voici une histoire…")

    # =========================================================== dictée
    def start_dictation(self):
        self.dictation = True
        self.say("Dictée : parle, puis reclique sur le micro. J'écrirai dans la fenêtre ouverte.")
        QTimer.singleShot(1200, self.toggle_mic)

    def type_text(self, text):
        def work():
            time.sleep(0.4)
            tool = extras.type_text(text + " ")
            self.bridge.ai_done.emit(lambda _t: self._typed(text, tool), "")
        threading.Thread(target=work, daemon=True).start()

    def _typed(self, text, tool):
        if tool:
            self.say("C'est écrit !")
        else:
            QApplication.clipboard().setText(text)
            self.say("Je l'ai mis dans ton presse-papiers : colle-le avec Ctrl+V. (Installe « ydotool » pour "
                     "que je l'écrive moi-même.)")

    # =========================================================== mode concentration
    def in_focus(self):
        return time.time() < float(self.cfg.get("focus_until", 0) or 0)

    def set_focus(self, minutes):
        QTimer.singleShot(1500, self._auto_outfit)        # tenue « concentration »
        if minutes > 0:
            self.stat("concentration_min", int(minutes))
        if minutes <= 0:
            was = self.in_focus()
            self.cfg["focus_until"] = 0
            save_config(self.cfg)
            if was:
                self.happy_until = time.monotonic() + 2
                self._spawn("etoile", 3)
                self.say("Fin de la concentration ! Bravo, tu as bien travaillé.")
        else:
            self.cfg["focus_until"] = time.time() + minutes * 60
            save_config(self.cfg)
            self._focus_water = time.monotonic()
            self.say(f"Mode concentration pour {extras.fmt_duree(minutes * 60)}. Je me fais toute petite, "
                     "je te rappellerai juste de boire un peu.")
        self._rebuild_menus()

    def _check_focus(self):
        fu = float(self.cfg.get("focus_until", 0) or 0)
        if fu and time.time() >= fu:
            self.set_focus(0)
            return
        if self.in_focus() and time.monotonic() - self._focus_water > 40 * 60 and not self.bubble_text:
            self._focus_water = time.monotonic()
            self.say(random.choice(["Petite gorgée d'eau ? Et on se redresse !", "Pense à cligner des yeux "
                                    "et à boire un peu.", "Épaules relâchées, dos droit… et on continue !"]))

    # =========================================================== s'asseoir sur la fenêtre active
    def _perch_loop(self):
        while True:
            time.sleep(0.8)
            if not self.cfg.get("perch") or self.scene:
                continue
            try:
                g = extras.active_window_geometry({os.getpid()})
            except Exception:
                g = None
            try:
                self.bridge.perch.emit(g)
            except RuntimeError:                    # Viki est en train de quitter
                return

    def _on_perch(self, g):
        if (not self.cfg.get("perch") or self.drag or self.walk or self.duo or self.scene or self.fs_hidden
                or time.monotonic() < self.perch_pause):
            return
        scr = (self.app.screenAt(self.geometry().center()) or self.app.primaryScreen()).availableGeometry()
        ok = False
        if g:
            x, y, w, h = g
            ok = (w >= self.cw * 0.9 and y - self.ch * 0.85 >= scr.top() and h > 120
                  and not (x <= scr.left() + 2 and y <= scr.top() + 2 and w >= scr.width() - 4))
        if ok:
            tx = x + w - self.W - 20
            tx = max(x - self.margin, min(tx, scr.right() - self.W))
            self.perch_target = (int(tx), int(y - self.H + 6))
        elif self.perch_target:
            home = self.cfg.get("home_pos") or self.cfg.get("pos")
            self.perch_target = (int(home[0]), int(home[1])) if home else None
            if self.perch_target and abs(self.perch_target[0] - self.x()) + abs(self.perch_target[1] - self.y()) < 3:
                self.perch_target = None

    def set_perch(self, on):
        self.cfg["perch"] = on
        if on:
            self.cfg["home_pos"] = [self.x(), self.y()]
        else:
            home = self.cfg.get("home_pos")
            self.perch_target = (int(home[0]), int(home[1])) if home else None
        save_config(self.cfg)
        self._rebuild_menus()
        if on:
            ok = shutil.which("kdotool") or shutil.which("xdotool")
            self.say("Je vais m'asseoir sur ta fenêtre active !" if ok else
                     "Pour m'asseoir sur tes fenêtres, il me faut « kdotool » (paru -S kdotool).")

    # =========================================================== vie entre amies
    def _friend_dir(self, hx, hy):
        best = None
        for name, (rect, head, t) in list(self.friends.items()):
            if time.monotonic() - t > 30:
                continue
            vx, vy = head.x() - hx, head.y() - hy
            dist = math.hypot(vx, vy)
            if dist > 1 and (best is None or dist < best[0]):
                best = (dist, QPointF(vx / dist * 0.85, max(-0.4, min(0.4, vy / dist * 0.85))))
        return best[1] if best else None

    def _my_geom_msg(self):
        g = self.geometry()
        h = self._head_point()
        return f"{g.x()},{g.y()},{g.width()},{g.height()},{int(g.x() + h.x())},{int(g.y() + h.y())}"

    def _store_friend(self, name, data):
        try:
            x, y, w, h, hx, hy = [int(v) for v in data.split(",")]
        except ValueError:
            return
        self.friends[name] = (QRect(x, y, w, h), QPoint(hx, hy), time.monotonic())

    def _report_to_main(self):
        """(invitée) donne sa position à l'héroïne et reçoit la sienne."""
        msg = self._my_geom_msg()
        if msg == getattr(self, "_last_report", "") and time.monotonic() - getattr(self, "_last_report_t", 0) < 12:
            return
        self._last_report, self._last_report_t = msg, time.monotonic()
        s = QLocalSocket(self)
        s.connectToServer(INSTANCE_BASE)
        if not s.waitForConnected(300):
            s.deleteLater()
            return
        s.write(f"pos:{PROFIL}:{msg}".encode())
        s.flush()
        if s.waitForReadyRead(400):
            rep = bytes(s.readAll()).decode(errors="ignore")
            if rep.startswith("pos:"):
                self._store_friend("main", rep[4:])
        s.disconnectFromServer()
        s.deleteLater()

    def _approach_friend(self, slug):
        """Avant de discuter, elle s'approche de son amie. Renvoie la durée de la marche."""
        fr = self.friends.get(slug)
        if not fr or self.scene or self.perch_target:
            return 0.0
        rect = fr[0]
        my = self.geometry()
        if rect.center().x() >= my.center().x():
            target = rect.x() - int(self.W * 0.78)
        else:
            target = rect.right() - int(self.W * 0.22)
        scr = (self.app.screenAt(my.center()) or self.app.primaryScreen()).availableGeometry()
        target = max(scr.left() - self.margin, min(target, scr.right() - self.W + self.margin))
        dist = abs(target - self.x())
        if dist < 40:
            return 0.0
        dur = max(1.2, dist / 110.0)
        self.walk = {"x0": self.x(), "x1": target, "start": time.monotonic(), "dur": dur}
        return dur

    def _tell_friends_click(self):
        if GUEST:
            s = QLocalSocket()
            s.connectToServer(INSTANCE_BASE)
            if s.waitForConnected(200):
                s.write(f"clic:{PROFIL}".encode())
                s.flush()
                s.waitForBytesWritten(200)
            s.abort()
        else:
            for cdir in self.cfg.get("invites", []):
                self._guest_send(re.sub(r"[^\w\-]", "", Path(cdir).name),
                                 "clic_amie:" + self.char.get("name", "elle"))

    def friend_clicked(self, friend_name):
        now = time.monotonic()
        self.friend_clicks = [c for c in self.friend_clicks if now - c < 120] + [now]
        mine = [c for c in self.my_clicks if now - c < 120]
        if (len(self.friend_clicks) >= 4 and not mine and now - self.jealous_t > 600 and not self.bubble_text
                and not self.sleeping and not self.in_focus()):
            self.jealous_t = now
            self.friend_clicks = []
            self.angry_until = now + 1.5
            self.sad_until = now + 4
            self._spawn("colere", 1, 0.3)
            self.say(random.choice([f"Et moi alors ? Tu ne fais des câlins qu'à {friend_name} !",
                                    f"Hmpf… {friend_name} a de la chance. Moi aussi je veux de l'attention !",
                                    f"Je ne suis pas jalouse de {friend_name}. Bon… peut-être un tout petit peu."]))

    # ---------- adaptation au PC
    def _q(self):
        """Réglages de qualité en vigueur (mode auto : niveau ajusté en direct)."""
        if self.battery_saving():                     # sur batterie : léger, quoi qu'on ait choisi
            return QUALITY[min(1, getattr(self, "qlevel", 1))]
        mode = self.cfg.get("perf", "auto")
        if mode == "auto":
            return QUALITY[getattr(self, "qlevel", 2)]
        return {"fluide": {"fps": (30, 30), "gw": 14, "mesh_dt": 0.05, "anim": True, "breeze": True},
                "ultra": QUALITY[4], "equilibre": QUALITY[2], "econome": QUALITY[1]}.get(mode, QUALITY[2])

    def _adapt(self, now):
        """Toutes les 5 s : baisse la qualité si le rendu est lent ou le PC chargé, la remonte sinon."""
        if self.cfg.get("perf", "auto") != "auto" or now - self._adapt_t < 5:
            return
        self._adapt_t = now
        cores = self.hw[0]
        try:
            load = os.getloadavg()[0] / max(1, cores)
        except Exception:
            load = 0.0
        old = self.qlevel
        if (self.frame_ms > 11 or load > 0.9) and self.qlevel > 0:
            self.qlevel -= 1
            self._good_since = None
        elif self.frame_ms < 4.5 and load < 0.55 and self.qlevel < self.qmax:
            self._good_since = self._good_since or now
            if now - self._good_since > 30:                 # 30 s de calme avant de remonter
                self.qlevel += 1
                self._good_since = None
        else:
            self._good_since = None
        if self.qlevel != old:
            self.cfg["perf_level"] = self.qlevel
            self._build_mesh()
            print(f"Qualité auto : {QUALITY_NAMES[old]} -> {QUALITY_NAMES[self.qlevel]} "
                  f"(rendu {self.frame_ms:.1f} ms, charge {load:.2f})", file=sys.stderr)

    def _fullscreen_watch(self):
        """Fil de fond : un jeu ou une vidéo passe en plein écran ? (X11, sans outil externe)"""
        try:
            xlib = ctypes.CDLL("libX11.so.6")
            xlib.XOpenDisplay.restype = ctypes.c_void_p
            xlib.XOpenDisplay.argtypes = [ctypes.c_char_p]
            xlib.XDefaultRootWindow.argtypes = [ctypes.c_void_p]
            xlib.XDefaultRootWindow.restype = ctypes.c_ulong
            xlib.XInternAtom.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_int]
            xlib.XInternAtom.restype = ctypes.c_ulong
            xlib.XGetWindowProperty.argtypes = [
                ctypes.c_void_p, ctypes.c_ulong, ctypes.c_ulong, ctypes.c_long, ctypes.c_long, ctypes.c_int,
                ctypes.c_ulong, ctypes.POINTER(ctypes.c_ulong), ctypes.POINTER(ctypes.c_int),
                ctypes.POINTER(ctypes.c_ulong), ctypes.POINTER(ctypes.c_ulong),
                ctypes.POINTER(ctypes.POINTER(ctypes.c_ulong))]
            xlib.XFree.argtypes = [ctypes.c_void_p]
            dpy = xlib.XOpenDisplay(None)
            if not dpy:
                return
        except Exception:
            return
        root = xlib.XDefaultRootWindow(dpy)
        a_active = xlib.XInternAtom(dpy, b"_NET_ACTIVE_WINDOW", 0)
        a_state = xlib.XInternAtom(dpy, b"_NET_WM_STATE", 0)
        a_full = xlib.XInternAtom(dpy, b"_NET_WM_STATE_FULLSCREEN", 0)

        def prop(win, atom):
            t, f, n, after = ctypes.c_ulong(), ctypes.c_int(), ctypes.c_ulong(), ctypes.c_ulong()
            data = ctypes.POINTER(ctypes.c_ulong)()
            if xlib.XGetWindowProperty(dpy, win, atom, 0, 64, 0, 0, ctypes.byref(t), ctypes.byref(f),
                                       ctypes.byref(n), ctypes.byref(after), ctypes.byref(data)) != 0:
                return []
            out = [data[i] for i in range(n.value)] if data else []
            if data:
                xlib.XFree(data)
            return out
        while True:
            try:
                full = False
                if self.cfg.get("fullscreen_pause", True):
                    act = prop(root, a_active)
                    if act and act[0]:
                        full = a_full in prop(act[0], a_state)
                if full != self.fs_hidden:
                    self.bridge.fullscreen.emit(full)
            except Exception:
                pass
            time.sleep(2)

    def _fullscreen_watch_win(self):
        """Windows : jeu ou vidéo en plein écran ? (état « ne pas déranger » du système)"""
        import ctypes as _c
        prev = False
        while True:
            time.sleep(2)
            if not self.cfg.get("fullscreen_pause", True):
                continue
            try:
                st = _c.c_int(0)
                _c.windll.shell32.SHQueryUserNotificationState(_c.byref(st))
                full = st.value in (3, 4)         # appli plein écran / jeu Direct3D
            except Exception:
                full = False
            if full != prev:
                prev = full
                self.bridge.fullscreen.emit(full)

    def _on_fullscreen(self, full):
        self.fs_hidden = full
        if fun and (self.overlay or not full):
            self._overlay_tick()                         # neige & co : jamais par-dessus un jeu ou un film
        if full:
            self._stop_audio()
            self.hide()
            if self.input_box:
                self.input_box.hide()
        else:
            self.show()
            QTimer.singleShot(60, self._update_mask)

    # ---------- objets personnalisés
    def objects_lib(self, reload=False):
        if self._objs is None or reload:
            self._objs = {}
            if OBJ_ROOT.exists():
                for d in sorted(OBJ_ROOT.iterdir()):
                    try:
                        o = json.loads((d / "objet.json").read_text())
                        o["_dir"] = str(d)
                        self._objs[d.name] = o
                    except Exception:
                        pass
            self._obj_pix = {}
        return self._objs

    def _place_key(self):
        return self.cfg.get("lieu") or "bureau"

    def placed_here(self):
        lib = self.objects_lib()
        return [pl for pl in self.cfg.get("objets_places", {}).get(self._place_key(), []) if pl["slug"] in lib]

    def _obj_used(self, slug):
        return bool(self.cfg.get("objets_etat", {}).get(slug))

    def _obj_pixmap(self, slug):
        o = self.objects_lib().get(slug)
        if not o:
            return None
        used = self._obj_used(slug) and o.get("image2")
        h = max(12, int(self.ch * float(o.get("taille", 0.3))))
        key = (slug, bool(used), h)
        if key not in self._obj_pix:
            pm = QPixmap(str(Path(o["_dir"]) / (o["image2"] if used else o["image"])))
            self._obj_pix[key] = pm.scaledToHeight(h, Qt.TransformationMode.SmoothTransformation)
        return self._obj_pix[key]

    def _placed_rect(self, pl):
        pm = self._obj_pixmap(pl["slug"])
        if pm is None or not self.scene:
            return None
        x = self.scene.left() + pl["u"] * self.scene.width()
        y = self.scene.top() + pl["v"] * self.scene.height()
        return QRectF(x - pm.width() / 2, y - pm.height(), pm.width(), pm.height())

    def _hand_point(self):
        mains = [z for z in self.zones if z["type"] == "main"]
        if mains:
            cx, cy = zone_center(mains[0])
            return QPointF(self.char_cx - self.cw / 2 + cx * self.scale, BUBBLE_AREA + cy * self.scale)
        return QPointF(self.char_cx + self.cw * 0.3, BUBBLE_AREA + self.ch * 0.58)

    def _held_rect(self):
        slug = self.cfg.get("objet_porte", "")
        pm = self._obj_pixmap(slug) if slug else None
        if pm is None:
            return None
        o = self.objects_lib()[slug]
        hand = self._hand_point()
        if o.get("haut") and self._obj_used(slug):        # tenu dans la main, ouvert au-dessus de la tête
            top = BUBBLE_AREA - 0.14 * self.ch
            h = max(pm.height(), hand.y() - top)
            w = pm.width() * h / max(1, pm.height())
            cx = self.char_cx + (hand.x() - self.char_cx) * 0.45
            return QRectF(cx - w / 2, top, w, h)
        return QRectF(hand.x() - pm.width() / 2, hand.y() - pm.height() * 0.7, pm.width(), pm.height())

    def _draw_objects(self, p, front):
        if not front and self.scene:
            for pl in self.placed_here():
                r = self._placed_rect(pl)
                if r:
                    p.drawPixmap(r.topLeft(), self._obj_pixmap(pl["slug"]))
        if front:
            r = self._held_rect()
            if r:
                p.drawPixmap(r, self._obj_pixmap(self.cfg["objet_porte"]), QRectF())

    def _object_at(self, pos):
        r = self._held_rect()
        if r and r.contains(pos):
            return ("porte", self.cfg["objet_porte"])
        for pl in reversed(self.placed_here()):
            r = self._placed_rect(pl)
            if r and r.contains(pos):
                return ("pose", pl)
        return None

    def add_object(self, path=None):
        self._import_mode = "objet"
        self.new_character(path)

    def _finish_new_object(self, img):
        img = tidy_image(img)
        dlg = ObjectDialog(img, self)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        data = dlg.result_data()
        slug = re.sub(r"[^a-z0-9]+", "-", data["name"].lower()).strip("-") or "objet"
        d = OBJ_ROOT / slug
        n = 2
        while d.exists():
            d = OBJ_ROOT / f"{slug}-{n}"
            n += 1
        d.mkdir(parents=True)
        img.save(str(d / "image.png"))
        data["image"] = "image.png"
        data["image2"] = ""
        if dlg.img2 is not None:
            dlg.img2.save(str(d / "image2.png"))
            data["image2"] = "image2.png"
        (d / "objet.json").write_text(json.dumps(data, indent=2, ensure_ascii=False))
        self.objects_lib(reload=True)
        self.last_obj = d.name
        if self.scene:
            self.place_object(d.name, 0.3 if self.char_cx > self.W / 2 else 0.7, 0.95)
            self.say(f"Oh ! {data['name']} ! C'est pour moi ?")
        else:
            self.cfg["objet_porte"] = d.name
            save_config(self.cfg)
            self.say(f"Oh ! {data['name']} ! Merci !")
        self._rebuild_menus()

    def place_object(self, slug, u=None, v=None):
        places = self.cfg.setdefault("objets_places", {})
        here = places.setdefault(self._place_key(), [])
        here[:] = [pl for pl in here if pl["slug"] != slug]
        if u is None:
            u = (self.char_cx + self.cw * 0.35 - self.scene.left()) / self.scene.width()
        here.append({"slug": slug, "u": round(min(0.97, max(0.03, u)), 3), "v": round(v or 0.95, 3)})
        if self.cfg.get("objet_porte") == slug:
            self.cfg["objet_porte"] = ""
        save_config(self.cfg)
        self._update_mask()

    def remove_object_here(self, slug):
        here = self.cfg.setdefault("objets_places", {}).setdefault(self._place_key(), [])
        here[:] = [pl for pl in here if pl["slug"] != slug]
        if self.cfg.get("objet_porte") == slug:
            self.cfg["objet_porte"] = ""
        save_config(self.cfg)
        self._update_mask()

    def delete_object(self, slug):
        o = self.objects_lib().get(slug)
        if not o or QMessageBox.question(None, "Supprimer", f"Supprimer définitivement « {o['name']} » ?") \
                != QMessageBox.StandardButton.Yes:
            return
        for k in list(self.cfg.get("objets_places", {})):
            self.cfg["objets_places"][k] = [pl for pl in self.cfg["objets_places"][k] if pl["slug"] != slug]
        if self.cfg.get("objet_porte") == slug:
            self.cfg["objet_porte"] = ""
        d = Path(o["_dir"]).resolve()
        if d.parent == OBJ_ROOT.resolve():
            shutil.rmtree(d, ignore_errors=True)
        save_config(self.cfg)
        self.objects_lib(reload=True)
        self._rebuild_menus()

    def _resize_object(self, slug, factor):
        o = self.objects_lib().get(slug)
        if not o:
            return
        o["taille"] = round(min(1.2, max(0.05, float(o.get("taille", 0.3)) * factor)), 3)
        data = {k: v for k, v in o.items() if not k.startswith("_")}
        (Path(o["_dir"]) / "objet.json").write_text(json.dumps(data, indent=2, ensure_ascii=False))
        self._obj_pix = {}
        self._update_mask()

    def _object_menu(self, gpos, slug):
        o = self.objects_lib().get(slug)
        if not o:
            return
        m = QMenu()
        name = o["name"]
        held = self.cfg.get("objet_porte") == slug
        m.addAction(f"— {name} —").setEnabled(False)
        m.addAction("Utiliser" + (" (refermer / éteindre)" if self._obj_used(slug) else ""),
                    lambda: self.queue([("utiliser", slug)]))
        if not held:
            m.addAction("Prendre", lambda: self.queue([("prendre", slug)]))
        elif self.scene:
            m.addAction("Poser ici", lambda: self.queue([("poser", slug)]))
        m.addAction("Agrandir", lambda: self._resize_object(slug, 1.15))
        m.addAction("Réduire", lambda: self._resize_object(slug, 1 / 1.15))
        m.addAction("Ranger (retirer du décor)", lambda: self.queue([("ranger", slug)]))
        self.popup_menu(m, gpos, block=True)

    # ---------- ordres : file d'actions
    def queue(self, actions, reply=None):
        """actions : liste de (action, cible). Exécutées une par une."""
        self.actions.extend(actions)
        if reply:
            self.say(reply)

    def _obj_phrase(self, slug, kind, default):
        o = self.objects_lib().get(slug, {})
        lines = o.get("phrases_" + kind) or default
        return random.choice(lines)

    def _run_actions(self, now):
        if not self.actions or self.walk or self.drag:
            return
        act, target = self.actions.pop(0)
        lib = self.objects_lib()
        if act == "lieu":
            self.set_lieu(target)
            return
        if act == "dire":
            self.say(target)
            return
        builtin = target not in lib
        if builtin:                                        # objet d'un décor
            if not self.scene or target not in [n for n, _ in self.lieu_obj.objects()]:
                self.say("Je ne vois pas ça ici…")
                self.actions.clear()
                return
            if act in ("prendre", "poser", "ranger"):
                self.say("Ça, je ne peux pas le prendre, mais je peux m'en servir !")
                act = "utiliser"
            c = self.lieu_obj.object_center(target, now - self.t0)
            tx = self.scene.left() + c[0] * self.scene.width()
            lo, hi = self.cw * 0.5 + 6, self.W - self.cw * 0.5 - 6
            tx = min(max(tx, lo), hi)
            self.walk = {"x0": self.char_cx, "x1": tx, "start": now,
                         "dur": max(0.4, abs(tx - self.char_cx) / 90.0), "inner": True, "then": target}
            return
        self.last_obj = target
        held = self.cfg.get("objet_porte") == target
        placed = next((pl for pl in self.placed_here() if pl["slug"] == target), None)
        if act in ("prendre", "utiliser", "aller") and not held and placed and self.scene:
            tx = self.scene.left() + placed["u"] * self.scene.width() - self.cw * 0.3
            lo, hi = self.cw * 0.5 + 6, self.W - self.cw * 0.5 - 6
            tx = min(max(tx, lo), hi)
            if abs(tx - self.char_cx) > 8:                  # d'abord, elle y va
                self.actions.insert(0, (act, target))
                self.walk = {"x0": self.char_cx, "x1": tx, "start": now,
                             "dur": max(0.4, abs(tx - self.char_cx) / 90.0), "inner": True}
                return
        name = lib[target]["name"]
        if act == "prendre":
            if held:
                self.say(f"Je l'ai déjà dans les mains !")
                return
            if placed:
                self.remove_object_here(target)
            self.cfg["objet_porte"] = target
            save_config(self.cfg)
            self.hop_start = now
            self.say(self._obj_phrase(target, "prendre", ["Je le prends !"]))
        elif act == "utiliser":
            if not held and not placed:                     # rangé : elle va le chercher
                self.cfg["objet_porte"] = target
            etat = self.cfg.setdefault("objets_etat", {})
            etat[target] = not etat.get(target, False)
            save_config(self.cfg)
            self._obj_pix = {k: v for k, v in self._obj_pix.items() if k[0] != target}
            eff = lib[target].get("effet", "etoile")
            self.happy_until = now + 1.5
            if eff and eff != "aucun":
                r = self._held_rect() or (self._placed_rect(placed) if placed else None)
                c = r.center() if r else self._head_point()
                self._spawn_at(eff, c.x(), c.y(), 4, fall=eff in ("goutte", "feuille", "flocon"))
            self.say(self._obj_phrase(target, "utiliser", ["Et voilà !"]))
        elif act == "poser":
            if self.scene:
                self.place_object(target)
                self.say("Je le pose là.")
            else:
                self.remove_object_here(target)
                self.say("Je le range, il n'y a pas de place sur ton bureau !")
        elif act == "ranger":
            self.remove_object_here(target)
            self.say(f"J'ai rangé : {name}.")
        elif act == "aller":
            self.happy_until = now + 1
        self._update_mask()

    def _find_objects(self, t):
        """Objets cités dans le texte -> [(position, cible)]."""
        found = []
        for slug, o in self.objects_lib().items():
            for word in {o["name"].lower(), slug.replace("-", " ")}:
                for m in re.finditer(r"\b" + re.escape(word) + r"s?\b", t):
                    found.append((m.start(), slug))
        if self.scene:
            here = {n for n, _ in self.lieu_obj.objects()}
            for word, b in BUILTIN_NOMS.items():
                if b in here:
                    for m in re.finditer(r"\b" + re.escape(word) + r"\b", t):
                        found.append((m.start(), b))
        for m in re.finditer(r"\b(cet objet|ce truc|[çc]a|celui-ci|celle-ci)\b", t):
            if self.last_obj:
                found.append((m.start(), self.last_obj))
        return sorted(set(found))

    def parse_order(self, text):
        t = " " + text.lower().replace("’", "'") + " "
        objs = self._find_objects(t)
        verbs = []
        for act, pat in VERBES:
            for m in re.finditer(pat, t):
                verbs.append((m.start(), act, m.end()))
        verbs.sort()
        if not verbs or (not objs and not self.last_obj and not self.cfg.get("objet_porte")):
            return []
        actions, last = [], None
        for pos, act, end in verbs:
            after = [o for p2, o in objs if p2 >= end and (not verbs or all(
                not (end <= v[0] < p2) for v in verbs if v[0] != pos))]
            target = after[0] if after else (last or self.cfg.get("objet_porte") or self.last_obj)
            if not target:
                continue
            if actions and actions[-1] == (act, target):
                continue
            actions.append((act, target))
            last = target
        return actions

    def _plan_with_ai(self, text):
        lib = self.objects_lib()
        here = [n for n, _ in self.lieu_obj.objects()] if self.scene else []
        objets = []
        for slug, o in lib.items():
            where = ("dans tes mains" if self.cfg.get("objet_porte") == slug else
                     "ici" if any(pl["slug"] == slug for pl in self.placed_here()) else "rangé")
            objets.append(f"{o['name']} (id {slug}, {where}, {'utilisé' if self._obj_used(slug) else 'normal'})")
        objets += [f"{n} (id {n}, élément du décor)" for n in here]
        prompt = (
            "Tu pilotes les gestes d'un personnage de bureau. Transforme la demande de l'utilisateur en "
            "actions. Actions possibles : aller, prendre, utiliser (ouvrir/allumer/fermer/se servir), "
            "poser, ranger, lieu (cible : " + ", ".join(lieux.LIEUX) + "). "
            f"Objets disponibles : {'; '.join(objets) or 'aucun'}. "
            f"Dernier objet dont on a parlé : {self.last_obj or 'aucun'}. "
            "Réponds UNIQUEMENT en JSON : {\"actions\": [{\"action\": \"...\", \"cible\": \"id\"}], "
            "\"reponse\": \"phrase courte et naturelle en français\"}. "
            "Si la demande n'est pas une action, renvoie une liste d'actions vide.\n\n"
            f"Demande : {text}")
        try:
            plan = self.llm_json([{"role": "user", "content": prompt}])
            plan.setdefault("actions", [])
        except Exception as e:
            print("Ordre (IA) :", e, file=sys.stderr)
            plan = {"actions": []}
        plan["_texte"] = text
        self.bridge.plan_ready.emit(plan)

    def _on_plan(self, plan):
        lib = self.objects_lib()
        valid = set(lib) | ({n for n, _ in self.lieu_obj.objects()} if self.scene else set())
        acts = []
        for a in plan.get("actions", []) or []:
            act, cible = str(a.get("action", "")).lower(), str(a.get("cible", "")).lower()
            if act == "lieu" and lieux and cible in lieux.LIEUX:
                acts.append(("lieu", cible))
                continue
            if cible not in valid:                       # nom au lieu de l'id ?
                cible = next((s2 for s2, o in lib.items() if o["name"].lower() == cible), cible)
                cible = BUILTIN_NOMS.get(cible, cible)
            if act in ("aller", "prendre", "utiliser", "poser", "ranger") and cible in valid:
                acts.append((act, cible))
        if acts:
            self.queue(acts, plan.get("reponse") or "D'accord !")
        else:                                           # ce n'était pas un ordre : on discute
            self.send_chat(plan["_texte"])

    # ---------- lieux
    def _on_character(self, pos):
        ix = int((pos.x() - (self.char_cx - self.cw / 2)) / self.scale)
        iy = int((pos.y() - BUBBLE_AREA) / self.scale)
        if not hasattr(self, "_src_img"):
            self._src_img = self.src.toImage()
        img = self._src_img
        return 0 <= ix < img.width() and 0 <= iy < img.height() and img.pixelColor(ix, iy).alpha() > 40

    def _scene_object_at(self, pos):
        if not self.scene:
            return None
        u = (pos.x() - self.scene.left()) / self.scene.width()
        v = (pos.y() - self.scene.top()) / self.scene.height()
        return self.lieu_obj.object_at(u, v, time.monotonic() - self.t0)

    def _meteo(self):
        w = getattr(self, "weather", "soleil")
        if w != "soleil":
            return {"nuages": "un peu gris", "pluie": "pluie dehors", "orage": "un orage dehors",
                    "neige": "de la neige dehors", "brouillard": "du brouillard"}.get(w, "gris")
        per = lieux.period(datetime.datetime.now().hour) if lieux else "jour"
        return {"jour": "beau dehors", "soir": "presque nuit", "nuit": "nuit noire"}[per]

    def _auto_weather(self):
        """Météo simulée selon la saison ; elle change toutes les 3 heures environ."""
        now = datetime.datetime.now()
        rnd = random.Random(f"{now.date()}-{now.hour // 3}")
        season = self._season()
        table = {"hiver": [("soleil", 30), ("nuages", 30), ("neige", 25), ("pluie", 10), ("brouillard", 5)],
                 "ete": [("soleil", 62), ("nuages", 18), ("orage", 10), ("pluie", 10)],
                 "mi": [("soleil", 35), ("nuages", 30), ("pluie", 22), ("brouillard", 8), ("orage", 5)]}[season]
        return rnd.choices([w for w, _ in table], [p for _, p in table])[0]

    def _real_weather(self):
        """Seul accès internet, uniquement si tu l'actives : Open-Meteo (gratuit, sans compte)."""
        ville = self.cfg.get("meteo_ville", "").strip()
        if not ville:
            return None
        try:
            from urllib.parse import quote
            if self.cfg.get("meteo_lat") is not None and self.cfg.get("meteo_lon") is not None:
                res = {"latitude": self.cfg["meteo_lat"], "longitude": self.cfg["meteo_lon"]}   # ville choisie
            else:
                with urllib.request.urlopen("https://geocoding-api.open-meteo.com/v1/search?count=1&language=fr&"
                                            "name=" + quote(ville), timeout=8) as r:
                    res = json.load(r)["results"][0]
            url = (f"https://api.open-meteo.com/v1/forecast?latitude={res['latitude']}"
                   f"&longitude={res['longitude']}&current=weather_code,temperature_2m")
            with urllib.request.urlopen(url, timeout=8) as r:
                cur = json.load(r)["current"]
            code = int(cur["weather_code"])
            self.temperature = cur.get("temperature_2m")
            if code in (0, 1):
                return "soleil"
            if code in (2, 3):
                return "nuages"
            if code in (45, 48):
                return "brouillard"
            if code in (71, 73, 75, 77, 85, 86):
                return "neige"
            if code >= 95:
                return "orage"
            return "pluie"
        except Exception as e:
            print("Météo réelle indisponible :", e, file=sys.stderr)
            return None

    def _update_weather(self, announce=True):
        mode = self.cfg.get("meteo", "auto")
        if mode == "reelle":
            if time.monotonic() - getattr(self, "_weather_t", -9999) < 1800 and getattr(self, "_real_w", None):
                w = self._real_w
            else:
                self._weather_t = time.monotonic()
                threading.Thread(target=lambda: setattr(self, "_real_w", self._real_weather()),
                                 daemon=True).start()
                w = getattr(self, "_real_w", None) or self._auto_weather()
        elif mode in (lieux.METEOS if lieux else {}):
            w = mode
        else:
            w = self._auto_weather()
        old = getattr(self, "weather", None)
        self.weather = w
        if self.lieu_obj:
            self.lieu_obj.weather = w
        if old is not None and old != w:
            self._auto_outfit()
            if announce and self.scene and self.cfg.get("chatty") and not self.bubble_text and not self.sleeping:
                self.say_from("meteo_" + w if w != "nuages" else "meteo_soleil")

    def choisir_ville(self):
        """📍 Fenêtre claire pour choisir sa ville (suggestions) ; active la météo réelle."""
        return self.set_weather("reelle")

    def set_weather(self, mode):
        if mode == "reelle":
            try:
                import ville as _ville
                v = _ville.choisir(None, self.cfg)
            except Exception:
                log_error("choix de la ville")
                v = None
            if not v:
                return
            self.cfg.update(meteo_ville=v["nom"], meteo_lieu=v["label"], meteo_lat=v["lat"], meteo_lon=v["lon"])
            self._weather_t = -9999
            self._real_w = None
        self.cfg["meteo"] = mode
        save_config(self.cfg)
        self._update_weather()
        self._rebuild_menus()

    def _use_object(self, name, by_her=False):
        now = time.monotonic()
        fx = self.lieu_obj.interact(name, lieux.period(datetime.datetime.now().hour))
        self.last_interaction = now
        if not by_her:
            self._mood(+2)
        self.happy_until = now + fx.get("happy", 1.0)
        if fx.get("blush"):
            self.blush_until = now + fx["blush"]
        if fx.get("react"):
            self.react = (fx["react"], now)
        if fx.get("yawn"):
            self.yawn_start = now
        if fx.get("outfit"):
            QTimer.singleShot(600, self.next_outfit)
            fx["say"] = "obj_armoire"
        if fx.get("slide") and self.scene:                  # luge : elle traverse le décor
            lo, hi = self.cw * 0.5 + 6, self.W - self.cw * 0.5 - 6
            tx = lo if self.char_cx > self.W / 2 else hi
            self.walk = {"x0": self.char_cx, "x1": tx, "start": now, "dur": 1.1, "inner": True}
        for kind, u, v, n in fx.get("parts", []):
            x = self.scene.left() + u * self.scene.width()
            y = self.scene.top() + v * self.scene.height()
            self._spawn_at(kind, x, y, n, fall=kind in ("feuille", "goutte", "flocon"))
        if not by_her or random.random() < 0.5:        # toujours une réponse quand c'est toi qui cliques
            self.say_from(fx["say"])

    def _visit_object(self, now):
        """Elle va d'elle-même vers un objet du décor et l'utilise."""
        names = [n for n, _ in self.lieu_obj.objects()]
        name = random.choice(names)
        c = self.lieu_obj.object_center(name, now - self.t0)
        if not c:
            return
        tx = self.scene.left() + c[0] * self.scene.width()
        lo, hi = self.cw * 0.5 + 6, self.W - self.cw * 0.5 - 6
        tx = min(max(tx + random.uniform(-20, 20), lo), hi)
        dist = abs(tx - self.char_cx)
        self.walk = {"x0": self.char_cx, "x1": tx, "start": now, "dur": max(0.8, dist / 70.0),
                     "inner": True, "then": name}

    def set_lieu(self, kind):
        self.cfg["lieu"] = kind
        save_config(self.cfg)
        self.walk = None
        anchor = QPoint(self.geometry().center().x(), self.geometry().bottom())
        self._old_W = None
        self._apply_scale(self.scale, keep_anchor=False)
        self.move(anchor.x() - self.W // 2, anchor.y() - self.H + 1)
        self._clamp_on_screen()
        self._rebuild_menus()
        self.next_walk = time.monotonic() + random.uniform(8, 20)
        if self.lieu_obj:
            self.lieu_obj.weather = self.weather or "soleil"
        self._auto_outfit()
        if kind:
            self.react = ("salut", time.monotonic())
            self.say_from("lieu_" + kind)
        else:
            self.say("Retour sur ton bureau !")

    def _auto_lieu(self):
        if not self.cfg.get("lieu_auto") or not lieux:
            return
        h = datetime.datetime.now().hour
        season = self._season()
        dehors = ("neige" if season == "hiver" else
                  ("plage" if datetime.date.today().day % 2 else "piscine") if season == "ete" else "parc")
        if getattr(self, "weather", "") in ("pluie", "orage") and dehors != "neige":
            dehors = "cafe"
        want = ("chambre" if h < 8 or h >= 22 else "cafe" if h < 10 else "maison" if h < 12
                else "cafe" if h < 14 else dehors if h < 18 else "maison")
        if want != self.cfg.get("lieu"):
            self.set_lieu(want)

    def _track_rub(self, pos):
        """Frotter la tête avec la souris (sans cliquer) = caresse."""
        z = self._zone_at(pos)
        now = time.monotonic()
        if not z or z["type"] not in ("tete", "cheveux") or self.sleeping:
            return
        self.rub = [r for r in self.rub if now - r[0] < 1.3] + [(now, pos.x())]
        turns = 0
        for i in range(2, len(self.rub)):
            a = self.rub[i - 1][1] - self.rub[i - 2][1]
            b = self.rub[i][1] - self.rub[i - 1][1]
            if a * b < 0 and abs(b) > 1:
                turns += 1
        if turns >= 4 and now - self.last_pet > 2.5:
            self.last_pet = now
            self.cfg["stats"]["caresses"] = self.cfg["stats"].get("caresses", 0) + 1
            self.rub = []
            self.react = ("caresse", now)
            self._mood(+6)
            self.happy_until = now + 2.2
            self.blush_until = now + 3.5
            self._spawn("coeur", 3)
            if random.random() < 0.6:
                self.say_from("caresse")
            self.last_interaction = now

    def _idle_anim(self, now, kind=None):
        self.next_idle_anim = now + random.uniform(35, 110)
        if kind is None:
            night = datetime.datetime.now().hour >= 22 or datetime.datetime.now().hour < 6
            choices = ["etirement", "regarde", "fredonne", "clin", "sourire", "baille"]
            weights = [2, 3, 2, 2, 2, 4 if night else 1]
            kind = random.choices(choices, weights)[0]
        talk = random.random() < 0.25
        if kind == "clin":
            self.wink_eye, self.wink_until = random.randint(0, 1), now + 0.5
            self._spawn("etoile", 1, 0.4)
        elif kind == "sourire":
            self.happy_until = now + 1.3
        elif kind == "baille":
            self.yawn_start = now
            if talk:
                QTimer.singleShot(2400, lambda: self.say_from("baille"))
        else:
            self.react = (kind, now)
            if kind == "fredonne":
                self.happy_until = now + 2.4
                self._spawn("note", 3)
                if talk:
                    self.say_from("fredonne")
            elif kind == "etirement":
                self.happy_until = now + 1.8
                if talk:
                    QTimer.singleShot(1800, lambda: self.say_from("etirement"))

    def _mood(self, delta):
        self.cfg["mood"] = max(0, min(100, self.cfg.get("mood", 70) + delta))

    def _react(self, kind):
        now = time.monotonic()
        self.cfg["stats"]["clics"] = self.cfg["stats"].get("clics", 0) + 1
        if extras:
            self.my_clicks = [c for c in self.my_clicks if now - c < 120] + [now]
            if now - self._xp_t > 8:
                self._xp_t = now
                self.add_xp(1)
            self._tell_friends_click()
        self._mood(+5 if kind in ("tete", "joue") else +2)
        if getattr(self, "l2d", None) and not getattr(self, "_area_tapped", False):
            self.l2d[0].tap()
        if self.cfg["mood"] < 30 and random.random() < 0.5 and kind is not None:
            self.react = ("regarde", now)
            self.sad_until = now + 2
            QTimer.singleShot(200, lambda: self.say_from("boude"))
            return
        if kind is None:
            self.hop_start = now
            QTimer.singleShot(250, lambda: self.say_from("clic"))
            return
        self.react = (kind, now)
        if kind == "tete":
            self.happy_until = now + 1.8
            self.blush_until = now + 3.0
            self._spawn("coeur", 4 if self.level() >= 4 else 2)
        elif kind == "cheveux":
            self.happy_until = now + 1.2
            self.blush_until = now + 1.5
        elif kind == "epaule":
            self.surprise_until = now + 0.9
            self._spawn("exclam", 1, 0.3)
        elif kind == "pieds":
            self.happy_until = now + 1.6
            self._spawn("note", 3)
        elif kind == "joue":
            self.blush_until = now + 4.0
            self.wink_eye, self.wink_until = random.randint(0, 1), now + 0.7
            self._spawn("coeur", 1, 0.5)
        elif kind == "nez":
            self.happy_until = now + 0.9
            self._spawn("etoile", 2, 0.4)
        elif kind == "bras":
            self.surprise_until = now + 0.5
            self._spawn("goutte", 1, 0.3)
        elif kind == "accessoire":
            self.happy_until = now + 1.5
            self._spawn("etoile", 3)
        self.big_motion = True
        self._update_mask()
        QTimer.singleShot(200, lambda: self.say_from("zone_" + kind))

    def _wake_up(self):
        self.sleeping = False
        now = time.monotonic()
        self.surprise_until = now + 0.9
        self.react = ("epaule", now)
        self._spawn("exclam", 1, 0.3)
        self.last_interaction = now
        QTimer.singleShot(300, lambda: self.say_from("reveil"))

    def _play_anim(self, key):
        now = time.monotonic()
        self.sleeping = False
        if key in ("clin", "baille", "fredonne", "etirement", "regarde"):
            self._idle_anim(now, key)
        elif key == "salut":
            self.react = ("salut", now)
            self.happy_until = now + 1.2
        else:
            self._react(key)

    def nap(self):
        self.bubble_text = ""
        self._stop_audio()
        self.sleeping = True
        self._update_mask()

    # ---------- phrases spontanées
    def _idle_check(self):
        mono = time.monotonic()
        was = getattr(self, "_was_muted", False)
        now_m = self.is_muted()
        if was and not now_m:                       # fin du muet temporaire : menus et barre à jour
            self._rebuild_menus()
        self._was_muted = now_m
        # l'humeur baisse doucement si on l'ignore longtemps
        if mono - self.last_interaction > 30 * 60:
            self._mood(-1 if self.cfg.get("mood", 70) > 15 else 0)
        save_config(self.cfg)
        self._check_battery()
        self._check_pomodoro()
        self._check_reminders()
        self._auto_lieu()
        self._update_weather()
        self._auto_outfit()
        self._theme_tick()
        self._fond_tick()
        self._night_tick()
        self._week_digest_tick()
        try:
            self._follow_tick()
        except Exception:
            log_error("suivis")
        threading.Thread(target=self._natural_watchdog_bg, daemon=True).start()
        if extras and not GUEST:
            for chk in (self._check_agenda, self._check_pc, self._update_fete, self._check_journal):
                try:
                    chk()
                except Exception:
                    log_error(chk.__name__)
        # s'endort plus vite tard le soir
        hour = datetime.datetime.now().hour
        if (self.cfg.get("sleepy") and not self.sleeping and (hour >= 23 or hour < 6)
                and mono - self.last_interaction > 5 * 60 and not self.bubble_text):
            self.sleeping = True
        if extras and not GUEST:
            self._check_focus()
            self._check_shutdown()
        if not GUEST:
            self._check_messages()
        if not self.cfg["chatty"] or self.bubble_text or self.sleeping:
            return
        if self.is_muted() and self.cfg.get("mute_bubbles"):
            return
        if self.in_focus():
            return
        now = datetime.datetime.now()
        today = now.date().isoformat()
        for key, (h1, m1) in (("matin_cafe", (8, 30)), ("midi_faim", (12, 30)), ("nuit_dodo", (22, 45))):
            t1 = now.replace(hour=h1, minute=m1, second=0)
            if 0 <= (now - t1).total_seconds() < 20 * 60 and self.routine_done.get(key) != today:
                self.routine_done[key] = today
                self.say_from(key)
                return
        if getattr(self, "brain", None) and self._brain_tick(now):
            return
        if self._brain_quiet():
            return
        if quotidien and not GUEST and self._quotidien_tick(now, mono):
            return
        mood = self.cfg.get("mood", 70)
        if mood < 30 and random.random() < 0.08:
            self.sad_until = mono + 4
            self.say_from("boude")
            return
        if mood > 85 and random.random() < 0.05:
            self.say_from("content")
            return
        if (extras and not GUEST and self.cfg.get("invites") and not self.duo and random.random() < 0.035
                and not self.in_focus()
                and mono - self.last_interaction < 40 * 60):
            self.start_duo()
            return
        if now.minute == 0 and now.hour != self.last_hour_said:
            self.last_hour_said = now.hour
            self.say_from("heure")
        elif time.monotonic() > self.next_idle and not (getattr(self, "brain", None) and (
                (self.cfg.get("contexte_activite", True) and self.brain.busy_coding()
                 and mono - self.last_interaction > 120) or not self.brain.spont_ok("spont"))):
            if getattr(self, "brain", None):
                self.brain.spont_said("spont")
            f = max(2, int(self.cfg.get("freq_phrases", 18)))          # minutes en moyenne
            L = getattr(self, "learn", None)
            if L:                         # elle a appris si ses phrases te plaisent, et tes horaires
                f = f / L.freq_factor() * (1.0 if L.is_usual_hour(now.hour) else 1.6)
            self.next_idle = time.monotonic() + random.uniform(0.6 * f, 1.4 * f) * 60
            lvl = self.level()
            pools = [ph for k, v in (extras.PHRASES_NIVEAU.items() if extras else []) if lvl >= k for ph in v]
            perso = [p for p in self.cfg.get("phrases_perso", []) if p.strip()] + \
                list(getattr(self, "_mod_repliques", []))
            cats = [c_ for c_, ok in (("perso", bool(perso)), ("complicite", bool(pools)), ("spontanees", True))
                    if ok and (not L or L.allows(c_))] or ["spontanees"]
            weights = {"perso": 0.5, "complicite": 0.2, "spontanees": 0.3}
            cat = random.choices(cats, [weights[c_] for c_ in cats])[0]
            if L:
                L.note_spont(cat)
            if cat == "perso":
                self.say(random.choice(perso).replace("{prenom}", self.cfg.get("prenom", "") or "toi"))
            elif cat == "complicite":
                self.say(random.choice(pools))
            else:
                self.say_from("spontanees")

