def open_link(url):
    try:
        if IS_WIN:
            os.startfile(url)
        else:
            subprocess.Popen(["xdg-open", url], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                             start_new_session=True)
    except Exception:
        from PyQt6.QtGui import QDesktopServices
        from PyQt6.QtCore import QUrl
        QDesktopServices.openUrl(QUrl(url))


CLI_CMDS = ("say", "dis", "emote", "run", "fini", "jouer", "play", "aide", "help")


def cli(args):
    """viki say "texte" | viki emote 🎉 | viki run <commande> | viki jouer — depuis un terminal ou un script."""
    from PyQt6.QtCore import QCoreApplication
    cmd = args[0].lstrip("-")
    rest = args[1:]
    if cmd in ("aide", "help"):
        print("viki say \"texte\"     : elle le dit\n"
              "viki emote 🎉         : elle réagit avec cette émote\n"
              "viki run <commande>   : lance la commande ici ; Viki te prévient à la fin (et t'aide si ça échoue)\n"
              "viki jouer            : ouvre le menu des jeux (pratique pour un raccourci clavier)")
        return 0
    payload, code = b"", 0
    if cmd in ("say", "dis"):
        payload = ("say:" + " ".join(rest)).encode()
    elif cmd == "emote":
        payload = ("emote:" + (rest[0] if rest else "😊")).encode()
    elif cmd in ("jouer", "play"):
        payload = b"jouer"
    elif cmd == "fini":                      # envoyé par le suivi automatique du terminal (dev.py)
        if len(rest) < 3:
            return 2
        payload = f"run:{rest[0]}|{rest[1]}|{' '.join(rest[2:])}\n".encode("utf-8", "replace")
    elif cmd == "run":
        if not rest:
            print("Usage : viki run <commande>   (exemple : viki run make)")
            return 2
        import collections
        shell = len(rest) == 1 and " " in rest[0]
        import shlex
        shown = rest[0] if shell else shlex.join(rest)
        t0 = time.time()
        tail = collections.deque(maxlen=80)
        try:
            p = subprocess.Popen(rest[0] if shell else rest, shell=shell, stdout=subprocess.PIPE,
                                 stderr=subprocess.STDOUT)
            for line in iter(p.stdout.readline, b""):
                sys.stdout.buffer.write(line)
                sys.stdout.buffer.flush()
                tail.append(line.decode("utf-8", "replace"))
            code = p.wait()
        except KeyboardInterrupt:
            code = 130
        except FileNotFoundError:
            print(f"viki : commande introuvable : {rest[0]}", file=sys.stderr)
            tail.append(f"commande introuvable : {rest[0]}")
            code = 127
        dur = time.time() - t0
        payload = f"run:{code}|{dur:.1f}|{shown}\n{''.join(tail)[-6000:]}".encode("utf-8", "replace")
    else:
        return 2
    app = QCoreApplication.instance() or QCoreApplication(sys.argv[:1])
    sock = QLocalSocket()
    sock.connectToServer(INSTANCE_BASE)
    if sock.waitForConnected(800):
        sock.write(payload)
        sock.flush()
        sock.waitForBytesWritten(1500)
        sock.disconnectFromServer()
    elif cmd != "run":
        print("Viki n'est pas lancée.", file=sys.stderr)
        return 1
    return code


EMOJI_FAMILIES = ("Noto Color Emoji", "Twemoji", "Twitter Color Emoji", "JoyPixels", "EmojiOne Color", "Apple Color Emoji",
                  "Segoe UI Emoji", "OpenMoji Color", "Blobmoji", "Emoji One")


def _emoji_systeme_ok():
    """On dessine quelques emoji avec les polices du système : s'ils sortent en couleur, tout va bien.
    Sinon (pas de police d'emoji, ou une police que Qt n'affiche pas, comme sur Bazzite / Fedora récent),
    on prendra la nôtre."""
    try:
        from PyQt6.QtGui import QImage, QPainter, QFont, QColor
        img = QImage(160, 40, QImage.Format.Format_ARGB32)
        img.fill(QColor(255, 255, 255))
        p = QPainter(img)
        f = QFont()
        f.setPixelSize(28)
        p.setFont(f)
        p.setPen(QColor(0, 0, 0))
        p.drawText(4, 32, "\U0001F525\U0001F4A7\U0001F534")          # 🔥 💧 🔴 : rouge, bleu, rouge
        p.end()
        n = 0
        for y in range(0, 40, 2):
            for x in range(0, 160, 2):
                c = img.pixelColor(x, y)
                if max(c.red(), c.green(), c.blue()) - min(c.red(), c.green(), c.blue()) > 60:
                    n += 1
        return n > 30
    except Exception:
        return False


def _load_emoji_font(app):
    """Les icônes des menus et des tuiles sont des emoji. Certains systèmes n'ont pas de police d'emoji, et d'autres
    (Fedora 41+, Bazzite…) en ont une au format « COLRv1 » que Qt n'affiche pas : les icônes devenaient des blancs.
    On fournit donc toujours la nôtre (Noto Color Emoji, licence OFL, renommée « Viki Emoji ») et on la déclare
    comme police d'emoji de l'appli : mêmes icônes partout. La police du texte, elle, ne change pas."""
    try:
        from PyQt6.QtGui import QFontDatabase
        f = APP_DIR / "assets" / "polices" / "VikiEmoji.ttf"
        if not f.exists():
            return ""
        if os.environ.get("VIKI_EMOJI") != "1" and _emoji_systeme_ok():
            return ""                                   # le système les affiche bien (CachyOS, Arch, Ubuntu…) : on n'y touche pas
        fid = QFontDatabase.addApplicationFont(str(f))
        fams = QFontDatabase.applicationFontFamilies(fid) if fid >= 0 else []
        if not fams:
            return ""
        try:
            import menu_style as _ms
            _ms.secours = True                          # et des pictogrammes nets dans les menus
        except Exception:
            pass
        if hasattr(QFontDatabase, "addApplicationEmojiFontFamily"):        # Qt 6.9 et plus (celui de l'AppImage)
            QFontDatabase.addApplicationEmojiFontFamily(fams[0])
        for fam in ("Inter", "Sans Serif", "sans-serif", app.font().family()):
            QFont.insertSubstitution(fam, fams[0])                         # Qt plus ancien : en secours
        return fams[0]
    except Exception as e:
        print("Police d'emoji :", e, file=sys.stderr)
        return ""

def _load_ui_font(app):
    """Même police partout (KDE, GNOME, Xfce…) : Inter, fournie avec Viki (licence OFL). Les langues qu'elle
    ne couvre pas (chinois, japonais, hindi…) passent automatiquement par les polices du système.
    Réglages → Apparence → « Police du système » pour garder celle du bureau."""
    try:
        if json.loads(CONFIG_FILE.read_text()).get("police", "viki") == "systeme":
            return ""
    except Exception:
        pass
    try:
        from PyQt6.QtGui import QFontDatabase
        fam = ""
        for w in ("Regular", "Medium", "SemiBold", "Bold"):
            f = APP_DIR / "assets" / "polices" / f"Inter-{w}.ttf"
            if f.exists():
                fid = QFontDatabase.addApplicationFont(str(f))
                fams = QFontDatabase.applicationFontFamilies(fid) if fid >= 0 else []
                fam = fam or (fams[0] if fams else "")
        if not fam:
            return ""
        base = app.font()
        pt = base.pointSizeF() if base.pointSizeF() > 0 else 10.0
        f = QFont(fam)
        f.setPointSizeF(max(10.0, min(pt, 11.0)))          # ni minuscule (zoom 100 %) ni énorme
        f.setHintingPreference(QFont.HintingPreference.PreferNoHinting)
        app.setFont(f)
        return fam
    except Exception as e:
        print("Police Inter :", e, file=sys.stderr)
        return ""


def main():
    if len(sys.argv) > 1 and sys.argv[1].lstrip("-") in CLI_CMDS:
        sys.exit(cli(sys.argv[1:]))
    if "--diagnostic" in sys.argv:
        return diagnostic()
    if "--ecoute" in sys.argv:                 # .exe Windows : l'oreille, lancée à part
        import runpy
        sys.argv = [str(APP_DIR / "ecoute.py")]
        runpy.run_path(str(APP_DIR / "ecoute.py"), run_name="__main__")
        return
    _install_safety_net()
    _etape("6 lancement de l'interface")
    app = QApplication(sys.argv)
    _etape("7 interface ok")
    _load_emoji_font(app)
    _load_ui_font(app)
    app.setApplicationName("viki")
    app.setDesktopFileName("viki")
    app.setQuitOnLastWindowClosed(False)
    # déjà lancée ? on lui transmet la demande (ex. « --ecrire » depuis un raccourci clavier)
    sock = QLocalSocket()
    sock.connectToServer(INSTANCE_NAME)
    if sock.waitForConnected(300):
        sock.write(b"parler" if "--parler" in sys.argv else b"ecrire" if "--ecrire" in sys.argv
                   else b"traduire" if "--traduire" in sys.argv else b"lire" if "--lire" in sys.argv
                   else b"ecran" if "--ecran" in sys.argv else b"zone" if "--zone" in sys.argv
                   else b"salon" if "--salon" in sys.argv else b"montrer")
        sock.flush()
        sock.waitForBytesWritten(300)
        return
    QLocalServer.removeServer(INSTANCE_NAME)
    w = Companion(app)
    _install_safety_net.companion = w
    QTimer.singleShot(8000, w._refresh_autostart)
    QTimer.singleShot(1500, w.start_ronds)
    QTimer.singleShot(12000, w.check_brain)
    _maj_t = QTimer(w)
    _maj_t.timeout.connect(w._update_tick)
    _maj_t.start(3600_000)
    QTimer.singleShot(45_000, w._update_tick)
    if not w.first_run:
        QTimer.singleShot(30_000, w.ask_update_consent)
    if curseur:
        def _curseur_go():
            curseur.start()
            if curseur.etat != "x11":
                QTimer.singleShot(15000, lambda: log_note(
                    f"suivi de la souris : {curseur.etat} — {curseur.raison} — "
                    f"position reçue de KWin : {'oui' if curseur.recu() else 'non'} — "
                    f"bureau {os.environ.get('XDG_CURRENT_DESKTOP', '?')}, session "
                    f"{os.environ.get('XDG_SESSION_TYPE', '?')}"))
        QTimer.singleShot(1200, _curseur_go)
    server = QLocalServer()
    w.server = server

    def on_conn():
        c = server.nextPendingConnection()
        buf = bytearray()

        def read():
            buf.extend(bytes(c.readAll()))
            if buf.startswith(b"run:"):             # sortie de « viki run » : peut arriver en plusieurs morceaux
                return
            msg = bytes(buf).decode(errors="ignore")
            buf.clear()
            handle(msg)

        def run_done():
            if buf.startswith(b"run:"):
                msg = bytes(buf).decode(errors="ignore")
                buf.clear()
                handle(msg)

        def handle(msg):
            if msg.startswith("quitter"):
                w.quit()
                return
            if msg.startswith("pos:"):              # position d'une invitée -> on répond avec la nôtre
                _, name, data = msg.split(":", 2)
                w._store_friend(name, data)
                c.write(("pos:" + w._my_geom_msg()).encode())
                c.flush()
                return
            if msg.startswith("clic:"):             # on câline son amie
                slug = msg[5:]
                try:
                    nm = json.loads((Path(next(x for x in w.cfg.get("invites", []) if Path(x).name == slug))
                                     / "character.json").read_text()).get("name", "elle")
                except Exception:
                    nm = "elle"
                w.friend_clicked(nm)
                return
            if msg.startswith("clic_amie:"):
                w.friend_clicked(msg[10:])
                return
            if msg.startswith("msg:"):              # quelqu'un lui parle (à la voix, via l'héroïne)
                w.bubble_text = f"« {msg[4:]} »"
                w.handle_message(msg[4:])
                return
            if msg.startswith("ecoute"):
                w.sleeping = False
                w.hop_start = time.monotonic()
                w.say(random.choice(["Oui ?", "Je t'écoute !", "Oui, dis-moi ?"]))
                return
            if msg.startswith("anim:"):
                k = msg[5:]
                if k == "pieds":
                    w._react("pieds")
                else:
                    w._play_anim(k)
                return
            if msg.startswith("renvoye:"):          # un invité est parti de lui-même
                if Path(msg[8:]).resolve().parent == (ASSETS_DIR / "amies").resolve():
                    w.cfg["amies_auto"] = False
                w.cfg["invites"] = [x for x in w.cfg.get("invites", []) if x != msg[8:]]
                save_config(w.cfg)
                w._rebuild_menus()
                return
            if msg.startswith("say:"):              # viki say "…"
                w.show()
                w.say(msg[4:].strip() or "Coucou !")
                return
            if msg.startswith("emote:"):            # viki emote 🎉
                w.react_emote(msg[6:].strip() or "😊")
                return
            if msg.startswith("jouer"):             # viki jouer (raccourci clavier)
                w.play_menu()
                return
            if msg.startswith("run:"):              # viki run <commande> : résultat
                w.on_run_result(msg[4:])
                return
            if msg.startswith("taille:") and GUEST:  # l'héroïne a changé de taille : on suit
                try:
                    px = float(msg[7:])
                    w.cfg["taille_hote"] = px
                    w._apply_scale(px / max(1, w._fig_h()))
                    w._update_mask()
                    save_config(w.cfg)
                except Exception as e:
                    print("Taille :", e, file=sys.stderr)
                return
            if msg.startswith("dire:"):             # réplique d'un dialogue entre personnages
                w.say(msg[5:])
                st = time.monotonic()
                tm = QTimer(w)

                def check():
                    now = time.monotonic()
                    if (now - st > 1.0 and not w.is_speaking(now)) or now - st > 40:
                        tm.stop()
                        try:
                            c.write(b"fini")
                            c.flush()
                        except RuntimeError:
                            pass
                tm.timeout.connect(check)
                tm.start(200)
                return
            w.show()
            if msg.startswith("zone"):
                w.translate_zone()
            elif msg.startswith("salon"):
                w.open_services()
            elif "parler" in msg:
                w.toggle_mic()
            elif "ecrire" in msg:
                w.open_input()
            elif "traduire" in msg:
                w.translate_selection()
            elif "lire" in msg:
                w.read_selection()
            elif "ecran" in msg:
                w.describe_screen()
        c.readyRead.connect(read)
        c.disconnected.connect(lambda: (read(), run_done()) if c.bytesAvailable() else run_done())
    server.newConnection.connect(on_conn)
    server.listen(INSTANCE_NAME)
    w.show()
    w._update_mask()
    if "--ecrire" in sys.argv:
        QTimer.singleShot(1200, w.open_input)
    for _flag, _fn in (("--traduire", "translate_selection"), ("--lire", "read_selection"), ("--ecran", "describe_screen"),
                       ("--zone", "translate_zone"), ("--salon", "open_services")):
        if _flag in sys.argv:
            QTimer.singleShot(2500, getattr(w, _fn))
    if "--capture" in sys.argv:   # pour les tests : capture d'écran puis quitter
        out = sys.argv[sys.argv.index("--capture") + 1]
        def shot():
            w.grab().save(out)
            app.quit()
        QTimer.singleShot(int(float(os.environ.get("CAPTURE_DELAY", "2.2")) * 1000), shot)
    sys.exit(app.exec())


if __name__ == "__main__":
    main()
